```java
import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.http.HttpRequestActionBuilder;

import java.util.Collections;
import java.util.List;
import java.util.UUID;
import java.util.function.BiFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String BASE_URL = resolveBase();
  private static final int SLOTS = 12;

  private static final Pattern NAME_CSRF =
      Pattern.compile("(?i)\\bname\\s*=\\s*(?:\"csrf\"|'csrf'|csrf(?=[\\s/>]))");
  private static final Pattern VALUE_ATTR =
      Pattern.compile("(?i)\\bvalue\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'>]+))");
  private static final Pattern HIDDEN_TYPE =
      Pattern.compile("(?i)\\btype\\s*=\\s*(?:\"hidden\"|'hidden'|hidden(?=[\\s/>]))");

  private static String resolveBase() {
    String v = System.getenv("BASE_URL");
    if (v == null || v.trim().isEmpty()) return "http://127.0.0.1:8000";
    String t = v.trim();
    while (t.endsWith("/")) t = t.substring(0, t.length() - 1);
    return t;
  }

  private final HttpProtocolBuilder protocol = http
      .baseUrl(BASE_URL)
      .disableFollowRedirect()
      .disableCaching()
      .acceptHeader("application/json")
      .userAgentHeader("bench-shop-flow");

  public ModelSimulation() {
    setUp(
        journey("bench-1", false).injectOpen(atOnceUsers(1)),
        journey("bench-2", true).injectOpen(atOnceUsers(1))
    )
        .protocols(protocol)
        .assertions(
            global().failedRequests().count().is(0L),
            global().successfulRequests().percent().is(100.0)
        );
  }

  /* ---------------- journey: one fresh login + one cart + one order per iteration ---------------- */

  private ScenarioBuilder journey(String username, boolean reverseCatalog) {
    return scenario("shop-flow-" + username)
        .exec(s -> s.set("username", username).set("reverse", reverseCatalog))
        .repeat(2).on(
            exec(flushSessionCookies())
                .exec(s -> s.set("csrf", "").set("formCsrf", "").set("cartId", "").set("etag", "")
                    .set("idemKey", "").set("orderId", "").set("loginLoc", "").set("accepted", "")
                    .set("productId", "").set("variantId", "")
                    .set("st", 0).set("err", "").set("didAuth", false))
                .exec(loginForm())
                .exec(login())
                .exec(catalog())
                .exec(createCart())
                .exec(readCart())
                .exec(patchCart())
                .exec(placeOrder())
                .exec(s -> {
                  if (intOf(s, "st") != 201) return s.markAsFailed();
                  if (!truthy(raw(s, "accepted"))) return s.markAsFailed();
                  if (str(s, "orderId").isEmpty()) return s.markAsFailed();
                  return s;
                })
        );
  }

  /* ---------------- login: hidden input selection + token/cookie pairing ---------------- */

  private ChainBuilder loginForm() {
    return exec(http("login-form")
        .get("/v2/login-form")
        .header("Accept", "text/html")
        .check(status().is(200))
        .check(css("form input[type=hidden][name=csrf]", "value").find().optional().saveAs("tokA"))
        .check(css("form input[name=csrf]", "value").find().optional().saveAs("tokB"))
        .check(css("input[type=hidden][name=csrf]", "value").find().optional().saveAs("tokC"))
        .check(css("input[name=csrf]", "value").find().optional().saveAs("tokD"))
        .check(regex("(?is)<input\\b[^>]*>").findAll().optional().saveAs("inputTags"))
    ).exec(s -> {
      String t = firstNonEmpty(s, "tokA", "tokB", "tokC", "tokD");
      if (t.isEmpty()) t = tokenFromTags(raw(s, "inputTags"));
      if (t.isEmpty()) return s.markAsFailed();
      return s.set("csrf", t).set("formCsrf", t).set("st", 0).set("err", "");
    });
  }

  private ChainBuilder login() {
    return exec(s -> s.set("loginLoc", ""))
        .exec(http("login")
            .post("/v2/login")
            .header("Content-Type", "application/json")
            .header("Accept", "application/json")
            .body(StringBody(s -> "{\"username\":" + jsonValue(s.getString("username"))
                + ",\"password\":\"bench\",\"csrf\":" + jsonValue(str(s, "csrf")) + "}"))
            .check(status().in(200, 302))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(header("Location").optional().saveAs("loginLoc")))
        .exec(s -> {
          String loc = str(s, "loginLoc");
          if (!loc.isEmpty() && !loc.startsWith("/") && !loc.startsWith(BASE_URL)) return s.markAsFailed();
          return s;
        })
        .doIf(s -> !str(s, "loginLoc").isEmpty())
        .then(exec(http("login-redirect")
            .get("#{loginLoc}")
            .check(status().is(200))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))))
        .exec(s -> str(s, "csrf").isEmpty() ? s.markAsFailed() : s);
  }

  /* ---------------- catalog: real ids only, both fixture orders ---------------- */

  private ChainBuilder catalog() {
    return exec(http("catalog")
        .get("/v2/catalog")
        .check(status().is(200))
        .check(jsonPath("$.data.products[*].id").findAll().saveAs("allProductIds"))
        .check(jsonPath("$.data.products[0].id").optional().saveAs("pid0"))
        .check(jsonPath("$.data.products[0].variants[*].id").findAll().optional().saveAs("vid0"))
        .check(jsonPath("$.data.products[0].variants[*].in_stock").findAll().optional().saveAs("stk0"))
        .check(jsonPath("$.data.products[1].id").optional().saveAs("pid1"))
        .check(jsonPath("$.data.products[1].variants[*].id").findAll().optional().saveAs("vid1"))
        .check(jsonPath("$.data.products[1].variants[*].in_stock").findAll().optional().saveAs("stk1"))
        .check(jsonPath("$.data.products[2].id").optional().saveAs("pid2"))
        .check(jsonPath("$.data.products[2].variants[*].id").findAll().optional().saveAs("vid2"))
        .check(jsonPath("$.data.products[2].variants[*].in_stock").findAll().optional().saveAs("stk2"))
        .check(jsonPath("$.data.products[3].id").optional().saveAs("pid3"))
        .check(jsonPath("$.data.products[3].variants[*].id").findAll().optional().saveAs("vid3"))
        .check(jsonPath("$.data.products[3].variants[*].in_stock").findAll().optional().saveAs("stk3"))
        .check(jsonPath("$.data.products[4].id").optional().saveAs("pid4"))
        .check(jsonPath("$.data.products[4].variants[*].id").findAll().optional().saveAs("vid4"))
        .check(jsonPath("$.data.products[4].variants[*].in_stock").findAll().optional().saveAs("stk4"))
        .check(jsonPath("$.data.products[5].id").optional().saveAs("pid5"))
        .check(jsonPath("$.data.products[5].variants[*].id").findAll().optional().saveAs("vid5"))
