  private static String str(Session s, String key) {
    Object v = raw(s, key);
    return v == null ? "" : String.valueOf(v);
  }

  private static int intOf(Session s, String key) {
    Object v = raw(s, key);
    if (v instanceof Number) return ((Number) v).intValue();
    try {
      return v == null ? -1 : Integer.parseInt(String.valueOf(v).trim());
    } catch (NumberFormatException e) {
      return -1;
    }
  }

  private static boolean boolOf(Session s, String key) {
    return truthy(raw(s, key));
  }

  private static boolean truthy(Object v) {
    if (v == null) return false;
    if (v instanceof Boolean) return (Boolean) v;
    String t = String.valueOf(v).trim();
    return t.equalsIgnoreCase("true") || t.equals("1");
  }

  private static List<?> listOf(Object v) {
    if (v == null) return Collections.emptyList();
    if (v instanceof List) return (List<?>) v;
    return Collections.singletonList(v);
  }

  private static String firstNonEmpty(Session s, String... keys) {
    for (String k : keys) {
      String v = str(s, k).trim();
      if (!v.isEmpty()) return v;
    }
    return "";
  }

  private static String tokenFromTags(Object rawTags) {
    if (!(rawTags instanceof List)) return "";
    String fallback = "";
    for (Object o : (List<?>) rawTags) {
      String tag = String.valueOf(o);
      if (!NAME_CSRF.matcher(tag).find()) continue;
      Matcher m = VALUE_ATTR.matcher(tag);
      if (!m.find()) continue;
      String v = m.group(1) != null ? m.group(1) : (m.group(2) != null ? m.group(2) : m.group(3));
      if (v == null || v.trim().isEmpty()) continue;
      if (HIDDEN_TYPE.matcher(tag).find()) return v.trim();
      if (fallback.isEmpty()) fallback = v.trim();
    }
    return fallback;
  }

  private static String jsonValue(Object v) {
    if (v == null) return "null";
    if (v instanceof Number || v instanceof Boolean) return v.toString();
    String t = String.valueOf(v);
    StringBuilder b = new StringBuilder("\"");
    for (int i = 0; i < t.length(); i++) {
      char c = t.charAt(i);
      if (c == '"' || c == '\\') b.append('\\').append(c);
      else if (c == '\n') b.append("\\n");
      else if (c == '\r') b.append("\\r");
      else if (c == '\t') b.append("\\t");
      else b.append(c);
    }
    return b.append('"').toString();
  }
