import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    shop_flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '3m',
      gracefulStop: '10s',
    },
  },
  thresholds: {
    checks: ['rate==1.0'],
    business_failure: ['rate<0.01'],
    http_req_failed: ['rate<0.01'],
  },
};

http.setResponseCallback(http.expectedStatuses({ min: 200, max: 399 }, 401, 412, 428, 429));

function absoluteUrl(u) {
  if (!u || typeof u !== 'string') return null;
  if (u.indexOf('http://') === 0 || u.indexOf('https://') === 0) {
    return u.indexOf(BASE_URL) === 0 ? u : null;
  }
  if (u.charAt(0) === '/') return BASE_URL + u;
  return BASE_URL + '/' + u;
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const target = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === target) return res.headers[keys[i]];
  }
  return null;
}

function jsonOf(res) {
  if (!res || !res.body) return null;
  try { return res.json(); } catch (e) { return null; }
}

function captureCsrf(res, state) {
  const j = jsonOf(res);
  if (j && typeof j.csrf === 'string' && j.csrf.length > 0) state.csrf = j.csrf;
}

function merge(a, b) {
  const out = {};
  if (a) Object.keys(a).forEach(function (k) { out[k] = a[k]; });
  if (b) Object.keys(b).forEach(function (k) { out[k] = b[k]; });
  return out;
}

function raw(method, path, body, state, extraHeaders, label) {
  const url = absoluteUrl(path);
  const headers = {
    'Content-Type': 'application/json',
    Accept: 'application/json, text/html;q=0.9, */*;q=0.8',
  };
  if (method !== 'GET' && state && state.csrf) headers['X-CSRF-Token'] = state.csrf;
  const extra = extraHeaders || {};
  Object.keys(extra).forEach(function (k) { headers[k] = extra[k]; });
  const params = { headers: headers, redirects: 0, tags: { name: label || path } };
  const payload = body === null || body === undefined ? null : JSON.stringify(body);
  if (method === 'GET') return http.get(url, params);
  if (method === 'POST') return http.post(url, payload, params);
  if (method === 'PATCH') return http.patch(url, payload, params);
  if (method === 'PUT') return http.put(url, payload, params);
  return http.request(method, url, payload, params);
}

function decodeEntities(s) {
  if (!s) return s;
  return s
    .replace(/&#x([0-9a-fA-F]+);/g, function (_, h) { return String.fromCharCode(parseInt(h, 16)); })
    .replace(/&#([0-9]+);/g, function (_, d) { return String.fromCharCode(parseInt(d, 10)); })
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function parseAttrs(s) {
  const attrs = {};
  const re = /([^\s=\/>"']+)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    const name = m[1].toLowerCase();
    let val = '';
    if (m[2] !== undefined) val = m[2];
    else if (m[3] !== undefined) val = m[3];
    else if (m[4] !== undefined) val = m[4];
    if (!(name in attrs)) attrs[name] = decodeEntities(val);
  }
  return attrs;
}

function pickCsrfFromRegion(region, strict) {
  const inputRe = /<input\b((?:"[^"]*"|'[^']*'|[^>"'])*)\/?>/gi;
  let m;
  while ((m = inputRe.exec(region)) !== null) {
    const a = parseAttrs(m[1]);
    if (a.name !== 'csrf') continue;
    if ('disabled' in a) continue;
    if ('data-decoy' in a || 'data-fake' in a) continue;
    if (strict && a.type !== 'hidden') continue;
    if (!strict && a.type && a.type !== 'hidden' && a.type !== 'text') continue;
    if (!('value' in a)) continue;
    const v = a.value;
    if (!v || /decoy|dummy|fake/i.test(v)) continue;
    return v;
  }
  return null;
}

function extractCsrf(html) {
  if (!html) return null;
  const doc = String(html)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style>/gi, ' ')
    .replace(/<template\b[\s\S]*?<\/template>/gi, ' ');
  const regions = [];
  const formRe = /<form\b((?:"[^"]*"|'[^']*'|[^>"'])*)>([\s\S]*?)<\/form>/gi;
  let fm;
  while ((fm = formRe.exec(doc)) !== null) {
    const attrs = parseAttrs(fm[1]);
    if ((attrs.action || '').indexOf('/v2/login') !== -1) regions.push(fm[2]);
  }
  regions.push(doc);
  for (let r = 0; r < regions.length; r++) {
    const t = pickCsrfFromRegion(regions[r], true) || pickCsrfFromRegion(regions[r], false);
    if (t) return t;
  }
  return null;
}

function freshLogin(state) {
  state.csrf = null;
  const formRes = raw('GET', '/v2/login-form', null, state, null, 'GET /v2/login-form');
  if (!check(formRes, { 'login form 200': function (r) { return r.status === 200; } })) return false;
  const token = extractCsrf(formRes.body || '');
  if (!check(token, { 'hidden csrf input extracted': function (t) { return typeof t === 'string' && t.length > 0; } })) return false;
  state.csrf = token;
  let res = raw('POST', '/v2/login', { username: state.username, password: 'bench', csrf: token }, state, null, 'POST /v2/login');
  if (res.status >= 300 && res.status < 400) {
    const loc = absoluteUrl(header(res, 'Location'));
    if (!check(loc, { 'login redirect location present': function (l) { return !!l; } })) return false;
    res = raw('GET', loc, null, state, null, 'GET /v2/login (redirect)');
  }
  captureCsrf(res, state);
  const j = jsonOf(res);
  const ok = check(res, { 'login authorized': function (r) { return r.status >= 200 && r.status < 300; } });
  check(j, { 'login returns session csrf': function (x) { return !!(x && typeof x.csrf === 'string' && x.csrf.length > 0); } });
  return ok && !!state.csrf;
}

function renewAndRecover(state, mode) {
  if (mode === 'expired') {
    const renew = raw('POST', '/v2/session/renew', {}, state, null, 'POST /v2/session/renew');
    captureCsrf(renew, state);
    if (!(renew.status >= 200 && renew.status < 300)) freshLogin(state);
  } else {
    freshLogin(state);
  }
  if (state.cartId) {
    const rec = raw('POST', '/v2/carts/' + state.cartId + '/recover', {}, state, null, 'POST /v2/carts/{id}/recover');
    captureCsrf(rec, state);
  }
}

function authed(method, path, body, state, extraHeaders, label, budget) {
  budget = budget || { recoveries: 0 };
  let res = raw(method, path, body, state, extraHeaders, label);
  captureCsrf(res, state);
  if (res.status === 401 && budget.recoveries < 1) {
    const j = jsonOf(res);
    const err = j && j.error;
    if (err === 'denied') {
      check(res, { '401 denied must fail assertion': function () { return false; } });
      return res;
    }
    if (err === 'expired' || err === 'session') {
      budget.recoveries++;
      renewAndRecover(state, err);
      res = raw(method, path, body, state, extraHeaders, label);
      captureCsrf(res, state);
    } else {
      check(res, { 'unexpected 401 shape': function () { return false; } });
    }
  }
  return res;
}

function businessWork(state) {
  let retries429 = 0;
  let recovered = false;
  for (;;) {
    const res = raw('POST', '/v2/work', {}, state, null, 'POST /v2/work');
    captureCsrf(res, state);
    if (res.status === 429) {
      businessFailure.add(false);
      if (retries429 >= 4) {
        check(res, { 'work completed within retry budget': function () { return false; } });
        return;
      }
      retries429++;
      let wait = parseFloat(header(res, 'Retry-After') || '1');
      if (!isFinite(wait) || wait < 1) wait = 1;
      sleep(wait);
      continue;
    }
    if (res.status === 401) {
      const j = jsonOf(res);
      const err = j && j.error;
      if ((err === 'expired' || err === 'session') && !recovered) {
        businessFailure.add(false);
        recovered = true;
        renewAndRecover(state, err);
        continue;
      }
      businessFailure.add(true);
      check(res, { 'work authorized': function () { return false; } });
      return;
    }
    const j = jsonOf(res);
    const ok = res.status === 200 && !!(j && j.ok === true);
    businessFailure.add(!ok);
    check(res, { 'work ok': function () { return ok; } });
    return;
  }
}

function pickProduct(state) {
  let products = [];
  const res = authed('GET', '/v2/catalog', null, state, null, 'GET /v2/catalog');
  if (res.status === 200) {
    const j = jsonOf(res);
    if (j && j.data && Array.isArray(j.data.products)) products = j.data.products;
  }
  if (!products.length) {
    let next = '/v2/catalog/page';
    for (let page = 0; page < 3 && next; page++) {
      const r = authed('GET', next, null, state, null, 'GET /v2/catalog/page');
      if (r.status !== 200) break;
      const j = jsonOf(r);
      if (j && j.data) {
        if (Array.isArray(j.data.products)) products = products.concat(j.data.products);
        else if (j.data.product) products.push(j.data.product);
      }
      next = j && j.next ? j.next : null;
    }
  }
  check(products.length, { 'catalog products available': function (n) { return n > 0; } });
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p || p.id === undefined || !Array.isArray(p.variants)) continue;
    for (let v = 0; v < p.variants.length; v++) {
      const variant = p.variants[v];
      if (variant && variant.id !== undefined && variant.in_stock) {
        return { productId: p.id, variantId: variant.id };
      }
    }
  }
  check(null, { 'in-stock variant found': function () { return false; } });
  return null;
}

export default function () {
  const jar = http.cookieJar();
  jar.clear(BASE_URL);
  const state = { username: 'bench-' + __VU, csrf: null, cartId: null };

  if (!freshLogin(state)) return;
  businessWork(state);

  const pick = pickProduct(state);
  if (!pick) return;

  const create = authed('POST', '/v2/carts', { product_id: pick.productId, variant_id: pick.variantId }, state, null, 'POST /v2/carts');
  const cj = jsonOf(create);
  const created = check(create, { 'cart created 201': function (r) { return r.status === 201; } });
  if (!created || !cj || cj.id === undefined) return;
  state.cartId = cj.id;
  let etag = header(create, 'ETag');
  const cartPath = '/v2/carts/' + state.cartId;

  const getRes = authed('GET', cartPath, null, state, null, 'GET /v2/carts/{id}');
  check(getRes, { 'cart readable': function (r) { return r.status === 200; } });
  etag = header(getRes, 'ETag') || etag;

  const patchBudget = { recoveries: 0 };
  let patch = authed('PATCH', cartPath, { quantity: 2 }, state, etag ? { 'If-Match': etag } : null, 'PATCH /v2/carts/{id}', patchBudget);
  if (patch.status === 412) {
    const rr = authed('GET', cartPath, null, state, null, 'GET /v2/carts/{id}', patchBudget);
    etag = header(rr, 'ETag') || etag;
    patch = authed('PATCH', cartPath, { quantity: 2 }, state, etag ? { 'If-Match': etag } : null, 'PATCH /v2/carts/{id}', patchBudget);
  }
  const patched = check(patch, { 'cart quantity updated': function (r) { return r.status >= 200 && r.status < 300; } });
  etag = header(patch, 'ETag') || etag;
  if (!patched) return;

  const idem = 'order-' + state.username + '-' + __ITER + '-' + state.cartId;
  const orderBudget = { recoveries: 0 };
  let order = authed('POST', '/v2/orders', { cart_id: state.cartId }, state, merge({ 'Idempotency-Key': idem }, etag ? { 'If-Match': etag } : null), 'POST /v2/orders', orderBudget);
  if (order.status === 412 || order.status === 428) {
    const rr = authed('GET', cartPath, null, state, null, 'GET /v2/carts/{id}', orderBudget);
    etag = header(rr, 'ETag') || etag;
    order = authed('POST', '/v2/orders', { cart_id: state.cartId }, state, merge({ 'Idempotency-Key': idem }, etag ? { 'If-Match': etag } : null), 'POST /v2/orders', orderBudget);
  }
  const oj = jsonOf(order);
  check(order, {
    'order committed 201 accepted': function (r) { return r.status === 201 && !!(oj && oj.accepted === true && oj.id !== undefined); },
  });
}
