```python
"""Locust 2.47 locustfile: HTML login-form CSRF extraction -> authenticated shop flow.

Contract: 2 virtual users x 2 iterations (flow mode), one committed order per journey.
Profiles:
  slot A: {"login_csrf": True}
  slot B: {"login_csrf": True, "html_layout": 1, "reverse_catalog": True}
"""

import json
import os
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
PASSWORD = "bench"
TOTAL_USERS = 2
ITERATIONS_PER_USER = 2
TOTAL_JOURNEYS = TOTAL_USERS * ITERATIONS_PER_USER
MAX_WALL_SECONDS = 180.0

RUNTIME = {"next_slot": 0, "finished": 0, "journeys": 0, "orders": 0}


# --------------------------------------------------------------------------- #
# HTML parsing: pick the real hidden input[name=csrf], ignore decoy variants.  #
# --------------------------------------------------------------------------- #
class _LoginFormParser(HTMLParser):
    _SKIP = {"script", "style", "template"}

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._forms = []
        self._skip = 0
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in self._SKIP:
            self._skip += 1
            return
        a = {}
        for k, v in attrs:
            k = k.lower()
            if k not in a:
                a[k] = "" if v is None else v
        if tag == "form":
            self._forms.append(a.get("action", ""))
            return
        if tag != "input" or self._skip:
            return
        if a.get("name", "").strip() != "csrf":
            return
        if a.get("type", "").strip().lower() != "hidden":
            return
        if "disabled" in a:
            return
        value = a.get("value", "")
        if not value:
            return
        for k, v in a.items():
            if k == "value":
                continue
            if "decoy" in k or "decoy" in (v or "").lower():
                return
        self.candidates.append((value, self._forms[-1] if self._forms else None))

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in self._SKIP:
            if self._skip:
                self._skip -= 1
            return
        if tag == "form" and self._forms:
            self._forms.pop()


def extract_login_csrf(html):
    parser = _LoginFormParser()
    try:
        parser.feed(html or "")
        parser.close()
    except Exception:
        pass
    if not parser.candidates:
        return None
    for value, action in parser.candidates:
        if not action:
            continue
        try:
            if urlsplit(action).path.rstrip("/") == "/v2/login":
                return value
        except Exception:
            continue
    return parser.candidates[0][0]


def _json(resp):
    try:
        data = resp.json()
    except Exception:
        return None
    return data if isinstance(data, dict) else None


def _has_products(data):
    block = data.get("data") or {}
    products = block.get("products")
    return isinstance(products, list) and len(products) > 0


def _cart_ok(data):
    return bool(data.get("id"))


def _order_ok(data):
    return data.get("accepted") is True and bool(data.get("id"))


def _work_ok(data):
    return data.get("ok") is True


# --------------------------------------------------------------------------- #
# User                                                                         #
# --------------------------------------------------------------------------- #
class ShopUser(HttpUser):
    abstract = True
    host = BASE_URL
    wait_time = constant(0.05)
    profile = {"login_csrf": True}

    def on_start(self):
        self.slot = RUNTIME["next_slot"]
        RUNTIME["next_slot"] += 1
        self.username = "bench-%d" % ((self.slot % 16) + 1)
        self.iterations = 0
        self._done = False
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idem = None

    # ---------------------------- transport ------------------------------- #
    def _request(self, method, path, payload=None, expected=(200,), name=None,
                 headers=None, check=None, allow_precondition=False,
                 retry_429=False, track_etag=False):
        url = path if path.startswith("http") else BASE_URL + path
        hdrs = {"Accept": "application/json"}
        if method != "GET" and self.csrf:
            hdrs["X-CSRF-Token"] = self.csrf
        if headers:
            hdrs.update(headers)
        kwargs = {
            "catch_response": True,
            "allow_redirects": False,
            "name": name or path,
            "headers": hdrs,
        }
        if payload is not None:
            kwargs["json"] = payload
        fn = getattr(self.client, method.lower())
        with fn(url, **kwargs) as resp:
            data = _json(resp)
            code = resp.status_code
            hdrs_out = dict(resp.headers)
            if code in expected and (check is None or (isinstance(data, dict) and check(data))):
                resp.success()
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                if track_etag and hdrs_out.get("ETag"):
                    self.cart_etag = hdrs_out["ETag"]
                return data, "ok", code, hdrs_out
            if code == 401 and isinstance(data, dict) and data.get("error") in ("expired", "session"):
                resp.success()
                return data, data["error"], code, hdrs_out
            if code == 429 and retry_429:
                resp.success()
                return data, "ratelimited", code, hdrs_out
            if allow_precondition and code in (412, 428):
                resp.success()
                return data, "precondition", code, hdrs_out
            resp.failure("%s %s -> HTTP %s %s" % (
                method, name or path, code, (resp.text or "")[:200]))
            return data, "error", code, hdrs_out

    def _auth(self, method, path, payload=None, expected=(200,), name=None,
              headers=None, check=None, allow_precondition=False,
              retry_429=False, track_etag=False):
        data, state, code, hdrs = self._request(
            method, path, payload=payload, expected=expected, name=name,
            headers=headers, check=check, allow_precondition=allow_precondition,
            retry_429=retry_429, track_etag=track_etag)
        if state in ("expired", "session"):
            if self._recover(state):
                data, state, code, hdrs = self._request(
                    method, path, payload=payload, expected=expected, name=name,
                    headers=headers, check=check,
                    allow_precondition=allow_precondition,
                    retry_429=retry_429, track_etag=track_etag)
        return data, state, code, hdrs

    def _recover(self, kind):
        renewed = False
        if kind == "expired":
            _, state, _, _ = self._request(
                "POST", "/v2/session/renew", payload={},
                expected=(200, 201, 202), name="/v2/session/renew")
            if state == "ok":
                renewed = True
            elif state in ("expired", "session"):
                renewed = self._login()
            else:
                return False
        else:
            renewed = self._login()
        if not renewed:
            return False
        if self.cart_id:
            self._request(
                "POST", "/v2/carts/%s/recover" % self.cart_id, payload={},
                expected=(200, 201, 202), name="/v2/carts/[id]/recover",
                track_etag=True)
        return True

    # ------------------------------ login --------------------------------- #
    def _form_token(self):
        with self.client.get(
            BASE_URL + "/v2/login-form",
            catch_response=True, allow_redirects=False,
            name="/v2/login-form", headers={"Accept": "text/html"},
        ) as resp:
            if resp.status_code != 200:
                resp.failure("login-form -> HTTP %s" % resp.status_code)
                return None
            token = extract_login_csrf(resp.text or "")
            if not token:
                resp.failure("login-form: no enabled hidden input[name=csrf] value")
                return None
            resp.success()
            return token

    def _login(self):
        self.csrf = None
        token = self._form_token()
        if not token:
            return False
        payload = {"username": self.username, "password": PASSWORD, "csrf": token}
        location = None
        with self.client.post(
            BASE_URL + "/v2/login", json=payload, catch_response=True,
            allow_redirects=False, name="/v2/login",
            headers={"Accept": "application/json"},
        ) as resp:
            code = resp.status_code
            if code in (200, 201):
                data = _json(resp) or {}
                self.csrf = data.get("csrf") or token
                resp.success()
                return True
            if code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 without Location")
                    return False
                resp.success()
            else:
                resp.failure("login -> HTTP %s %s" % (code, (resp.text or "")[:200]))
                return False
        target = urljoin(BASE_URL + "/v2/login", location)
        with self.client.get(
            target, catch_response=True, allow_redirects=False,
            name="/v2/login/redirect", headers={"Accept": "application/json"},
        ) as resp:
            if resp.status_code != 200:
                resp.failure("login redirect -> HTTP %s" % resp.status_code)
                return False
            data = _json(resp) or {}
            self.csrf = data.get("csrf") or token
            resp.success()
            return True

    # ------------------------------- work --------------------------------- #
    def _work(self):
        throttled = 0
        recovered = False
        while True:
            _, state, _, hdrs = self._request(
                "POST", "/v2/work", payload={}, expected=(200,),
                name="/v2/work", check=_work_ok, retry_429=True)
            if state == "ok":
                return True
            if state == "ratelimited":
                throttled += 1
                if throttled > 4:
                    return False
                try:
                    delay = float(hdrs.get("Retry-After", "1"))
                except (TypeError, ValueError):
                    delay = 1.0
                time.sleep(max(0.05, delay))
                continue
            if state in ("expired", "session") and not recovered:
                recovered = True
                if self._recover(state):
                    continue
            return False

    # ------------------------------ catalog ------------------------------- #
    def _catalog(self):
        products = []
        if self.profile.get("reverse_catalog"):
            path = "/v2/catalog/page"
            for _ in range(3):
                data, state, _, _ = self._auth(
                    "GET", path, expected=(200,), name="/v2/catalog/page",
                    check=_has_products)
                if state != "ok" or not isinstance(data, dict):
                    return None, None
                block = data.get("data") or {}
                page = block.get("products") or []
                if isinstance(page, dict):
                    page = [page]
                products.extend(page)
                nxt = data.get("next")
                if not nxt:
                    break
                path = urljoin(BASE_URL + "/v2/catalog/page", nxt)
            products = list(reversed(products))
        else:
            data, state, _, _ = self._auth(
                "GET", "/v2/catalog", expected=(200,), name="/v2/catalog",
                check=_has_products)
            if state != "ok" or not isinstance(data, dict):
                return None, None
            products = (data.get("data") or {}).get("products") or []
        fallback = None
        for product in products:
            if not isinstance(product, dict):
                continue
            pid = product.get("id")
            for variant in product.get("variants") or []:
                if not isinstance(variant, dict):
                    continue
                vid = variant.get("id")
                if pid is None or vid is None:
                    continue
                if fallback is None:
                    fallback = (pid, vid)
                if variant.get("in_stock"):
                    return pid, vid
        if fallback:
            return fallback
        return None, None

    # -------------------------------- cart -------------------------------- #
    def _create_cart(self, product_id, variant_id):
        data, state, _, _ = self._auth(
            "POST", "/v2/carts",
            payload={"product_id": product_id, "variant_id": variant_id},
            expected=(201,), name="/v2/carts", check=_cart_ok, track_etag=True)
        if state != "ok":
            return False
        self.cart_id = data["id"]
        self.idem = uuid.uuid4().hex
        return True

    def _read_cart(self):
        _, state, _, _ = self._auth(
            "GET", "/v2/carts/%s" % self.cart_id, expected=(200,),
            name="/v2/carts/[id]", track_etag=True)
        return state == "ok"

    def _patch_quantity(self, quantity):
        payload = {"quantity": quantity}
        if not self.cart_etag and not self._read_cart():
            return False
        for attempt in range(2):
            headers = {}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            _, state, _, _ = self._auth(
                "PATCH", "/v2/carts/%s" % self.cart_id, payload=payload,
                expected=(200, 201, 202), name="/v2/carts/[id]",
                headers=headers, allow_precondition=True, track_etag=True)
            if state == "ok":
                return True
            if state == "precondition" and attempt == 0:
                if not self._read_cart():
                    return False
                continue
            return False
        return False

    def _checkout(self):
        payload = {"cart_id": self.cart_id}
        for attempt in range(2):
            headers = {"Idempotency-Key": self.idem}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            _, state, _, _ = self._auth(
                "POST", "/v2/orders", payload=payload, expected=(201,),
                name="/v2/orders", headers=headers, check=_order_ok,
                allow_precondition=True)
            if state == "ok":
                RUNTIME["orders"] += 1
                return True
            if state == "precondition" and attempt == 0:
                if not self._read_cart():
                    return False
                continue
            return False
        return False

    # ------------------------------ journey ------------------------------- #
    def _run_journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idem = None
        if not self._login():
            return
        self._work()
        product_id, variant_id = self._catalog()
        if product_id is None:
            return
        if not self._create_cart(product_id, variant_id):
            return
        if not self._patch_quantity(2):
            return
        self._checkout()

    def _complete(self):
        if not self._done:
            self._done = True
            RUNTIME["finished"] += 1

    @task
    def journey(self):
        if self.slot >= TOTAL_USERS:
            raise StopUser()
        if self.iterations >= ITERATIONS_PER_USER or RUNTIME["journeys"] >= TOTAL_JOURNEYS:
            self._complete()
            raise StopUser()
        RUNTIME["journeys"] += 1
        self.iterations += 1
        try:
            self._run_journey()
        except StopUser:
            raise
        except Exception:
            pass
        if self.iterations >= ITERATIONS_PER_USER:
            self._complete()
            raise StopUser()


