import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final int USERS = 2;
  private static final int ITERATIONS = 2;
  private static final String BASE_URL = resolveBase();
  private static final AtomicInteger OWNER = new AtomicInteger(0);

  private static final Pattern INPUT_TAG = Pattern.compile("<input\\b[^>]*>", Pattern.CASE_INSENSITIVE);
  private static final Pattern ATTRIBUTE =
      Pattern.compile("([a-zA-Z_:][-a-zA-Z0-9_:.]*)(\\s*=\\s*(\"([^\"]*)\"|'([^']*)'|([^\\s\"'>]+)))?");

  private static String resolveBase() {
    String env = System.getenv("BASE_URL");
    if (env == null || env.trim().isEmpty()) return "http://127.0.0.1:8000";
    String b = env.trim();
    while (b.endsWith("/")) b = b.substring(0, b.length() - 1);
    return b;
  }

  private static String absolutize(String url) {
    if (url == null) return null;
    if (url.startsWith("http://") || url.startsWith("https://")) return url;
    return url.startsWith("/") ? BASE_URL + url : BASE_URL + "/" + url;
  }

  /* ---------------- minimal JSON reader (no external libraries) ---------------- */

  private static final class Json {
    private final String src;
    private int pos;

    private Json(String src) {
      this.src = src;
      this.pos = 0;
    }

    static Object parse(String text) {
      if (text == null || text.trim().isEmpty()) return null;
      try {
        Json p = new Json(text);
        p.ws();
        return p.value();
      } catch (Exception e) {
        return null;
      }
    }

    private void ws() {
      while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) pos++;
    }

    private void expect(String lit) {
      if (!src.startsWith(lit, pos)) throw new IllegalStateException("literal");
      pos += lit.length();
    }

    private Object value() {
      ws();
      if (pos >= src.length()) throw new IllegalStateException("eof");
      char c = src.charAt(pos);
      if (c == '{') return object();
      if (c == '[') return array();
      if (c == '"') return string();
      if (c == 't') { expect("true"); return Boolean.TRUE; }
      if (c == 'f') { expect("false"); return Boolean.FALSE; }
      if (c == 'n') { expect("null"); return null; }
      return number();
    }

    private Map<String, Object> object() {
      Map<String, Object> m = new LinkedHashMap<>();
      pos++;
      ws();
      if (pos < src.length() && src.charAt(pos) == '}') { pos++; return m; }
      while (true) {
        ws();
        String k = string();
        ws();
        if (src.charAt(pos) != ':') throw new IllegalStateException("colon");
        pos++;
        m.put(k, value());
        ws();
        char c = src.charAt(pos);
        if (c == ',') { pos++; continue; }
        if (c == '}') { pos++; return m; }
        throw new IllegalStateException("object");
      }
    }

    private List<Object> array() {
      List<Object> l = new ArrayList<>();
      pos++;
      ws();
      if (pos < src.length() && src.charAt(pos) == ']') { pos++; return l; }
      while (true) {
        l.add(value());
        ws();
        char c = src.charAt(pos);
        if (c == ',') { pos++; continue; }
        if (c == ']') { pos++; return l; }
        throw new IllegalStateException("array");
      }
    }

    private String string() {
      if (src.charAt(pos) != '"') throw new IllegalStateException("quote");
      pos++;
      StringBuilder b = new StringBuilder();
      while (true) {
        char c = src.charAt(pos++);
        if (c == '"') return b.toString();
        if (c != '\\') { b.append(c); continue; }
        char e = src.charAt(pos++);
        if (e == 'u') {
          b.append((char) Integer.parseInt(src.substring(pos, pos + 4), 16));
          pos += 4;
        } else if (e == 'n') b.append('\n');
        else if (e == 'r') b.append('\r');
        else if (e == 't') b.append('\t');
        else if (e == 'b') b.append('\b');
        else if (e == 'f') b.append('\f');
        else b.append(e);
      }
    }

    private Object number() {
      int start = pos;
      while (pos < src.length() && "+-0123456789.eE".indexOf(src.charAt(pos)) >= 0) pos++;
      String t = src.substring(start, pos);
      if (t.isEmpty()) throw new IllegalStateException("number");
      if (t.indexOf('.') < 0 && t.indexOf('e') < 0 && t.indexOf('E') < 0) {
        try { return Long.valueOf(Long.parseLong(t)); } catch (Exception ignored) { }
      }
      return Double.valueOf(Double.parseDouble(t));
    }
  }

  @SuppressWarnings("unchecked")
  private static Map<String, Object> asMap(Object o) {
    return o instanceof Map ? (Map<String, Object>) o : null;
  }

  private static String str(Object o) {
    return o == null ? null : String.valueOf(o);
  }

  private static String lit(Object o) {
    if (o == null) return "null";
    if (o instanceof Number || o instanceof Boolean) return String.valueOf(o);
    String s = String.valueOf(o);
    StringBuilder b = new StringBuilder("\"");
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c == '"' || c == '\\') b.append('\\').append(c);
      else if (c < 0x20) b.append(String.format("\\u%04x", (int) c));
      else b.append(c);
    }
    return b.append('"').toString();
  }

  private static Object findKey(Object node, String key) {
    if (node instanceof Map) {
      Map<?, ?> m = (Map<?, ?>) node;
      if (m.containsKey(key)) return m.get(key);
      for (Object v : m.values()) {
        Object r = findKey(v, key);
        if (r != null) return r;
      }
    } else if (node instanceof List) {
      for (Object v : (List<?>) node) {
        Object r = findKey(v, key);
        if (r != null) return r;
      }
    }
    return null;
  }

  private static boolean truthy(Object o) {
    if (o == null) return false;
    if (o instanceof Boolean) return ((Boolean) o).booleanValue();
    if (o instanceof Number) return ((Number) o).doubleValue() > 0.0d;
    String s = String.valueOf(o).trim();
    return "true".equalsIgnoreCase(s) || "1".equals(s) || "yes".equalsIgnoreCase(s) || "in_stock".equalsIgnoreCase(s);
  }

  private static boolean inStock(Map<String, Object> variant) {
    Object direct = variant.get("in_stock");
    if (direct != null) return truthy(direct);
    return truthy(findKey(variant, "in_stock"));
  }

  private static String bodyOf(Session s, String key) {
    return s.contains(key) ? s.getString(key) : null;
  }

  private static Session applyCsrf(Session s, String key) {
    Map<String, Object> m = asMap(Json.parse(bodyOf(s, key)));
    if (m == null) return s;
    Object c = m.get("csrf");
    if (c instanceof String && !((String) c).isEmpty()) return s.set("csrf", c);
    return s;
  }

  private static String errorKind(String body) {
    Object e = findKey(Json.parse(body), "error");
    if (e instanceof Map) {
      Object c = ((Map<?, ?>) e).get("code");
      if (c == null) c = ((Map<?, ?>) e).get("type");
      return c == null ? "" : String.valueOf(c);
    }
    return e == null ? "" : String.valueOf(e);
  }

  /* ---------------- html csrf extraction (layout / attribute-order agnostic) ---------------- */

  private static String decode(String v) {
    return v.replace("&amp;", "&").replace("&quot;", "\"").replace("&#39;", "'")
        .replace("&lt;", "<").replace("&gt;", ">");
  }

  private static Map<String, String> attributes(String tag) {
    Map<String, String> a = new LinkedHashMap<>();
    Matcher m = ATTRIBUTE.matcher(tag);
    while (m.find()) {
      String k = m.group(1).toLowerCase(Locale.ROOT);
      String v;
      if (m.group(3) != null) v = m.group(3);
      else if (m.group(4) != null) v = m.group(4);
      else if (m.group(5) != null) {
        v = m.group(5);
        while (v.endsWith("/")) v = v.substring(0, v.length() - 1);
      } else v = "";
      if (!a.containsKey(k)) a.put(k, decode(v));
    }
    return a;
  }

  private static String extractCsrf(String html) {
    if (html == null) return null;
    Matcher m = INPUT_TAG.matcher(html);
    String fallback = null;
    while (m.find()) {
      Map<String, String> a = attributes(m.group());
      if (!"csrf".equals(a.get("name"))) continue;
      String v = a.get("value");
      if (v == null || v.isEmpty()) continue;
      String type = a.get("type");
      if (type == null || type.isEmpty() || "hidden".equalsIgnoreCase(type)) return v;
      if (fallback == null) fallback = v;
    }
    return fallback;
  }

  /* ---------------- catalog selection: parent-owned in-stock variant ---------------- */

  private static void collectProducts(Object node, List<Map<String, Object>> out) {
    if (node instanceof Map) {
      Map<?, ?> m = (Map<?, ?>) node;
      if (m.get("id") != null && m.get("variants") instanceof List) out.add(asMap(m));
      for (Object v : m.values()) collectProducts(v, out);
    } else if (node instanceof List) {
      for (Object v : (List<?>) node) collectProducts(v, out);
    }
  }

  private static int cmp(Object a, Object b) {
    String x = a == null ? "" : String.valueOf(a);
    String y = b == null ? "" : String.valueOf(b);
    return x.compareTo(y);
  }

  private static Session selectProduct(Session s) {
    Session out = s.remove("nextUrl");
    Object root = Json.parse(bodyOf(out, "catBody"));
    Map<String, Object> top = asMap(root);
    if (top != null) {
      Object nx = top.get("next");
      if (nx instanceof String && !((String) nx).isEmpty()) out = out.set("nextUrl", absolutize((String) nx));
    }
    List<Map<String, Object>> products = new ArrayList<>();
    collectProducts(root, products);

    Map<String, Object> bestProduct = null;
    Map<String, Object> bestVariant = null;
    for (Map<String, Object> p : products) {
      Object variants = p.get("variants");
      if (!(variants instanceof List) || p.get("id") == null) continue;
      for (Object vo : (List<?>) variants) {
        Map<String, Object> v = asMap(vo);
        if (v == null || v.get("id") == null || !inStock(v)) continue;
        if (bestProduct == null
            || cmp(p.get("id"), bestProduct.get("id")) < 0
            || (cmp(p.get("id"), bestProduct.get("id")) == 0 && cmp(v.get("id"), bestVariant.get("id")) < 0)) {
          bestProduct = p;
          bestVariant = v;
        }
      }
    }
    if (bestProduct != null) {
      out = out.set("productId", str(bestProduct.get("id")))
          .set("variantId", str(bestVariant.get("id")))
          .set("productIdJson", lit(bestProduct.get("id")))
          .set("variantIdJson", lit(bestVariant.get("id")));
    }
    boolean more = bestProduct == null && out.contains("nextUrl");
    return out.set("needPages", Boolean.valueOf(more));
  }

  /* ---------------- shared state helpers ---------------- */

  private static Session resetJourney(Session s) {
    return s.remove("cartId").remove("cartIdJson").remove("orderKey").remove("orderId")
        .remove("productId").remove("variantId").remove("productIdJson").remove("variantIdJson")
        .remove("nextUrl").remove("opBody").remove("etagTmp")
        .set("etag", "*")
        .set("hasCart", Boolean.FALSE)
        .set("needPages", Boolean.FALSE)
        .set("cartRetry", Boolean.FALSE)
        .set("readRetry", Boolean.FALSE)
        .set("patchRetry", Boolean.FALSE)
        .set("patchReread", Boolean.FALSE)
        .set("patch401", Boolean.FALSE)
        .set("orderRetry", Boolean.FALSE)
        .set("orderRefresh", Boolean.FALSE)
        .set("order401", Boolean.FALSE)
        .set("recExpired", Boolean.FALSE)
        .set("recSession", Boolean.FALSE);
  }

  private static ChainBuilder clearOp() {
    return exec(s -> s.remove("opBody").remove("etagTmp"));
  }

  private static Session verifyLink(Session s) {
    Object root = Json.parse(bodyOf(s, "opBody"));
    if (root == null) return s;
    boolean ok = true;
    Object vid = findKey(root, "variant_id");
    Object pid = findKey(root, "product_id");
    Map<String, Object> m = asMap(root);
    Object cid = m == null ? null : m.get("id");
    if (vid != null && s.contains("variantId") && !String.valueOf(vid).equals(s.getString("variantId"))) ok = false;
    if (pid != null && s.contains("productId") && !String.valueOf(pid).equals(s.getString("productId"))) ok = false;
    if (cid != null && s.contains("cartId") && !String.valueOf(cid).equals(s.getString("cartId"))) ok = false;
    if (!ok) return s.remove("etag").remove("cartIdJson");
    return s;
  }

  /* ---------------- login (fresh per journey, dynamic 302 followed once) ---------------- */

  private static ChainBuilder loginSequence() {
    return exec(s -> s.remove("loginLocation").remove("loginUrl").remove("formBody").remove("loginBody"))
        .exec(http("login-form").get("/v2/login-form")
            .check(status().is(200))
            .check(bodyString().saveAs("formBody")))
        .exec(s -> {
          String token = extractCsrf(bodyOf(s, "formBody"));
          return token == null ? s.remove("csrf") : s.set("csrf", token);
        })
        .exec(http("login").post("/v2/login")
            .header("Content-Type", "application/json")
            .body(StringBody("{\"username\":\"${username}\",\"password\":\"bench\",\"csrf\":\"${csrf}\"}"))
            .check(status().in(200, 302).saveAs("loginStatus"))
            .check(header("Location").optional().saveAs("loginLocation"))
            .check(bodyString().optional().saveAs("loginBody")))
        .exec(s -> {
          Session out = applyCsrf(s, "loginBody");
          int st = out.contains("loginStatus") ? out.getInt("loginStatus") : 0;
          String loc = out.contains("loginLocation") ? out.getString("loginLocation") : null;
          boolean follow = st == 302 && loc != null && !loc.isEmpty();
          out = out.set("followLogin", Boolean.valueOf(follow));
          if (follow) out = out.set("loginUrl", absolutize(loc));
          return out;
        })
        .doIf("${followLogin}").then(
            exec(http("login-redirect").get("${loginUrl}")
                .check(status().is(200))
                .check(bodyString().optional().saveAs("loginBody")))
                .exec(s -> applyCsrf(s, "loginBody")));
  }

  /* ---------------- bounded 401 recovery ---------------- */

  private static ChainBuilder recovery() {
    return doIf("${recExpired}").then(
        exec(http("session-renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "${csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 201, 202, 204))
            .check(bodyString().optional().saveAs("renewBody")))
            .exec(s -> applyCsrf(s, "renewBody")))
        .doIf("${recSession}").then(loginSequence())
        .doIf("${hasCart}").then(
            exec(http("cart-recover").post("/v2/carts/${cartId}/recover")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "${csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 201, 202, 204))
                .check(header("ETag").optional().saveAs("recoverEtag"))
                .check(bodyString().optional().saveAs("recoverBody")))
                .exec(s -> {
                  Session out = applyCsrf(s, "recoverBody");
                  if (out.contains("recoverEtag")) out = out.set("etag", out.getString("recoverEtag"));
                  return out;
                }));
  }

  /* ---------------- catalog ---------------- */

  private static ChainBuilder catalogSelection() {
    return exec(http("catalog").get("/v2/catalog")
        .check(status().is(200))
        .check(bodyString().saveAs("catBody")))
        .exec(s -> selectProduct(s))
        .repeat(3).on(
            doIf("${needPages}").then(
                exec(http("catalog-page").get("${nextUrl}")
                    .check(status().is(200))
                    .check(bodyString().saveAs("catBody")))
                    .exec(s -> selectProduct(s))));
  }

  /* ---------------- cart create ---------------- */

  private static Session afterCart(Session s) {
    Session out = applyCsrf(s, "opBody");
    int st = out.contains("cartStatus") ? out.getInt("cartStatus") : 0;
    out = out.set("recExpired", Boolean.FALSE).set("recSession", Boolean.FALSE);
    boolean retry = false;
    if (st == 201) {
      Map<String, Object> m = asMap(Json.parse(bodyOf(out, "opBody")));
      Object id = m == null ? null : m.get("id");
      if (id != null) {
        out = out.set("cartId", str(id)).set("cartIdJson", lit(id)).set("hasCart", Boolean.TRUE);
      }
      if (out.contains("etagTmp")) out = out.set("etag", out.getString("etagTmp"));
    } else if (st == 401) {
      retry = true;
      String kind = errorKind(bodyOf(out, "opBody"));
      out = out.set("recExpired", Boolean.valueOf("expired".equals(kind)))
          .set("recSession", Boolean.valueOf("session".equals(kind)));
    }
    return out.set("cartRetry", Boolean.valueOf(retry));
  }

  private static ChainBuilder cartCreate() {
    return clearOp()
        .exec(http("cart-create").post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "${csrf}")
            .body(StringBody("{\"product_id\":${productIdJson},\"variant_id\":${variantIdJson}}"))
            .check(status().in(201, 401).saveAs("cartStatus"))
            .check(header("ETag").optional().saveAs("etagTmp"))
            .check(bodyString().optional().saveAs("opBody")))
        .exec(s -> afterCart(s))
        .doIf("${cartRetry}").then(
            recovery()
                .exec(clearOp())
                .exec(http("cart-create").post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "${csrf}")
                    .body(StringBody("{\"product_id\":${productIdJson},\"variant_id\":${variantIdJson}}"))
                    .check(status().is(201).saveAs("cartStatus"))
                    .check(header("ETag").optional().saveAs("etagTmp"))
                    .check(bodyString().optional().saveAs("opBody")))
                .exec(s -> afterCart(s)));
  }

  /* ---------------- cart read ---------------- */

  private static Session afterRead(Session s) {
    Session out = applyCsrf(s, "opBody");
    if (out.contains("etagTmp")) out = out.set("etag", out.getString("etagTmp"));
    out = verifyLink(out);
