                    .body(StringBody("{\"product_id\":${productIdJson},\"variant_id\":${variantIdJson}}"))
                    .check(status().is(201).saveAs("cartStatus"))
                    .check(header("ETag").optional().saveAs("etagTmp"))
                    .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
                .exec(s -> afterCart(s))));
  }

  private static Session afterRead(Session s) {
    Session out = verifyLink(keepEtag(applyCsrf(s)));
    int st = out.contains("opStatus") ? out.getInt("opStatus") : 0;
    boolean retry = st == 401;
    String kind = retry ? errorKind(out) : "";
    return out.set("readRetry", Boolean.valueOf(retry))
        .set("recExpired", Boolean.valueOf("expired".equals(kind)))
        .set("recSession", Boolean.valueOf("session".equals(kind)));
  }

  private static ChainBuilder cartRead() {
    return exec(s -> clearOp(s))
        .exec(http("cart-read").get("/v2/carts/${cartId}")
            .check(status().in(200, 401).saveAs("opStatus"))
            .check(header("ETag").optional().saveAs("etagTmp"))
            .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
        .exec(s -> afterRead(s))
        .exec(doIf(s -> flag(s, "readRetry")).then(
            recovery()
                .exec(s -> clearOp(s))
                .exec(http("cart-read").get("/v2/carts/${cartId}")
                    .check(status().is(200).saveAs("opStatus"))
                    .check(header("ETag").optional().saveAs("etagTmp"))
                    .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
                .exec(s -> afterRead(s))));
  }

  private static ChainBuilder refreshEtag() {
    return exec(s -> clearOp(s))
        .exec(http("cart-etag").get("/v2/carts/${cartId}")
            .check(status().is(200))
            .check(header("ETag").saveAs("etag"))
            .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
        .exec(s -> verifyLink(applyCsrf(s)));
  }

  /* ---------- quantity patch with If-Match, one bounded retry ---------- */

  private static Session afterPatch(Session s) {
    Session out = keepEtag(applyCsrf(s));
    int st = out.contains("opStatus") ? out.getInt("opStatus") : 0;
    boolean is401 = st == 401;
    boolean is412 = st == 412;
    String kind = is401 ? errorKind(out) : "";
    return out.set("patch401", Boolean.valueOf(is401))
        .set("patchReread", Boolean.valueOf(is401 || is412))
        .set("patchRetry", Boolean.valueOf(is401 || is412))
        .set("recExpired", Boolean.valueOf("expired".equals(kind)))
        .set("recSession", Boolean.valueOf("session".equals(kind)));
  }

  private static ChainBuilder cartPatch() {
    return exec(s -> clearOp(s))
        .exec(http("cart-patch").patch("/v2/carts/${cartId}")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "${csrf}")
            .header("If-Match", "${etag}")
            .body(StringBody("{\"quantity\":2}"))
            .check(status().in(200, 201, 202, 204, 401, 412).saveAs("opStatus"))
            .check(header("ETag").optional().saveAs("etagTmp"))
            .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
        .exec(s -> afterPatch(s))
        .exec(doIf(s -> flag(s, "patch401")).then(recovery()))
        .exec(doIf(s -> flag(s, "patchReread")).then(refreshEtag()))
        .exec(doIf(s -> flag(s, "patchRetry")).then(
            exec(s -> clearOp(s))
                .exec(http("cart-patch").patch("/v2/carts/${cartId}")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "${csrf}")
                    .header("If-Match", "${etag}")
                    .body(StringBody("{\"quantity\":2}"))
                    .check(status().in(200, 201, 202, 204).saveAs("opStatus"))
                    .check(header("ETag").optional().saveAs("etagTmp"))
                    .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
                .exec(s -> afterPatch(s))));
  }

  /* ---------- exactly one committed order per journey, stable idempotency key ---------- */

  private static Session afterOrder(Session s) {
    Session out = applyCsrf(s);
    int st = out.contains("opStatus") ? out.getInt("opStatus") : 0;
    Map<String, Object> m = root(out);
    boolean accepted = m != null && truthy(m.get("accepted"));
    boolean is401 = st == 401;
    boolean is412 = st == 412;
    boolean committed = st == 201 && accepted;
    if (committed && m.get("id") != null) out = out.set("orderId", str(m.get("id")));
    String kind = is401 ? errorKind(out) : "";
    boolean retry = is401 || is412 || (st == 201 && !accepted);
    return out.set("order401", Boolean.valueOf(is401))
        .set("orderRefresh", Boolean.valueOf(is401 || is412))
        .set("orderRetry", Boolean.valueOf(retry))
        .set("recExpired", Boolean.valueOf("expired".equals(kind)))
        .set("recSession", Boolean.valueOf("session".equals(kind)));
  }

  private static ChainBuilder orderCommit() {
    return exec(s -> s.set("orderKey", "order-" + s.getString("cartId")))
        .exec(s -> clearOp(s))
        .exec(http("order-commit").post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "${csrf}")
            .header("Idempotency-Key", "${orderKey}")
            .header("If-Match", "${etag}")
            .body(StringBody("{\"cart_id\":${cartIdJson}}"))
            .check(status().in(201, 401, 412).saveAs("opStatus"))
            .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
        .exec(s -> afterOrder(s))
        .exec(doIf(s -> flag(s, "order401")).then(recovery()))
        .exec(doIf(s -> flag(s, "orderRefresh")).then(refreshEtag()))
        .exec(doIf(s -> flag(s, "orderRetry")).then(
            exec(s -> clearOp(s))
                .exec(http("order-commit").post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "${csrf}")
                    .header("Idempotency-Key", "${orderKey}")
                    .header("If-Match", "${etag}")
                    .body(StringBody("{\"cart_id\":${cartIdJson}}"))
                    .check(status().is(201).saveAs("opStatus"))
                    .check(jsonPath("$.accepted").ofBoolean().is(true))
                    .check(jsonPath("$").ofMap().optional().saveAs("opRoot")))
                .exec(s -> afterOrder(s))));
  }

  private static ChainBuilder journey() {
    return exec(s -> resetJourney(s))
        .exec(loginSequence())
        .exec(exitHereIfFailed())
        .exec(catalogSelection())
        .exec(exitHereIfFailed())
        .exec(cartCreate())
        .exec(exitHereIfFailed())
        .exec(cartRead())
        .exec(exitHereIfFailed())
        .exec(cartPatch())
        .exec(exitHereIfFailed())
        .exec(orderCommit())
        .exec(exitHereIfFailed());
  }

  {
    HttpProtocolBuilder protocol = http()
        .baseUrl(BASE_URL)
        .disableFollowRedirect()
        .disableCaching()
        .disableWarmUp()
        .acceptHeader("*/*")
        .userAgentHeader("gatling-model-simulation");

    ScenarioBuilder scn = scenario("in-stock-parent-variant-checkout")
        .exec(s -> resetJourney(s)
            .set("username", "bench-" + ((OWNER.getAndIncrement() % 16) + 1)))
        .exec(repeat(ITERATIONS).on(journey()));

    setUp(scn.injectOpen(atOnceUsers(USERS)))
        .protocols(protocol)
        .assertions(
            global().failedRequests().count().is(0L),
            details("order-commit").successfulRequests().count().gte((long) USERS * ITERATIONS));
  }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Counter } from 'k6/metrics';

/* k6 1.0.0 — nested catalog: pick an in-stock parent, use that parent's own variant id.
   Flow per journey: fresh login -> catalog -> one cart -> ETag PATCH -> reservation -> one order. */

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const PAGE_LIMIT = 3;
const QUANTITY = 2;
const POLL_LIMIT = 5;
const POLL_GAP_S = 0.06;

export const options = {
  scenarios: {
    purchase_flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '180s',
      gracefulStop: '5s'
    }
  },
  discardResponseBodies: false
};

const journeySuccess = new Rate('journey_success');
const ordersAccepted = new Counter('orders_accepted');

/* per-VU state (each VU owns its runtime, cookie jar and session) */
const S = { csrf: null, username: null, cartId: null, cartEtag: null };

/* ---------------------------------------------------------------- helpers */

function fakeRes() { return { status: 0, body: null, headers: {} }; }

function jparse(res) {
  if (!res || typeof res.body !== 'string') return null;
  const t = res.body.trim();
  if (t.length === 0) return null;
  const c = t.charAt(0);
  if (c !== '{' && c !== '[') return null;
  try { return JSON.parse(t); } catch (e) { return null; }
}

function pick(b, k) {
  if (!b || typeof b !== 'object') return undefined;
  if (b[k] !== undefined) return b[k];
  if (b.data && typeof b.data === 'object' && b.data[k] !== undefined) return b.data[k];
  return undefined;
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const want = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) {
      const v = res.headers[keys[i]];
      if (v === undefined || v === null) return null;
      return typeof v === 'string' ? v : String(v);
    }
  }
  return null;
}

function captureCsrf(res) {
  const t = pick(jparse(res), 'csrf');
  if (typeof t === 'string' && t.length > 0) S.csrf = t; /* retain previous when absent */
}

function errorOf(res) {
  const e = pick(jparse(res), 'error');
  return typeof e === 'string' ? e : '';
}

function resolveUrl(baseUrl, rel) {
  if (typeof rel !== 'string' || rel.length === 0) return null;
  if (/^https?:\/\//i.test(rel)) return rel.indexOf(BASE) === 0 ? rel : null;
  if (rel.charAt(0) === '/') return BASE + rel;
  const clean = baseUrl.split('?')[0].split('#')[0];
  if (rel.charAt(0) === '?') return clean + rel;
  const dir = clean.substring(0, clean.lastIndexOf('/') + 1);
  return dir + rel;
}

function toUrl(p) {
  if (typeof p !== 'string' || p.length === 0) return null;
  if (/^https?:\/\//i.test(p)) return p.indexOf(BASE) === 0 ? p : null;
  return BASE + (p.charAt(0) === '/' ? p : '/' + p);
}

function reqName(method, url) {
  let p = url;
  if (p.indexOf(BASE) === 0) p = p.substring(BASE.length);
  p = p.split('?')[0];
  p = p.replace(/\/v2\/carts\/[^\/]+/, '/v2/carts/{id}');
  p = p.replace(/\/v2\/reservations\/[^\/]+/, '/v2/reservations/{id}');
  p = p.replace(/\/v2\/challenges\/[^\/]+/, '/v2/challenges/{id}');
  return method + ' ' + p;
}

function rawHttp(method, url, body, extra) {
  const h = { Accept: 'application/json, text/html;q=0.9, */*;q=0.8' };
  let payload = null;
  if (body !== null && body !== undefined) {
    payload = JSON.stringify(body);
    h['Content-Type'] = 'application/json';
  }
  if (method !== 'GET' && method !== 'HEAD' && S.csrf) h['X-CSRF-Token'] = S.csrf;
  if (extra) {
    const keys = Object.keys(extra);
    for (let i = 0; i < keys.length; i++) {
      const v = extra[keys[i]];
      if (v !== null && v !== undefined) h[keys[i]] = v;
    }
  }
  const params = { headers: h, redirects: 0, timeout: '30s', tags: { name: reqName(method, url) } };
  try { return http.request(method, url, payload, params); } catch (e) { return fakeRes(); }
}

/* ------------------------------------------------------- HTML csrf parsing */

const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };

function decodeEntities(s) {
  if (!s) return '';
  return s.replace(/&(#\d+|#[xX][0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);/g, function (m, e) {
    if (e.charAt(0) === '#') {
      const code = (e.charAt(1) === 'x' || e.charAt(1) === 'X')
        ? parseInt(e.substring(2), 16) : parseInt(e.substring(1), 10);
      return isNaN(code) ? m : String.fromCharCode(code);
    }
    return Object.prototype.hasOwnProperty.call(ENT, e) ? ENT[e] : m;
  });
}

function parseAttrs(s) {
  const out = {};
  if (!s) return out;
  const re = /([A-Za-z_:][A-Za-z0-9_:.\-]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))|([A-Za-z_:][A-Za-z0-9_:.\-]*)/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    if (m[1] !== undefined) {
      let v = m[2];
      if (v === undefined) v = m[3];
      if (v === undefined) v = m[4];
      out[m[1].toLowerCase()] = decodeEntities(v === undefined ? '' : v);
    } else if (m[5] !== undefined) {
      out[m[5].toLowerCase()] = '';
    }
    if (m.index === re.lastIndex) re.lastIndex++;
  }
  return out;
}

function csrfFromInputs(segment, loginFormId) {
  const re = /<input\b((?:[^>"']|"[^"]*"|'[^']*')*)\/?>/gi;
  const cands = [];
  let m;
  while ((m = re.exec(segment)) !== null) {
    const a = parseAttrs(m[1]);
    if ((a.name || '') !== 'csrf') continue;             /* exact name, decoys excluded */
    if (a.disabled !== undefined) continue;
    if (a['data-decoy'] !== undefined) continue;
    if (loginFormId && a.form && a.form !== loginFormId) continue;
    const type = (a.type || 'text').toLowerCase();
    if (type === 'submit' || type === 'button' || type === 'checkbox' || type === 'radio') continue;
    const v = a.value;
    if (typeof v !== 'string' || v.length === 0) continue;
    cands.push({ v: v, hidden: type === 'hidden' ? 1 : 0 });
  }
  if (cands.length === 0) return null;
  cands.sort(function (x, y) { return y.hidden - x.hidden; });
  return cands[0].v;
}

function extractCsrf(html) {
  if (typeof html !== 'string' || html.length === 0) return null;
  const segments = [];
  let loginFormId = null;
  const formRe = /<form\b((?:[^>"']|"[^"]*"|'[^']*')*)>([\s\S]*?)<\/form>/gi;
  let m;
  while ((m = formRe.exec(html)) !== null) {
    const a = parseAttrs(m[1]);
    const action = a.action || '';
    if (action.indexOf('/v2/login') >= 0 || /login/i.test(action)) {
      if (a.id) loginFormId = a.id;
      segments.push({ body: m[2], id: a.id || null });
    }
  }
  for (let i = 0; i < segments.length; i++) {
    const t = csrfFromInputs(segments[i].body, segments[i].id);
    if (t) return t;
  }
  return csrfFromInputs(html, loginFormId);
}

/* ------------------------------------------------------------- auth / http */

function login(username) {
  S.username = username;
  const formRes = rawHttp('GET', BASE + '/v2/login-form', null, null);
  check(formRes.status, { 'login-form: 200': function (s) { return s === 200; } });
  const token = extractCsrf(formRes.body);
  const hasToken = typeof token === 'string' && token.length > 0;
  check(hasToken, { 'login-form: csrf input parsed': function (v) { return v === true; } });
  if (!hasToken) return false;
  S.csrf = token;
  let res = rawHttp('POST', BASE + '/v2/login',
    { username: username, password: PASSWORD, csrf: token }, null);
  if (res.status >= 300 && res.status < 400) {
    const loc = header(res, 'Location');
    const url = loc ? resolveUrl(BASE + '/v2/login', loc) : null;
    check(!!url, { 'login: dynamic Location resolved': function (v) { return v === true; } });
    if (!url) return false;
    res = rawHttp('GET', url, null, null); /* followed exactly once */
  }
  captureCsrf(res);
  const b = jparse(res);
  if (!b) {
    const t = extractCsrf(res.body);
    if (t) S.csrf = t;
  }
  const ok = res.status >= 200 && res.status < 300 && typeof S.csrf === 'string' && S.csrf.length > 0;
  check(ok, { 'login: session established': function (v) { return v === true; } });
  return ok;
}

function postSimple(url) {
  const res = rawHttp('POST', url, {}, null);
  captureCsrf(res);
  const et = header(res, 'ETag');
  if (et && url.indexOf('/v2/carts/') >= 0) S.cartEtag = et;
  return res.status >= 200 && res.status < 300;
}

function recoverSession(err) {
  let renewed = false;
  if (err !== 'session') renewed = postSimple(BASE + '/v2/session/renew');
  if (!renewed && !login(S.username)) return false;   /* revoked or renew failed -> fresh form/login */
  if (S.cartId) postSimple(cartUrl() + '/recover');
  return true;
}

function apiCall(method, url, body, opts) {
  opts = opts || {};
  const target = toUrl(url);
  if (!target) return fakeRes();
  let authRetry = false;
  let rateTries = 0;
  for (;;) {
    const extra = typeof opts.headers === 'function' ? opts.headers() : opts.headers;
    const res = rawHttp(method, target, body, extra);
    captureCsrf(res);
    if (res.status === 429 && rateTries < 4) {
      rateTries++;
      let ra = parseFloat(header(res, 'Retry-After'));
      if (!isFinite(ra) || ra < 1) ra = 1;
      sleep(ra);
      continue;
    }
    if (res.status === 401 && !authRetry) {
      authRetry = true;
      const err = errorOf(res);
      if (err === 'denied') {
        check(res.status, { 'auth: 401 denied is a failure, not expiry': function (s) { return s !== 401; } });
        return res;
      }
      if (!recoverSession(err)) return res;
      continue; /* retry only the interrupted operation, once */
    }
    return res;
  }
}

/* ---------------------------------------------------------- catalog select */

function isInStock(v) {
  return !!v && (v.in_stock === true || v.in_stock === 1 || v.in_stock === 'true');
}

function variantsOf(p) {
  if (!p || typeof p !== 'object') return [];
  let v = p.variants;
  if (!v && p.data && p.data.variants) v = p.data.variants;
  if (Array.isArray(v)) return v;
  if (v && typeof v === 'object' && Array.isArray(v.items)) return v.items;
  return [];
}

function collectArray(out, arr) {
  for (let i = 0; i < arr.length; i++) {
    const p = arr[i];
    if (p && typeof p === 'object' && p.id !== undefined) out.push(p);
  }
}

function extractProducts(body) {
  const out = [];
  const roots = [];
  if (body && typeof body === 'object') {
    roots.push(body);
    if (body.data && typeof body.data === 'object') roots.push(body.data);
  }
  for (let i = 0; i < roots.length; i++) {
    const r = roots[i];
    if (Array.isArray(r)) { collectArray(out, r); continue; }
    if (Array.isArray(r.products)) collectArray(out, r.products);
    if (Array.isArray(r.items)) collectArray(out, r.items);
    if (r.product && typeof r.product === 'object' && r.product.id !== undefined) out.push(r.product);
    if (r.id !== undefined && r.variants !== undefined) out.push(r);
  }
  return out;
}

function addProducts(list, incoming) {
  for (let i = 0; i < incoming.length; i++) {
    const p = incoming[i];
    if (!p || p.id === undefined) continue;
    let existing = null;
    for (let j = 0; j < list.length; j++) {
      if (String(list[j].id) === String(p.id)) { existing = list[j]; break; }
    }
    const vs = variantsOf(p);
    if (!existing) {
      const copy = [];
      for (let k = 0; k < vs.length; k++) if (vs[k] && vs[k].id !== undefined) copy.push(vs[k]);
      list.push({ id: p.id, variants: copy });
      continue;
    }
    for (let k = 0; k < vs.length; k++) {
      const v = vs[k];
      if (!v || v.id === undefined) continue;
      let found = false;
      for (let j = 0; j < existing.variants.length; j++) {
        if (String(existing.variants[j].id) === String(v.id)) {
          if (isInStock(v) && !isInStock(existing.variants[j])) existing.variants[j] = v;
          found = true;
          break;
        }
      }
      if (!found) existing.variants.push(v);
    }
  }
}

function hasEligible(products) {
  for (let i = 0; i < products.length; i++) {
    const vs = variantsOf(products[i]);
    for (let j = 0; j < vs.length; j++) if (isInStock(vs[j])) return true;
  }
  return false;
}

function loadCatalog() {
  const products = [];
  const res = apiCall('GET', BASE + '/v2/catalog', null, null);
  check(res.status, { 'catalog: 200': function (s) { return s === 200; } });
  const body = jparse(res);
  addProducts(products, extractProducts(body));
  if (!hasEligible(products)) {
    const next = pick(body, 'next');
    let url = next ? resolveUrl(BASE + '/v2/catalog', next) : BASE + '/v2/catalog/page';
    for (let i = 0; i < PAGE_LIMIT && url; i++) {
      const r = apiCall('GET', url, null, null);
      const b = jparse(r);
      addProducts(products, extractProducts(b));
      const n = pick(b, 'next');
      url = n ? resolveUrl(url, n) : null;   /* never guessed cursors */
    }
  }
  return products;
}

function cmpId(a, b) {
  const x = String(a), y = String(b);
  return x < y ? -1 : (x > y ? 1 : 0);
}

/* order-independent selection: stable across reversed / reordered records */
function selectTarget(products) {
  const eligible = [];
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const vs = variantsOf(p).filter(isInStock);
    if (vs.length > 0) eligible.push({ p: p, vs: vs });
  }
  if (eligible.length === 0) return null;
  eligible.sort(function (a, b) { return cmpId(a.p.id, b.p.id); });
  const chosen = eligible[0];
  const vs = chosen.vs.slice(0).sort(function (a, b) { return cmpId(a.id, b.id); });
  return { productId: chosen.p.id, variantId: vs[0].id };
}

function parentLink(products, target) {
  for (let i = 0; i < products.length; i++) {
    if (String(products[i].id) !== String(target.productId)) continue;
    const vs = variantsOf(products[i]);
    for (let j = 0; j < vs.length; j++) {
      if (String(vs[j].id) === String(target.variantId) && isInStock(vs[j])) return true;
    }
  }
  return false;
}

/* --------------------------------------------------------------- checkout */

function cartUrl() { return BASE + '/v2/carts/' + encodeURIComponent(String(S.cartId)); }
function ifMatch() { return { 'If-Match': S.cartEtag ? S.cartEtag : '*' }; }

function createCart(target) {
  const res = apiCall('POST', BASE + '/v2/carts',
    { product_id: target.productId, variant_id: target.variantId }, null);
  const b = jparse(res);
  const id = pick(b, 'id');
  const created = res.status === 201 && id !== undefined && id !== null && String(id).length > 0;
  check(created, { 'cart: 201 created with id': function (v) { return v === true; } });
  if (!created) return false;
  S.cartId = id;
  const et = header(res, 'ETag');
  if (et) S.cartEtag = et;
  const pid = pick(b, 'product_id');
  const vid = pick(b, 'variant_id');
  if (pid !== undefined && vid !== undefined) {
    const linked = String(pid) === String(target.productId) && String(vid) === String(target.variantId);
