# Locust 2.47 flow locustfile: select an in-stock parent product from nested JSON
# and check out exactly one cart using that parent's own (parent-specific) variant.
# Contract: 2 users x 2 iterations (journeys) = 4 committed orders, no extra carts.

import itertools
import json
import os
import re
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

import gevent
from locust import HttpUser, LoadTestShape, between, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
BASE_PARTS = urlsplit(BASE_URL)

USERS = 2
ITERATIONS_PER_USER = 2
TOTAL_JOURNEYS = USERS * ITERATIONS_PER_USER
MAX_PAGES = 3
MAX_429_RETRIES = 4
SHAPE_DEADLINE_S = 240.0

_claims = 0
_finished = 0
_retired = 0
_shape_start = None
_account_seq = itertools.count(1)


def _claim():
    global _claims
    if _claims >= TOTAL_JOURNEYS:
        return False
    _claims += 1
    return True


def _finish():
    global _finished
    _finished += 1


def _retire():
    global _retired
    _retired += 1


def _next_account():
    n = next(_account_seq)
    return "bench-%d" % (((n - 1) % 16) + 1)


def _truthy(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value > 0
    if isinstance(value, str):
        return value.strip().lower() in ("true", "1", "yes", "y", "in_stock", "available")
    return False


def _json_body(resp):
    try:
        text = resp.text
    except Exception:
        return None
    if not text:
        return None
    try:
        return json.loads(text)
    except Exception:
        return None


def _retry_after(resp):
    raw = resp.headers.get("Retry-After")
    try:
        wait = float(raw)
    except (TypeError, ValueError):
        wait = 1.0
    if wait < 1.0:
        wait = 1.0
    if wait > 5.0:
        wait = 5.0
    return wait


# ---------------------------------------------------------------- HTML parsing
class _FormParser(HTMLParser):
    """Attribute-order agnostic <input> collector (decoys kept, scored later)."""

    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.inputs = []
        self._forms = []

    def _attrs(self, attrs):
        seen = {}
        for key, value in attrs:
            if not key:
                continue
            key = key.lower()
            if key not in seen:
                seen[key] = value if value is not None else ""
        return seen

    def handle_starttag(self, tag, attrs):
        data = self._attrs(attrs)
        if tag == "form":
            self._forms.append(data.get("action", "") or "")
        elif tag == "input":
            self.inputs.append((data, self._forms[-1] if self._forms else ""))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag == "form" and self._forms:
            self._forms.pop()


_INPUT_RE = re.compile(r"<input\b[^>]*>", re.I)
_ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'=<>`]+))"""
)


def extract_csrf(text):
    if not text:
        return None
    if text.lstrip().startswith("{"):
        try:
            payload = json.loads(text)
        except Exception:
            payload = None
        if isinstance(payload, dict):
            token = payload.get("csrf")
            if isinstance(token, str) and token:
                return token

    parser = _FormParser()
    try:
        parser.feed(text)
        parser.close()
    except Exception:
        pass

    best = None
    best_score = None
    for attrs, action in parser.inputs:
        if (attrs.get("name") or "").strip().lower() != "csrf":
            continue
        value = attrs.get("value") or ""
        if not value:
            continue
        score = 0
        if "/v2/login" in (action or ""):
            score += 8
        if (attrs.get("type") or "hidden").lower() == "hidden":
            score += 2
        blob = " ".join(
            [attrs.get("id", ""), attrs.get("class", ""), attrs.get("data-role", ""), value]
        ).lower()
        if "decoy" in blob or "fake" in blob:
            score -= 16
        if "disabled" in attrs or "readonly" in attrs:
            score -= 8
        if any(k.startswith("data-decoy") for k in attrs):
            score -= 16
        if best_score is None or score > best_score:
            best, best_score = value, score
    if best:
        return best

    for tag in _INPUT_RE.findall(text):
        attrs = {}
        for match in _ATTR_RE.finditer(tag):
            key = match.group(1).lower()
            value = match.group(3) or match.group(4) or match.group(5) or ""
            attrs.setdefault(key, value)
        if attrs.get("name", "").lower() == "csrf" and attrs.get("value"):
            return attrs["value"]
    return None


# ------------------------------------------------------------- catalog helpers
def products_from(payload):
    out = []
    if not isinstance(payload, dict):
        return out
    containers = [payload]
    inner = payload.get("data")
    if isinstance(inner, dict):
        containers.append(inner)
    elif isinstance(inner, list):
        out.extend([p for p in inner if isinstance(p, dict)])
    for container in containers:
        items = container.get("products")
        if isinstance(items, list):
            out.extend([p for p in items if isinstance(p, dict)])
        single = container.get("product")
        if isinstance(single, dict):
            out.append(single)
        if "id" in container and "variants" in container:
            out.append(container)
    return out


def select_variant(products):
    """Deterministic, order-independent choice of an eligible parent + its own
    in-stock child variant. Never borrows a variant from another parent."""
    eligible = {}
    for product in products:
        if not isinstance(product, dict):
            continue
        pid = product.get("id")
        if pid is None:
            continue
        variants = product.get("variants")
        if isinstance(variants, dict):
            variants = [variants]
        if not isinstance(variants, list):
            continue
        choices = []
        for variant in variants:
            if not isinstance(variant, dict):
                continue
            vid = variant.get("id")
            if vid is None:
                continue
            owner = variant.get("product_id", variant.get("parent_id"))
            if owner is not None and str(owner) != str(pid):
                continue
            if not _truthy(variant.get("in_stock")):
                continue
            choices.append((str(vid), vid))
        if not choices:
            continue
        choices.sort(key=lambda item: item[0])
        key = str(pid)
        previous = eligible.get(key)
        if previous is None or choices[0][0] < str(previous[1]):
            eligible[key] = (pid, choices[0][1])
    if not eligible:
        return None
    first = sorted(eligible.keys())[0]
    return eligible[first]


def _gather_keys(node, key, out):
    if isinstance(node, dict):
        for k, v in node.items():
            if k == key and not isinstance(v, (dict, list)):
                out.append(v)
            else:
                _gather_keys(v, key, out)
    elif isinstance(node, list):
        for item in node:
            _gather_keys(item, key, out)


def body_links(data, product_id, variant_id, cart_id=None):
    if not isinstance(data, (dict, list)):
        return True
    for key, expected in (("product_id", product_id), ("variant_id", variant_id), ("cart_id", cart_id)):
        if expected is None:
            continue
        found = []
        _gather_keys(data, key, found)
        if found and not any(str(v) == str(expected) for v in found):
            return False
    return True


class _Result(object):
    __slots__ = ("status", "data", "headers", "ok")

    def __init__(self, status, data, headers, ok):
        self.status = status
        self.data = data
        self.headers = headers
        self.ok = ok


def _order_validator(status, data):
    if status not in (200, 201):
        return False, "order unexpected status %s" % status
    if not isinstance(data, dict):
        return False, "order body is not JSON"
    if not _truthy(data.get("accepted")):
        return False, "order accepted:false (business failure)"
    if not data.get("id"):
        return False, "order missing id"
    return True, ""


# ------------------------------------------------------------------- the user
class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0.05, 0.20)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.account = _next_account()
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.order_id = None
        self._retired = False

    # -------------------------------------------------------------- plumbing
    def _resolve(self, link, base_path):
        if not link or not isinstance(link, str):
            return None
        absolute = urljoin(BASE_URL + base_path, link.strip())
        parts = urlsplit(absolute)
        if parts.scheme not in ("http", "https"):
            return None
        if parts.netloc != BASE_PARTS.netloc:
            return None
        path = parts.path or "/"
        if parts.query:
            path += "?" + parts.query
        return path

    def _evaluate(self, status, data, expect, soft, validator, recoverable):
        error = data.get("error") if isinstance(data, dict) else None
        if status == 401:
            if recoverable and error in ("expired", "session"):
                return True, ""  # expected, bounded recovery happens in caller
            return False, "401 error=%s" % (error,)
        if status in soft:
            return True, ""
        if validator is not None:
            return validator(status, data)
        if status not in expect:
            return False, "unexpected status %s" % status
        return True, ""

    def _api(self, method, path, name, json_body=None, headers=None, expect=(200,),
             soft=(), validator=None, recoverable=False, retry_429=False):
        attempt = 0
        ok = False
        while True:
            hdrs = {"Accept": "application/json"}
            if method != "GET" and self.csrf:
                hdrs["X-CSRF-Token"] = self.csrf
            if headers:
                hdrs.update(headers)
            delay = None
            with self.client.request(
                method, path, name=name, json=json_body, headers=hdrs,
                allow_redirects=False, catch_response=True, timeout=20,
            ) as resp:
                status = resp.status_code
                data = _json_body(resp)
                rheaders = resp.headers
                if status == 429 and retry_429 and attempt < MAX_429_RETRIES:
                    resp.success()  # scheduled backpressure, not a failure
                    delay = _retry_after(resp)
                else:
                    ok, why = self._evaluate(status, data, expect, soft, validator, recoverable)
                    if ok:
                        resp.success()
                    else:
                        resp.failure(why)
            if delay is None:
                return _Result(status, data, rheaders, ok)
            attempt += 1
            gevent.sleep(delay)

    def _absorb(self, result):
        if isinstance(result.data, dict):
            token = result.data.get("csrf")
            if isinstance(token, str) and token:
                self.csrf = token  # retain previous token when absent
        etag = result.headers.get("ETag")
        if etag:
            self.cart_etag = etag

    def _fail_assert(self, name, message):
        with self.client.get("/v2/catalog", name=name, catch_response=True,
                             allow_redirects=False, timeout=20) as resp:
            resp.failure(message)

    # ----------------------------------------------------------------- login
    def _login(self):
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True, timeout=20) as resp:
            text = resp.text or ""
            token = extract_csrf(text)
            if resp.status_code != 200 or not token:
                resp.failure("login-form status=%s csrf_found=%s" % (resp.status_code, bool(token)))
                return False
            resp.success()

        body = {"username": self.account, "password": "bench", "csrf": token}
        with self.client.post("/v2/login", json=body, name="POST /v2/login",
                              allow_redirects=False, catch_response=True, timeout=20) as resp:
            status = resp.status_code
            data = _json_body(resp)
            location = resp.headers.get("Location")
            if status in (301, 302, 303, 307, 308):
                if not location:
                    resp.failure("login redirect without Location")
                    return False
                resp.success()
            elif status == 200 and isinstance(data, dict):
                self.csrf = data.get("csrf") or token
                resp.success()
                return True
            else:
                resp.failure("login failed status=%s" % status)
                return False

        target = self._resolve(location, "/v2/login")
        if not target:
            self._fail_assert("GET /v2/login (redirect)", "login Location off-target/absent")
            return False
        with self.client.get(target, name="GET /v2/login (redirect)", allow_redirects=False,
                             catch_response=True, timeout=20) as resp:
            data = _json_body(resp)
            if resp.status_code == 200:
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                else:
                    self.csrf = self.csrf or token
                resp.success()
                return True
            resp.failure("login redirect status=%s" % resp.status_code)
            return False

    def _renew(self):
        res = self._api("POST", "/v2/session/renew", "POST /v2/session/renew",
                        json_body={}, expect=(200,))
        if res.ok:
            self._absorb(res)
        return res.ok

    def _recover_cart(self):
        if not self.cart_id:
            return True
        res = self._api("POST", "/v2/carts/%s/recover" % self.cart_id,
                        "POST /v2/carts/:id/recover", json_body={}, expect=(200,))
        if res.ok:
            self._absorb(res)
        return res.ok

    def _api_rec(self, method, path, name, json_body=None, headers=None, expect=(200,),
                 soft=(), validator=None, retry_429=False):
        """One bounded recovery + one retry of the interrupted operation only."""
        res = self._api(method, path, name, json_body=json_body, headers=headers,
                        expect=expect, soft=soft, validator=validator,
                        recoverable=True, retry_429=retry_429)
        if res.status != 401:
            return res
        error = res.data.get("error") if isinstance(res.data, dict) else None
        if error == "expired":
            if not self._renew():
                self._login()
        elif error == "session":
            self._login()
        else:
            return res  # denied (or unknown) already failed its assertion
        self._recover_cart()
        return self._api(method, path, name + " (retry)", json_body=json_body, headers=headers,
                         expect=expect, soft=(), validator=validator,
                         recoverable=False, retry_429=retry_429)

    # --------------------------------------------------------------- catalog
    def _catalog(self):
        products = []
        seen = set()
        res = self._api("GET", "/v2/catalog", "GET /v2/catalog",
                        expect=(200,), soft=(404,), retry_429=True)
        base = "/v2/catalog"
        pages = 0
        if res.ok and res.status == 200:
            products.extend(products_from(res.data))
            pages = 1
            nxt = res.data.get("next") if isinstance(res.data, dict) else None
            while nxt and pages < MAX_PAGES:
                url = self._resolve(nxt, base)
                if not url or url in seen:
                    break
                seen.add(url)
                res = self._api("GET", url, "GET /v2/catalog (next)",
                                expect=(200,), soft=(404,), retry_429=True)
                pages += 1
                if not res.ok or res.status != 200:
                    break
                products.extend(products_from(res.data))
                base = url
                nxt = res.data.get("next") if isinstance(res.data, dict) else None

        if select_variant(products) is None:
            url = "/v2/catalog/page"
            base = url
            seen = set()
            pages = 0
            while url and pages < MAX_PAGES:
                if url in seen:
                    break
                seen.add(url)
                res = self._api("GET", url, "GET /v2/catalog/page",
                                expect=(200,), soft=(404,), retry_429=True)
                pages += 1
                if not res.ok or res.status != 200:
                    break
                products.extend(products_from(res.data))
                nxt = res.data.get("next") if isinstance(res.data, dict) else None
                if not nxt:
                    break
                base = url
                url = self._resolve(nxt, base)
        return products

    # --------------------------------------------------------------- journey
    def _journey(self):
        self.client.cookies.clear()
        self.csrf = None
