            reread = self._api_rec("GET", cart_path, "GET /v2/carts/:id (412 re-read)",
                                   expect=(200,), validator=cart_read)
            if reread.ok:
                self._absorb(reread)
            headers = {"If-Match": self.cart_etag} if self.cart_etag else {}
            patched = self._api("PATCH", cart_path, "PATCH /v2/carts/:id (412 retry)",
                                json_body=payload, headers=headers, expect=(200,))
        if not patched.ok:
            return
        self._absorb(patched)

        if not self.cart_etag:
            reread = self._api_rec("GET", cart_path, "GET /v2/carts/:id (etag)",
                                   expect=(200,), validator=cart_read)
            if reread.ok:
                self._absorb(reread)

        idem = "%s-%s-%s" % (self.account, self.cart_id, uuid.uuid4().hex)
        order_body = {"cart_id": self.cart_id}

        def order_ok(status, data):
            ok, why = _order_validator(status, data)
            if not ok:
                return ok, why
            if not body_links(data, product_id, variant_id, self.cart_id):
                return False, "order lost cart/variant linkage"
            return True, ""

        headers = {"Idempotency-Key": idem}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        order = self._api_rec("POST", "/v2/orders", "POST /v2/orders", json_body=order_body,
                              headers=headers, expect=(201,), soft=(412,), validator=order_ok)
        if order.status == 412:
            reread = self._api_rec("GET", cart_path, "GET /v2/carts/:id (order 412)",
                                   expect=(200,), validator=cart_read)
            if reread.ok:
                self._absorb(reread)
            headers = {"Idempotency-Key": idem}  # stable key on retry
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag
            order = self._api("POST", "/v2/orders", "POST /v2/orders (412 retry)",
                              json_body=order_body, headers=headers,
                              expect=(201,), validator=order_ok)
        if not order.ok:
            return
        self._absorb(order)
        self.order_id = order.data.get("id")

    @task
    def flow(self):
        for _ in range(ITERATIONS_PER_USER):
            if not _claim():
                break
            try:
                self._journey()
            finally:
                _finish()
        if not self._retired:
            self._retired = True
            _retire()
        raise StopUser()


class FlowShape(LoadTestShape):
    """Exactly one shape: 2 users, stop when every journey is finished."""

    def tick(self):
        global _shape_start
        now = time.time()
        if _shape_start is None:
            _shape_start = now
        if _finished >= TOTAL_JOURNEYS or _retired >= USERS:
            return None
        if now - _shape_start > SHAPE_DEADLINE_S:
            return None
        target = USERS - _retired
        if target < 1:
            return None
        return (target, USERS)
