import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.util.UUID;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String BASE =
      (System.getenv("BASE_URL") == null || System.getenv("BASE_URL").trim().isEmpty())
          ? "http://127.0.0.1:8000"
          : System.getenv("BASE_URL").trim();

  private static final int USERS = 2;
  private static final int ITERATIONS = 2;
  private static final int MAX_PAGES = 3;

  private static final String CSRF_NAME = "\\sname\\s*=\\s*[\"']?csrf[\"']?(?=[\\s/>])";
  private static final String CSRF_VALUE = "\\svalue\\s*=\\s*[\"']?([^\"'\\s>]+)[\"']?";
  private static final String HIDDEN_LOOKAHEAD =
      "(?=[^>]*\\stype\\s*=\\s*[\"']?hidden[\"']?(?=[\\s/>]))";

  private static final String RE_HIDDEN_CSRF =
      "<input\\b(?=[^>]*" + CSRF_NAME + ")" + HIDDEN_LOOKAHEAD + "[^>]*?" + CSRF_VALUE;
  private static final String RE_NAME_FIRST =
      "<input\\b(?=[^>]*" + CSRF_NAME + ")[^>]*?" + CSRF_VALUE;
  private static final String RE_VALUE_FIRST =
      "<input\\b[^>]*?" + CSRF_VALUE + "[^>]*" + CSRF_NAME;

  private static Session clear(Session s, String... keys) {
    Session out = s;
    for (String k : keys) {
      out = out.remove(k);
    }
    return out;
  }

  private static String str(Session s, String key) {
    if (!s.contains(key)) {
      return null;
    }
    String v = s.getString(key);
    if (v == null) {
      return null;
    }
    v = v.trim();
    if (v.isEmpty() || "null".equals(v)) {
      return null;
    }
    return v;
  }

  private static String pick(Session s, String... keys) {
    for (String k : keys) {
      String v = str(s, k);
      if (v != null) {
        return v;
      }
    }
    return null;
  }

  private static Session keepCsrf(Session s, String key) {
    String v = str(s, key);
    return v == null ? s : s.set("csrf", v);
  }

  private static Session keepEtag(Session s, String key) {
    String v = str(s, key);
    return v == null ? s : s.set("cartEtag", v);
  }

  private static String jsonLiteral(String v) {
    if (v == null) {
      return "\"\"";
    }
    if (v.matches("-?\\d+")) {
      return v;
    }
    return "\"" + v.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
  }

  private static boolean orderOk(Session s) {
    return s.contains("orderStatus")
        && s.getInt("orderStatus") == 201
        && s.contains("orderAccepted")
        && s.getBoolean("orderAccepted")
        && str(s, "orderId") != null;
  }

  private final HttpProtocolBuilder protocol =
      http.baseUrl(BASE)
          .disableFollowRedirect()
          .disableCaching()
          .acceptHeader("application/json")
          .acceptLanguageHeader("en-US,en;q=0.5")
          .userAgentHeader("model-cursor-simulation");

  private final ScenarioBuilder journeys =
      scenario("pagination_cursor_journey")
          .repeat(ITERATIONS)
          .on(
              exec(s -> clear(
                      s,
                      "csrfFormH", "csrfFormA", "csrfFormB", "loginCsrf", "loginRespCsrf",
                      "loginRedirectCsrf", "loginLocation", "csrf",
                      "pageUrl", "pages", "found", "productId", "variantId",
                      "productIdJson", "variantIdJson",
                      "pIdA", "pIdB", "pIdC", "pIdD",
                      "vIdA", "vIdB", "vIdC", "vIdD", "vIdE", "nextUrl",
                      "cartId", "cartIdJson", "cartCsrf", "cartEtag", "readCartCsrf",
                      "patchStatus", "patchCsrf", "patchEtag", "patchRetryCsrf", "patchRetryEtag",
                      "orderStatus", "orderAccepted", "orderId", "orderCsrf", "orderError",
                      "orderOk", "idemKey", "orderRetryCsrf", "renewCsrf", "recoverCsrf")
                  .set("username", "bench-" + (int) (Math.floorMod(s.userId(), 16L) + 1L)))

                  // ---- fresh login for every journey ----
                  .exec(http("login_form")
                      .get("/v2/login-form")
                      .header("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8")
                      .check(status().is(200))
                      .check(regex(RE_HIDDEN_CSRF).optional().saveAs("csrfFormH"))
                      .check(regex(RE_NAME_FIRST).optional().saveAs("csrfFormA"))
                      .check(regex(RE_VALUE_FIRST).optional().saveAs("csrfFormB")))
                  .exec(s -> {
                    String token = pick(s, "csrfFormH", "csrfFormA", "csrfFormB");
                    String safe = token == null ? "" : token;
                    return s.set("loginCsrf", safe).set("csrf", safe);
                  })
                  .exec(http("login")
                      .post("/v2/login")
                      .header("Content-Type", "application/json")
                      .body(StringBody("{\"username\":\"${username}\",\"password\":\"bench\",\"csrf\":\"${loginCsrf}\"}"))
                      .check(status().in(200, 302))
                      .check(jsonPath("$.csrf").ofString().optional().saveAs("loginRespCsrf"))
                      .check(header("Location").optional().saveAs("loginLocation")))
                  .exec(s -> keepCsrf(s, "loginRespCsrf"))
                  .doIf(s -> str(s, "loginLocation") != null)
                  .then(
                      exec(http("login_redirect")
                          .get("${loginLocation}")
                          .check(status().is(200))
                          .check(jsonPath("$.csrf").ofString().optional().saveAs("loginRedirectCsrf")))
                          .exec(s -> keepCsrf(s, "loginRedirectCsrf")))
                  .exitHereIfFailed()

                  // ---- bounded cursor traversal: at most MAX_PAGES pages ----
                  .exec(s -> s.set("pageUrl", "/v2/catalog/page").set("pages", 0).set("found", false))
                  .asLongAs(s -> !s.getBoolean("found")
                      && str(s, "pageUrl") != null
                      && s.getInt("pages") < MAX_PAGES)
                  .on(
                      exec(s -> clear(s, "pIdA", "pIdB", "pIdC", "pIdD",
                              "vIdA", "vIdB", "vIdC", "vIdD", "vIdE", "nextUrl")
                          .set("pages", s.getInt("pages") + 1))
                          .exec(http("catalog_page")
                              .get("${pageUrl}")
                              .check(status().is(200))
                              .check(jsonPath("$.data.products[0].id").ofString().optional().saveAs("pIdA"))
                              .check(jsonPath("$.data.product.id").ofString().optional().saveAs("pIdB"))
                              .check(jsonPath("$.products[0].id").ofString().optional().saveAs("pIdC"))
                              .check(jsonPath("$.product.id").ofString().optional().saveAs("pIdD"))
                              .check(jsonPath("$.data.products[0].variants[?(@.in_stock == true)].id").ofString().optional().saveAs("vIdA"))
                              .check(jsonPath("$.data.product.variants[?(@.in_stock == true)].id").ofString().optional().saveAs("vIdB"))
                              .check(jsonPath("$.products[0].variants[?(@.in_stock == true)].id").ofString().optional().saveAs("vIdC"))
                              .check(jsonPath("$.product.variants[?(@.in_stock == true)].id").ofString().optional().saveAs("vIdD"))
                              .check(jsonPath("$.data.products[0].variants[?(@.in_stock)].id").ofString().optional().saveAs("vIdE"))
                              .check(jsonPath("$.next").ofString().optional().saveAs("nextUrl")))
                          .exec(s -> {
                            String pid = pick(s, "pIdA", "pIdB", "pIdC", "pIdD");
                            String vid = pick(s, "vIdA", "vIdB", "vIdC", "vIdD", "vIdE");
                            Session out = s;
                            if (pid != null && vid != null) {
                              out = out.set("found", true)
                                  .set("productId", pid)
                                  .set("variantId", vid)
                                  .set("productIdJson", jsonLiteral(pid))
                                  .set("variantIdJson", jsonLiteral(vid));
                            }
                            String next = str(s, "nextUrl");
                            return next == null ? out.remove("pageUrl") : out.set("pageUrl", next);
                          }))
                  .exec(s -> s.getBoolean("found")
                      ? s
                      : s.set("productIdJson", "\"\"").set("variantIdJson", "\"\""))
                  .exitHereIfFailed()

                  // ---- one fresh cart per journey ----
                  .exec(http("create_cart")
                      .post("/v2/carts")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "${csrf}")
                      .body(StringBody("{\"product_id\":${productIdJson},\"variant_id\":${variantIdJson}}"))
                      .check(status().is(201))
                      .check(jsonPath("$.id").ofString().saveAs("cartId"))
                      .check(jsonPath("$.csrf").ofString().optional().saveAs("cartCsrf"))
                      .check(header("ETag").optional().saveAs("cartEtag")))
                  .exitHereIfFailed()
                  .exec(s -> keepCsrf(s, "cartCsrf").set("cartIdJson", jsonLiteral(str(s, "cartId"))))
                  .exec(http("read_cart")
                      .get("/v2/carts/${cartId}")
                      .check(status().is(200))
                      .check(header("ETag").saveAs("cartEtag"))
                      .check(jsonPath("$.csrf").ofString().optional().saveAs("readCartCsrf")))
                  .exec(s -> keepCsrf(s, "readCartCsrf"))
                  .exitHereIfFailed()

                  // ---- quantity update with If-Match, one bounded 412 retry ----
                  .exec(http("update_cart")
                      .patch("/v2/carts/${cartId}")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "${csrf}")
                      .header("If-Match", "${cartEtag}")
                      .body(StringBody("{\"quantity\":2}"))
                      .check(status().in(200, 201, 202, 412).saveAs("patchStatus"))
                      .check(jsonPath("$.csrf").ofString().optional().saveAs("patchCsrf"))
                      .check(header("ETag").optional().saveAs("patchEtag")))
                  .exec(s -> keepEtag(keepCsrf(s, "patchCsrf"), "patchEtag"))
                  .doIf(s -> s.contains("patchStatus") && s.getInt("patchStatus") == 412)
                  .then(
                      exec(http("reread_cart")
                          .get("/v2/carts/${cartId}")
                          .check(status().is(200))
                          .check(header("ETag").saveAs("cartEtag")))
                          .exec(http("update_cart_retry")
                              .patch("/v2/carts/${cartId}")
                              .header("Content-Type", "application/json")
                              .header("X-CSRF-Token", "${csrf}")
                              .header("If-Match", "${cartEtag}")
                              .body(StringBody("{\"quantity\":2}"))
                              .check(status().in(200, 201, 202))
                              .check(jsonPath("$.csrf").ofString().optional().saveAs("patchRetryCsrf"))
                              .check(header("ETag").optional().saveAs("patchRetryEtag")))
                          .exec(s -> keepEtag(keepCsrf(s, "patchRetryCsrf"), "patchRetryEtag")))
                  .exitHereIfFailed()

                  // ---- one committed order, idempotency key stable across the retry ----
                  .exec(http("cart_state_before_order")
                      .get("/v2/carts/${cartId}")
                      .check(status().is(200))
                      .check(header("ETag").saveAs("cartEtag")))
                  .exec(s -> s.set("idemKey", "idem-" + UUID.randomUUID().toString()))
                  .exec(http("create_order")
                      .post("/v2/orders")
                      .header("Content-Type", "application/json")
                      .header("X-CSRF-Token", "${csrf}")
                      .header("Idempotency-Key", "${idemKey}")
                      .header("If-Match", "${cartEtag}")
                      .body(StringBody("{\"cart_id\":${cartIdJson}}"))
                      .check(status().in(200, 201, 401, 412).saveAs("orderStatus"))
                      .check(jsonPath("$.accepted").ofBoolean().optional().is(true))
                      .check(jsonPath("$.id").ofString().optional().saveAs("orderId"))
                      .check(jsonPath("$.csrf").ofString().optional().saveAs("orderCsrf"))
                      .check(jsonPath("$.error").ofString().optional().saveAs("orderError")))
                  .exec(s -> keepCsrf(s, "orderCsrf").set("orderOk", orderOk(s)))
                  .exitHereIfFailed()
                  .doIf(s -> !s.getBoolean("orderOk"))
                  .then(
                      exec(s -> s.set("orderRetried", true))
                          .doIf(s -> "expired".equals(str(s, "orderError")))
                          .then(
                              exec(http("session_renew")
                                  .post("/v2/session/renew")
                                  .header("Content-Type", "application/json")
                                  .header("X-CSRF-Token", "${csrf}")
                                  .body(StringBody("{}"))
                                  .check(status().is(200))
                                  .check(jsonPath("$.csrf").ofString().saveAs("renewCsrf")))
                                  .exec(s -> keepCsrf(s, "renewCsrf"))
                                  .exec(http("recover_cart")
                                      .post("/v2/carts/${cartId}/recover")
                                      .header("Content-Type", "application/json")
                                      .header("X-CSRF-Token", "${csrf}")
                                      .body(StringBody("{}"))
                                      .check(status().is(200))
                                      .check(jsonPath("$.csrf").ofString().optional().saveAs("recoverCsrf")))
                                  .exec(s -> keepCsrf(s, "recoverCsrf")))
                          .exec(http("cart_state_for_order_retry")
                              .get("/v2/carts/${cartId}")
                              .check(status().is(200))
                              .check(header("ETag").saveAs("cartEtag")))
                          .exec(http("create_order_retry")
                              .post("/v2/orders")
                              .header("Content-Type", "application/json")
                              .header("X-CSRF-Token", "${csrf}")
                              .header("Idempotency-Key", "${idemKey}")
                              .header("If-Match", "${cartEtag}")
                              .body(StringBody("{\"cart_id\":${cartIdJson}}"))
                              .check(status().is(201))
                              .check(jsonPath("$.accepted").ofBoolean().is(true))
                              .check(jsonPath("$.id").ofString().saveAs("orderId"))
                              .check(jsonPath("$.csrf").ofString().optional().saveAs("orderRetryCsrf")))
                          .exec(s -> keepCsrf(s, "orderRetryCsrf").set("orderOk", orderOk(s))))
                  .exitHereIfFailed());

  {
    setUp(journeys.injectOpen(atOnceUsers(USERS)))
        .protocols(protocol)
        .assertions(
            global().failedRequests().count().is(0L),
            details("create_order").successfulRequests().count().gte((long) USERS * ITERATIONS));
  }
}
