import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

/* ------------------------------------------------------------------ *
 * Public shop protocol - mode: pagination
 * 2 VUs x 2 iterations (per user) = 4 journeys, 1 cart + 1 order each.
 * Same artifact runs against both fixture variants (html_layout /
 * reverse_catalog) without any feedback or hard-coded ids/cursors.
 * ------------------------------------------------------------------ */

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const VUS = Number(__ENV.K6_VUS || 2);
const ITERATIONS = Number(__ENV.K6_ITERATIONS || 2);
const JOURNEYS = VUS * ITERATIONS;

const MAX_PAGES = 3;          // bounded cursor traversal
const MAX_POLLS = 5;          // reservation polling bound
const POLL_SLEEP = 0.06;      // >= 50ms apart
const QUANTITY = 2;           // 1..20
const PASSWORD = 'bench';

const checkoutSuccess = new Rate('checkout_success');
const eligibleFound = new Rate('eligible_item_found');
const ordersCommitted = new Counter('orders_committed');
const cartsCreated = new Counter('carts_created');
const cursorLinks = new Counter('cursor_links_followed');
const pagesTrend = new Trend('catalog_pages_traversed');
const recoveries = new Counter('session_recoveries');

export const options = {
  scenarios: {
    pagination: {
      executor: 'per-vu-iterations',
      vus: VUS,
      iterations: ITERATIONS,
      exec: 'journey',
      maxDuration: '5m',
      gracefulStop: '10s',
    },
  },
  discardResponseBodies: false,
  thresholds: {
    checkout_success: ['rate==1'],
    eligible_item_found: ['rate==1'],
    orders_committed: ['count==' + JOURNEYS],
    carts_created: ['count==' + JOURNEYS],
  },
};

http.setResponseCallback(
  http.expectedStatuses({ min: 200, max: 399 }, 401, 409, 412, 422, 428, 429)
);

/* ----------------------------- helpers ---------------------------- */

function isRedirect(res) {
  return !!res && (res.status === 301 || res.status === 302 || res.status === 303 ||
    res.status === 307 || res.status === 308);
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const want = String(name).toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return res.headers[keys[i]];
  }
  return null;
}

function resolveUrl(baseUrl, link) {
  if (!link) return null;
  const s = String(link).trim();
  if (!s) return null;
  if (/^https?:\/\//i.test(s)) return s;
  if (s.charAt(0) === '/') return BASE_URL + s;
  if (s.indexOf('/') < 0 && s.indexOf('?') < 0 && s.indexOf('=') < 0) return null; // never guess
  const bare = String(baseUrl).split('#')[0].split('?')[0];
  const idx = bare.lastIndexOf('/');
  const dir = idx >= 0 ? bare.slice(0, idx + 1) : bare + '/';
  return dir + s;
}

function sameOrigin(u) {
  return typeof u === 'string' && (u === BASE_URL || u.indexOf(BASE_URL + '/') === 0);
}

function jsonBody(res) {
  if (!res) return {};
  try {
    const j = res.json();
    if (j && typeof j === 'object') return j;
  } catch (e) { /* not json */ }
  try {
    const p = JSON.parse(res.body);
    if (p && typeof p === 'object') return p;
  } catch (e) { /* not json */ }
  return {};
}

function errorCode(res) {
  const b = jsonBody(res);
  const c = b.error || b.code || b.reason || (b.data && b.data.error);
  return c ? String(c).toLowerCase() : '';
}

function labelFor(url) {
  let p = String(url).replace(BASE_URL, '').split('?')[0];
  p = p.replace(/\/(carts|orders|challenges|reservations)\/[^/]+/g, '/$1/:id');
  return p || '/';
}

function truthyFlag(v) {
  return v === true || v === 'true' || v === 1 || v === '1' ||
    (typeof v === 'number' && v > 0);
}

function firstId() {
  for (let i = 0; i < arguments.length; i++) {
    const v = arguments[i];
    if (v !== undefined && v !== null && v !== '') return String(v);
  }
  return null;
}

/* --------------------------- HTML parsing -------------------------- */

function stripNoise(html) {
  return String(html || '')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<template[\s\S]*?<\/template>/gi, ' ');
}

function decodeEntities(s) {
  return String(s)
    .replace(/&#x([0-9a-f]+);/gi, function (m, h) { return String.fromCharCode(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); })
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function parseAttrs(tag) {
  const attrs = {};
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)(\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'`=<>]+)))?/g;
  let m;
  while ((m = re.exec(String(tag))) !== null) {
    const name = m[1].toLowerCase();
    let val = '';
    if (m[2]) {
      if (m[4] !== undefined) val = m[4];
      else if (m[5] !== undefined) val = m[5];
      else if (m[6] !== undefined) val = m[6];
    }
    if (!(name in attrs)) attrs[name] = decodeEntities(val);
  }
  return attrs;
}

function inputsOf(html) {
  const out = [];
  const re = /<input\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;
  let m;
  while ((m = re.exec(String(html))) !== null) out.push(parseAttrs(m[0]));
  return out;
}

function formsOf(html) {
  const out = [];
  const re = /<form\b((?:[^>"']|"[^"]*"|'[^']*')*)>([\s\S]*?)<\/form>/gi;
  let m;
  while ((m = re.exec(String(html))) !== null) out.push({ attrs: parseAttrs(m[1]), inner: m[2] });
  return out;
}

function pickNamedInput(scope, name) {
  const inputs = inputsOf(scope);
  const good = [];
  for (let i = 0; i < inputs.length; i++) {
    const a = inputs[i];
    if ((a.name || '') !== name) continue;
    if (a.disabled !== undefined) continue;
    if (a['data-decoy'] !== undefined || a['data-fake'] !== undefined) continue;
    if (!a.value) continue;
    good.push(a);
  }
  if (!good.length) return null;
  for (let i = 0; i < good.length; i++) {
    if ((good[i].type || '').toLowerCase() === 'hidden') return good[i].value;
  }
  return good[0].value;
}

function extractCsrf(html) {
  const clean = stripNoise(html);
  const forms = formsOf(clean);
  const scopes = [];
  for (let i = 0; i < forms.length; i++) {
    if (String(forms[i].attrs.action || '').indexOf('/v2/login') >= 0) scopes.push(forms[i].inner);
  }
  for (let i = 0; i < forms.length; i++) scopes.push(forms[i].inner);
  scopes.push(clean);
  for (let s = 0; s < scopes.length; s++) {
    const v = pickNamedInput(scopes[s], 'csrf');
    if (v) return v;
  }
  const meta = /<meta\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;
  let m;
  while ((m = meta.exec(clean)) !== null) {
    const a = parseAttrs(m[0]);
    if ((a.name || '').toLowerCase() === 'csrf' && a.content) return a.content;
  }
  return null;
}

function extractChallenge(html) {
  const clean = stripNoise(html);
  const forms = formsOf(clean);
  for (let i = 0; i < forms.length; i++) {
    const action = String(forms[i].attrs.action || '');
    if (!/\/v2\/challenges\/[^"'\s>]+/.test(action)) continue;
    const value = pickNamedInput(forms[i].inner, 'challenge');
    if (value) return { action: action, challenge: value };
  }
  const am = /action\s*=\s*("([^"]*\/v2\/challenges\/[^"]*)"|'([^']*\/v2\/challenges\/[^']*)'|([^\s>]*\/v2\/challenges\/[^\s>]*))/i.exec(clean);
  if (am) {
    const action = decodeEntities(am[2] || am[3] || am[4] || '');
    const value = pickNamedInput(clean, 'challenge');
    if (action && value) return { action: action, challenge: value };
  }
  return null;
}

/* --------------------------- HTTP plumbing ------------------------- */

function freshJar() {
  let jar = null;
  try { jar = new http.CookieJar(); } catch (e) { jar = null; }
  if (!jar) {
    jar = http.cookieJar();
    try {
      const cookies = jar.cookiesForURL(BASE_URL + '/');
      const names = Object.keys(cookies || {});
      for (let i = 0; i < names.length; i++) {
        try { jar.delete(BASE_URL + '/', names[i]); } catch (e) { /* ignore */ }
      }
    } catch (e) { /* ignore */ }
  }
  return jar;
}

function absorbCsrf(state, res) {
  const b = jsonBody(res);
  const token = b.csrf || (b.data && b.data.csrf);
  if (token && typeof token === 'string') state.csrf = token; // retain previous when absent
}

function rawRequest(state, method, url, payload, extraHeaders, extraTags) {
  const h = { Accept: 'application/json, text/html;q=0.9' };
  if (extraHeaders) {
    const keys = Object.keys(extraHeaders);
    for (let i = 0; i < keys.length; i++) {
      const v = extraHeaders[keys[i]];
      if (v !== undefined && v !== null) h[keys[i]] = v;
    }
  }
  if (method !== 'GET' && method !== 'HEAD') {
    h['Content-Type'] = 'application/json';
    if (state.csrf) h['X-CSRF-Token'] = state.csrf;
  }
  const tags = { name: labelFor(url) };
  if (extraTags) {
    const keys = Object.keys(extraTags);
    for (let i = 0; i < keys.length; i++) tags[keys[i]] = extraTags[keys[i]];
  }
  const params = { jar: state.jar, redirects: 0, timeout: '30s', tags: tags };
  const data = (payload === null || payload === undefined) ? null : JSON.stringify(payload);
  const res = http.request(method, url, data, params);
  absorbCsrf(state, res);
  return res;
}

function getFollowingOnce(state, url) {
  let res = rawRequest(state, 'GET', url, null, {});
  if (isRedirect(res)) {
    const loc = header(res, 'Location');
    const target = loc ? resolveUrl(url, loc) : null;
    if (target && sameOrigin(target)) res = rawRequest(state, 'GET', target, null, {});
  }
  return res;
}

function login(state) {
  const formRes = getFollowingOnce(state, BASE_URL + '/v2/login-form');
  const fb = jsonBody(formRes);
  let formCsrf = fb.csrf || (fb.data && fb.data.csrf) || null;
  if (!formCsrf) formCsrf = extractCsrf(formRes.body || '');
  check(formRes, {
    'login form fetched': function (r) { return r.status === 200; },
    'login form csrf parsed': function () { return !!formCsrf; },
  });
  if (!formCsrf) return false;

  let res = rawRequest(state, 'POST', BASE_URL + '/v2/login',
    { username: state.username, password: PASSWORD, csrf: formCsrf }, {});
  if (isRedirect(res)) {
    const loc = header(res, 'Location');
    const target = loc ? resolveUrl(BASE_URL + '/v2/login', loc) : null;
    if (target && sameOrigin(target)) res = rawRequest(state, 'GET', target, null, {});
  }
  const b = jsonBody(res);
  const token = b.csrf || (b.data && b.data.csrf);
  if (token) state.csrf = token; else state.csrf = formCsrf;
  state.user = b.user || (b.data && b.data.user) || state.username;
  const ok = res.status >= 200 && res.status < 300 && !!state.csrf;
  check(res, { 'login succeeded': function () { return ok; } });
  return ok;
}

function recoverSession(state, code) {
  recoveries.add(1);
  let renewed = false;
  if (code !== 'session') {
    const r = rawRequest(state, 'POST', BASE_URL + '/v2/session/renew', {}, {});
    renewed = r.status >= 200 && r.status < 300;
  }
  if (!renewed) login(state);
  if (state.cartId) {
    rawRequest(state, 'POST', BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover', {}, {});
  }
}

/* one bounded recovery per operation, never restarts checkout */
function api(state, method, url, payload, extraHeaders, extraTags) {
  let res = rawRequest(state, method, url, payload, extraHeaders, extraTags);
  if (res.status === 401) {
    const code = errorCode(res);
    if (code === 'denied') {
      check(res, { 'denied is not expiry (must fail)': function () { return false; } });
      return res;
    }
    recoverSession(state, code);
    res = rawRequest(state, method, url, payload, extraHeaders, extraTags);
  }
  return res;
}

/* ------------------------- catalog cursors ------------------------- */

function productsFrom(b) {
  const out = [];
  const d = (b && b.data && typeof b.data === 'object') ? b.data : b;
  if (d && Array.isArray(d.products)) {
    for (let i = 0; i < d.products.length; i++) out.push(d.products[i]);
  } else if (d && d.product && typeof d.product === 'object') {
    out.push(d.product);
  } else if (d && d.id !== undefined && Array.isArray(d.variants)) {
    out.push(d);
  }
  if (!out.length && b && Array.isArray(b.products)) {
    for (let i = 0; i < b.products.length; i++) out.push(b.products[i]);
  }
  if (!out.length && b && b.product && typeof b.product === 'object') out.push(b.product);
  return out;
}

function nextLink(b) {
  const cands = [];
  if (b) {
    cands.push(b.next);
    if (b.data) cands.push(b.data.next);
    if (b.links) cands.push(b.links.next);
    if (b.pagination) cands.push(b.pagination.next);
    if (b.meta) cands.push(b.meta.next);
  }
  for (let i = 0; i < cands.length; i++) {
    const c = cands[i];
    if (!c) continue;
    if (typeof c === 'string' && c.trim()) return c.trim();
    if (typeof c === 'object') {
      const u = c.href || c.url || c.path;
      if (u) return String(u);
    }
  }
  return null;
}

function eligibleFrom(p) {
  if (!p || p.id === undefined || p.id === null) return null;
  if (p.eligible === false || p.disabled === true || p.hidden === true ||
    p.archived === true || p.purchasable === false) return null;
  const status = p.status ? String(p.status).toLowerCase() : '';
  if (status === 'disabled' || status === 'archived' || status === 'hidden' ||
    status === 'inactive' || status === 'unavailable') return null;
  const variants = Array.isArray(p.variants) ? p.variants : [];
  for (let i = 0; i < variants.length; i++) {
    const v = variants[i];
    if (!v || v.id === undefined || v.id === null) continue;
    if (v.disabled === true || v.eligible === false) continue;
    if (!truthyFlag(v.in_stock)) continue;
    return {
      productId: String(p.id),
      variantId: String(v.id),
      needsGrant: truthyFlag(p.requires_grant) || truthyFlag(p.grant_required) ||
        truthyFlag(p.challenge_required) || truthyFlag(v.requires_grant) || truthyFlag(v.grant_required),
      needsReservation: truthyFlag(p.requires_reservation) || truthyFlag(p.reservation_required) ||
        truthyFlag(v.requires_reservation) || truthyFlag(v.reservation_required),
    };
  }
  return null;
}

function scanProducts(list) {
  for (let i = 0; i < list.length; i++) {
    const sel = eligibleFrom(list[i]);
    if (sel) return sel;
  }
  return null;
}

function selectEligible(state) {
  let url = BASE_URL + '/v2/catalog/page';
  const visited = {};
  let pages = 0;
  let found = null;

  while (url && pages < MAX_PAGES) {
    if (visited[url]) break;            // cursor loop guard
    visited[url] = true;
    if (pages > 0) cursorLinks.add(1);  // followed a dynamic next link
    const res = api(state, 'GET', url, null, {});
    pages++;
    if (res.status !== 200) {
      check(res, { 'catalog page reachable': function (r) { return r.status === 200; } });
      break;
    }
    const b = jsonBody(res);
    found = scanProducts(productsFrom(b));
    if (found) break;                   // first-page hit stops traversal
    const nxt = nextLink(b);
    if (!nxt) { url = null; break; }    // last page (next:null)
    const resolved = resolveUrl(url, nxt);
    url = (resolved && sameOrigin(resolved)) ? resolved : null;
  }

  pagesTrend.add(pages);
  check(null, {
    'cursor traversal bounded (<=3 pages)': function () { return pages <= MAX_PAGES && pages >= 1; },
  });

  if (!found) {
    // bounded traversal exhausted: documented full catalog, never a guessed cursor
    const res = api(state, 'GET', BASE_URL + '/v2/catalog', null, {});
    if (res.status === 200) found = scanProducts(productsFrom(jsonBody(res)));
  }
  check(null, { 'eligible in-stock record selected': function () { return !!found; } });
  return found;
}

/* ---------------------- challenge / reservation -------------------- */

function obtainGrant(state) {
  const formRes = getFollowingOnce(state, BASE_URL + '/v2/challenge-form');
  if (formRes.status !== 200) return null;
  const parsed = extractChallenge(formRes.body || '');
  if (!parsed) return null;
  const action = resolveUrl(BASE_URL + '/v2/challenge-form', parsed.action);
  if (!action || !sameOrigin(action)) return null;
  const post = api(state, 'POST', action, { challenge: parsed.challenge }, {});
  if (!isRedirect(post)) return null;
  const loc = header(post, 'Location');
  const target = loc ? resolveUrl(action, loc) : null;
  if (!target || !sameOrigin(target)) return null;
  const fin = rawRequest(state, 'GET', target, null, {});
  const b = jsonBody(fin);
  return firstId(b.grant_id, b.data && b.data.grant_id);
}

function reserve(state) {
  const res = api(state, 'POST', BASE_URL + '/v2/reservations', { cart_id: state.cartId }, {});
  if (res.status !== 202) {
    check(res, { 'reservation accepted 202': function (r) { return r.status === 202; } });
    return null;
  }
  const b = jsonBody(res);
  const raw = b.status_url || (b.data && b.data.status_url);
  const statusUrl = raw ? resolveUrl(BASE_URL + '/v2/reservations', raw) : null;
  if (!statusUrl || !sameOrigin(statusUrl)) return null;
  for (let i = 0; i < MAX_POLLS; i++) {
    sleep(POLL_SLEEP);
    const s = api(state, 'GET', statusUrl, null, {});
    if (s.status !== 200) continue;
    const sb = jsonBody(s);
    const st = sb.status || (sb.data && sb.data.status);
    const rid = firstId(sb.reservation_id, sb.data && sb.data.reservation_id);
    if (st === 'ready' && rid) return rid;
    if (st === 'failed') return null;   // pending/failed never reach checkout
  }
  return null;
}

/* ----------------------------- cart/order -------------------------- */

function cartUrl(state) {
  return BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId);
}

function wantsGrant(res) {
  const c = errorCode(res);
  return c.indexOf('grant') >= 0 || c.indexOf('challenge') >= 0;
}

function wantsReservation(res) {
  const b = jsonBody(res);
  const c = errorCode(res);
  return c.indexOf('reservation') >= 0 && !firstId(b.id, b.order_id, b.data && b.data.id);
}

function createCart(state, sel) {
  const payload = { product_id: sel.productId, variant_id: sel.variantId };
  if (sel.needsGrant) {
    const g = obtainGrant(state);
    if (g) payload.grant_id = g;
  }
  let res = api(state, 'POST', BASE_URL + '/v2/carts', payload, {}, { stage: 'cart_create' });
  if (res.status !== 201 && !state.cartId && wantsGrant(res)) {
    const g = obtainGrant(state);
    if (g) {
      payload.grant_id = g;
      res = api(state, 'POST', BASE_URL + '/v2/carts', payload, {}, { stage: 'cart_create' });
    }
  }
  const b = jsonBody(res);
  const id = firstId(b.id, b.cart_id, b.data && b.data.id);
  const ok = res.status === 201 && !!id;
  check(res, {
    'cart created 201': function (r) { return r.status === 201; },
    'cart id extracted': function () { return !!id; },
  });
  if (!ok) return false;
  state.cartId = id;
  cartsCreated.add(1);
  const et = header(res, 'ETag');
  if (et) state.etag = et;
  state.idemKey = 'order-' + state.cartId + '-' + __VU + '-' + __ITER + '-' +
    Math.floor(Math.random() * 1000000000).toString(36);
  return true;
}

function readCartEtag(state) {
  const res = api(state, 'GET', cartUrl(state), null, {}, { cart_id: state.cartId });
  check(res, { 'cart re-read for ETag': function (r) { return r.status === 200; } });
  const et = header(res, 'ETag');
  if (et) state.etag = et;
  return state.etag;
}

function patchQuantity(state, qty) {
  let etag = readCartEtag(state);
  let h = etag ? { 'If-Match': etag } : {};
  let res = api(state, 'PATCH', cartUrl(state), { quantity: qty }, h, { cart_id: state.cartId });
  if (res.status === 412 || res.status === 428) {
    etag = readCartEtag(state);         // re-read, same payload, one retry
    h = etag ? { 'If-Match': etag } : {};
    res = api(state, 'PATCH', cartUrl(state), { quantity: qty }, h, { cart_id: state.cartId });
  }
  check(res, { 'cart quantity patched': function (r) { return r.status >= 200 && r.status < 300; } });
  const et = header(res, 'ETag');
  if (et) state.etag = et;
  return res.status >= 200 && res.status < 300;
}

function placeOrder(state, sel) {
  if (sel.needsReservation && !state.reservationId) {
    const rid = reserve(state);
    if (rid) state.reservationId = rid;
  }
  const payload = { cart_id: state.cartId };
  if (state.reservationId) payload.reservation_id = state.reservationId;

  let headers = { 'Idempotency-Key': state.idemKey };
  if (state.etag) headers['If-Match'] = state.etag;
  let res = api(state, 'POST', BASE_URL + '/v2/orders', payload, headers,
    { stage: 'order_create', cart_id: state.cartId });

  if (res.status === 412 || res.status === 428) {
    const et = readCartEtag(state);
    headers = { 'Idempotency-Key': state.idemKey };
    if (et) headers['If-Match'] = et;
    res = api(state, 'POST', BASE_URL + '/v2/orders', payload, headers,
      { stage: 'order_create', cart_id: state.cartId });
  }

  if (wantsReservation(res) && !state.reservationId) {
    const rid = reserve(state);
    if (rid) {
      state.reservationId = rid;
      payload.reservation_id = rid;
      res = api(state, 'POST', BASE_URL + '/v2/orders', payload, headers,
        { stage: 'order_create', cart_id: state.cartId });
    }
  }

  const b = jsonBody(res);
  const orderId = firstId(b.id, b.order_id, b.data && b.data.id);
  const accepted = b.accepted === true || (b.data && b.data.accepted === true);
  const ok = res.status === 201 && accepted && !!orderId;

  check(res, {
    'order http 201': function (r) { return r.status === 201; },
    'order accepted true': function () { return accepted === true; },
    'order id extracted': function () { return !!orderId; },
  });

  if (ok) {
    state.orderId = orderId;
    const echo = firstId(b.cart_id, b.data && b.data.cart_id, b.cart && b.cart.id);
    check(null, {
      'order correlates cart id': function () { return echo === null || echo === state.cartId; },
      'one order per journey': function () { return !!state.orderId && !!state.cartId; },
    });
  }
  return ok;
}

/* ------------------------------ journey ---------------------------- */

export function journey() {
  const accountIndex = (((__VU - 1) * ITERATIONS + __ITER) % 16) + 1;
  const state = {
    jar: freshJar(),
    username: 'bench-' + accountIndex,
    csrf: null,
    user: null,
    cartId: null,
    etag: null,
    idemKey: null,
    reservationId: null,
    orderId: null,
  };

  if (!login(state)) {
    eligibleFound.add(false);
    checkoutSuccess.add(false);
    return;
  }

  const sel = selectEligible(state);
  eligibleFound.add(!!sel);
  if (!sel) {
    checkoutSuccess.add(false);
    return;
  }

  if (!createCart(state, sel)) {
    checkoutSuccess.add(false);
    return;
  }

  patchQuantity(state, QUANTITY);

  const ok = placeOrder(state, sel);
  checkoutSuccess.add(ok);
  if (ok) ordersCommitted.add(1);

  sleep(0.05);
}

export default function () {
  journey();
}
