"""Public shop protocol - pagination journey (Locust 2.47).

2 virtual users x 2 iterations = 4 journeys, one cart + one committed order each.
Every cursor, id, token, ETag and grant is taken from a live response.
"""

import json
import os
import re
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, between, task

try:
    from locust import StopUser
except ImportError:  # older/newer export location
    from locust.exception import StopUser


HOST = (os.environ.get("BASE_URL") or "http://127.0.0.1:8000").rstrip("/")
_HOST = urlsplit(HOST)

USERS = 2
ITERATIONS = 2
TOTAL_JOURNEYS = USERS * ITERATIONS
SPAWN_RATE = 2
MAX_PAGES = 3
MAX_RUNTIME = 240.0
MAX_POLLS = 5
POLL_GAP = 0.06
THROTTLE_RETRIES = 4
QUANTITY = 2

_STATE = {"claimed": 0, "completed": 0, "account": 0}
_BAD = ("fail", "denied", "expired", "session")
_MISSING = object()
_REDIRECTS = (301, 302, 303, 307, 308)


class JourneyAbort(Exception):
    """Controlled abort; the offending sample was already marked failed."""


def _claim():
    if _STATE["claimed"] >= TOTAL_JOURNEYS:
        return False
    _STATE["claimed"] += 1
    return True


def _finish():
    _STATE["completed"] += 1


def _account():
    _STATE["account"] += 1
    return "bench-%d" % (((_STATE["account"] - 1) % 16) + 1)


def _json(resp):
    try:
        data = resp.json()
    except Exception:
        try:
            data = json.loads(resp.text or "")
        except Exception:
            data = None
    return data if isinstance(data, (dict, list)) else None


class _FormParser(HTMLParser):
    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.inputs = []
        self.actions = []
        self._stack = []

    def handle_starttag(self, tag, attrs):
        d = {}
        for k, v in attrs:
            k = (k or "").lower()
            if k not in d:
                d[k] = v if v is not None else ""
        if tag == "form":
            action = d.get("action", "") or ""
            self.actions.append(action)
            self._stack.append(action)
        elif tag == "input":
            d["_action"] = self._stack[-1] if self._stack else ""
            self.inputs.append(d)

    def handle_endtag(self, tag):
        if tag == "form" and self._stack:
            self._stack.pop()


def _parse_html(text):
    p = _FormParser()
    try:
        p.feed(text or "")
        p.close()
    except Exception:
        pass
    return p.inputs, p.actions


def _pick_input(inputs, name, action_hint=None):
    best = None
    best_score = None
    for d in inputs:
        if d.get("name") != name:
            continue
        value = d.get("value") or d.get("data-value") or ""
        if not value:
            continue
        score = 0
        typ = (d.get("type") or "").lower()
        if typ == "hidden":
            score += 6
        elif typ in ("", "text"):
            score += 2
        else:
            score -= 3
        action = d.get("_action") or ""
        if action_hint:
            if action and action_hint in action:
                score += 8
            elif action:
                score -= 6
        if "disabled" in d:
            score -= 25
        markers = " ".join(
            list(d.keys())
            + [str(d.get(k, "")) for k in ("id", "class", "data-role", "data-kind",
                                           "data-decoy", "data-fake", "aria-hidden")]
        ).lower()
        if "decoy" in markers or "fake" in markers or "honeypot" in markers:
            score -= 30
        if "decoy" in value.lower():
            score -= 20
        if len(value) >= 24:
            score += 1
        if best_score is None or score > best_score:
            best, best_score = d, score
    return best


def _find_action(inputs, actions, text, hint):
    for a in actions:
        if hint in (a or ""):
            return a
    for d in inputs:
        if hint in (d.get("_action") or ""):
            return d["_action"]
    m = re.search(r"""action\s*=\s*['"]([^'"]*%s[^'"]*)['"]""" % re.escape(hint),
                  text or "", re.I)
    if m:
        return m.group(1)
    m = re.search(r"""action\s*=\s*([^\s>'"]*%s[^\s>'"]*)""" % re.escape(hint),
                  text or "", re.I)
    if m:
        return m.group(1)
    return None


def _collect_products(node, out, depth=0):
    if depth > 6:
        return
    if isinstance(node, dict):
        if "id" in node and isinstance(node.get("variants"), list):
            out.append(node)
            return
        for v in node.values():
            _collect_products(v, out, depth + 1)
    elif isinstance(node, list):
        for v in node:
            _collect_products(v, out, depth + 1)


def _in_stock(flag):
    if flag is True:
        return True
    if isinstance(flag, (int, float)) and not isinstance(flag, bool):
        return flag > 0
    if isinstance(flag, str):
        return flag.strip().lower() in ("true", "1", "yes", "in_stock")
    return False


def _eligible(products):
    for p in products:
        pid = p.get("id")
        if pid is None:
            continue
        if p.get("available") is False or p.get("active") is False:
            continue
        if str(p.get("status", "")).lower() in ("archived", "disabled", "hidden"):
            continue
        for v in p.get("variants") or []:
            if not isinstance(v, dict):
                continue
            vid = v.get("id")
            if vid is None:
                continue
            if _in_stock(v.get("in_stock")):
                return pid, vid
    return None


def _next_value(node, depth=0):
    if depth > 4 or not isinstance(node, dict):
        return _MISSING
    for key in ("next", "next_url", "next_page"):
        if key in node:
            return node[key]
    for key in ("data", "meta", "pagination", "links", "page"):
        sub = node.get(key)
        if isinstance(sub, dict):
            found = _next_value(sub, depth + 1)
            if found is not _MISSING:
                return found
    return _MISSING


def _next_link(payload):
    nxt = _next_value(payload)
    if nxt is _MISSING or nxt is None:
        return None
    if isinstance(nxt, dict):
        nxt = nxt.get("href") or nxt.get("url")
    if isinstance(nxt, str) and nxt.strip():
        return nxt.strip()
    return None


class ShopUser(HttpUser):
    host = HOST
    wait_time = between(0.05, 0.15)

    def on_start(self):
        self.username = _account()
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.order_id = None
        self.idem = None

    # ---------------- plumbing ----------------

    def _headers(self, extra=None, auth=True):
        h = {"Accept": "application/json"}
        if auth and self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if extra:
            h.update(extra)
        return h

    def _absorb(self, data):
        if isinstance(data, dict):
            tok = data.get("csrf")
            if isinstance(tok, str) and tok:
                self.csrf = tok

    def _abs_url(self, base, link):
        if not isinstance(link, str) or not link.strip():
            return None
        absolute = urljoin(base, link.strip())
        parts = urlsplit(absolute)
        if parts.scheme != _HOST.scheme or parts.netloc != _HOST.netloc:
            return None
        if not parts.path.startswith("/v2/"):
            return None
        return absolute

    def _sig_401(self, r, data, retry):
        err = ""
        if isinstance(data, dict):
            err = str(data.get("error") or "").lower()
        if err == "denied":
            r.failure("401 denied (not expiry)")
            return ("denied", None)
        if retry:
            r.failure("401 %s after bounded recovery" % (err or "unknown"))
            return ("fail", None)
        if err in ("expired", "session"):
            r.success()  # expected, handled by bounded recovery
            return (err, None)
        r.failure("unexpected 401 error=%r" % err)
        return ("fail", None)

    def _do(self, op, recover=True):
        tag, payload = op(False)
        if recover and tag in ("expired", "session"):
            self._recover(tag)
            tag, payload = op(True)  # retry only the interrupted operation once
        if tag in _BAD:
            raise JourneyAbort(tag)
        return tag, payload

    def _recover(self, kind):
        if kind == "expired":
            if not self._renew():
                self._login()
        else:
            self._login()
        if self.cart_id:
            self._recover_cart()

    def _renew(self):
        with self.client.post("/v2/session/renew", json={}, name="/v2/session/renew",
                              headers=self._headers(), allow_redirects=False,
                              catch_response=True) as r:
            data = _json(r)
            if r.status_code == 200:
                self._absorb(data)
                r.success()
                return True
            if r.status_code == 401:
                r.success()  # renew may legitimately fail on a revoked session
                return False
            r.failure("session renew status=%s" % r.status_code)
            raise JourneyAbort("renew")

    def _recover_cart(self):
        url = "/v2/carts/%s/recover" % self.cart_id
        with self.client.post(url, json={}, name="/v2/carts/[id]/recover",
                              headers=self._headers(), allow_redirects=False,
                              catch_response=True) as r:
            data = _json(r)
            if r.status_code in (200, 201, 202, 204):
                self._absorb(data)
                r.success()
                return
            r.failure("cart recover status=%s" % r.status_code)
            raise JourneyAbort("cart recover")

    # ---------------- journey ----------------

    @task
    def journey(self):
        for _ in range(ITERATIONS):
            if not _claim():
                raise StopUser()
            try:
                self._run_journey()
            except JourneyAbort:
                pass
            finally:
                _finish()
        raise StopUser()

    def _run_journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.order_id = None
        self.idem = None

        self._login()
        product_id, variant_id = self._find_eligible()
        self.grant_id = self._challenge()
        self._create_cart(product_id, variant_id)
        self.grant_id = None  # a grant is consumed by exactly one cart
        self._patch_quantity(QUANTITY)
        reservation_id = self._reservation()
        self._order(reservation_id)
        self._work()

    def _login(self):
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             headers={"Accept": "text/html,application/json"},
                             allow_redirects=False, catch_response=True) as r:
            if r.status_code != 200:
                r.failure("login-form status=%s" % r.status_code)
                raise JourneyAbort("login-form")
            text = r.text or ""
            inputs, _actions = _parse_html(text)
            node = _pick_input(inputs, "csrf", "/v2/login")
            token = (node.get("value") or node.get("data-value")) if node else None
            if not token:
                data = _json(r)
                if isinstance(data, dict) and isinstance(data.get("csrf"), str):
                    token = data["csrf"]
            if not token:
                r.failure("login-form: no usable input[name=csrf]")
                raise JourneyAbort("login csrf")
            r.success()

        body = {"username": self.username, "password": "bench", "csrf": token}
        location = None
        data = None
        with self.client.post("/v2/login", json=body, name="/v2/login",
                              headers={"Accept": "application/json"},
                              allow_redirects=False, catch_response=True) as r:
            payload = _json(r)
            if r.status_code in _REDIRECTS:
                location = self._abs_url(HOST + "/v2/login", r.headers.get("Location"))
                if location is None:
                    r.failure("login redirect without usable Location")
                    raise JourneyAbort("login redirect")
                r.success()
            elif r.status_code == 200 and isinstance(payload, dict) and payload.get("csrf"):
                data = payload
                r.success()
            else:
                r.failure("login status=%s" % r.status_code)
                raise JourneyAbort("login")

        if location is not None:
            with self.client.get(location, name="/v2/login/[redirect]",
                                 headers={"Accept": "application/json"},
                                 allow_redirects=False, catch_response=True) as r:
                payload = _json(r)
                if r.status_code != 200 or not isinstance(payload, dict) or not payload.get("csrf"):
                    r.failure("login redirect target status=%s" % r.status_code)
                    raise JourneyAbort("login redirect target")
                data = payload
                r.success()

        self.csrf = data["csrf"]

    def _find_eligible(self):
        url = HOST + "/v2/catalog/page"
        seen = set()
        pages = 0
        while url and pages < MAX_PAGES:
            if url in seen:
                break
            seen.add(url)
            pages += 1
            current = url

            def op(retry, current=current, page=pages):
                with self.client.get(current, name="/v2/catalog/page",
                                     headers=self._headers(auth=False),
                                     allow_redirects=False, catch_response=True) as r:
                    data = _json(r)
                    if r.status_code == 401:
                        return self._sig_401(r, data, retry)
                    if r.status_code != 200 or not isinstance(data, dict):
                        r.failure("catalog page status=%s" % r.status_code)
                        return ("fail", None)
                    products = []
                    _collect_products(data, products)
                    pick = _eligible(products)
                    nxt = _next_link(data)
                    resolved = None
                    if nxt is not None:
                        resolved = self._abs_url(current, nxt)
                        if resolved is None:
                            r.failure("catalog next cursor unusable: %r" % nxt)
                            return ("fail", None)
                    last = (resolved is None) or (page >= MAX_PAGES)
                    if pick is None and last:
                        r.failure("no in-stock variant within %d page(s)" % page)
                        return ("fail", None)
                    r.success()
                    return ("ok", (pick, resolved))

            _tag, payload = self._do(op)
            pick, nxt = payload
            if pick is not None:
                return pick
            url = nxt
        raise JourneyAbort("catalog traversal exhausted")

    def _challenge(self):
        with self.client.get("/v2/challenge-form", name="/v2/challenge-form",
                             headers=self._headers(auth=False),
                             allow_redirects=False, catch_response=True) as r:
            if r.status_code != 200:
                r.failure("challenge-form status=%s" % r.status_code)
                raise JourneyAbort("challenge-form")
            text = r.text or ""
            inputs, actions = _parse_html(text)
            action = _find_action(inputs, actions, text, "/v2/challenges/")
            node = _pick_input(inputs, "challenge", "/v2/challenges/")
            action_url = self._abs_url(HOST + "/v2/challenge-form", action) if action else None
            if action_url is None or node is None:
                r.failure("challenge-form: missing action or input[name=challenge]")
                raise JourneyAbort("challenge parse")
            challenge_value = node.get("value") or node.get("data-value")
            r.success()

        def op(retry):
            with self.client.post(action_url, json={"challenge": challenge_value},
                                  name="/v2/challenges/[id]", headers=self._headers(),
                                  allow_redirects=False, catch_response=True) as r:
                data = _json(r)
                if r.status_code == 401:
                    return self._sig_401(r, data, retry)
                if r.status_code in _REDIRECTS:
                    target = self._abs_url(action_url, r.headers.get("Location"))
                    if target is None:
                        r.failure("challenge redirect without usable Location")
                        return ("fail", None)
                    r.success()
                    return ("ok", target)
                if r.status_code == 200 and isinstance(data, dict) and data.get("grant_id"):
                    self._absorb(data)
                    r.success()
                    return ("done", data["grant_id"])
                r.failure("challenge post status=%s" % r.status_code)
                return ("fail", None)

        tag, payload = self._do(op)
        if tag == "done":
            return payload

        with self.client.get(payload, name="/v2/challenges/[grant]",
                             headers=self._headers(auth=False),
                             allow_redirects=False, catch_response=True) as r:
            data = _json(r)
            if r.status_code != 200 or not isinstance(data, dict) or not data.get("grant_id"):
                r.failure("grant fetch status=%s" % r.status_code)
                raise JourneyAbort("grant")
            self._absorb(data)
            r.success()
            return data["grant_id"]

    def _create_cart(self, product_id, variant_id):
        body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id

        def op(retry):
            with self.client.post("/v2/carts", json=body, name="/v2/carts",
                                  headers=self._headers(), allow_redirects=False,
                                  catch_response=True) as r:
                data = _json(r)
                if r.status_code == 401:
                    return self._sig_401(r, data, retry)
                if r.status_code != 201 or not isinstance(data, dict) or not data.get("id"):
                    r.failure("cart create status=%s" % r.status_code)
                    return ("fail", None)
                self._absorb(data)
                etag = r.headers.get("ETag")
                r.success()
                return ("ok", (data["id"], etag))

        _tag, payload = self._do(op)
        self.cart_id, self.cart_etag = payload
        self.idem = "order-%s-%s" % (self.cart_id, uuid.uuid4().hex)

    def _read_cart(self):
        url = "/v2/carts/%s" % self.cart_id

        def op(retry):
            with self.client.get(url, name="/v2/carts/[id]",
                                 headers=self._headers(auth=False),
                                 allow_redirects=False, catch_response=True) as r:
                data = _json(r)
                if r.status_code == 401:
                    return self._sig_401(r, data, retry)
                if r.status_code != 200:
                    r.failure("cart read status=%s" % r.status_code)
                    return ("fail", None)
                etag = r.headers.get("ETag")
                if not etag:
                    r.failure("cart read missing ETag")
                    return ("fail", None)
                r.success()
                return ("ok", etag)

        _tag, etag = self._do(op)
        self.cart_etag = etag
        return etag

    def _patch_quantity(self, quantity):
        url = "/v2/carts/%s" % self.cart_id
        body = {"quantity": quantity}
        etag = self.cart_etag or self._read_cart()
        for attempt in range(2):
            last = attempt == 1

            def op(retry, etag=etag, last=last):
                with self.client.patch(url, json=body, name="/v2/carts/[id]",
                                       headers=self._headers({"If-Match": etag}),
                                       allow_redirects=False, catch_response=True) as r:
                    data = _json(r)
                    if r.status_code == 401:
                        return self._sig_401(r, data, retry)
                    if r.status_code == 412:
                        if last:
                            r.failure("412 after ETag re-read")
                            return ("fail", None)
                        r.success()  # documented re-read + retry path
                        return ("precondition", None)
                    if r.status_code not in (200, 202, 204):
                        r.failure("cart patch status=%s" % r.status_code)
                        return ("fail", None)
                    self._absorb(data)
                    new_etag = r.headers.get("ETag")
                    r.success()
                    return ("ok", new_etag)

            tag, new_etag = self._do(op)
            if tag == "ok":
                if new_etag:
                    self.cart_etag = new_etag
                return
            if last:
                raise JourneyAbort("patch precondition")
            etag = self._read_cart()  # same payload, one retry

    def _reservation(self):
        def create(retry):
            with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                                  name="/v2/reservations", headers=self._headers(),
                                  allow_redirects=False, catch_response=True) as r:
                data = _json(r)
                if r.status_code == 401:
                    return self._sig_401(r, data, retry)
                if r.status_code not in (200, 201, 202) or not isinstance(data, dict):
                    r.failure("reservation create status=%s" % r.status_code)
                    return ("fail", None)
                target = self._abs_url(HOST + "/v2/reservations", data.get("status_url"))
                if target is None:
                    r.failure("reservation missing usable status_url")
                    return ("fail", None)
                self._absorb(data)
                r.success()
                return ("ok", target)

        _tag, status_url = self._do(create)

        for i in range(MAX_POLLS):
            time.sleep(POLL_GAP)
            last = i == MAX_POLLS - 1

            def poll(retry, last=last):
                with self.client.get(status_url, name="/v2/reservations/[status]",
                                     headers=self._headers(auth=False),
                                     allow_redirects=False, catch_response=True) as r:
                    data = _json(r)
                    if r.status_code == 401:
                        return self._sig_401(r, data, retry)
                    if r.status_code != 200 or not isinstance(data, dict):
                        r.failure("reservation status=%s" % r.status_code)
                        return ("fail", None)
                    state = str(data.get("status") or "").lower()
                    if state == "ready":
                        rid = data.get("reservation_id")
                        if not rid:
                            r.failure("ready without reservation_id")
                            return ("fail", None)
                        r.success()
                        return ("ready", rid)
                    if state == "pending":
                        if last:
                            r.failure("reservation still pending after %d polls" % MAX_POLLS)
                            return ("fail", None)
                        r.success()
                        return ("pending", None)
                    r.failure("reservation state=%s (never checkout)" % (state or "unknown"))
                    return ("fail", None)

            tag, rid = self._do(poll)
            if tag == "ready":
                return rid
        raise JourneyAbort("reservation not ready")

    def _order(self, reservation_id):
        body = {"cart_id": self.cart_id}
        if reservation_id:
            body["reservation_id"] = reservation_id
        etag = self._read_cart()
        for attempt in range(2):
            last = attempt == 1

            def op(retry, etag=etag, last=last):
                headers = self._headers({"Idempotency-Key": self.idem, "If-Match": etag})
                with self.client.post("/v2/orders", json=body, name="/v2/orders",
                                      headers=headers, allow_redirects=False,
                                      catch_response=True) as r:
                    data = _json(r)
                    if r.status_code == 401:
                        return self._sig_401(r, data, retry)
                    if r.status_code in (412, 428):
                        if last:
                            r.failure("order precondition after ETag re-read")
                            return ("fail", None)
                        r.success()  # documented If-Match refresh path
                        return ("precondition", None)
                    if (r.status_code == 201 and isinstance(data, dict)
                            and data.get("accepted") is True and data.get("id")):
                        self._absorb(data)
                        r.success()
                        return ("ok", data["id"])
                    if r.status_code == 200:
                        r.failure("order accepted:false (business failure)")
                        return ("fail", None)
                    r.failure("order status=%s" % r.status_code)
                    return ("fail", None)

            tag, order_id = self._do(op)
            if tag == "ok":
                self.order_id = order_id
                return
            if last:
                raise JourneyAbort("order precondition")
            etag = self._read_cart()  # same Idempotency-Key, same payload

    def _work(self):
        for attempt in range(THROTTLE_RETRIES + 1):
            last = attempt == THROTTLE_RETRIES

            def op(retry, last=last):
                with self.client.post("/v2/work", json={}, name="/v2/work",
                                      headers=self._headers(), allow_redirects=False,
                                      catch_response=True) as r:
                    data = _json(r)
                    if r.status_code == 401:
                        return self._sig_401(r, data, retry)
                    if r.status_code == 429:
                        ra = r.headers.get("Retry-After")
                        if ra is None:
                            r.failure("429 without Retry-After")
                            return ("fail", None)
                        if last:
                            r.failure("429 after %d retries" % THROTTLE_RETRIES)
                            return ("fail", None)
                        r.success()  # scheduled throttle, expected
                        return ("throttled", ra)
                    if r.status_code != 200:
                        r.failure("work status=%s (unexpected)" % r.status_code)
                        return ("fail", None)
                    if not isinstance(data, dict) or data.get("ok") is not True:
                        r.failure("work ok!=true")
                        return ("fail", None)
                    self._absorb(data)
                    r.success()
                    return ("ok", None)

            tag, ra = self._do(op)
            if tag == "ok":
                return
            try:
                delay = float(ra)
            except (TypeError, ValueError):
                delay = 1.0
            time.sleep(max(0.0, min(delay, 5.0)))


class ShopShape(LoadTestShape):
    """Exactly the contracted workload: 2 users, 2 iterations each, then stop."""

    def tick(self):
        if _STATE["completed"] >= TOTAL_JOURNEYS:
            return None
        if self.get_run_time() > MAX_RUNTIME:
            return None
        return (USERS, SPAWN_RATE)
