import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String ENV_BASE = System.getenv("BASE_URL");
  private static final String BASE_URL =
      (ENV_BASE == null || ENV_BASE.trim().isEmpty()) ? "http://127.0.0.1:8000" : ENV_BASE.trim();

  private static final int USERS = 2;
  private static final int ITERATIONS = 2;
  private static final int QUANTITY = 2;
  private static final int MAX_PATCH_ATTEMPTS = 2;
  private static final int MAX_ORDER_ATTEMPTS = 2;
  private static final int MAX_PAGES = 3;

  private static final Pattern COMMENT = Pattern.compile("<!--.*?-->", Pattern.DOTALL);
  private static final Pattern INPUT_TAG = Pattern.compile("<input\\b[^>]*>", Pattern.CASE_INSENSITIVE);
  private static final Pattern ATTR = Pattern.compile(
      "([A-Za-z_:][-A-Za-z0-9_:.]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'>]+))");

  /* ---------------- session helpers ---------------- */

  private static String sv(Session s, String key) {
    if (!s.contains(key)) return "";
    Object v = s.get(key);
    return v == null ? "" : v.toString();
  }

  private static boolean flag(Session s, String key) {
    return "true".equals(sv(s, key));
  }

  private static int iv(Session s, String key) {
    try {
      return Integer.parseInt(sv(s, key).trim());
    } catch (RuntimeException e) {
      return 0;
    }
  }

  private static String jsonValue(String raw) {
    if (raw == null || raw.isEmpty()) return "null";
    if (raw.matches("-?\\d+")) return raw;
    return "\"" + raw.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
  }

  /* ---------------- minimal JSON reader (JDK only) ---------------- */

  private static Object parseJson(String text) {
    if (text == null || text.isEmpty()) return null;
    int[] pos = new int[] {0};
    try {
      return readValue(text, pos);
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static void ws(String t, int[] p) {
    while (p[0] < t.length() && Character.isWhitespace(t.charAt(p[0]))) p[0]++;
  }

  private static Object readValue(String t, int[] p) {
    ws(t, p);
    if (p[0] >= t.length()) return null;
    char c = t.charAt(p[0]);
    if (c == '{') {
      p[0]++;
      Map<String, Object> m = new LinkedHashMap<>();
      ws(t, p);
      if (p[0] < t.length() && t.charAt(p[0]) == '}') {
        p[0]++;
        return m;
      }
      while (p[0] < t.length()) {
        ws(t, p);
        Object k = readValue(t, p);
        ws(t, p);
        if (p[0] < t.length() && t.charAt(p[0]) == ':') p[0]++;
        Object v = readValue(t, p);
        m.put(k == null ? "" : k.toString(), v);
        ws(t, p);
        if (p[0] < t.length() && t.charAt(p[0]) == ',') {
          p[0]++;
          continue;
        }
        if (p[0] < t.length() && t.charAt(p[0]) == '}') p[0]++;
        break;
      }
      return m;
    }
    if (c == '[') {
      p[0]++;
      List<Object> l = new ArrayList<>();
      ws(t, p);
      if (p[0] < t.length() && t.charAt(p[0]) == ']') {
        p[0]++;
        return l;
      }
      while (p[0] < t.length()) {
        l.add(readValue(t, p));
        ws(t, p);
        if (p[0] < t.length() && t.charAt(p[0]) == ',') {
          p[0]++;
          continue;
        }
        if (p[0] < t.length() && t.charAt(p[0]) == ']') p[0]++;
        break;
      }
      return l;
    }
    if (c == '"') {
      p[0]++;
      StringBuilder sb = new StringBuilder();
      while (p[0] < t.length()) {
        char d = t.charAt(p[0]++);
        if (d == '\\' && p[0] < t.length()) {
          char e = t.charAt(p[0]++);
          if (e == 'n') sb.append('\n');
          else if (e == 't') sb.append('\t');
          else if (e == 'r') sb.append('\r');
          else if (e == 'b') sb.append('\b');
          else if (e == 'f') sb.append('\f');
          else if (e == 'u') {
            if (p[0] + 4 <= t.length()) {
              try {
                sb.append((char) Integer.parseInt(t.substring(p[0], p[0] + 4), 16));
              } catch (RuntimeException ex) {
                sb.append(' ');
              }
              p[0] += 4;
            }
          } else sb.append(e);
        } else if (d == '"') break;
        else sb.append(d);
      }
      return sb.toString();
    }
    if (t.startsWith("true", p[0])) {
      p[0] += 4;
      return Boolean.TRUE;
    }
    if (t.startsWith("false", p[0])) {
      p[0] += 5;
      return Boolean.FALSE;
    }
    if (t.startsWith("null", p[0])) {
      p[0] += 4;
      return null;
    }
    int start = p[0];
    while (p[0] < t.length() && "+-0123456789.eE".indexOf(t.charAt(p[0])) >= 0) p[0]++;
    if (p[0] == start) {
      p[0]++;
      return null;
    }
    return t.substring(start, p[0]);
  }

  @SuppressWarnings("unchecked")
  private static Map<String, Object> obj(Object o) {
    if (o instanceof Map) return (Map<String, Object>) o;
    return new LinkedHashMap<>();
  }

  @SuppressWarnings("unchecked")
  private static List<Object> arr(Object o) {
    if (o instanceof List) return (List<Object>) o;
    return new ArrayList<>();
  }

  /* ---------------- csrf / html helpers ---------------- */

  private static String unescape(String v) {
    return v.replace("&quot;", "\"").replace("&#39;", "'").replace("&lt;", "<")
        .replace("&gt;", ">").replace("&amp;", "&");
  }

  private static String formCsrf(String html) {
    if (html == null || html.isEmpty()) return null;
    String clean = COMMENT.matcher(html).replaceAll(" ");
    String best = null;
    int bestScore = -100;
    Matcher tags = INPUT_TAG.matcher(clean);
    while (tags.find()) {
      String tag = tags.group();
      Map<String, String> attrs = new HashMap<>();
      Matcher am = ATTR.matcher(tag);
      while (am.find()) {
        String name = am.group(1).toLowerCase();
        String value = am.group(2) != null ? am.group(2)
            : (am.group(3) != null ? am.group(3) : (am.group(4) != null ? am.group(4) : ""));
        if (!attrs.containsKey(name)) attrs.put(name, value);
      }
      String name = attrs.get("name");
      if (name == null || !"csrf".equals(name.trim())) continue;
      if (attrs.containsKey("disabled")) continue;
      String value = attrs.get("value");
      if (value == null || value.trim().isEmpty()) continue;
      int score = 1;
      String type = attrs.get("type");
      if (type != null && "hidden".equalsIgnoreCase(type.trim())) score += 2;
      String lower = tag.toLowerCase();
      if (lower.contains("decoy") || lower.contains("data-fake")) score -= 4;
      if (score > bestScore) {
        bestScore = score;
        best = unescape(value.trim());
      }
    }
    return best;
  }

  private static Session applyCsrf(Session s, String bodyKey) {
    Map<String, Object> body = obj(parseJson(sv(s, bodyKey)));
    Object token = body.get("csrf");
    Session r = s;
    if (token != null && !token.toString().trim().isEmpty()) {
      r = r.set("csrf", token.toString().trim());
    }
    return r.set(bodyKey, "");
  }

  /* ---------------- journey state ---------------- */

  private static Session reset(Session s) {
    String[] keys = {
        "loginHtml", "loginBody", "loginLocation", "redirectBody", "catalogBody", "pageBody",
        "cartBody", "patchBody", "cartReadBody", "orderBody", "etagHint", "patchStatus",
        "orderStatus", "productId", "variantId", "productIdJson", "variantIdJson", "pageUrl",
        "cartId", "cartIdJson", "etag", "idemKey", "orderId", "csrf"
    };
    Session r = s;
    for (String k : keys) r = r.set(k, "");
    return r.set("pages", 0)
        .set("patchAttempts", 0)
        .set("orderAttempts", 0)
        .set("patchDone", "false")
        .set("orderDone", "false")
        .set("redirectDone", "false")
        .set("patchPayload", "{\"quantity\":" + QUANTITY + "}");
  }

  private static Session pickProduct(Session s, String bodyKey) {
    Map<String, Object> root = obj(parseJson(sv(s, bodyKey)));
    Object dataNode = root.containsKey("data") ? root.get("data") : root;
    for (Object po : arr(obj(dataNode).get("products"))) {
      Map<String, Object> p = obj(po);
      for (Object vo : arr(p.get("variants"))) {
        Map<String, Object> v = obj(vo);
        Object stock = v.get("in_stock");
        boolean inStock = stock != null
            && ("true".equalsIgnoreCase(stock.toString()) || "1".equals(stock.toString()));
        if (!inStock) continue;
        String pid = p.get("id") == null ? "" : p.get("id").toString();
        String vid = v.get("id") == null ? "" : v.get("id").toString();
        if (pid.isEmpty() || vid.isEmpty()) continue;
        return s.set("productId", pid).set("variantId", vid)
            .set("productIdJson", jsonValue(pid)).set("variantIdJson", jsonValue(vid));
      }
    }
    return s;
  }

  private static Session advancePage(Session s, String bodyKey) {
    Map<String, Object> root = obj(parseJson(sv(s, bodyKey)));
    Object next = root.get("next");
    if (next == null) next = obj(root.get("data")).get("next");
    String n = next == null ? "" : next.toString().trim();
    if ("null".equalsIgnoreCase(n)) n = "";
    return s.set("pageUrl", n).set("pages", iv(s, "pages") + 1).set(bodyKey, "");
  }

  private static Session afterCreate(Session s) {
    Map<String, Object> body = obj(parseJson(sv(s, "cartBody")));
    String id = body.get("id") == null ? "" : body.get("id").toString();
    Session r = applyCsrf(s, "cartBody");
    return r.set("cartId", id).set("cartIdJson", jsonValue(id)).set("idemKey", "order-" + id);
  }

  private static Session afterPatch(Session s) {
    String status = sv(s, "patchStatus");
    String hint = sv(s, "etagHint");
    Session r = applyCsrf(s, "patchBody");
    r = r.set("patchAttempts", iv(r, "patchAttempts") + 1);
    if (!hint.isEmpty()) r = r.set("etag", hint);
    boolean ok = "200".equals(status) || "201".equals(status);
    return r.set("patchDone", ok ? "true" : "false").set("etagHint", "").set("patchStatus", "");
  }

  private static Session afterOrder(Session s) {
    Map<String, Object> body = obj(parseJson(sv(s, "orderBody")));
    String status = sv(s, "orderStatus");
    Object accepted = body.get("accepted");
    boolean ok = "201".equals(status) && accepted != null
        && "true".equalsIgnoreCase(accepted.toString());
    Session r = applyCsrf(s, "orderBody");
    r = r.set("orderAttempts", iv(r, "orderAttempts") + 1);
    if (body.get("id") != null) r = r.set("orderId", body.get("id").toString());
    return r.set("orderDone", ok ? "true" : "false").set("orderStatus", "");
  }

  /* ---------------- chains ---------------- */

  private static final ChainBuilder LOGIN =
      exec(http("login.form")
          .get("/v2/login-form")
          .check(status().is(200))
          .check(bodyString().saveAs("loginHtml")))
      .exec(session -> {
        String token = formCsrf(sv(session, "loginHtml"));
        return session.set("csrf", token == null ? "" : token).set("loginHtml", "");
      })
      .exec(http("login.submit")
          .post("/v2/login")
          .header("Content-Type", "application/json")
          .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
          .check(status().in(200, 302))
          .check(bodyString().optional().saveAs("loginBody"))
          .check(header("Location").optional().saveAs("loginLocation")))
      .exec(session -> applyCsrf(session, "loginBody"))
      .asLongAs(session -> !flag(session, "redirectDone") && !sv(session, "loginLocation").isEmpty())
      .on(exec(http("login.redirect")
              .get("#{loginLocation}")
              .check(status().is(200))
              .check(bodyString().optional().saveAs("redirectBody")))
          .exec(session -> applyCsrf(session, "redirectBody").set("redirectDone", "true")));

  private static final ChainBuilder CATALOG =
      exec(http("catalog.list")
          .get("/v2/catalog")
          .check(status().is(200))
          .check(bodyString().saveAs("catalogBody")))
      .exec(session -> pickProduct(session, "catalogBody"))
      .exec(session -> session.set("pageUrl", "/v2/catalog/page").set("pages", 0))
      .asLongAs(session -> sv(session, "productId").isEmpty()
          && !sv(session, "pageUrl").isEmpty()
          && iv(session, "pages") < MAX_PAGES)
      .on(exec(http("catalog.page")
              .get("#{pageUrl}")
              .check(status().is(200))
              .check(bodyString().saveAs("pageBody")))
          .exec(session -> advancePage(pickProduct(session, "pageBody"), "pageBody")));

  private static final ChainBuilder CART_CREATE =
      exec(http("cart.create")
          .post("/v2/carts")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .body(StringBody("{\"product_id\":#{productIdJson},\"variant_id\":#{variantIdJson}}"))
          .check(status().is(201))
          .check(header("ETag").saveAs("etag"))
          .check(bodyString().saveAs("cartBody")))
      .exec(session -> afterCreate(session));

  private static final ChainBuilder CONDITIONAL_PATCH =
      exec(http("cart.patch.conditional")
          .patch("/v2/carts/#{cartId}")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .header("If-Match", "#{etag}")
          .body(StringBody("#{patchPayload}"))
          .check(status().in(200, 201, 412))
          .check(status().saveAs("patchStatus"))
          .check(header("ETag").optional().saveAs("etagHint"))
          .check(bodyString().optional().saveAs("patchBody")))
      .exec(session -> afterPatch(session))
      .asLongAs(session -> !flag(session, "patchDone")
          && iv(session, "patchAttempts") < MAX_PATCH_ATTEMPTS)
      .on(exec(http("cart.reread.revision")
              .get("/v2/carts/#{cartId}")
              .check(status().is(200))
              .check(header("ETag").saveAs("etag"))
              .check(bodyString().optional().saveAs("cartReadBody")))
          .exec(session -> applyCsrf(session, "cartReadBody"))
          .exec(http("cart.patch.retry")
              .patch("/v2/carts/#{cartId}")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{etag}")
              .body(StringBody("#{patchPayload}"))
              .check(status().in(200, 201))
              .check(status().saveAs("patchStatus"))
              .check(header("ETag").optional().saveAs("etagHint"))
              .check(bodyString().optional().saveAs("patchBody")))
          .exec(session -> afterPatch(session)))
      .exec(session -> flag(session, "patchDone") ? session : session.markAsFailed())
      .exitHereIfFailed();

  private static final ChainBuilder CHECKOUT =
      exec(http("cart.revision.for.order")
          .get("/v2/carts/#{cartId}")
          .check(status().is(200))
          .check(header("ETag").saveAs("etag"))
          .check(bodyString().optional().saveAs("cartReadBody")))
      .exec(session -> applyCsrf(session, "cartReadBody"))
      .exec(http("order.submit")
          .post("/v2/orders")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .header("If-Match", "#{etag}")
          .header("Idempotency-Key", "#{idemKey}")
          .body(StringBody("{\"cart_id\":#{cartIdJson}}"))
          .check(status().in(201, 412))
          .check(status().saveAs("orderStatus"))
          .check(bodyString().optional().saveAs("orderBody")))
      .exec(session -> afterOrder(session))
      .asLongAs(session -> !flag(session, "orderDone")
          && iv(session, "orderAttempts") < MAX_ORDER_ATTEMPTS)
      .on(exec(http("order.reread.revision")
              .get("/v2/carts/#{cartId}")
              .check(status().is(200))
              .check(header("ETag").saveAs("etag"))
              .check(bodyString().optional().saveAs("cartReadBody")))
          .exec(session -> applyCsrf(session, "cartReadBody"))
          .exec(http("order.retry")
              .post("/v2/orders")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{etag}")
              .header("Idempotency-Key", "#{idemKey}")
              .body(StringBody("{\"cart_id\":#{cartIdJson}}"))
              .check(status().is(201))
              .check(regex("\"accepted\"\\s*:\\s*true").exists())
              .check(status().saveAs("orderStatus"))
              .check(bodyString().optional().saveAs("orderBody")))
          .exec(session -> afterOrder(session)))
      .exec(session -> flag(session, "orderDone") ? session : session.markAsFailed())
      .exitHereIfFailed();

  private static final ChainBuilder JOURNEY =
      exec(session -> reset(session))
          .exec(LOGIN)
          .exec(CATALOG)
          .exec(CART_CREATE)
          .exec(CONDITIONAL_PATCH)
          .exec(CHECKOUT);

  private static Iterator<Map<String, Object>> accounts() {
    List<Map<String, Object>> records = new ArrayList<>();
    for (int i = 1; i <= USERS; i++) {
      Map<String, Object> row = new HashMap<>();
      row.put("username", "bench-" + i);
      records.add(row);
    }
    return records.iterator();
  }

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(BASE_URL)
      .disableFollowRedirect()
      .disableCaching()
      .acceptHeader("application/json")
      .userAgentHeader("gatling-etag-conditional-cart");

  private final ScenarioBuilder scn = scenario("etag-conditional-cart-update")
      .feed(accounts())
      .repeat(ITERATIONS, "journey").on(JOURNEY);

  {
    setUp(scn.injectOpen(atOnceUsers(USERS)))
        .protocols(httpProtocol)
        .assertions(global().failedRequests().count().is(0L));
  }
}

```javascript
// k6 1.0.0 — ETag journey: extract revision, conditional PATCH, recover one scheduled 412,
// commit exactly one order per journey. Contract: 2 users x 2 iterations, quantity 2.
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const QUANTITY = 2;
const VUS = 2;
const ITERATIONS = 2;
const PASSWORD = 'bench';

const cartsCreated = new Counter('carts_created');
const cartMutationsCommitted = new Counter('cart_mutations_committed');
const etagConflicts = new Counter('etag_conflicts_observed');
const etagConflictRecoveries = new Counter('etag_conflict_recoveries');
const ordersCommitted = new Counter('orders_committed');
const businessFailures = new Counter('business_failures');

const EXPECTED = http.expectedStatuses({ min: 200, max: 399 }, 401, 412);

export const options = {
  scenarios: {
    etag_journey: {
      executor: 'per-vu-iterations',
      vus: VUS,
      iterations: ITERATIONS,
      maxDuration: '180s',
      gracefulStop: '5s',
    },
  },
  userAgent: 'k6-etag-journey/1.0.0',
  insecureSkipTLSVerify: true,
};

/* ------------------------------------------------------------------ helpers */

function jsonParse(text) {
  if (typeof text !== 'string' || text.length === 0) return null;
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function jsonOf(res) {
  if (!res) return null;
  const b = res.body;
  if (typeof b !== 'string') return null;
  const t = b.trim();
  if (t.length === 0 || (t[0] !== '{' && t[0] !== '[')) return null;
  return jsonParse(t);
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const want = String(name).toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return res.headers[keys[i]];
  }
  return null;
}

function decodeEntities(s) {
  return String(s)
    .replace(/&quot;/g, '"')
    .replace(/&#0*34;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#0*39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#x0*2f;/gi, '/')
    .replace(/&#0*47;/g, '/')
    .replace(/&amp;/g, '&');
}

function attrs(tag) {
  const out = {};
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'>]+))/g;
  let m;
  while ((m = re.exec(tag)) !== null) {
    const key = m[1].toLowerCase();
    const val = m[3] !== undefined ? m[3] : m[4] !== undefined ? m[4] : m[5];
    if (!Object.prototype.hasOwnProperty.call(out, key)) out[key] = decodeEntities(val);
  }
  return out;
}

function csrfInputs(html) {
  const found = [];
  const tags = String(html).match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    const a = attrs(tags[i]);
    const nm = (a.name || '').toLowerCase();
    if (nm !== 'csrf') continue;
    if (a.disabled !== undefined) continue;
    if (a.value === undefined || a.value === '') continue;
    found.push(a.value);
  }
  return found;
}

// Handles both fixture layouts: decoys, attribute reordering, quoting/case variants.
function extractCsrf(body, actionHint) {
  if (body === null || body === undefined) return null;
  const text = String(body);
  const j = jsonParse(text.trim());
  if (j && typeof j.csrf === 'string' && j.csrf.length > 0) return j.csrf;

  const html = text.replace(/<!--[\s\S]*?-->/g, '');
  const formRe = /<form\b([^>]*)>([\s\S]*?)<\/form>/gi;
  let m;
  let best = null;
  let bestScore = -1;
  while ((m = formRe.exec(html)) !== null) {
    const fa = attrs('<form' + m[1] + '>');
    const vals = csrfInputs(m[2]);
    if (vals.length === 0) continue;
    const action = (fa.action || '').toLowerCase();
    let score = 1;
    if (actionHint && action.indexOf(String(actionHint).toLowerCase()) >= 0) score = 4;
    else if (action === '') score = 3;
    else if (/decoy|trap|dummy|fake|noise/.test(action)) score = 0;
    if (/decoy|trap|dummy|fake|noise/.test(vals[0].toLowerCase())) score = 0;
    if (score > bestScore) {
      bestScore = score;
      best = vals[0];
    }
  }
  if (best !== null && bestScore >= 3) return best;

  const global = csrfInputs(html);
  const clean = [];
  for (let i = 0; i < global.length; i++) {
    if (!/decoy|trap|dummy|fake|noise/.test(global[i].toLowerCase())) clean.push(global[i]);
  }
  if (clean.length > 0) return clean[0];
  if (best !== null) return best;
  if (global.length > 0) return global[0];

  const metas = html.match(/<meta\b[^>]*>/gi) || [];
  for (let i = 0; i < metas.length; i++) {
    const a = attrs(metas[i]);
    const nm = (a.name || a.property || '').toLowerCase();
    if (nm === 'csrf' && a.content) return a.content;
  }
  const dj = /(?:data-csrf|csrf-token)\s*=\s*("([^"]*)"|'([^']*)')/i.exec(html);
  if (dj) return decodeEntities(dj[2] !== undefined ? dj[2] : dj[3]);
  return null;
}

// ETag is taken verbatim from the header; body carriers are only a defensive fallback.
function extractEtag(res) {
  const h = header(res, 'ETag');
  if (h !== null && String(h).trim() !== '') return String(h).trim();
  const b = jsonOf(res);
  if (b) {
    const carriers = [b, b.data, b.cart, b.revision];
    for (let i = 0; i < carriers.length; i++) {
      const c = carriers[i];
      if (!c) continue;
      const v = c.etag || c.ETag || c.eTag;
      if (typeof v === 'string' && v.trim() !== '') return v.trim();
    }
  }
  const body = res && typeof res.body === 'string' ? res.body : '';
  if (body.indexOf('<') >= 0) {
    const html = body.replace(/<!--[\s\S]*?-->/g, '');
    const vals = csrfLikeValues(html, 'etag');
    if (vals.length > 0) return vals[0];
    const metas = html.match(/<meta\b[^>]*>/gi) || [];
    for (let i = 0; i < metas.length; i++) {
      const a = attrs(metas[i]);
      if ((a.name || '').toLowerCase() === 'etag' && a.content) return a.content;
    }
    const de = /data-etag\s*=\s*("([^"]*)"|'([^']*)')/i.exec(html);
    if (de) return decodeEntities(de[2] !== undefined ? de[2] : de[3]);
  }
  return null;
}

function csrfLikeValues(html, name) {
  const out = [];
  const tags = String(html).match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    const a = attrs(tags[i]);
    if ((a.name || '').toLowerCase() === name && a.value) out.push(a.value);
  }
  return out;
}

function absUrl(u, refUrl) {
  if (u === null || u === undefined) return null;
  const s = decodeEntities(String(u).trim());
  if (s === '') return null;
  if (/^https?:\/\//i.test(s)) return s.indexOf(BASE_URL) === 0 ? s : null;
  if (s.charAt(0) === '/') return BASE_URL + s;
  const ref = refUrl || BASE_URL + '/';
  let refPath = ref.indexOf(BASE_URL) === 0 ? ref.slice(BASE_URL.length) : ref;
  refPath = refPath.split('?')[0] || '/';
  let dir = refPath.replace(/[^/]*$/, '');
  if (dir.charAt(0) !== '/') dir = '/' + dir;
  return BASE_URL + dir + s;
}

function urlTag(url) {
  let p = url.indexOf(BASE_URL) === 0 ? url.slice(BASE_URL.length) : url;
  p = p.split('?')[0];
  p = p.replace(/\/[0-9a-fA-F-]{6,}(\/|$)/g, '/{id}$1');
  return p;
}

function buildHeaders(st, method, extra, payload) {
  const h = { Accept: 'application/json' };
  if (payload !== null && payload !== undefined) h['Content-Type'] = 'application/json';
  if (String(method).toUpperCase() !== 'GET' && st.csrf) h['X-CSRF-Token'] = st.csrf;
  if (extra) {
    const keys = Object.keys(extra);
    for (let i = 0; i < keys.length; i++) {
      if (extra[keys[i]] !== null && extra[keys[i]] !== undefined) h[keys[i]] = extra[keys[i]];
    }
  }
  return h;
}

function rawRequest(method, url, payload, headers) {
  const params = {
    headers: headers || {},
    redirects: 0,
    responseCallback: EXPECTED,
    tags: { name: urlTag(url) },
  };
  const m = String(method).toUpperCase();
  if (m === 'GET') return http.get(url, params);
  if (m === 'DELETE') return http.del(url, null, params);
  return http.request(m, url, payload === undefined ? null : payload, params);
}

// Retain previous CSRF when a mutation response omits a fresh one.
function absorb(st, res) {
  const b = jsonOf(res);
  if (b && typeof b.csrf === 'string' && b.csrf.length > 0) st.csrf = b.csrf;
  return b;
}

function errorOf(res) {
  const b = jsonOf(res) || {};
  const e = b.error || b.code || (b.data && b.data.error) || '';
  return String(e).toLowerCase();
}

function ok2xx(res) {
  return !!res && res.status >= 200 && res.status < 300;
}

/* -------------------------------------------------------------- session ops */

function login(st) {
  const jar = http.cookieJar();
  jar.clear(BASE_URL);
  jar.clear(BASE_URL + '/');
  st.csrf = null;

  const form = rawRequest('GET', BASE_URL + '/v2/login-form', null, { Accept: 'text/html' });
  check(form, { 'session: login-form 200': (r) => r.status === 200 });
  const formCsrf = extractCsrf(form.body, '/v2/login');
  check(formCsrf, { 'session: login nonce csrf extracted': (v) => !!v });
  if (!formCsrf) return false;
  st.csrf = formCsrf;

  const payload = JSON.stringify({ username: st.username, password: PASSWORD, csrf: formCsrf });
  const res = rawRequest('POST', BASE_URL + '/v2/login', payload, {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  });

  let body = null;
  if (res.status >= 300 && res.status < 400) {
    const loc = header(res, 'Location');
    check(loc, { 'session: login redirect Location present': (v) => !!v });
    const target = absUrl(loc, BASE_URL + '/v2/login');
    check(target, { 'session: login Location on target origin': (v) => !!v });
    if (!target) return false;
    const followed = rawRequest('GET', target, null, { Accept: 'application/json' });
    check(followed, { 'session: login Location followed once (2xx)': (r) => ok2xx(r) });
    body = absorb(st, followed);
    if (!st.csrf) st.csrf = extractCsrf(followed.body, '');
  } else {
    check(res, { 'session: login 200': (r) => r.status === 200 });
    body = absorb(st, res);
  }
  if (body && body.csrf) st.csrf = body.csrf;
  check(st.csrf, { 'session: authenticated csrf retained': (v) => !!v });
  return !!st.csrf;
}

function recoverSession(st, err) {
  let renewed = false;
  if (err === 'expired') {
    const payload = '{}';
    const r = rawRequest(
      'POST',
      BASE_URL + '/v2/session/renew',
      payload,
      buildHeaders(st, 'POST', null, payload)
    );
    absorb(st, r);
    renewed = ok2xx(r);
  }
  if (!renewed) renewed = login(st);
  if (renewed && st.cartId) {
    const payload = '{}';
    const rec = rawRequest(
      'POST',
      BASE_URL + '/v2/carts/' + st.cartId + '/recover',
      payload,
      buildHeaders(st, 'POST', null, payload)
    );
    absorb(st, rec);
    check(rec, { 'session: cart recover accepted': (r) => ok2xx(r) });
  }
  return renewed;
}

function authed(st, method, pathOrUrl, body, extra) {
  const url = String(pathOrUrl).indexOf('http') === 0 ? String(pathOrUrl) : BASE_URL + pathOrUrl;
  const payload =
    body === undefined || body === null ? null : typeof body === 'string' ? body : JSON.stringify(body);
  let headers = buildHeaders(st, method, extra, payload);
  let res = rawRequest(method, url, payload, headers);
  absorb(st, res);

  let throttle = 0;
  while (res.status === 429 && throttle < 4) {
    const ra = parseFloat(header(res, 'Retry-After') || '1');
    sleep(Math.max(1, isFinite(ra) ? ra : 1));
    throttle++;
    headers = buildHeaders(st, method, extra, payload);
    res = rawRequest(method, url, payload, headers);
    absorb(st, res);
  }

  if (res.status === 401) {
    const err = errorOf(res);
    if (err === 'denied') {
      check(res, { 'auth: 401 denied is not expiry (assertion must fail)': (r) => r.status !== 401 });
      return res;
    }
    if (recoverSession(st, err)) {
      let retryExtra = extra;
      if (extra && extra['If-Match'] && st.cartId) {
        const reread = rawRequest(
          'GET',
          BASE_URL + '/v2/carts/' + st.cartId,
          null,
          buildHeaders(st, 'GET', null, null)
        );
        absorb(st, reread);
        const t = extractEtag(reread);
        if (t) {
          retryExtra = {};
          const keys = Object.keys(extra);
          for (let i = 0; i < keys.length; i++) retryExtra[keys[i]] = extra[keys[i]];
          retryExtra['If-Match'] = t;
        }
      }
      headers = buildHeaders(st, method, retryExtra, payload);
      res = rawRequest(method, url, payload, headers); // retry interrupted operation once
      absorb(st, res);
    }
  }
  return res;
}

/* -------------------------------------------------------------- catalog ops */

function collectProducts(res) {
  let out = [];
  const b = jsonOf(res);
  if (b) {
    const d = b.data || b;
    if (Array.isArray(d.products)) out = out.concat(d.products);
    else if (d.product) out.push(d.product);
    else if (Array.isArray(b.products)) out = out.concat(b.products);
  }
  if (out.length === 0 && res && typeof res.body === 'string' && res.body.indexOf('<') >= 0) {
    const html = res.body.replace(/<!--[\s\S]*?-->/g, '');
    const re = /data-product-id\s*=\s*["']([^"']+)["'][^>]*?data-variant-id\s*=\s*["']([^"']+)["']/gi;
    let m;
    while ((m = re.exec(html)) !== null) {
      const inStock = !/data-in-stock\s*=\s*["'](false|0)["']/i.test(m[0]);
      out.push({ id: m[1], variants: [{ id: m[2], in_stock: inStock }] });
    }
  }
  return out;
}

function nextLink(res, refUrl) {
  const b = jsonOf(res) || {};
  let next = b.next;
  if (next === undefined && b.data) next = b.data.next;
  if (next === undefined || next === null || next === '') return null;
  return absUrl(next, refUrl);
}

// Works for forward and reverse catalog orderings; never guesses ids or cursors.
function pickVariant(st) {
  let products = [];
  const full = authed(st, 'GET', '/v2/catalog');
  if (ok2xx(full)) products = collectProducts(full);

  if (products.length === 0) {
    let url = BASE_URL + '/v2/catalog/page';
    for (let page = 0; page < 3 && url; page++) {
      const r = authed(st, 'GET', url);
      if (!ok2xx(r)) break;
      products = products.concat(collectProducts(r));
      url = nextLink(r, url);
    }
  }

  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const vs = p && Array.isArray(p.variants) ? p.variants : [];
    for (let k = 0; k < vs.length; k++) {
      if (p.id && vs[k] && vs[k].id && vs[k].in_stock === true) {
        return { product_id: p.id, variant_id: vs[k].id };
      }
    }
  }
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const vs = p && Array.isArray(p.variants) ? p.variants : [];
    if (p.id && vs.length > 0 && vs[0].id) return { product_id: p.id, variant_id: vs[0].id };
  }
  return null;
}

/* ---------------------------------------------------------- reservation ops */

function needsReservation(res) {
  if (!res || (res.status !== 400 && res.status !== 409 && res.status !== 422)) return false;
  const b = jsonOf(res);
  if (!b) return false;
  return JSON.stringify(b).toLowerCase().indexOf('reservation') >= 0;
}

function reserve(st) {
  const res = authed(st, 'POST', '/v2/reservations', { cart_id: st.cartId });
  if (res.status !== 202) return null;
  const b = jsonOf(res) || {};
  const statusUrl = absUrl(b.status_url, BASE_URL + '/v2/reservations');
  if (!statusUrl) return null;
  for (let i = 0; i < 5; i++) {
    sleep(0.06); // >= 50ms apart, at most 5 polls
    const poll = authed(st, 'GET', statusUrl);
    const pb = jsonOf(poll) || {};
    if (pb.status === 'ready' && pb.reservation_id) return pb.reservation_id;
    if (pb.status === 'failed') return null;
  }
  return null;
}

/* ------------------------------------------------------------------ journey */

export default function () {
  const st = {
    username: 'bench-' + (((__VU - 1) % 16) + 1),
    csrf: null,
    cartId: null,
  };

  if (!login(st)) return;

  const pick = pickVariant(st);
