  const create = authed(st, 'POST', '/v2/carts', {
    product_id: pick.product_id,
    variant_id: pick.variant_id,
  });
  check(create, { 'cart: created 201': (r) => r.status === 201 });
  const cb = jsonOf(create) || {};
  const cartId = cb.id || (cb.data && cb.data.id) || (cb.cart && cb.cart.id);
  if (!check(cartId, { 'cart: id returned (never guessed)': (v) => !!v })) return;
  st.cartId = String(cartId);
  cartsCreated.add(1);

