  let etag = extractEtag(create);
  if (!etag) {
    const initialRead = authed(st, 'GET', '/v2/carts/' + st.cartId);
    etag = extractEtag(initialRead);
  }
  if (!check(etag, { 'setup: initial revision (ETag) extracted': (v) => !!v })) return;

  // behavior: conditional update; one scheduled conflict -> re-read -> same payload once.
  const payload = JSON.stringify({ quantity: QUANTITY });
  let mutations = 0;
  let retried = false;
  let retryPayload = null;
  let retryTag = null;
  let staleTag = etag;

  let patch = authed(st, 'PATCH', '/v2/carts/' + st.cartId, payload, { 'If-Match': etag });
  check(patch, {
    'behavior: first conditional PATCH answered (412 or 2xx)': (r) =>
      r.status === 412 || (r.status >= 200 && r.status < 300),
  });

  if (patch.status === 412) {
    etagConflicts.add(1);
    check(patch, { 'behavior: stale If-Match rejected with 412': (r) => r.status === 412 });
    const reread = authed(st, 'GET', '/v2/carts/' + st.cartId);
    check(reread, { 'behavior: conflict triggers cart re-read (2xx)': (r) => ok2xx(r) });
    const fresh = extractEtag(reread);
    check(fresh, { 'behavior: fresh revision extracted on re-read': (v) => !!v });
    if (fresh) {
      retried = true;
      retryPayload = payload; // byte-identical payload
      retryTag = fresh;
      patch = authed(st, 'PATCH', '/v2/carts/' + st.cartId, retryPayload, { 'If-Match': fresh });
      if (ok2xx(patch)) etagConflictRecoveries.add(1);
