        ? pb.quantity
        : pb.cart && pb.cart.quantity !== undefined
        ? pb.cart.quantity
        : pb.data && pb.data.quantity !== undefined
        ? pb.data.quantity
        : null;
    if (q !== null && q !== undefined) {
