    const rid = reserve(st);
    check(rid, { 'order: ready reservation_id obtained': (v) => !!v });
    if (rid) {
      const reread = authed(st, 'GET', '/v2/carts/' + st.cartId);
      const t = extractEtag(reread) || orderTag;
      orderPayload = JSON.stringify({ cart_id: st.cartId, reservation_id: rid });
