  check(ob.accepted, { 'order: accepted === true (200 accepted:false is failure)': (v) => v === true });
  check(ob.id, { 'order: id returned': (v) => !!v });

  const committed = order.status === 201 && ob.accepted === true && !!ob.id ? 1 : 0;
  if (committed === 1) ordersCommitted.add(1);
  else businessFailures.add(1);

  check(mutations, { 'safety: exactly one cart mutation committed': (n) => n === 1 });
  check(committed, { 'safety: exactly one order committed per journey': (n) => n === 1 });
  check(1, { 'safety: exactly one cart created per journey': (n) => n === 1 });
}
