import html
import itertools
import os
import re
import time
import uuid
from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

HOST = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
USER_COUNT = 2
ITERATIONS_PER_USER = 2
QUANTITY = 2
TOTAL_JOURNEYS = USER_COUNT * ITERATIONS_PER_USER
MAX_SECONDS = 180.0
REQ_TIMEOUT = 20

STATE = {"claimed": 0, "done": 0}
ACCOUNT_SEQ = itertools.count()


def claim_journey():
    if STATE["claimed"] >= TOTAL_JOURNEYS:
        return False
    STATE["claimed"] += 1
    return True


class JourneyError(Exception):
    pass


_COMMENT_RE = re.compile(r"<!--.*?-->", re.S)
_INPUT_RE = re.compile(r"<input\b[^>]*>", re.I | re.S)
_ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))"""
)
_DISABLED_RE = re.compile(r"\bdisabled\b", re.I)


def extract_csrf(markup):
    """input[name=csrf] with decoys, comments and attribute-order variants."""
    text = _COMMENT_RE.sub(" ", markup or "")
    candidates = []
    for tag in _INPUT_RE.findall(text):
        attrs = {}
        for m in _ATTR_RE.finditer(tag):
            raw = m.group(2)
            if raw is None:
                raw = m.group(3)
            if raw is None:
                raw = m.group(4)
            attrs[m.group(1).lower()] = html.unescape(raw or "")
        if attrs.get("name") != "csrf":
            continue
        if _DISABLED_RE.search(tag):
            continue
        if attrs.get("type", "").lower() in ("submit", "button", "image"):
            continue
        marker = " ".join(
            [attrs.get("id", ""), attrs.get("class", ""), attrs.get("data-role", "")]
        ).lower()
        if "decoy" in marker or attrs.get("data-decoy", "").lower() in ("1", "true", "yes"):
            continue
        if any("decoy" in k for k in attrs):
            continue
        value = attrs.get("value", "")
        if not value:
            continue
        candidates.append((attrs.get("type", "").lower() == "hidden", value))
    if not candidates:
        return None
    for hidden, value in candidates:
        if hidden:
            return value
    return candidates[0][1]


def find_quantity(data):
    if not isinstance(data, dict):
        return None
    for key in ("quantity",):
        if isinstance(data.get(key), int):
            return data[key]
    for key in ("data", "cart"):
        inner = data.get(key)
        if isinstance(inner, dict):
            got = find_quantity(inner)
            if got is not None:
                return got
    items = data.get("items")
    if isinstance(items, list):
        for item in items:
            if isinstance(item, dict) and isinstance(item.get("quantity"), int):
                return item["quantity"]
    return None


class ShopUser(HttpUser):
    host = HOST
    wait_time = constant(0.05)

    # ---------------- lifecycle ----------------

    def on_start(self):
        idx = next(ACCOUNT_SEQ)
        self.account = "bench-%d" % (idx % 16 + 1)
        self.password = "bench"
        self.csrf = None
        self.cart_id = None
        self.iterations_done = 0
        self._form_token = None

    @task
    def run_journey(self):
        if self.iterations_done >= ITERATIONS_PER_USER or not claim_journey():
            raise StopUser()
        self.iterations_done += 1
        try:
            self._journey()
        except JourneyError:
            pass
        except StopUser:
            raise
        except Exception as exc:  # truthful sample for unexpected internal faults
            self._fail_sample("journey:unexpected", repr(exc))
        finally:
            STATE["done"] += 1
        if self.iterations_done >= ITERATIONS_PER_USER:
            raise StopUser()

    # ---------------- plumbing ----------------

    def _fail_sample(self, name, message):
        self.environment.events.request.fire(
            request_type="ASSERT",
            name=name,
            response_time=0,
            response_length=0,
            exception=AssertionError(message),
            context={},
            start_time=time.time(),
        )

    def _headers(self, extra=None):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if extra:
            headers.update(extra)
        return headers

    @staticmethod
    def _snippet(resp):
        try:
            return (resp.text or "")[:160]
        except Exception:
            return "<no body>"

    @staticmethod
    def _json(resp):
        try:
            data = resp.json()
        except Exception:
            return {}
        return data if isinstance(data, dict) else {}

    def _error_code(self, resp):
        return str(self._json(resp).get("error") or "")

    def _request(self, method, path, name, body=None, headers=None, ok=(200,), check=None):
        with self.client.request(
            method,
            path,
            name=name,
            json=body,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
            timeout=REQ_TIMEOUT,
        ) as resp:
            if getattr(resp, "error", None) or resp.status_code == 0:
                return resp
            problem = None
            if resp.status_code not in ok:
                problem = "unexpected status %s: %s" % (resp.status_code, self._snippet(resp))
            elif check is not None:
                try:
                    problem = check(resp)
                except Exception as exc:
                    problem = "invalid response: %r" % exc
            if problem:
                resp.failure(problem)
            else:
                resp.success()
            return resp

    def _must(self, resp, ok):
        if resp.status_code not in ok:
            raise JourneyError("status %s" % resp.status_code)
        return resp

    def _auth_request(self, method, path, name, body=None, extra=None, ok=(200,), check=None):
        """Authenticated call with bounded 401 expiry/revocation recovery."""

        def combined(resp):
            if resp.status_code == 401:
                if self._error_code(resp) == "denied":
                    return "401 denied is not an expiry"
                return None  # expected scheduled expiry, recovered below
            return check(resp) if check else None

        headers = self._headers(extra)
        resp = self._request(
            method, path, name, body=body, headers=headers,
            ok=tuple(ok) + (401,), check=combined,
        )
        if resp.status_code != 401:
            return resp
        if self._error_code(resp) == "denied":
            raise JourneyError("denied")
        self._recover(self._error_code(resp))
        headers = self._headers(extra)
        if "If-Match" in headers and self.cart_id:
            tag, _ = self._read_cart(required=False)
            if tag:
                headers["If-Match"] = tag
        # retry only the interrupted operation, exactly once
        return self._request(method, path, name, body=body, headers=headers, ok=ok, check=check)

    def _recover(self, error):
        if error == "expired":
            resp = self._request(
                "POST", "/v2/session/renew", "POST /v2/session/renew",
                body={}, headers=self._headers(), ok=(200,),
            )
            data = self._json(resp)
            if resp.status_code == 200 and data.get("csrf"):
                self.csrf = data["csrf"]
            elif resp.status_code != 200:
                self._login()
        else:  # revoked session (or unknown): fresh form + login
            self._login()
        if self.cart_id:
            resp = self._request(
                "POST", "/v2/carts/%s/recover" % self.cart_id, "POST /v2/carts/{id}/recover",
                body={}, headers=self._headers(), ok=(200, 202),
            )
            data = self._json(resp)
            if data.get("csrf"):
                self.csrf = data["csrf"]

    # ---------------- protocol steps ----------------

    def _login(self):
        self._form_token = None

        def check_form(resp):
            self._form_token = extract_csrf(resp.text)
            return None if self._form_token else "login form: input[name=csrf] not found"

        resp = self._request("GET", "/v2/login-form", "GET /v2/login-form", ok=(200,), check=check_form)
        self._must(resp, (200,))
        token = self._form_token
        if not token:
            raise JourneyError("no login csrf")

        def check_login(r):
            if r.status_code == 302 and not r.headers.get("Location"):
                return "302 without Location"
            return None

        resp = self._request(
            "POST", "/v2/login", "POST /v2/login",
            body={"username": self.account, "password": self.password, "csrf": token},
            ok=(200, 302), check=check_login,
        )
        self._must(resp, (200, 302))
        if resp.status_code == 302:
            target = urljoin(HOST + "/v2/login", resp.headers["Location"])
            resp = self._request("GET", target, "GET /v2/login (location)", ok=(200,))
            self._must(resp, (200,))
        data = self._json(resp)
        self.csrf = data.get("csrf") or token

    @staticmethod
    def _extract_products(data):
        if not isinstance(data, dict):
            return []
        inner = data.get("data")
        for container in (inner, data):
            if isinstance(container, dict):
                if isinstance(container.get("products"), list):
                    return [p for p in container["products"] if isinstance(p, dict)]
                if isinstance(container.get("product"), dict):
                    return [container["product"]]
        return []

    def _products(self):
        resp = self._request("GET", "/v2/catalog", "GET /v2/catalog", ok=(200, 404, 405))
        products = []
        if resp.status_code == 200:
            products = self._extract_products(self._json(resp))
        if products:
            return products
        url = HOST + "/v2/catalog/page"
        for _ in range(3):  # at most 3 pages
            resp = self._request("GET", url, "GET /v2/catalog/page", ok=(200,))
            self._must(resp, (200,))
            data = self._json(resp)
            products.extend(self._extract_products(data))
            nxt = data.get("next")
            if not nxt or not isinstance(nxt, str):
                break
            url = urljoin(url, nxt)
        return products

    @staticmethod
    def _choose(products):
        for in_stock_only in (True, False):
            for product in products:
                pid = product.get("id")
                if pid is None:
                    continue
                for variant in product.get("variants") or []:
                    if not isinstance(variant, dict) or variant.get("id") is None:
                        continue
                    if in_stock_only and not variant.get("in_stock"):
                        continue
                    return pid, variant["id"]
        return None, None

    def _read_cart(self, required=True):
        resp = self._request(
            "GET", "/v2/carts/%s" % self.cart_id, "GET /v2/carts/{id}", ok=(200,)
        )
        if resp.status_code != 200:
            if required:
                raise JourneyError("cart re-read failed")
            return None, {}
        return resp.headers.get("ETag"), self._json(resp)

    def _create_cart(self, product_id, variant_id):
        def check(resp):
            return None if self._json(resp).get("id") else "cart id missing"

        resp = self._auth_request(
            "POST", "/v2/carts", "POST /v2/carts",
            body={"product_id": product_id, "variant_id": variant_id},
            ok=(201,), check=check,
        )
        self._must(resp, (201,))
        data = self._json(resp)
        self.cart_id = data["id"]
        if data.get("csrf"):
            self.csrf = data["csrf"]
        etag = resp.headers.get("ETag")
        if not etag:
            etag, _ = self._read_cart()
        if not etag:
            self._fail_sample("cart:initial-etag", "no initial ETag extracted")
            raise JourneyError("no initial etag")
        return etag

    def _update_quantity(self, etag):
        path = "/v2/carts/%s" % self.cart_id
        payload = {"quantity": QUANTITY}  # identical payload on the conditional retry
        resp = self._auth_request(
            "PATCH", path, "PATCH /v2/carts/{id}",
            body=payload, extra={"If-Match": etag}, ok=(200, 202, 412),
        )
        if resp.status_code == 412:
            fresh, _ = self._read_cart()  # re-read the current revision
            if not fresh:
                self._fail_sample("cart:reread-etag", "no ETag after 412 re-read")
                raise JourneyError("no etag after 412")
            resp = self._auth_request(
                "PATCH", path, "PATCH /v2/carts/{id} (retry)",
                body=payload, extra={"If-Match": fresh}, ok=(200, 202),
            )
            self._must(resp, (200, 202))
            return resp.headers.get("ETag") or fresh
        self._must(resp, (200, 202))
        return resp.headers.get("ETag") or etag

    def _verify_and_refresh(self, etag):
        tag, data = self._read_cart()
        quantity = find_quantity(data)
        if quantity is not None and quantity != QUANTITY:
            self._fail_sample(
                "cart:quantity", "committed quantity %r != %d" % (quantity, QUANTITY)
            )
            raise JourneyError("payload not preserved")
        return tag or etag

    def _order(self, etag):
        key = "%s-%s" % (self.cart_id, uuid.uuid4().hex)  # unique per cart, stable on retry
        body = {"cart_id": self.cart_id}

        def check(resp):
            data = self._json(resp)
            if data.get("accepted") is not True:
                return "order not accepted"
            if not data.get("id"):
                return "order id missing"
            return None

        extra = {"Idempotency-Key": key, "If-Match": etag}
        resp = self._auth_request(
            "POST", "/v2/orders", "POST /v2/orders",
            body=body, extra=extra, ok=(201, 412), check=check,
        )
        if resp.status_code == 412:
            fresh, _ = self._read_cart()
            if not fresh:
                self._fail_sample("order:reread-etag", "no ETag for order retry")
                raise JourneyError("no etag for order retry")
            extra = {"Idempotency-Key": key, "If-Match": fresh}
            resp = self._auth_request(
                "POST", "/v2/orders", "POST /v2/orders (retry)",
                body=body, extra=extra, ok=(201,), check=check,
            )
        self._must(resp, (201,))
        data = self._json(resp)
        if data.get("csrf"):
            self.csrf = data["csrf"]
        if data.get("accepted") is not True:
            raise JourneyError("order not accepted")

    def _journey(self):
        self.csrf = None
        self.cart_id = None
        self._login()
        product_id, variant_id = self._choose(self._products())
        if product_id is None:
            self._fail_sample("catalog:select", "no product/variant available in catalog")
            raise JourneyError("no product")
        etag = self._create_cart(product_id, variant_id)
        etag = self._update_quantity(etag)
        etag = self._verify_and_refresh(etag)
        self._order(etag)


class EtagJourneyShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._started = None
        self._done_at = None

    def tick(self):
        now = time.monotonic()
        if self._started is None:
            self._started = now
        if STATE["done"] >= TOTAL_JOURNEYS:
            if self._done_at is None:
                self._done_at = now
            if now - self._done_at >= 1.0:
                return None
            return (0, USER_COUNT)
        if now - self._started > MAX_SECONDS:
            return None
        return (USER_COUNT, USER_COUNT)
