      .exec(s -> s.set("username", "bench-" + (int) (((s.userId() - 1L) % 16L) + 1L)))
      .repeat(2).on(journey());

  {
    setUp(scn.injectOpen(atOnceUsers(2)))
        .protocols(protocol)
        .assertions(
            global().failedRequests().count().is(0L),
            global().successfulRequests().count().gte(8L));
  }

  /* ------------------------------------------------------------------ */
  /* journey                                                            */
  /* ------------------------------------------------------------------ */

  private static ChainBuilder journey() {
    return exec(s -> s
            .remove("cartId").remove("cartIdJson").remove("cartIdRaw")
            .remove("etag").remove("etagFix").remove("orderId").remove("accepted")
            .remove("productId").remove("variantId").remove("productIdJson").remove("variantIdJson")
            .remove("fbPid").remove("fbVid")
            .remove("products").remove("productOne").remove("nextUrl").remove("nextRaw")
            .remove("pageDone").remove("pageUrl")
            .remove("st").remove("err").remove("recoverErr").remove("renewSt")
            .remove("loc").remove("formBody"))
        .exec(login("login"))
        .exec(catalog())
        .exec(createCart())
        .exec(patchQuantity())
        .pause(Duration.ofMillis(2100))
        .exec(checkout());
  }

  /* ------------------------------------------------------------------ */
  /* authentication                                                     */
  /* ------------------------------------------------------------------ */

  private static ChainBuilder login(String tag) {
    return exec(s -> s.remove("loc").remove("formBody"))
        .exec(http(tag + "-form").get("/v2/login-form")
            .check(status().is(200), bodyString().saveAs("formBody")))
        .exec(s -> s.set("csrf", csrfFromForm(s)))
        .exec(http(tag + "-submit").post("/v2/login")
            .body(StringBody(s -> "{\"username\":\"" + esc(str(s, "username"))
                + "\",\"password\":\"bench\",\"csrf\":\"" + esc(str(s, "csrf")) + "\"}"))
            .asJson()
            .check(status().in(200, 302),
                header("Location").optional().saveAs("loc"),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.user").optional().saveAs("authUser")))
        .doIf(s -> hasStr(s, "loc")).then(
            exec(http(tag + "-continue").get("#{loc}")
                .check(status().is(200),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.user").optional().saveAs("authUser")))
                .exec(s -> s.remove("loc")));
  }

  private static ChainBuilder renew() {
    return exec(s -> s.remove("renewSt"))
        .exec(http("session-renew").post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .asJson()
            .check(status().in(200, 201, 202, 401, 403),
                status().saveAs("renewSt"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
  }

  private static ChainBuilder recoverCart() {
    return doIf(s -> hasStr(s, "cartId")).then(
        exec(http("cart-recover").post("/v2/carts/#{cartId}/recover")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .asJson()
            .check(status().in(200, 201, 202),
