            exec(http("catalog-retry").get("/v2/catalog")
                .check(status().is(200),
                    jsonPath("$.data.products").optional().saveAs("products"),
                    jsonPath("$.data.product").optional().saveAs("productOne"))))
        .exec(s -> pick(s))
        .exec(s -> s.remove("nextUrl").remove("nextRaw").remove("pageDone"))
        .repeat(3).on(
            doIf(s -> !hasStr(s, "productId") && !s.contains("pageDone")).then(page()))
        .exec(s -> fallbackPick(s));
