  private static ChainBuilder page() {
    return exec(s -> s.remove("nextRaw").remove("products").remove("productOne")
            .set("pageUrl", hasStr(s, "nextUrl") ? str(s, "nextUrl") : "/v2/catalog/page"))
        .exec(http("catalog-page").get("#{pageUrl}")
            .check(status().in(200, 401),
                status().saveAs("st"),
