                jsonPath("$.error").optional().saveAs("err"),
                jsonPath("$.data.products").optional().saveAs("products"),
                jsonPath("$.data.product").optional().saveAs("productOne"),
                jsonPath("$.next").optional().saveAs("nextRaw"),
                jsonPath("$.data.next").optional().saveAs("nextRaw")))
        .doIf(s -> recoverable(s)).then(recovery())
        .doIf(s -> st(s) == 401 && !"denied".equals(err(s))).then(
            exec(http("catalog-page-retry").get("#{pageUrl}")
                .check(status().is(200),
                    jsonPath("$.data.products").optional().saveAs("products"),
                    jsonPath("$.data.product").optional().saveAs("productOne"),
                    jsonPath("$.next").optional().saveAs("nextRaw"),
                    jsonPath("$.data.next").optional().saveAs("nextRaw"))))
        .exec(s -> pick(s))
        .exec(s -> {
          if (hasStr(s, "nextRaw")) {
            return s.set("nextUrl", str(s, "nextRaw"));
