      return exec(http(name).post("/v2/orders")
          .header("X-CSRF-Token", "#{csrf}")
          .header("Idempotency-Key", "ord-#{cartId}")
          .header("If-Match", "#{etag}")
          .body(StringBody(s -> "{\"cart_id\":" + str(s, "cartIdJson") + "}"))
          .asJson()
          .check(status().in(200, 201),
              status().saveAs("st"),
              jsonPath("$.accepted").is(true),
              jsonPath("$.accepted").optional().saveAs("accepted"),
