          .header("X-CSRF-Token", "#{csrf}")
          .header("Idempotency-Key", "ord-#{cartId}")
          .header("If-Match", "#{etag}")
          .body(StringBody(s -> "{\"cart_id\":" + str(s, "cartIdJson") + "}"))
          .asJson()
          .check(status().in(200, 201, 412, 428),
              status().saveAs("st"),
              jsonPath("$.error").optional().not("denied"),
              jsonPath("$.error").optional().saveAs("err"),
              jsonPath("$.accepted").optional().is(true),
              jsonPath("$.accepted").optional().saveAs("accepted"),
              jsonPath("$.id").optional().saveAs("orderId"),
              jsonPath("$.csrf").optional().saveAs("csrf")));
    }
    return exec(http(name).post("/v2/orders")
        .header("X-CSRF-Token", "#{csrf}")
        .header("Idempotency-Key", "ord-#{cartId}")
        .header("If-Match", "#{etag}")
        .body(StringBody(s -> "{\"cart_id\":" + str(s, "cartIdJson") + "}"))
        .asJson()
        .check(status().in(200, 201, 401, 412, 428),
            status().saveAs("st"),
            jsonPath("$.error").optional().not("denied"),
            jsonPath("$.error").optional().saveAs("err"),
            jsonPath("$.accepted").optional().is(true),
            jsonPath("$.accepted").optional().saveAs("accepted"),
            jsonPath("$.id").optional().saveAs("orderId"),
            jsonPath("$.csrf").optional().saveAs("csrf")));
  }

  /* ------------------------------------------------------------------ */
  /* state helpers                                                      */
  /* ------------------------------------------------------------------ */

  private static boolean recoverable(Session s) {
    String e = err(s);
    return st(s) == 401 && ("expired".equals(e) || "session".equals(e));
  }

  private static boolean retryCode(Session s) {
    int c = st(s);
    return c == 401 || c == 412 || c == 428;
