    }
    List<Object> items = new ArrayList<>();
    Object raw = s.contains("products") ? s.get("products") : null;
    if (raw instanceof List) {
      items.addAll((List<?>) raw);
    }
    Object one = s.contains("productOne") ? s.get("productOne") : null;
    if (one instanceof Map) {
      items.add(one);
    }
    for (Object p : items) {
      if (!(p instanceof Map)) {
        continue;
      }
      Map<?, ?> pm = (Map<?, ?>) p;
      Object pid = pm.get("id");
      Object vs = pm.get("variants");
      if (pid == null || !(vs instanceof List)) {
        continue;
      }
      for (Object v : (List<?>) vs) {
        if (!(v instanceof Map)) {
          continue;
        }
        Map<?, ?> vm = (Map<?, ?>) v;
        Object vid = vm.get("id");
        if (vid == null) {
