  private static int intOf(Session s, String k) {
    if (!s.contains(k)) {
      return 0;
    }
    Object v = s.get(k);
    if (v instanceof Number) {
      return ((Number) v).intValue();
    }
    try {
      return Integer.parseInt(String.valueOf(v));
    } catch (RuntimeException e) {
