  private static String esc(String in) {
    StringBuilder b = new StringBuilder();
    for (int i = 0; i < in.length(); i++) {
      char c = in.charAt(i);
      if (c == '"') {
        b.append("\\\"");
      } else if (c == '\\') {
        b.append("\\\\");
      } else if (c == '\n') {
        b.append("\\n");
      } else if (c == '\r') {
        b.append("\\r");
      } else if (c == '\t') {
        b.append("\\t");
      } else if (c < 0x20) {
        b.append(' ').append(Integer.toHexString((int) c));
      } else {
        b.append(c);
      }
    }
    return b.toString();
