  /* ------------------------------------------------------------------ */

  private static final Pattern COMMENT = Pattern.compile("(?s)<!--.*?-->");
  private static final Pattern SCRIPT = Pattern.compile("(?is)<script\\b.*?</script>");
  private static final Pattern TEMPLATE = Pattern.compile("(?is)<template\\b.*?</template>");
  private static final Pattern NOSCRIPT = Pattern.compile("(?is)<noscript\\b.*?</noscript>");
  private static final Pattern FORM = Pattern.compile("(?is)<form\\b([^>]*)>(.*?)</form>");
  private static final Pattern INPUT = Pattern.compile("(?is)<input\\b[^>]*>");
  private static final Pattern ATTR = Pattern.compile(
      "(?is)([a-z_:][-a-z0-9_:.]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`]+))");

  private static String csrfFromForm(Session s) {
    String found = extractCsrf(str(s, "formBody"));
    return found == null ? "" : found;
