  private static String extractCsrf(String html) {
    if (html == null || html.isEmpty()) {
      return null;
    }
    String doc = COMMENT.matcher(html).replaceAll(" ");
    doc = SCRIPT.matcher(doc).replaceAll(" ");
    doc = TEMPLATE.matcher(doc).replaceAll(" ");
    doc = NOSCRIPT.matcher(doc).replaceAll(" ");
    Matcher forms = FORM.matcher(doc);
    String best = null;
    while (forms.find()) {
      String attrs = forms.group(1).toLowerCase();
      String token = pickFromInputs(forms.group(2));
      if (token == null) {
        continue;
      }
      if (attrs.contains("/v2/login")) {
        return token;
      }
      if (best == null) {
        best = token;
      }
    }
    if (best != null) {
      return best;
    }
    return pickFromInputs(doc);
  }

  private static String pickFromInputs(String fragment) {
    Matcher tags = INPUT.matcher(fragment);
    String fallback = null;
    while (tags.find()) {
      String tag = tags.group();
      String low = tag.toLowerCase();
      Map<String, String> attrs = attrs(tag);
      String name = attrs.get("name");
      if (name == null || !"csrf".equals(name.trim())) {
        continue;
      }
      String value = attrs.get("value");
      if (value == null || value.trim().isEmpty()) {
        continue;
      }
      boolean decoy = low.contains("decoy") || low.contains("fake") || low.contains("trap")
          || low.contains("dummy") || low.contains("bogus") || low.contains("disabled");
      if (decoy) {
        continue;
      }
      String type = attrs.get("type");
      String clean = value.trim();
      if (type == null || "hidden".equalsIgnoreCase(type.trim())) {
        return clean;
      }
      if (fallback == null) {
        fallback = clean;
      }
    }
    return fallback;
  }

  private static Map<String, String> attrs(String tag) {
    Map<String, String> m = new HashMap<>();
    Matcher a = ATTR.matcher(tag);
    while (a.find()) {
      String k = a.group(1).toLowerCase();
      String v = a.group(2) != null ? a.group(2)
          : (a.group(3) != null ? a.group(3) : (a.group(4) != null ? a.group(4) : ""));
      if (!m.containsKey(k)) {
        m.put(k, unescape(v));
      }
    }
    return m;
  }

  private static String unescape(String v) {
    return v.replace("&quot;", "\"").replace("&#34;", "\"")
        .replace("&#39;", "'").replace("&#x27;", "'").replace("&apos;", "'")
        .replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&");
  }
