// k6 1.0.0 — Public shop: recover from session expiry between cart creation and checkout.
// Execution contract: users=2, iterations=2 (iterations PER user), mode=expiry.
// Invariants: one fresh login + one cart + one committed order per journey, no extra carts,
// stable Idempotency-Key per cart, at most one recovery + one retry per interrupted operation.

import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Counter, Rate } from 'k6/metrics';

/* ------------------------------------------------------------------ config */

function envInt(names, dflt) {
  for (let i = 0; i < names.length; i++) {
    const raw = __ENV[names[i]];
    if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
      const n = parseInt(String(raw), 10);
      if (!isNaN(n) && n > 0) return n;
    }
  }
  return dflt;
}

function envFloat(names, dflt) {
  for (let i = 0; i < names.length; i++) {
    const raw = __ENV[names[i]];
    if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
      const n = parseFloat(String(raw));
      if (!isNaN(n) && n >= 0) return n;
    }
  }
  return dflt;
}

const BASE = String(__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = __ENV.PASSWORD || 'bench';
const POOL = 16;                                   // bench-1 .. bench-16
const USERS = envInt(['USERS', 'K6_VUS', 'VUS'], 2);
const ITERATIONS = envInt(['ITERATIONS', 'K6_ITERATIONS'], 2);
const THINK = envFloat(['THINK_TIME', 'EXPIRY_GAP'], 1.2); // cart -> checkout window (>2s total)

const MAX_RENEW = 4;        // bounded reauthentication per journey
const MAX_RELOGIN = 2;      // bounded fresh form/login per journey
const MAX_429_RETRIES = 4;  // scheduled throttle retries
const MAX_ORDER_CALLS = 3;  // initial + one 412 retry + one post-recovery retry
const MAX_CART_CALLS = 2;   // never build a second cart

/* ----------------------------------------------------------------- metrics */

const businessFailure = new Rate('business_failure');       // one point per raw /v2/work response
const journeySuccess = new Rate('journey_success');
const ordersCommitted = new Counter('orders_committed');
const cartsCreated = new Counter('carts_created');
const expiryRecognized = new Counter('expiry_recognized');
const renewCalls = new Counter('session_renew_calls');
const reloginCalls = new Counter('fresh_login_calls');
const recoverCalls = new Counter('cart_recover_calls');
const resumedOps = new Counter('interrupted_operation_retries');

export const options = {
  vus: USERS,
  iterations: ITERATIONS,          // per-VU iterations (non-workload counts are per user)
  discardResponseBodies: false,
  tags: { test_mode: __ENV.MODE || 'expiry' },
  thresholds: {
    business_failure: ['rate==0'],
    journey_success: ['rate==1'],
    checks: ['rate==1'],
  },
};

/* ------------------------------------------------------------- small utils */

function absolute(u) {
  if (u === null || u === undefined) return null;
  const s = String(u).trim();
  if (s === '') return null;
  if (/^https?:\/\//i.test(s)) return s.indexOf(BASE) === 0 ? s : null; // never leave the origin
  if (s.charAt(0) === '/') return BASE + s;
  return BASE + '/' + s;
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const want = String(name).toLowerCase();
  for (const k in res.headers) {
    if (String(k).toLowerCase() === want) {
      const v = res.headers[k];
      return Array.isArray(v) ? v[0] : v;
    }
  }
  return null;
}

function body(res) {
  if (!res || !res.body) return null;
  try {
    const j = res.json();
    return j && typeof j === 'object' ? j : null;
  } catch (e) {
    return null;
  }
}

function errCode(res) {
  const j = body(res);
  if (!j) return null;
  if (typeof j.error === 'string') return j.error;
  if (j.error && typeof j.error.code === 'string') return j.error.code;
  if (typeof j.code === 'string') return j.code;
  return null;
}

function ok2xx(res) {
  return !!res && res.status >= 200 && res.status < 300;
}

function deadResponse() {
  return { status: 0, headers: {}, body: null, json: function () { return null; } };
}

/* --------------------------------------------------------------- HTML form */

function stripNoise(html) {
  return String(html)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript\b[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<template\b[\s\S]*?<\/template>/gi, ' ');
}

const INPUT_RE = /<input\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;
const FORM_RE = /<form\b(?:[^>"']|"[^"]*"|'[^']*')*>[\s\S]*?<\/form>/gi;
const FORM_OPEN_RE = /<form\b(?:[^>"']|"[^"]*"|'[^']*')*>/i;
const ATTR_RE = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+)))?/g;

function attrsOf(tag) {
  const out = {};
  let m;
  ATTR_RE.lastIndex = 0;
  while ((m = ATTR_RE.exec(tag)) !== null) {
    const key = String(m[1]).toLowerCase();
    let val = '';
    if (m[2] !== undefined) val = m[2];
    else if (m[3] !== undefined) val = m[3];
    else if (m[4] !== undefined) val = m[4];
    if (!(key in out)) out[key] = val;
    if (ATTR_RE.lastIndex === m.index) ATTR_RE.lastIndex++;
  }
  return out;
}

function decodeEntities(s) {
  return String(s)
    .replace(/&#x([0-9a-fA-F]+);/g, function (_, h) { return String.fromCharCode(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (_, d) { return String.fromCharCode(parseInt(d, 10)); })
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

// Robust input[name=<field>] extraction: attribute order / quote style / unquoted values,
// decoy names, commented-out or non-input decoys, visible/disabled/marked decoys.
function pickToken(html, field, actionHint) {
  const clean = stripNoise(html || '');
  const scopes = [];
  const forms = clean.match(FORM_RE) || [];
  for (let i = 0; i < forms.length; i++) {
    const open = forms[i].match(FORM_OPEN_RE);
    const a = open ? attrsOf(open[0]) : {};
    scopes.push({ html: forms[i], action: String(a.action || '').toLowerCase(), scoped: true });
  }
  scopes.push({ html: clean, action: '', scoped: false });

  let best = null;
  let bestScore = -Infinity;
  for (let s = 0; s < scopes.length; s++) {
    const sc = scopes[s];
    let m;
    INPUT_RE.lastIndex = 0;
    while ((m = INPUT_RE.exec(sc.html)) !== null) {
      const a = attrsOf(m[0]);
      if (!a.name || String(a.name).toLowerCase() !== field) continue;
      const value = decodeEntities(a.value === undefined ? '' : a.value).trim();
      if (!value) continue;

      let score = 0;
      const type = String(a.type || '').toLowerCase();
      if (type === 'hidden') score += 6;
      else if (type === '') score += 2;
      else score -= 4;
      if (a.disabled !== undefined) score -= 20;
      if (a.readonly !== undefined) score -= 2;
      if (actionHint && sc.action && sc.action.indexOf(actionHint) >= 0) score += 8;
      if (sc.scoped) score += 1;
      for (const k in a) {
        if (/decoy|fake|dummy|bogus|trap|placeholder/i.test(k)) score -= 20;
        if (k !== 'value' && /decoy|fake|dummy|bogus|trap/i.test(String(a[k]))) score -= 12;
      }
      if (/decoy|fake|dummy|bogus|trap/i.test(value)) score -= 15;

      if (score > bestScore) {
        bestScore = score;
        best = value;
      }
    }
  }
  return best;
}

/* ------------------------------------------------------------ journey state */

let S = null;

function newState(username) {
  return {
    username: username,
    csrf: null,
    cartId: null,
    etag: null,
    idemKey: null,
    nonce: String(Date.now()) + '-' + String(Math.floor(Math.random() * 1000000000)),
    product: null,
    variant: null,
    carts: 0,
    orders: 0,
    orderId: null,
    expiries: 0,
    renewCount: 0,
    reloginCount: 0,
    checkoutStarts: 0,
    orderCalls: 0,
    cartCalls: 0,
    patchCalls: 0,
    fatal: false,
  };
}

function clearCookies() {
  try {
    const jar = http.cookieJar();
    if (jar && typeof jar.clear === 'function') {
      jar.clear();
      return;
    }
  } catch (e) { /* fall through */ }
  try {
    const jar = http.cookieJar();
    const url = BASE + '/';
    const cookies = jar.cookiesForURL(url) || {};
    for (const name in cookies) {
      try { jar.delete(url, name); } catch (e1) {
        try { jar.delete(name); } catch (e2) { /* ignore */ }
      }
    }
  } catch (e) { /* ignore */ }
