function absorb(res) {
  // Successful mutations may return a fresh csrf; retain the previous token when absent.
  if (!ok2xx(res)) return;
  const j = body(res);
  if (j && typeof j.csrf === 'string' && j.csrf.length > 0) S.csrf = j.csrf;
