// business_failure: one point per RAW /v2/work response (retries included).
// numerator = unexpected failures; expected expiry interruptions and scheduled 429 are excluded
// from the numerator but stay in the denominator.
function recordBusiness(path, res) {
  if (String(path).indexOf('/v2/work') !== 0) return;
  const code = errCode(res);
  const succeeded = res.status === 200 && body(res) && body(res).ok === true;
  const scheduled429 = res.status === 429 && header(res, 'Retry-After') !== null;
  const expectedAuthInterrupt = res.status === 401 && (code === 'expired' || code === 'session');
  const unexpected = !(succeeded || scheduled429 || expectedAuthInterrupt);
