function rawRequest(method, path, payload, headers, tag) {
  const url = absolute(path);
  if (!url) {
    check(null, { 'request stays on the target origin': function () { return false; } });
    return deadResponse();
  }
  const h = headers || {};
  let payloadStr = null;
  if (payload !== null && payload !== undefined) {
    payloadStr = JSON.stringify(payload);
    h['Content-Type'] = 'application/json';
  }
  const res = http.request(method, url, payloadStr, {
    headers: h,
    redirects: 0, // dynamic Location is followed manually, exactly once
    tags: { name: tag || 'req' },
  });
