  if (res.status >= 301 && res.status <= 308) {
    const loc = absolute(header(res, 'Location'));
    if (!check(loc, { 'login redirect Location present': function (l) { return !!l; } })) return false;
    res = rawRequest('GET', loc, null, { Accept: 'application/json' }, 'login-redirect'); // exactly once
  }

  const j = body(res);
  const good = check(res, {
    'login established session + csrf': function (r) {
      const b = body(r);
      return r.status === 200 && !!b && typeof b.csrf === 'string' && b.csrf.length > 0;
