      S.reloginCount += 1;
      reloginCalls.add(1);
      clearCookies();
      if (!login()) { S.fatal = true; return false; }
      rc = rawRequest('POST', '/v2/carts/' + S.cartId + '/recover', {}, baseHeaders(true), 'cart-recover');
