function readCartEtag() {
  if (!S.cartId) return;
  let res = rawRequest('GET', '/v2/carts/' + S.cartId, null, baseHeaders(true), 'cart-read');
  if (isAuthInterrupt(res)) {
    if (!recoverSession(res, 'cart-read')) return;
    res = rawRequest('GET', '/v2/carts/' + S.cartId, null, baseHeaders(true), 'cart-read');
  }
  const et = header(res, 'ETag');
  if (et) S.etag = et;
}

// One 412 re-read+retry, one auth recovery+retry — never more, never a checkout restart.
function authedCall(label, method, path, payload, extra) {
  extra = extra || {};
  let recovered = false;
  let preconditionRetried = false;
  let res = deadResponse();

  for (let i = 0; i < 4; i++) {
    if (extra.countKey) {
      if (S[extra.countKey] >= (extra.maxCalls || 3)) {
        check(null, { 'operation call budget respected': function () { return false; } });
        return res;
      }
      S[extra.countKey] += 1;
    }

    const h = baseHeaders(true);
    if (extra.ifMatch && S.etag) h['If-Match'] = S.etag;
    if (extra.idemKey) h['Idempotency-Key'] = extra.idemKey;

    res = rawRequest(method, path, payload, h, extra.tag || label);

    if (res.status === 412 && extra.ifMatch && !preconditionRetried) {
      preconditionRetried = true;
      readCartEtag();                       // re-read, then retry the SAME payload once
      continue;
    }

    if (res.status === 401 && errCode(res) === 'denied') {
      check(res, { '401 denied is not an expiry': function (r) { return errCode(r) !== 'denied'; } });
      S.fatal = true;
      return res;
    }

    if (isAuthInterrupt(res) && !recovered) {
      recovered = true;
      if (!recoverSession(res, label)) return res;
      if (extra.ifMatch) readCartEtag();    // recovery may rotate the cart ETag
      resumedOps.add(1);
      continue;                             // retry only the interrupted operation, once
    }

    if (recovered) {
      check(res, { 'interrupted operation resumed after recovery': function (r) { return ok2xx(r); } });
    }
    return res;
  }
  return res;
}

