function collectProducts(j) {
  const out = [];
  if (!j) return out;
  const push = function (p) { if (p && typeof p === 'object') out.push(p); };
  const d = j.data !== undefined ? j.data : j;
  if (Array.isArray(d)) {
    d.forEach(push);
  } else if (d && typeof d === 'object') {
    if (Array.isArray(d.products)) d.products.forEach(push);
    if (Array.isArray(d.items)) d.items.forEach(push);
    if (d.product) push(d.product);
    if (d.id !== undefined && d.variants) push(d);
  }
  if (Array.isArray(j.products)) j.products.forEach(push);
  if (j.product) push(j.product);
  return out;
}

function pickInStock(j) {
  const products = collectProducts(j);
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const variants = Array.isArray(p.variants) ? p.variants : [];
    for (let v = 0; v < variants.length; v++) {
      const variant = variants[v];
      if (variant && variant.in_stock === true && variant.id !== undefined && variant.id !== null &&
