  const res = authedCall('catalog', 'GET', '/v2/catalog', null, { tag: 'catalog' });
  check(res, { 'catalog readable': function (r) { return r.status === 200; } });

  let picked = res.status === 200 ? pickInStock(body(res)) : null;

  if (!picked) {
    let path = '/v2/catalog/page';
    for (let page = 0; page < 3 && !picked; page++) {   // traverse at most 3 pages
      const r = authedCall('catalog-page', 'GET', path, null, { tag: 'catalog-page' });
      if (r.status !== 200) break;
