function businessWork() {
  let throttled = 0;
  let recovered = false;

  for (let i = 0; i < 8; i++) {
    const res = rawRequest('POST', '/v2/work', {}, baseHeaders(true), 'work');

    if (res.status === 429) {
      if (throttled >= MAX_429_RETRIES) {
        check(res, { 'work completed within retry budget': function () { return false; } });
        return false;
      }
      throttled += 1;
