      sleep(!isNaN(ra) && ra > 0 ? Math.min(ra, 10) : 1); // honour Retry-After (1s)
      continue;
    }

    if (isAuthInterrupt(res) && !recovered) {
      recovered = true;
      if (!recoverSession(res, 'work')) return false;
      resumedOps.add(1);
      continue; // retry the interrupted work once
    }

    if (res.status === 401 && errCode(res) === 'denied') {
      check(res, { '401 denied is not an expiry': function (r) { return errCode(r) !== 'denied'; } });
      S.fatal = true;
      return false;
    }

    const good = check(res, {
      'business work accepted': function (r) {
        const b = body(r);
        return r.status === 200 && !!b && b.ok === true;
      },
    });
    if (recovered) {
      check(res, { 'interrupted work resumed after recovery': function (r) { return ok2xx(r); } });
    }
