}

/* ----------------------------------------------------------------- checkout */

function checkout() {
  S.checkoutStarts += 1;
  readCartEtag(); // fresh ETag; also re-reads after any recovery

  const payload = { cart_id: S.cartId };
  const res = authedCall('order', 'POST', '/v2/orders', payload, {
    ifMatch: true,
    idemKey: S.idemKey,          // stable on retry -> server-side dedupe, never a second order
    tag: 'orders',
    countKey: 'orderCalls',
    maxCalls: MAX_ORDER_CALLS,
  });

  const j = body(res);
  const committed = res.status === 201 && !!j && j.accepted === true && j.id !== undefined && j.id !== null;

  check(res, {
    'order committed (201 accepted:true)': function (r) {
      const b = body(r);
      return r.status === 201 && !!b && b.accepted === true;
    },
    'HTTP 200 accepted:false is a business failure': function (r) {
      const b = body(r);
      return !(r.status === 200 && !!b && b.accepted === false);
    },
  });

  if (committed) {
    if (S.orders === 0) {
      S.orders = 1;
      S.orderId = j.id;
      ordersCommitted.add(1);
    }
  }
