    sleep(THINK);                // user reviews the cart: session expiry window opens here
    businessWork();
    sleep(THINK);
    if (!S.fatal) checkout();    // never restarted, never duplicated
  }

  const success = S.carts === 1 && S.orders === 1 && !S.fatal;
  journeySuccess.add(success);

  check(S, {
    'journey: exactly one cart created': function (s) { return s.carts === 1; },
    'journey: exactly one committed order': function (s) { return s.orders === 1; },
    'journey: checkout never restarted': function (s) { return s.checkoutStarts <= 1; },
    'journey: reauthentication bounded': function (s) {
      return s.renewCount <= MAX_RENEW && s.reloginCount <= MAX_RELOGIN;
    },
    'journey: order attempts bounded': function (s) { return s.orderCalls <= MAX_ORDER_CALLS; },
  });
