# Locust 2.47 locustfile.
# Business journey: fresh login -> catalog -> challenge grant -> cart -> (session expiry
# boundary) -> cart quantity PATCH -> checkout.  Expiry (401 error=expired / error=session)
# is absorbed by renew (or fresh form/login) + the permitted cart recovery path, then the
# interrupted operation is retried exactly once with a stable Idempotency-Key.
#
# Contract: 2 virtual users x 2 iterations each = 4 journeys, one committed order per
# journey, one cart per journey, bounded re-authentication, no checkout restarts.

import logging
import os
import re
import time
import uuid
from html import unescape
from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

LOG = logging.getLogger("shop-expiry")

BASE_URL = (os.environ.get("BASE_URL") or "http://127.0.0.1:8000").rstrip("/")
