ITERATIONS = 2
TOTAL_JOURNEYS = USERS * ITERATIONS
PASSWORD = "bench"

MAX_REAUTH_PER_JOURNEY = 4          # hard bound on renew/re-login per journey
MAX_429_RETRIES = 4                 # scheduled 429: Retry-After, at most 4 retries
MAX_CATALOG_PAGES = 3               # traverse at most 3 catalog pages
THINK_AFTER_CART = 2.1              # think time: expiry boundary sits before checkout
RUN_TIMEOUT = 240.0

STATE = {"started_users": 0, "active": 0, "finished": 0, "t0": None}
IN_USE = set()

_COMMENT_RE = re.compile(r"<!--.*?-->", re.S)
_INPUT_RE = re.compile(r"<\s*input\b([^>]*)>", re.I | re.S)
_META_RE = re.compile(r"<\s*meta\b([^>]*)>", re.I | re.S)
_FORM_RE = re.compile(r"<\s*form\b([^>]*)>(.*?)<\s*/\s*form\s*>", re.I | re.S)
_ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?"""
)
_DECOY_WORDS = ("decoy", "fake", "trap", "bogus", "dummy", "ignore", "sample")


def _attrs(raw):
    out = {}
    for m in _ATTR_RE.finditer(raw or ""):
        key = m.group(1).lower()
        val = m.group(2)
        if val is None:
            val = m.group(3)
        if val is None:
            val = m.group(4)
            if val is not None:
                val = val.rstrip("/")
        if val is None:
            val = ""
        if key not in out:
            out[key] = val
    return out


def _form_spans(text, hint):
    spans = []
    if not hint:
        return spans
    for m in _FORM_RE.finditer(text):
        a = _attrs(m.group(1))
        if hint in unescape(a.get("action", "")):
            spans.append((m.start(2), m.end(2)))
    return spans


def extract_field(html_text, field, action_hint=None):
    """Attribute-order / quote-style tolerant hidden field extraction, decoy aware."""
    if not html_text:
        return None
    text = _COMMENT_RE.sub(" ", html_text)
    spans = _form_spans(text, action_hint)
    best_key = None
    best_val = None
    field = field.lower()
    for m in _INPUT_RE.finditer(text):
        a = _attrs(m.group(1))
        if a.get("name", "").strip().lower() != field:
            continue
        raw = a.get("value") or a.get("data-value") or ""
        val = unescape(raw).strip()
        if not val:
            continue
        score = 0
        typ = a.get("type", "").strip().lower()
        if typ == "hidden":
            score += 6
        if typ in ("submit", "button", "reset", "image", "checkbox", "radio"):
            score -= 60
        if "disabled" in a:
            score -= 60
        blob = " ".join([a.get("id", ""), a.get("class", ""), a.get("data-role", "")]).lower()
        if any(w in blob for w in _DECOY_WORDS):
            score -= 80
        if any(w in val.lower() for w in _DECOY_WORDS):
            score -= 60
        for k in ("data-decoy", "data-fake", "data-ignore", "data-trap", "aria-hidden"):
            if k in a and a[k].strip().lower() not in ("", "false", "0", "no"):
                score -= 80
        if len(val) >= 16:
            score += 3
        pos = m.start()
        for s, e in spans:
            if s <= pos < e:
                score += 25
                break
        key = (score, -pos)
        if best_key is None or key > best_key:
            best_key, best_val = key, val
    if best_val:
        return best_val
    for m in _META_RE.finditer(text):
        a = _attrs(m.group(1))
        if a.get("name", "").strip().lower() == field or a.get("property", "").strip().lower() == field:
            v = unescape(a.get("content", "")).strip()
            if v:
                return v
    m = re.search(r"""data-%s\s*=\s*["']([^"']+)["']""" % re.escape(field), text, re.I)
    if m:
        return unescape(m.group(1)).strip()
    m = re.search(r"""["']%s["']\s*:\s*["']([^"']+)["']""" % re.escape(field), text)
    if m:
        return m.group(1).strip()
    return None


def extract_challenge(html_text):
    if not html_text:
        return None, None
    text = _COMMENT_RE.sub(" ", html_text)
    action = None
    for m in re.finditer(r"<\s*form\b([^>]*)>", text, re.I):
        a = _attrs(m.group(1))
        act = unescape(a.get("action", "")).strip()
        if "/v2/challenges/" in act:
            action = act
            break
