    return action, value


def collect_products(node, out=None):
    if out is None:
        out = []
    if isinstance(node, dict):
        if "id" in node and isinstance(node.get("variants"), (list, dict)):
            out.append(node)
        for k, v in node.items():
            if k in ("data", "products", "product", "items", "results"):
                collect_products(v, out)
    elif isinstance(node, list):
        for item in node:
            collect_products(item, out)
