def next_link(data):
    if not isinstance(data, dict):
        return None
    for key in ("next", "next_url", "next_page"):
        v = data.get(key)
        if isinstance(v, str) and v.strip():
            return v.strip()
    inner = data.get("data")
    if isinstance(inner, dict):
        return next_link(inner)
    return None


def pick_variant(products):
    for p in products:
        if not isinstance(p, dict):
            continue
        pid = p.get("id")
        if pid is None:
            continue
        variants = p.get("variants") or []
        if isinstance(variants, dict):
            variants = [variants]
        for v in variants:
            if not isinstance(v, dict):
                continue
            vid = v.get("id")
            if vid is None:
                continue
            stock = v.get("in_stock")
            if stock is True or stock in (1, "1", "true", "True", "yes"):
