def snippet(text):
    if not text:
        return "<empty>"
    return " ".join(str(text).split())[:200]


def retry_delay(value):
    try:
        d = float(str(value).strip())
    except Exception:
        d = 1.0
    if d < 1.0:
        d = 1.0
    if d > 5.0:
        d = 5.0
    return d


def acquire_account():
    for i in range(1, 17):
        name = "bench-%d" % i
        if name not in IN_USE:
            IN_USE.add(name)
            return name
    return "bench"


def release_account(name):
    if name in IN_USE:
        IN_USE.discard(name)


class Result(object):
    __slots__ = ("ok", "status", "data", "headers", "text", "auth_error", "error")

    def __init__(self, ok, status, data, headers, text, auth_error, error):
        self.ok = ok
        self.status = status
        self.data = data if isinstance(data, dict) else {}
        self.headers = headers or {}
        self.text = text or ""
        self.auth_error = auth_error
        self.error = error


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    # ---------------- lifecycle ----------------

    def on_start(self):
        self.allowed = 0
        self.done = 0
        self.counted = False
        self.username = None
        self.csrf = None
        self.login_csrf = None
        self.reauth_used = 0
        self.etags = {}
        self.orders = 0
        if STATE["started_users"] < USERS:
            STATE["started_users"] += 1
            self.allowed = ITERATIONS
            self.username = acquire_account()
