            self.csrf = tok.strip()  # retain previous token when absent

    def _send(self, op, tolerate_auth=False):
        method = op["method"].upper()
        name = op.get("name") or op["path"]
        expect = tuple(op.get("expect", (200,)))
        validate = op.get("validate")
        payload = op.get("payload")
        attempt = 0
        while True:
            status = 0
            data = {}
            hdrs = {}
            text = ""
            err = None
            auth_error = None
            retry_after = None
            try:
                url = self._abs(op["path"], op.get("base"))
                headers = {"Accept": "application/json, text/html;q=0.9, */*;q=0.8"}
                if method != "GET" and self.csrf:
                    headers["X-CSRF-Token"] = self.csrf
                if op.get("idem"):
                    headers["Idempotency-Key"] = op["idem"]
                if op.get("if_match"):
                    headers["If-Match"] = op["if_match"]
                if op.get("headers"):
                    headers.update(op["headers"])
                kwargs = {
                    "name": name,
                    "headers": headers,
                    "catch_response": True,
                    "allow_redirects": False,
                    "timeout": 20,
                }
                if payload is not None:
                    kwargs["json"] = payload
                with self.client.request(method, url, **kwargs) as resp:
                    status = int(resp.status_code or 0)
                    hdrs = getattr(resp, "headers", {}) or {}
                    try:
                        text = resp.text or ""
                    except Exception:
                        text = ""
                    try:
                        parsed = resp.json()
                    except Exception:
                        parsed = None
                    data = parsed if isinstance(parsed, dict) else {}
                    if status == 401:
