                    scheduled = (status == 429 and retry_after is not None
                                 and attempt < MAX_429_RETRIES)
                    expected_auth = (status == 401 and auth_error in ("expired", "session")
                                     and tolerate_auth)
                    if status in expect:
                        if validate is not None:
                            try:
                                err = validate(data, resp)
                            except Exception as exc:
                                err = "assertion raised %s: %s" % (type(exc).__name__, exc)
                    elif scheduled or expected_auth:
                        err = None  # expected protocol states, not sample failures
                    else:
