                "validate": vland,
            }, tolerate_auth=False)  # dynamic Location followed exactly once
            if not res.ok:
                return False

        self._absorb(res.data)
        return bool(self.csrf)

    def _recover(self, kind, cart_id):
        self.reauth_used += 1
        renewed = False
        if kind == "expired":
            res = self._send({
                "method": "POST",
                "path": "/v2/session/renew",
                "name": "/v2/session/renew",
                "payload": {},
                "expect": (200, 201, 202),
            }, tolerate_auth=True)  # current (stale) CSRF is intentional here
            renewed = res.ok
        if not renewed:
            # revoked session (or renew refused): fresh form + login
            if not self._login():
                return False
        if cart_id:
            res = self._send({
                "method": "POST",
                "path": "/v2/carts/%s/recover" % cart_id,
                "name": "/v2/carts/{id}/recover",
                "payload": {},
                "expect": (200, 201, 202),
            }, tolerate_auth=False)
            if not res.ok:
                return False
            etag = res.headers.get("ETag")
            if etag:
                self.etags[cart_id] = etag
        return True

    # ---------------- catalog / challenge ----------------

    def _select_product(self):
        box = {}

        def v(data, resp):
            prods = collect_products(data)
            if not prods:
                return "catalog: no products in payload"
            box["products"] = prods
            return None

        res = self._perform({
            "method": "GET",
            "path": "/v2/catalog",
            "name": "/v2/catalog",
            "expect": (200,),
            "validate": v,
        })
        if res.ok:
            pick = pick_variant(box.get("products", []))
            if pick:
                return pick

        path = "/v2/catalog/page"
        base = None
        for _ in range(MAX_CATALOG_PAGES):
            current = self._abs(path, base)
            page = {}

            def vp(data, resp, page=page):
                prods = collect_products(data)
                if not prods:
                    return "catalog page: no product in payload"
                page["products"] = prods
                page["next"] = next_link(data)
                return None

            res = self._perform({
                "method": "GET",
                "path": path,
                "name": "/v2/catalog/page",
                "base": base,
                "expect": (200,),
                "validate": vp,
            })
            if not res.ok:
                return None
            pick = pick_variant(page.get("products", []))
            if pick:
                return pick
            nxt = page.get("next")
            if not nxt:
                return None
            base = current
            path = nxt
        return None

    def _challenge_grant(self):
        box = {}

        def vform(data, resp):
            if resp.status_code == 404:
                box["skip"] = True
                return None
            action, value = extract_challenge(resp.text)
            if not action:
                return "challenge-form: no /v2/challenges/{id} action"
            if not value:
                return "challenge-form: no input[name=challenge] value"
            box["action"] = action
            box["value"] = value
            return None

        res = self._perform({
            "method": "GET",
            "path": "/v2/challenge-form",
            "name": "/v2/challenge-form",
            "expect": (200, 404),
            "validate": vform,
            "headers": {"Accept": "text/html,application/xhtml+xml"},
        })
        if not res.ok or box.get("skip"):
            return None

        def vpost(data, resp):
            if resp.status_code == 302:
                if not resp.headers.get("Location"):
                    return "challenge: 302 without Location"
                return None
            if not data.get("grant_id"):
                return "challenge: no grant_id in body"
            return None

        action = box["action"]
        res = self._perform({
            "method": "POST",
            "path": action,
            "name": "/v2/challenges/{id}",
            "payload": {"challenge": box["value"]},
            "expect": (200, 302),
            "validate": vpost,
        })
        if not res.ok:
            return None

        if res.status == 302:
            loc = res.headers.get("Location")

            def vland(data, resp):
                if not data.get("grant_id"):
                    return "challenge landing: no grant_id"
                return None

            res = self._perform({
                "method": "GET",
                "path": loc,
                "name": "/v2/challenges/{id}",
                "base": self._abs(action),
                "expect": (200,),
                "validate": vland,
            })
            if not res.ok:
                return None
        return res.data.get("grant_id")

    # ---------------- business journey ----------------

    def _journey(self):
        self.csrf = None
        self.reauth_used = 0
        self.etags = {}
        orders_before = self.orders

        if not self._login():
            return
        choice = self._select_product()
        if not choice:
            return
        product_id, variant_id = choice

        grant_id = self._challenge_grant()  # grant lives 2s: spend it immediately
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id

        box = {}

        def vcart(data, resp):
            cid = data.get("id")
            if cid is None:
                return "cart create: missing id"
            box["id"] = str(cid)
            return None

        res = self._perform({
            "method": "POST",
            "path": "/v2/carts",
            "name": "/v2/carts",
            "payload": payload,
            "expect": (201,),
            "validate": vcart,
        })
        if not res.ok:
            return
        cart_id = box["id"]
        etag = res.headers.get("ETag")
        if etag:
            self.etags[cart_id] = etag

        # think time between cart creation and checkout: the expiry boundary lands here
        time.sleep(THINK_AFTER_CART)

        if not self.etags.get(cart_id):
            self._fetch_etag(cart_id)

        res = self._perform({
            "method": "PATCH",
            "path": "/v2/carts/%s" % cart_id,
            "name": "/v2/carts/{id}",
            "payload": {"quantity": 2},
            "expect": (200, 201, 202, 204),
            "if_match": self.etags.get(cart_id),
            "cart": cart_id,
        })
        if not res.ok:
            return
        etag = res.headers.get("ETag")
        if etag:
            self.etags[cart_id] = etag

        # exactly one checkout attempt chain; key unique per cart, stable on every retry
        idem = "%s.%s" % (cart_id, uuid.uuid4().hex)

        def vorder(data, resp):
            if not data:
                return "order: empty/invalid body"
            if data.get("accepted") is not True:
                return "order: accepted=%r (business failure, not success)" % (data.get("accepted"),)
            if not data.get("id"):
                return "order: accepted without order id"
            box["order"] = str(data["id"])
            return None

        res = self._perform({
            "method": "POST",
            "path": "/v2/orders",
            "name": "/v2/orders",
            "payload": {"cart_id": cart_id},
            "expect": (200, 201),
            "validate": vorder,
            "idem": idem,
            "cart": cart_id,
        })
        if not res.ok:
            return
        self.orders += 1
        if self.orders != orders_before + 1:
            LOG.warning("order accounting anomaly for %s", self.username)
        # committed: never restart checkout, never create another cart in this journey


class ExpiryRecoveryShape(LoadTestShape):
    """2 users, 2 iterations each; stop as soon as every journey has finished."""

    def tick(self):
        now = time.time()
        if STATE["t0"] is None:
            STATE["t0"] = now
        if STATE["finished"] >= TOTAL_JOURNEYS:
            return None
        if STATE["started_users"] >= USERS and STATE["active"] <= 0:
            return None
        if now - STATE["t0"] > RUN_TIMEOUT:
            return None
        return USERS, USERS
