import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  /* ----------------------------- configuration ----------------------------- */

  private static final String BASE = base();
  private static final int USERS = envInt("USERS", 2);
  private static final int ITERATIONS = envInt("ITERATIONS", 2);
  private static final int MAX_POLLS = 5;
  private static final long POLL_GAP_MS =
      Math.max(50L, Math.round(1000.0 * envDouble("POLL_INTERVAL", envDouble("poll_interval", 0.02))));

  private static final Pattern INPUT_TAG =
      Pattern.compile("<input\\b[^>]*>", Pattern.CASE_INSENSITIVE);
  private static final Pattern ATTRIBUTE =
      Pattern.compile("([a-zA-Z_:][-a-zA-Z0-9_:.]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'>]+))");
  private static final String CSRF_INPUT =
      "<input(?=[^>]*\\sname\\s*=\\s*[\"']?csrf[\"']?(?=[\\s/>]))(?=[^>]*\\svalue\\s*=\\s*[\"']?([^\"'\\s>]+))[^>]*>";
  private static final String JOB_ALIVE = "\"status\"\\s*:\\s*\"(?:pending|ready)\"";

  public ModelSimulation() {
    ChainBuilder journey =
        clearJourney()
            .exec(loginFlow())
            .exec(catalogFlow())
            .exec(cartFlow())
            .exec(reservationFlow())
            .exec(checkoutFlow());

    ScenarioBuilder scn = scenario("reservation-journey").repeat(ITERATIONS, "iter").on(journey);

    setUp(scn.injectOpen(atOnceUsers(USERS)))
        .protocols(httpProtocol())
        .assertions(
            details("checkout").successfulRequests().count().is((long) USERS * ITERATIONS),
            details("job-poll").failedRequests().count().is(0L),
            details("create-reservation").failedRequests().count().is(0L));
  }

  private HttpProtocolBuilder httpProtocol() {
    return http.baseUrl(BASE)
        .disableFollowRedirect()
        .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8")
        .contentTypeHeader("application/json")
        .userAgentHeader("model-simulation")
        .warmUp(BASE + "/v2/health");
  }

  /* ----------------------------- journey state ----------------------------- */

  private ChainBuilder clearJourney() {
    return exec(s -> drop(s.set("csrf", "")
            .set("username", "bench-" + (int) ((s.getUserId() - 1) % 16 + 1))
            .set("loginCsrf", "")
            .set("cartId", "")
            .set("cartEtag", "")
            .set("idemKey", "")
            .set("statusUrl", "")
            .set("jobStatus", "pending")
            .set("reservationId", "")
            .set("polls", 0)
            .set("productId", "")
            .set("variantId", ""),
        "csrfL", "errL", "cartIdL", "statusUrlL", "jobStatusL", "resIdL", "orderIdL",
        "loginLocation", "loginCsrfFallback", "loginFormHtml", "products",
        "pid0", "vid0", "stock0", "pid1", "vid1", "stock1", "pid2", "vid2", "stock2",
        "loginSt", "cartSt", "patchSt", "resSt", "orderSt", "renewSt"));
  }

  /* --------------------------------- login --------------------------------- */

  private ChainBuilder loginFlow() {
    return exec(s -> drop(s, "loginFormHtml", "loginCsrfFallback", "loginLocation", "csrfL"))
        .exec(http("login-form").get("/v2/login-form")
            .check(status().is(200),
                bodyString().saveAs("loginFormHtml"),
                regex(CSRF_INPUT).find().optional().saveAs("loginCsrfFallback")))
        .exec(s -> {
          String token = extractCsrf(s.getString("loginFormHtml"));
          if ((token == null || token.isEmpty()) && s.contains("loginCsrfFallback")) {
            token = s.getString("loginCsrfFallback");
          }
          return s.set("loginCsrf", token == null ? "" : token);
        })
        .exec(http("login").post("/v2/login")
            .header("Content-Type", "application/json")
            .body(StringBody(s -> "{\"username\":\"" + esc(s.getString("username"))
                + "\",\"password\":\"bench\",\"csrf\":\"" + esc(s.getString("loginCsrf")) + "\"}"))
            .check(status().saveAs("loginSt"),
                header("Location").optional().saveAs("loginLocation"),
                jsonPath("$.csrf").findAll().optional().saveAs("csrfL")))
        .exec(ModelSimulation::refreshCsrf)
        .doIf(s -> code(s, "loginSt") == 302 && s.contains("loginLocation"))
        .then(exec(http("login-redirect").get("#{loginLocation}")
                .check(status().is(200), jsonPath("$.csrf").findAll().saveAs("csrfL")))
            .exec(ModelSimulation::refreshCsrf));
  }

  /* -------------------------------- catalog -------------------------------- */

  private ChainBuilder catalogFlow() {
    return exec(s -> drop(s, "products", "pid0", "vid0", "stock0", "pid1", "vid1", "stock1",
            "pid2", "vid2", "stock2"))
        .exec(http("catalog").get("/v2/catalog")
            .check(status().is(200),
                jsonPath("$.data.products[*]").findAll().optional().saveAs("products"),
                jsonPath("$.data.products[0].id").findAll().optional().saveAs("pid0"),
                jsonPath("$.data.products[0].variants[*].id").findAll().optional().saveAs("vid0"),
                jsonPath("$.data.products[0].variants[*].in_stock").findAll().optional().saveAs("stock0"),
                jsonPath("$.data.products[1].id").findAll().optional().saveAs("pid1"),
                jsonPath("$.data.products[1].variants[*].id").findAll().optional().saveAs("vid1"),
                jsonPath("$.data.products[1].variants[*].in_stock").findAll().optional().saveAs("stock1"),
                jsonPath("$.data.products[2].id").findAll().optional().saveAs("pid2"),
                jsonPath("$.data.products[2].variants[*].id").findAll().optional().saveAs("vid2"),
                jsonPath("$.data.products[2].variants[*].in_stock").findAll().optional().saveAs("stock2")))
        .exec(ModelSimulation::pickVariant);
  }

  /* ------------------------------ cart lifecycle ---------------------------- */

  private ChainBuilder createCartRequest() {
    return exec(s -> drop(s, "csrfL", "errL", "cartIdL"))
        .exec(http("create-cart").post("/v2/carts")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .body(StringBody(s -> "{\"product_id\":" + jsonValue(s.getString("productId"))
                + ",\"variant_id\":" + jsonValue(s.getString("variantId")) + "}"))
            .check(status().is(201),
                status().saveAs("cartSt"),
                header("ETag").optional().saveAs("cartEtag"),
                jsonPath("$.id").findAll().optional().saveAs("cartIdL"),
                jsonPath("$.csrf").findAll().optional().saveAs("csrfL"),
                jsonPath("$.error").findAll().optional().saveAs("errL")));
  }

  private ChainBuilder patchRequest(String name) {
    return exec(s -> drop(s, "csrfL", "errL"))
        .exec(http(name).patch("/v2/carts/#{cartId}")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{cartEtag}")
            .header("Content-Type", "application/json")
            .body(StringBody("{\"quantity\":1}"))
            .check(status().saveAs("patchSt"),
                header("ETag").optional().saveAs("cartEtag"),
                jsonPath("$.csrf").findAll().optional().saveAs("csrfL"),
                jsonPath("$.error").findAll().optional().saveAs("errL")))
        .exec(ModelSimulation::refreshCsrf);
  }

  private ChainBuilder cartFlow() {
    return doIf(s -> !s.getString("productId").isEmpty() && !s.getString("variantId").isEmpty())
        .then(createCartRequest()
            .exec(ModelSimulation::applyCart)
            .doIf(s -> code(s, "cartSt") == 401 && !"denied".equals(first(s, "errL")))
            .then(recoverFlow(false)
                .exec(createCartRequest())
                .exec(ModelSimulation::applyCart))
            .doIf(s -> !s.getString("cartId").isEmpty())
            .then(patchRequest("cart-patch")
                .doIf(s -> code(s, "patchSt") == 412
                    || (code(s, "patchSt") == 401 && !"denied".equals(first(s, "errL"))))
                .then(doIf(s -> code(s, "patchSt") == 401).then(recoverFlow(true))
                    .exec(http("cart-read").get("/v2/carts/#{cartId}")
                        .check(status().is(200), header("ETag").saveAs("cartEtag")))
                    .exec(patchRequest("cart-patch-retry")))));
  }

  /* --------------------- reservation job + dynamic polling ------------------ */

  private ChainBuilder reservationFlow() {
    return doIf(s -> !s.getString("cartId").isEmpty())
        .then(exec(s -> drop(s.set("jobStatus", "pending").set("polls", 0)
                .set("statusUrl", "").set("reservationId", ""), "statusUrlL", "jobStatusL", "resIdL", "csrfL"))
            .exec(http("create-reservation").post("/v2/reservations")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody(s -> "{\"cart_id\":" + jsonValue(s.getString("cartId")) + "}"))
                .check(status().is(202),
                    status().saveAs("resSt"),
                    jsonPath("$.status_url").findAll().saveAs("statusUrlL"),
                    jsonPath("$.csrf").findAll().optional().saveAs("csrfL")))
            .exec(s -> {
              Session t = refreshCsrf(s);
              String url = first(t, "statusUrlL");
              return drop(t, "statusUrlL").set("statusUrl", url == null ? "" : url);
            })
            .repeat(MAX_POLLS, "pollIdx")
            .on(doIf(s -> "pending".equals(s.getString("jobStatus"))
                    && !s.getString("statusUrl").isEmpty()
                    && s.getInt("polls") < MAX_POLLS)
                .then(pause(Duration.ofMillis(POLL_GAP_MS))
                    .exec(s -> s.set("polls", s.getInt("polls") + 1))
                    .exec(s -> drop(s, "jobStatusL", "resIdL", "csrfL"))
                    .exec(http("job-poll").get("#{statusUrl}")
                        .check(regex(JOB_ALIVE).exists(),
                            jsonPath("$.status").findAll().saveAs("jobStatusL"),
                            jsonPath("$.reservation_id").findAll().optional().saveAs("resIdL"),
                            jsonPath("$.csrf").findAll().optional().saveAs("csrfL")))
                    .exec(ModelSimulation::applyJob))));
  }

  /* -------------------------------- checkout -------------------------------- */

  private ChainBuilder checkoutRequest() {
    return exec(s -> drop(s, "csrfL", "errL", "orderIdL"))
        .exec(http("checkout").post("/v2/orders")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{idemKey}")
            .header("If-Match", "#{cartEtag}")
            .header("Content-Type", "application/json")
            .body(StringBody(s -> "{\"cart_id\":" + jsonValue(s.getString("cartId"))
                + ",\"reservation_id\":" + jsonValue(s.getString("reservationId")) + "}"))
            .check(status().is(201),
                status().saveAs("orderSt"),
                jsonPath("$.accepted").is(true),
                jsonPath("$.id").findAll().optional().saveAs("orderIdL"),
                jsonPath("$.csrf").findAll().optional().saveAs("csrfL"),
                jsonPath("$.error").findAll().optional().saveAs("errL")))
        .exec(ModelSimulation::refreshCsrf);
  }

  private ChainBuilder checkoutFlow() {
    return doIf(s -> "ready".equals(s.getString("jobStatus"))
            && !s.getString("reservationId").isEmpty()
            && !s.getString("cartId").isEmpty()
            && !s.getString("idemKey").isEmpty())
        .then(exec(http("cart-final-read").get("/v2/carts/#{cartId}")
                .check(status().is(200), header("ETag").saveAs("cartEtag")))
            .exec(checkoutRequest())
            .doIf(s -> code(s, "orderSt") == 401 && !"denied".equals(first(s, "errL")))
            .then(recoverFlow(true)
                .exec(http("cart-final-read").get("/v2/carts/#{cartId}")
                    .check(status().is(200), header("ETag").saveAs("cartEtag")))
                .exec(checkoutRequest())));
  }

  /* --------------------------- bounded 401 recovery ------------------------- */

  private ChainBuilder recoverFlow(boolean withCart) {
    ChainBuilder c = exec(s -> drop(s, "csrfL", "errL"))
        .exec(http("session-renew").post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .body(StringBody("{}"))
            .check(status().saveAs("renewSt"),
                jsonPath("$.csrf").findAll().optional().saveAs("csrfL")))
        .exec(ModelSimulation::refreshCsrf)
        .doIf(s -> code(s, "renewSt") != 200).then(loginFlow());
    if (withCart) {
      c = c.doIf(s -> !s.getString("cartId").isEmpty())
          .then(exec(s -> drop(s, "csrfL"))
              .exec(http("cart-recover").post("/v2/carts/#{cartId}/recover")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("Content-Type", "application/json")
                  .body(StringBody("{}"))
                  .check(status().saveAs("recoverSt"),
                      header("ETag").optional().saveAs("cartEtag"),
                      jsonPath("$.csrf").findAll().optional().saveAs("csrfL")))
              .exec(ModelSimulation::refreshCsrf));
    }
    return c;
  }

  /* ------------------------------ session helpers --------------------------- */

  private static Session applyCart(Session s) {
    Session t = refreshCsrf(s);
    String id = first(t, "cartIdL");
    t = drop(t, "cartIdL");
    if (id != null && !id.isEmpty()) {
      t = t.set("cartId", id)
          .set("idemKey", "ik-" + t.getUserId() + "-" + t.getInt("iter") + "-" + id);
    }
    return t;
  }

  private static Session applyJob(Session s) {
    Session t = refreshCsrf(s);
    String state = first(t, "jobStatusL");
    String rid = first(t, "resIdL");
    t = drop(t, "jobStatusL", "resIdL");
    t = t.set("jobStatus", state == null ? "unknown" : state);
    if ("ready".equals(state) && rid != null && !rid.isEmpty()) {
      return t.set("reservationId", rid);
    }
    return t.set("reservationId", "");
  }

  private static Session refreshCsrf(Session s) {
    String token = first(s, "csrfL");
    Session t = drop(s, "csrfL");
    if (token != null && !token.isEmpty()) {
      return t.set("csrf", token);
    }
    return t;
  }

  private static Session pickVariant(Session s) {
    if (s.contains("products")) {
      for (Object po : s.getList("products")) {
        if (!(po instanceof Map)) continue;
        Map<?, ?> p = (Map<?, ?>) po;
        Object pid = p.get("id");
        Object vs = p.get("variants");
        if (pid == null || !(vs instanceof List)) continue;
        for (Object vo : (List<?>) vs) {
          if (!(vo instanceof Map)) continue;
          Map<?, ?> v = (Map<?, ?>) vo;
          if (v.get("id") != null && truthy(v.get("in_stock"))) {
            return s.set("productId", String.valueOf(pid)).set("variantId", String.valueOf(v.get("id")));
          }
        }
      }
    }
    for (int i = 0; i < 3; i++) {
      String pid = first(s, "pid" + i);
      if (pid == null || !s.contains("vid" + i) || !s.contains("stock" + i)) continue;
      List<Object> ids = s.getList("vid" + i);
      List<Object> stock = s.getList("stock" + i);
      for (int j = 0; j < ids.size() && j < stock.size(); j++) {
        if (truthy(stock.get(j)) && ids.get(j) != null) {
          return s.set("productId", pid).set("variantId", String.valueOf(ids.get(j)));
        }
      }
    }
    return s.set("productId", "").set("variantId", "");
  }

  private static String extractCsrf(String html) {
    if (html == null) return null;
    Matcher tags = INPUT_TAG.matcher(html);
    String fallback = null;
    while (tags.find()) {
      Matcher attrs = ATTRIBUTE.matcher(tags.group());
      String name = null, value = null, type = null;
      boolean decoy = false;
      while (attrs.find()) {
        String k = attrs.group(1).toLowerCase(Locale.ROOT);
        String v = attrs.group(2) != null ? attrs.group(2)
            : attrs.group(3) != null ? attrs.group(3) : attrs.group(4);
        if (v == null) v = "";
        if ("name".equals(k)) name = v;
        else if ("value".equals(k)) value = v;
        else if ("type".equals(k)) type = v;
        else if ("disabled".equals(k) || k.startsWith("data-decoy")) decoy = true;
      }
      if (!"csrf".equals(name) || value == null || value.isEmpty() || decoy) continue;
      if (type != null && "hidden".equalsIgnoreCase(type)) return value;
      if (fallback == null) fallback = value;
    }
    return fallback;
  }

  private static Session drop(Session s, String... keys) {
    Session t = s;
    for (String k : keys) t = t.remove(k);
