            .header("Content-Type", "application/json")
            .body(StringBody(s -> "{\"username\":\"" + esc(s.getString("username"))
                + "\",\"password\":\"bench\",\"csrf\":\"" + esc(s.getString("csrf")) + "\"}"))
            .check(status().in(200, 302),
                status().saveAs("loginSt"),
                header("Location").optional().saveAs("loginLoc"),
                jsonPath("$.csrf").find().optional().saveAs("csrfNew")))
        .exec(ModelSimulation::refreshCsrf)
        .doIf(s -> !value(s, "loginLoc").isEmpty())
        .then(exec(http("login-redirect").get("#{loginLoc}")
                .check(status().is(200),
                    jsonPath("$.csrf").find().optional().saveAs("csrfNew")))
            .exec(ModelSimulation::refreshCsrf));
  }

  /* --------------------------------- catalog -------------------------------- */

  private ChainBuilder catalogFlow() {
    return exec(s -> drop(s, "products", "pid0", "vid0"))
        .exec(http("catalog").get("/v2/catalog")
            .check(status().is(200),
                jsonPath("$.data.products[*]").findAll().saveAs("products"),
                jsonPath("$.data.products[0].id").find().optional().saveAs("pid0"),
                jsonPath("$.data.products[0].variants[0].id").find().optional().saveAs("vid0")))
        .exec(ModelSimulation::pickVariant);
  }

  /* ------------------------------ cart lifecycle ---------------------------- */

  private ChainBuilder createCart() {
    return exec(s -> drop(s, "csrfNew", "err"))
        .exec(http("create-cart").post("/v2/carts")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .body(StringBody(s -> "{\"product_id\":" + jsonValue(s.getString("productId"))
                + ",\"variant_id\":" + jsonValue(s.getString("variantId")) + "}"))
            .check(status().is(201),
                status().saveAs("cartSt"),
                jsonPath("$.id").find().saveAs("cartId"),
                header("ETag").optional().saveAs("cartEtag"),
                jsonPath("$.csrf").find().optional().saveAs("csrfNew"),
                jsonPath("$.error").find().optional().saveAs("err")))
        .exec(ModelSimulation::applyCart);
  }

  private ChainBuilder patchCart(String name, boolean tolerant) {
    ChainBuilder c = exec(s -> drop(s, "csrfNew", "err"))
        .exec(http(name).patch("/v2/carts/#{cartId}")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{cartEtag}")
            .header("Content-Type", "application/json")
            .body(StringBody("{\"quantity\":1}"))
            .check(tolerant ? status().in(200, 201, 202, 401, 412) : status().in(200, 201, 202),
                status().saveAs("patchSt"),
                header("ETag").optional().saveAs("cartEtag"),
                jsonPath("$.csrf").find().optional().saveAs("csrfNew"),
                jsonPath("$.error").find().optional().saveAs("err")))
        .exec(ModelSimulation::refreshCsrf);
    return c;
  }

  private ChainBuilder cartFlow() {
    return doIf(s -> !s.getString("productId").isEmpty() && !s.getString("variantId").isEmpty())
        .then(createCart()
            .doIf(s -> code(s, "cartSt") == 401 && !"denied".equals(value(s, "err")))
            .then(recoverFlow(false).exec(createCart()))
            .doIf(s -> !s.getString("cartId").isEmpty())
            .then(patchCart("cart-patch", true)
                .doIf(s -> code(s, "patchSt") == 412
                    || (code(s, "patchSt") == 401 && !"denied".equals(value(s, "err"))))
                .then(doIf(s -> code(s, "patchSt") == 401).then(recoverFlow(true))
                    .exec(http("cart-read").get("/v2/carts/#{cartId}")
                        .check(status().is(200), header("ETag").saveAs("cartEtag")))
                    .exec(patchCart("cart-patch-retry", false)))));
  }

  /* -------------------- reservation job + dynamic poll URL ------------------ */

  private ChainBuilder reservationFlow() {
    return doIf(s -> !s.getString("cartId").isEmpty())
        .then(exec(s -> drop(s.set("jobStatus", "pending")
                .set("polls", 0)
                .set("statusUrl", "")
                .set("reservationId", ""), "csrfNew", "resId"))
            .exec(http("create-reservation").post("/v2/reservations")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody(s -> "{\"cart_id\":" + jsonValue(s.getString("cartId")) + "}"))
                .check(status().is(202),
                    jsonPath("$.status_url").find().saveAs("statusUrl"),
                    jsonPath("$.csrf").find().optional().saveAs("csrfNew")))
            .exec(ModelSimulation::refreshCsrf)
            .repeat(MAX_POLLS, "pollIdx")
            .on(doIf(s -> "pending".equals(s.getString("jobStatus"))
                    && !s.getString("statusUrl").isEmpty()
                    && s.getInt("polls") < MAX_POLLS)
                .then(pause(Duration.ofMillis(GAP_MS))
                    .exec(s -> s.set("polls", s.getInt("polls") + 1))
                    .exec(s -> drop(s, "csrfNew", "resId"))
                    .exec(http("job-poll").get("#{statusUrl}")
                        .check(status().in(200, 202),
                            regex(JOB_ALIVE).exists(),
                            jsonPath("$.status").find().saveAs("jobStatus"),
                            jsonPath("$.reservation_id").find().optional().saveAs("resId"),
                            jsonPath("$.csrf").find().optional().saveAs("csrfNew")))
                    .exec(ModelSimulation::applyJob))));
  }

  /* -------------------------------- checkout -------------------------------- */

  private ChainBuilder placeOrder() {
    return exec(s -> drop(s, "csrfNew", "err", "accepted"))
        .exec(http("checkout").post("/v2/orders")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{idemKey}")
            .header("If-Match", "#{cartEtag}")
            .header("Content-Type", "application/json")
            .body(StringBody(s -> "{\"cart_id\":" + jsonValue(s.getString("cartId"))
                + ",\"reservation_id\":" + jsonValue(s.getString("reservationId")) + "}"))
            .check(status().is(201),
                status().saveAs("orderSt"),
                regex(ORDER_ACCEPTED).exists(),
                jsonPath("$.id").find().optional().saveAs("orderId"),
                jsonPath("$.csrf").find().optional().saveAs("csrfNew"),
                jsonPath("$.error").find().optional().saveAs("err")))
        .exec(ModelSimulation::refreshCsrf);
  }

  private ChainBuilder checkoutFlow() {
    return doIf(s -> "ready".equals(s.getString("jobStatus"))
            && !s.getString("reservationId").isEmpty()
            && !s.getString("cartId").isEmpty()
            && !s.getString("idemKey").isEmpty())
        .then(exec(http("cart-final-read").get("/v2/carts/#{cartId}")
                .check(status().is(200), header("ETag").saveAs("cartEtag")))
            .exec(placeOrder())
            .doIf(s -> code(s, "orderSt") == 401 && !"denied".equals(value(s, "err")))
            .then(recoverFlow(true)
                .exec(http("cart-final-read").get("/v2/carts/#{cartId}")
                    .check(status().is(200), header("ETag").saveAs("cartEtag")))
                .exec(placeOrder())));
  }

  /* --------------------------- bounded 401 recovery ------------------------- */

  private ChainBuilder recoverFlow(boolean withCart) {
    ChainBuilder c = exec(s -> drop(s, "csrfNew", "err"))
        .exec(http("session-renew").post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Content-Type", "application/json")
            .body(StringBody("{}"))
            .check(status().saveAs("renewSt"),
                jsonPath("$.csrf").find().optional().saveAs("csrfNew")))
        .exec(ModelSimulation::refreshCsrf)
        .doIf(s -> code(s, "renewSt") != 200).then(loginFlow());
    if (withCart) {
      c = c.doIf(s -> !s.getString("cartId").isEmpty())
          .then(exec(s -> drop(s, "csrfNew"))
              .exec(http("cart-recover").post("/v2/carts/#{cartId}/recover")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("Content-Type", "application/json")
                  .body(StringBody("{}"))
                  .check(status().in(200, 201, 202),
                      header("ETag").optional().saveAs("cartEtag"),
                      jsonPath("$.csrf").find().optional().saveAs("csrfNew")))
              .exec(ModelSimulation::refreshCsrf));
    }
    return c;
  }

  /* ------------------------------ session helpers --------------------------- */

  private static Session applyCart(Session s) {
    Session t = refreshCsrf(s);
    String id = value(t, "cartId");
    if (!id.isEmpty()) {
      t = t.set("cartId", id)
          .set("idemKey", "ik-" + t.getUserId() + "-" + t.getInt("iter") + "-" + id);
    }
    return t;
  }

  private static Session applyJob(Session s) {
    String state = value(s, "jobStatus");
    String rid = value(s, "resId");
    Session t = drop(refreshCsrf(s), "resId");
    t = t.set("jobStatus", state.isEmpty() ? "unknown" : state);
    if ("ready".equals(state) && !rid.isEmpty()) {
      return t.set("reservationId", rid);
    }
    return t.set("reservationId", "");
  }

  private static Session refreshCsrf(Session s) {
    String token = value(s, "csrfNew");
    Session t = drop(s, "csrfNew");
    return token.isEmpty() ? t : t.set("csrf", token);
  }

  private static Session parseLoginForm(Session s) {
    String html = value(s, "formHtml");
    String token = extractCsrf(html);
    return drop(s, "formHtml").set("csrf", token == null ? "" : token);
  }

  private static Session pickVariant(Session s) {
    if (s.contains("products")) {
      List<Object> products = s.getList("products");
      for (Object po : products) {
        if (!(po instanceof Map)) continue;
        Map<?, ?> p = (Map<?, ?>) po;
        Object pid = p.get("id");
        Object vs = p.get("variants");
        if (pid == null || !(vs instanceof List)) continue;
        for (Object vo : (List<?>) vs) {
          if (!(vo instanceof Map)) continue;
          Map<?, ?> v = (Map<?, ?>) vo;
          if (v.get("id") != null && truthy(v.get("in_stock"))) {
            return s.set("productId", String.valueOf(pid))
                .set("variantId", String.valueOf(v.get("id")));
          }
        }
      }
    }
    return s.set("productId", value(s, "pid0")).set("variantId", value(s, "vid0"));
  }

  private static String extractCsrf(String html) {
    if (html == null || html.isEmpty()) return null;
    String cleaned = TEMPLATE.matcher(COMMENT.matcher(html).replaceAll(" ")).replaceAll(" ");
    Matcher tags = INPUT_TAG.matcher(cleaned);
    String fallback = null;
    while (tags.find()) {
      Matcher attrs = ATTRIBUTE.matcher(tags.group());
      String name = null, val = null, type = null;
      boolean decoy = false;
      while (attrs.find()) {
        String k = attrs.group(1).toLowerCase(Locale.ROOT);
        String v = attrs.group(2) != null ? attrs.group(2)
            : attrs.group(3) != null ? attrs.group(3) : attrs.group(4);
        if (v == null) v = "";
        if ("name".equals(k)) name = v;
        else if ("value".equals(k)) val = v;
        else if ("type".equals(k)) type = v;
        else if ("disabled".equals(k) || k.startsWith("data-decoy") || "aria-hidden".equals(k)) decoy = true;
      }
      if (!"csrf".equals(name) || val == null || val.isEmpty() || decoy) continue;
      if (type != null && "hidden".equalsIgnoreCase(type)) return val;
      if (fallback == null) fallback = val;
    }
    return fallback;
  }

  private static Session drop(Session s, String... keys) {
    Session t = s;
    for (String k : keys) t = t.remove(k);
    return t;
  }

  private static String value(Session s, String key) {
    if (!s.contains(key)) return "";
    Object o = s.get(key);
    return o == null ? "" : String.valueOf(o);
  }

  private static int code(Session s, String key) {
    try {
      return Integer.parseInt(value(s, key).trim());
    } catch (Exception e) {
      return -1;
    }
  }

  private static boolean truthy(Object o) {
    if (o == null) return false;
    if (o instanceof Boolean) return (Boolean) o;
    String v = String.valueOf(o).trim().toLowerCase(Locale.ROOT);
    return "true".equals(v) || "1".equals(v) || "yes".equals(v);
  }

  private static String jsonValue(String v) {
    if (v == null || v.isEmpty()) return "null";
    if (v.matches("-?\\d+")) return v;
    return "\"" + esc(v) + "\"";
  }

  private static String esc(String v) {
    if (v == null) return "";
    return v.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "").replace("\r", "");
  }

  private static String base() {
    String b = env("BASE_URL", "http://127.0.0.1:8000");
    while (b.endsWith("/")) b = b.substring(0, b.length() - 1);
    return b;
  }

  private static String env(String k, String d) {
    try {
      String v = System.getenv(k);
      return (v == null || v.trim().isEmpty()) ? d : v.trim();
    } catch (Exception e) {
      return d;
    }
  }

  private static int envInt(String k, int d) {
    try {
      return Integer.parseInt(env(k, String.valueOf(d)));
    } catch (Exception e) {
      return d;
    }
  }

  private static double envDouble(String k, double d) {
    try {
      return Double.parseDouble(env(k, String.valueOf(d)));
    } catch (Exception e) {
      return d;
    }
  }
}

/*
 * k6 1.0.0 — public shop, reservation mode.
 * Contract: 2 VUs x 2 iterations per VU (per-vu-iterations), one fresh login + one cart
 * + one 202 reservation job + one committed order per journey.
 * Variant agnostic: CSRF is parsed from real input[name=csrf] (decoys/attribute order
 * ignored), catalog order/paging is traversed dynamically, the 202 job id and its
 * dynamic status_url are extracted (never guessed) and correlated, and only a
 * status=ready reservation_id is ever handed to checkout.
 * Poll budget: <= 5 GETs per job, spaced by the profile poll_interval with the
 * protocol floor of 50ms (max(profile, 0.05)); pending/failed never reaches checkout.
 */

import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Counter, Rate, Trend } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = __ENV.PASSWORD || 'bench';
const ACCOUNTS = 16;
const VUS = parseInt(__ENV.VUS || '2', 10);
const ITERS = parseInt(__ENV.ITERATIONS || '2', 10);
const MAX_POLLS = 5;
const MAX_PAGES = 3;
const PROFILE_INTERVAL = parseFloat(__ENV.POLL_INTERVAL || '0.05');
const POLL_INTERVAL = Math.max(0.05, isNaN(PROFILE_INTERVAL) ? 0.05 : PROFILE_INTERVAL);

const jobCreated = new Rate('reservation_job_202');
const jobCorrelated = new Rate('job_status_url_correlated');
const reservationReady = new Rate('reservation_ready');
const orderAccepted = new Rate('order_accepted');
const ordersCommitted = new Counter('orders_committed');
const cartsCreated = new Counter('carts_created');
const pollBudgetOk = new Rate('poll_budget_ok');
const pollSpacingOk = new Rate('poll_spacing_ok');
const checkoutGuardOk = new Rate('checkout_guard_ok');
const pollCount = new Trend('job_poll_count', false);
const pollGapMs = new Trend('job_poll_gap_ms', true);

export const options = {
  scenarios: {
    reservation_journey: {
      executor: 'per-vu-iterations',
      vus: VUS,
      iterations: ITERS,
      maxDuration: '180s',
      gracefulStop: '10s',
    },
  },
  thresholds: {
    poll_budget_ok: ['rate==1'],
    checkout_guard_ok: ['rate==1'],
  },
  discardResponseBodies: false,
  summaryTrendStats: ['avg', 'min', 'max', 'p(95)'],
  tags: { mode: 'reservation' },
};

/* ---------------------------------------------------------------- helpers */

function json(res) {
  if (!res || typeof res.body !== 'string' || res.body.length === 0) return null;
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  const want = name.toLowerCase();
  const hs = (res && res.headers) || {};
  for (const k in hs) {
    if (k.toLowerCase() === want) return hs[k];
  }
  return null;
}

function isRedirect(status) {
  return status === 301 || status === 302 || status === 303 || status === 307 || status === 308;
}

function resolveUrl(u, basePath) {
  if (u === undefined || u === null) return null;
  const s = String(u).trim();
  if (s.length === 0) return null;
  if (/^https?:\/\//i.test(s)) {
    return s.substring(0, BASE_URL.length) === BASE_URL ? s : null; // no egress
  }
  if (s.charAt(0) === '/') return BASE_URL + s;
  const dir = (basePath || '/').replace(/[^/]*$/, '');
  return BASE_URL + (dir.charAt(0) === '/' ? dir : '/' + dir) + s;
}

function errorOf(res) {
  const b = json(res);
  if (!b) return '';
  const e = b.error || b.code || b.reason || '';
  return String(e).toLowerCase();
}

function retryAfterSeconds(res) {
  const raw = header(res, 'Retry-After');
  const n = parseFloat(raw);
  if (!isNaN(n) && n > 0) return Math.max(1, n);
  return 1;
}

function parseAttrs(tag) {
  const attrs = {};
  const re = /([a-zA-Z_:][-\w:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))/g;
  let m;
  while ((m = re.exec(tag)) !== null) {
    const key = m[1].toLowerCase();
    const val = m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4];
    if (!(key in attrs)) attrs[key] = val === undefined ? '' : val;
  }
  return attrs;
}

function csrfFromInputs(scope) {
  if (!scope) return null;
  const tags = scope.match(/<input\b[\s\S]*?>/gi) || [];
  let fallback = null;
  for (let i = 0; i < tags.length; i++) {
    const a = parseAttrs(tags[i]);
    if (!a.name || a.name.toLowerCase() !== 'csrf') continue; // decoys: csrf_alt, data-name=csrf...
    if (a['data-decoy'] !== undefined || a.disabled !== undefined) continue;
    if (!a.value) continue;
    if (a.type && a.type.toLowerCase() === 'hidden') return a.value;
    if (fallback === null) fallback = a.value;
  }
  return fallback;
}

function extractCsrfFromHtml(body) {
  if (!body || typeof body !== 'string') return null;
  const forms = body.match(/<form\b[\s\S]*?<\/form>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const open = forms[i].match(/<form\b[\s\S]*?>/i);
    const a = open ? parseAttrs(open[0]) : {};
    if (a.action && a.action.indexOf('/v2/login') >= 0) {
      const t = csrfFromInputs(forms[i]);
      if (t) return t;
    }
  }
  const any = csrfFromInputs(body);
  if (any) return any;
  const metas = body.match(/<meta\b[\s\S]*?>/gi) || [];
  for (let i = 0; i < metas.length; i++) {
    const a = parseAttrs(metas[i]);
    if (a.name && a.name.toLowerCase() === 'csrf' && a.content) return a.content;
  }
  return null;
}

function captureCsrf(state, res) {
  if (!res || res.status >= 400) return;
  const b = json(res);
  if (b && typeof b.csrf === 'string' && b.csrf.length > 0) state.csrf = b.csrf;
}

function captureEtag(state, res) {
  if (!res || res.status >= 400) return;
  const e = header(res, 'ETag');
  if (e) state.etag = e;
}

function authHeaders(state, withBody) {
  const h = { Accept: 'application/json' };
  if (withBody) h['Content-Type'] = 'application/json';
  if (state.csrf) h['X-CSRF-Token'] = state.csrf;
  return h;
}

function globalIteration() {
  try {
    if (exec && exec.scenario && typeof exec.scenario.iterationInTest === 'number') {
      return exec.scenario.iterationInTest;
    }
  } catch (e) {
    /* fall through */
  }
  let local = 0;
  try {
    local = exec.vu.iterationInScenario || 0;
  } catch (e2) {
    local = 0;
  }
  return (__VU - 1) * ITERS + local;
}

/* ------------------------------------------------------- session / login */

function login(state) {
  const formRes = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'GET /v2/login-form' },
  });
  if (!check(formRes, { 'login form 200': (r) => r.status === 200 })) return false;

  const formCsrf = extractCsrfFromHtml(formRes.body);
  if (!check(formCsrf, { 'login csrf parsed from real input[name=csrf]': (v) => !!v })) return false;
  state.csrf = formCsrf;

  let res = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({ username: state.username, password: PASSWORD, csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      redirects: 0,
      tags: { name: 'POST /v2/login' },
    }
  );

  if (isRedirect(res.status)) {
    const loc = header(res, 'Location');
    if (!check(loc, { 'login 302 carries dynamic Location': (v) => !!v })) return false;
    const target = resolveUrl(loc, '/v2/login');
    if (!target) return false;
    res = http.get(target, {
      headers: { Accept: 'application/json' },
      redirects: 0,
      tags: { name: 'GET /v2/login (redirect, once)' },
    });
  }

  const b = json(res);
  if (b && typeof b.csrf === 'string' && b.csrf.length > 0) state.csrf = b.csrf;
  else {
    const t = extractCsrfFromHtml(res.body);
    if (t) state.csrf = t;
  }
  const ok = check(res, { 'login session established': (r) => r.status >= 200 && r.status < 300 });
  return ok && !!state.csrf;
}

function readCart(state) {
  if (!state.cartId) return null;
  const res = http.get(BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId), {
    headers: { Accept: 'application/json' },
    redirects: 0,
    tags: { name: 'GET /v2/carts/{id}' },
  });
  captureEtag(state, res);
  return res;
}

function recoverCart(state) {
  if (!state.cartId) return;
  const res = http.post(
    BASE_URL + '/v2/carts/' + encodeURIComponent(state.cartId) + '/recover',
    JSON.stringify({}),
    { headers: authHeaders(state, true), redirects: 0, tags: { name: 'POST /v2/carts/{id}/recover' } }
  );
  captureCsrf(state, res);
  captureEtag(state, res);
}

function recoverSession(state, err) {
  if (err === 'expired') {
    const res = http.post(BASE_URL + '/v2/session/renew', JSON.stringify({}), {
      headers: authHeaders(state, true),
      redirects: 0,
      tags: { name: 'POST /v2/session/renew' },
    });
    captureCsrf(state, res);
    if (res.status >= 200 && res.status < 300) {
      recoverCart(state);
      return true;
    }
  }
  // revoked session (or renew refused): fresh form/login, then recover the same cart.
  if (!login(state)) return false;
  recoverCart(state);
  return true;
}

/* --------------------------------------------------- generic API wrapper */

function api(state, method, path, body, opts) {
  const o = opts || {};
  const url = /^https?:\/\//i.test(path) ? path : BASE_URL + path;
  const isRead = method === 'GET' || method === 'HEAD';
  let authRetried = false;
  let etagRetried = false;
  let rateRetries = 0;

  for (;;) {
    const headers = isRead ? { Accept: 'application/json' } : authHeaders(state, true);
    if (o.idemKey) headers['Idempotency-Key'] = o.idemKey;
    if (o.ifMatch && state.etag) headers['If-Match'] = state.etag;
    const params = {
      headers: headers,
      redirects: 0,
      tags: Object.assign({ name: method + ' ' + (o.name || path) }, o.tags || {}),
    };
    const payload = isRead ? null : JSON.stringify(body === undefined ? {} : body);
    const res = http.request(method, url, payload, params);
    captureCsrf(state, res);
    captureEtag(state, res);

    if (res.status === 401) {
      const err = errorOf(res);
      if (err === 'denied') {
        check(res, { '401 denied is not expiry (must fail)': () => false });
        return res;
      }
      if (authRetried) return res;
      authRetried = true;
      if (!recoverSession(state, err)) return res;
      continue; // retry only the interrupted operation, once
    }

    if (res.status === 412 && o.ifMatch && !etagRetried && state.cartId) {
      etagRetried = true;
      readCart(state);
      continue; // same payload, same Idempotency-Key
    }

    if (res.status === 429 && rateRetries < 4) {
      rateRetries += 1;
      sleep(retryAfterSeconds(res));
      continue;
    }

    return res;
  }
}

/* -------------------------------------------------------------- catalog */

function pushProducts(list, b) {
  if (!b) return;
  const data = b.data ? b.data : b;
  if (data.products && data.products.length) {
    for (let i = 0; i < data.products.length; i++) list.push(data.products[i]);
  } else if (data.product) {
    list.push(data.product);
  } else if (b.products && b.products.length) {
    for (let i = 0; i < b.products.length; i++) list.push(b.products[i]);
  }
}

function collectProducts(state) {
  const list = [];
  const first = api(state, 'GET', '/v2/catalog', null, { name: '/v2/catalog' });
  if (first.status === 200) {
    let b = json(first);
    pushProducts(list, b);
    let next = b ? b.next : null;
    let pages = 1;
    while (next && pages < MAX_PAGES) {
      const u = resolveUrl(next, '/v2/catalog');
      if (!u) break;
      const r = api(state, 'GET', u, null, { name: '/v2/catalog (page)' });
      if (r.status !== 200) break;
      b = json(r);
      pushProducts(list, b);
      next = b ? b.next : null;
      pages += 1;
    }
    if (list.length > 0) return list;
  }
  let url = '/v2/catalog/page';
  for (let p = 0; p < MAX_PAGES && url; p++) {
    const r = api(state, 'GET', url, null, { name: '/v2/catalog/page' });
    if (r.status !== 200) break;
    const b = json(r);
    pushProducts(list, b);
    url = b && b.next ? resolveUrl(b.next, '/v2/catalog/page') : null;
  }
  return list;
}

function inStock(v) {
  return v === true || v === 1 || v === 'true' || (typeof v === 'number' && v > 0);
}

function pickVariant(products) {
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p || p.id === undefined || p.id === null) continue;
    const vs = p.variants || [];
    for (let k = 0; k < vs.length; k++) {
      const v = vs[k];
      if (v && v.id !== undefined && v.id !== null && inStock(v.in_stock)) {
        return { productId: String(p.id), variantId: String(v.id) };
      }
    }
  }
  return null;
}

/* ------------------------------------------------- 202 job + status polls */

function extractJobId(b) {
  if (!b) return null;
  const c = [
    b.job_id,
    b.jobId,
    b.reservation_job_id,
    b.id,
    b.job ? b.job.id : null,
    b.data ? b.data.job_id || b.data.id : null,
  ];
  for (let i = 0; i < c.length; i++) {
    if (c[i] !== undefined && c[i] !== null && String(c[i]).length > 0) return String(c[i]);
  }
  return null;
}

function extractStatusUrl(b) {
  if (!b) return null;
  const c = [
    b.status_url,
    b.statusUrl,
    b.links ? b.links.status : null,
    b.job ? b.job.status_url : null,
    b.data ? b.data.status_url : null,
  ];
  for (let i = 0; i < c.length; i++) {
    if (c[i] !== undefined && c[i] !== null && String(c[i]).length > 0) return String(c[i]);
  }
  return null;
}

function pollJob(state, jobId, initialUrl) {
  let url = initialUrl;
  let polls = 0;
  let last = null;
  let status = null;
  let reservationId = null;
  let sawEcho = false;
  let correlated = String(initialUrl).indexOf(String(jobId)) >= 0;
  let recoveryUsed = false;

  while (polls < MAX_POLLS) {
    sleep(POLL_INTERVAL); // profile poll_interval, never below the 50ms protocol floor
    const started = Date.now();
    const res = http.get(url, {
      headers: { Accept: 'application/json' },
      redirects: 0,
      tags: { name: 'GET /v2/reservations/status', job_id: String(jobId) },
    });
    polls += 1;
    if (last !== null) {
      const gap = started - last;
      pollGapMs.add(gap);
      pollSpacingOk.add(gap >= POLL_INTERVAL * 1000 - 10 ? 1 : 0);
    }
    last = started;

    if (res.status === 401) {
      const err = errorOf(res);
      if (err === 'denied') {
        check(res, { 'status poll denied is not expiry (must fail)': () => false });
        status = 'denied';
        break;
      }
      if (!recoveryUsed) {
        recoveryUsed = true;
        recoverSession(state, err);
      }
      continue;
    }
    if (res.status === 429) {
      sleep(retryAfterSeconds(res));
      continue;
    }
    if (res.status !== 200) {
      check(res, { 'job status poll 200': (r) => r.status === 200 });
      break;
    }

    const b = json(res);
    if (!b) {
      check(null, { 'job status body parsed': () => false });
      break;
    }
    const echo = b.job_id || b.id || (b.job ? b.job.id : null);
    if (echo !== undefined && echo !== null && String(echo).length > 0) {
      sawEcho = true;
      correlated = String(echo) === String(jobId);
      if (!correlated) break;
    }
    status = String(b.status || b.state || '').toLowerCase();
    if (b.status_url) {
      const nu = resolveUrl(b.status_url, '/v2/reservations');
      if (nu) url = nu;
    }
    if (status === 'ready') {
      const rid = b.reservation_id || (b.reservation ? b.reservation.id : null);
      if (rid !== undefined && rid !== null && String(rid).length > 0) reservationId = String(rid);
      break;
    }
    if (status === 'failed' || status === 'error' || status === 'cancelled') break;
  }

  if (!sawEcho) correlated = true; // status_url came from the same 202 payload as the job id
  return { polls: polls, status: status, reservationId: reservationId, correlated: correlated };
}

/* -------------------------------------------------------------- journey */

function runJourney(state, journeyIndex) {
  const out = { guardOk: true, polls: 0, ordered: false };

  if (!login(state)) return out;

  const pick = pickVariant(collectProducts(state));
  if (!check(pick, { 'catalog yielded an in-stock variant': (p) => !!p })) return out;

  // Exactly one cart per journey.
  const cartRes = api(
    state,
    'POST',
    '/v2/carts',
    { product_id: pick.productId, variant_id: pick.variantId },
    { name: '/v2/carts', tags: { stage: 'cart' } }
  );
  const cartBody = json(cartRes);
  const cartOk = check(cartRes, { 'cart created 201': (r) => r.status === 201 });
  if (!cartOk || !cartBody || cartBody.id === undefined || cartBody.id === null) return out;
  state.cartId = String(cartBody.id);
  cartsCreated.add(1);

  // 202 reservation job for THIS cart.
  const jobRes = api(
    state,
    'POST',
    '/v2/reservations',
    { cart_id: state.cartId },
    { name: '/v2/reservations', tags: { stage: 'reservation', cart_id: state.cartId } }
  );
  const jobBody = json(jobRes);
  const accepted202 = check(jobRes, { 'reservation job accepted 202': (r) => r.status === 202 });
  jobCreated.add(accepted202 ? 1 : 0);
  if (!accepted202 || !jobBody) return out;

  const jobId = extractJobId(jobBody);
  const rawStatusUrl = extractStatusUrl(jobBody);
  const statusUrl = resolveUrl(rawStatusUrl, '/v2/reservations');
  const setupOk = check(
    { jobId: jobId, statusUrl: statusUrl },
    {
      '202 job id extracted': (v) => !!v.jobId,
      '202 dynamic status_url extracted (not guessed)': (v) => !!v.statusUrl,
    }
  );
  if (!setupOk) return out;

  const poll = pollJob(state, jobId, statusUrl);
  out.polls = poll.polls;
  jobCorrelated.add(poll.correlated ? 1 : 0);
  check(poll, { 'pollled status URL belongs to the 202 job': (p) => p.correlated === true });

  const ready = poll.status === 'ready' && !!poll.reservationId;
  reservationReady.add(ready ? 1 : 0);
  // Negative control (job_fails) and exhausted pending jobs fail here and never check out.
  if (!check(poll, { 'reservation ready before checkout': (p) => p.status === 'ready' && !!p.reservationId })) {
    return out;
  }
  if (!poll.correlated) return out;

  readCart(state); // fresh ETag for If-Match

  const idemKey = 'order-' + state.cartId + '-' + journeyIndex; // unique per cart, stable on retry
  const orderRes = api(
    state,
    'POST',
    '/v2/orders',
    { cart_id: state.cartId, reservation_id: poll.reservationId },
    {
      name: '/v2/orders',
      idemKey: idemKey,
      ifMatch: true,
      tags: { stage: 'order', cart_id: state.cartId, job_id: String(jobId) },
    }
  );
  const ob = json(orderRes);
  const committed = !!(orderRes.status === 201 && ob && ob.accepted === true && ob.id !== undefined && ob.id !== null);
