    { res: orderRes, body: ob, committed: committed, cartId: state.cartId, rid: poll.reservationId },
    {
      'order committed 201 accepted:true': (v) => v.committed === true,
      'no HTTP200 accepted:false business failure': (v) => !(v.res.status === 200 && v.body && v.body.accepted === false),
      'checkout consumed this cart': (v) => !v.body || v.body.cart_id === undefined || String(v.body.cart_id) === v.cartId,
      'checkout consumed the ready reservation': (v) =>
        !v.body || v.body.reservation_id === undefined || String(v.body.reservation_id) === v.rid,
    }
  );
  orderAccepted.add(committed ? 1 : 0);
  if (committed) {
    ordersCommitted.add(1);
    out.ordered = true;
  }
  return out;
}

export default function () {
  const journeyIndex = globalIteration();
  const username = 'bench-' + ((journeyIndex % ACCOUNTS) + 1);

  const jar = http.cookieJar(); // per-VU jar: per-user cookies preserved
  jar.clear(BASE_URL); // fresh login/cart for every journey

  const state = { username: username, csrf: null, cartId: null, etag: null };
  const out = runJourney(state, journeyIndex);

  pollCount.add(out.polls);
  pollBudgetOk.add(out.polls <= MAX_POLLS ? 1 : 0);
  checkoutGuardOk.add(out.guardOk ? 1 : 0);
}

