    p = _parse_html(text)
    cands = []
    for form in p.forms:
        act = form["action"] or ""
        for inp in form["inputs"]:
            if inp["name"] == "csrf" and _usable(inp):
                score = 3.0 if (action_hint and action_hint in act) else 2.0
                if inp["type"] == "hidden":
                    score += 0.5
                cands.append((score, inp["value"]))
    for inp in p.inputs:
        if inp["name"] == "csrf" and _usable(inp):
            cands.append((1.0 + (0.5 if inp["type"] == "hidden" else 0.0), inp["value"]))
    if not cands:
        return None
    cands.sort(key=lambda x: -x[0])
    return cands[0][1]


