# locustfile.py — reservation mode: 202 job -> dynamic status_url -> ready reservation_id -> one order
import os
import re
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, constant, task

HOST = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")

USERS = 2
ITERATIONS = 2
MODE = "reservation"

PROFILES = [
    {"job_polls": 2, "poll_interval": 0.02},
    {"job_polls": 3, "poll_interval": 0.02, "html_layout": 1, "reverse_catalog": True},
]

MAX_POLLS = 5
MIN_POLL_GAP = 0.05
MAX_PAGES = 3
RUN_BUDGET_S = 150.0

_STATE = {"slots": list(range(USERS)), "done": 0, "t0": None}
TOTAL_JOURNEYS = USERS * ITERATIONS


# --------------------------------------------------------------------------- html


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.stack = []
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        a = {}
        for k, v in attrs:
            a[k.lower()] = v if v is not None else ""
        if tag == "form":
            form = {"action": a.get("action", ""), "inputs": []}
            self.forms.append(form)
            self.stack.append(form)
        elif tag == "input":
            rec = {
                "name": a.get("name", ""),
                "value": a.get("value", ""),
                "type": (a.get("type") or "").lower(),
                "attrs": a,
            }
            self.inputs.append(rec)
            if self.stack:
                self.stack[-1]["inputs"].append(rec)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag == "form" and self.stack:
            self.stack.pop()


def _parse_html(text):
    p = FormParser()
    try:
        p.feed(text or "")
        p.close()
    except Exception:
        pass
    return p


def _usable(inp):
    a = inp["attrs"]
    if "disabled" in a:
        return False
    if inp["type"] in ("submit", "button", "reset", "image", "checkbox", "radio"):
        return False
    if a.get("data-decoy") or a.get("data-fake"):
        return False
    return bool(inp["value"])


def csrf_from_html(text, action_hint):
    p = _parse_html(text)
    cands = []
    for form in p.forms:
        act = form["action"] or ""
        for inp in form["inputs"]:
            if inp["name"] == "csrf" and _usable(inp):
                score = 3.0 if (action_hint and action_hint in act) else 2.0
                if inp["type"] == "hidden":
                    score += 0.5
                cands.append((score, inp["value"]))
    for inp in p.inputs:
        if inp["name"] == "csrf" and _usable(inp):
            cands.append((1.0 + (0.5 if inp["type"] == "hidden" else 0.0), inp["value"]))
    if not cands:
        return None
    cands.sort(key=lambda x: -x[0])
    return cands[0][1]


def challenge_from_html(text):
    p = _parse_html(text)
    action = None
    for form in p.forms:
        act = form["action"] or ""
        if "/v2/challenges/" in act:
            action = act
            for inp in form["inputs"]:
                if inp["name"] == "challenge" and _usable(inp):
                    return act, inp["value"]
    if action is None:
        m = re.search(r"""action\s*=\s*["']?(/v2/challenges/[^"'\s>]+)""", text or "")
        if m:
            action = m.group(1)
    value = None
    for inp in p.inputs:
        if inp["name"] == "challenge" and _usable(inp):
            value = inp["value"]
            break
    if action and value is not None:
        return action, value
    return None, None


def job_view(d):
    """(status, reservation_id, explicit_job_id) from a job/status payload."""
    if not isinstance(d, dict):
        return None, None, None
    node = d.get("job") if isinstance(d.get("job"), dict) else d
    status = node.get("status") or node.get("state") or d.get("status") or d.get("state")
    rid = node.get("reservation_id") or d.get("reservation_id")
    if not rid:
        res = node.get("reservation") if isinstance(node.get("reservation"), dict) else None
        if res is None and isinstance(d.get("reservation"), dict):
            res = d["reservation"]
        if res:
            rid = res.get("id") or res.get("reservation_id")
    jid = node.get("job_id") or d.get("job_id")
    if isinstance(status, str):
        status = status.lower()
    return status, rid, jid


def _body(r):
    try:
        return r.json()
    except Exception:
        return None


def _text(r):
    try:
        return r.text or ""
    except Exception:
        return ""


# --------------------------------------------------------------------------- user


class ReservationUser(HttpUser):
    host = HOST
    wait_time = constant(0.05)
    abstract = False

    def on_start(self):
        self.slot = _STATE["slots"].pop(0) if _STATE["slots"] else None
        self.profile = PROFILES[self.slot % len(PROFILES)] if self.slot is not None else PROFILES[0]
        self.iteration = 0
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.account = None

    # ------------------------------------------------------------------ transport

    def api(self, method, path, payload=None, headers=None, name=None,
            validator=None, allow_recovery=True, redirects=True):
        url = urljoin(HOST + "/", path)
        hdrs = dict(headers or {})
        if method.upper() != "GET" and self.csrf:
            hdrs.setdefault("X-CSRF-Token", self.csrf)
        hdrs.setdefault("Accept", "application/json")
        out = {"status": 0, "data": None, "headers": {}, "text": "", "error": None, "retry": False}
        sample = name or path
        with self.client.request(
            method,
            url,
            json=payload,
            headers=hdrs,
            name=sample,
            catch_response=True,
            allow_redirects=redirects,
        ) as r:
            data = _body(r)
            text = _text(r)
            out["status"] = r.status_code
            out["data"] = data
            out["headers"] = dict(r.headers)
            out["text"] = text
            kind = data.get("error") if isinstance(data, dict) else None
            if r.status_code == 401 and kind in ("expired", "session"):
                if not allow_recovery:
                    msg = "401 %s after bounded recovery" % kind
                    out["error"] = msg
                    r.failure(msg)
                elif self._recover_session(kind):
                    r.success()  # scheduled/expected interruption, handled once
                    out["retry"] = True
                else:
                    msg = "401 %s: session recovery failed" % kind
                    out["error"] = msg
                    r.failure(msg)
            else:
                if validator is not None:
                    err = validator(r.status_code, data, r.headers, text)
                else:
                    err = None if r.status_code < 400 else "HTTP %s" % r.status_code
                if err:
                    out["error"] = err
                    r.failure(err)
                else:
                    r.success()
        if out["retry"]:
            h2 = dict(headers or {})
            h2.pop("X-CSRF-Token", None)
            if "If-Match" in h2 and self.cart_etag:
                h2["If-Match"] = self.cart_etag
            return self.api(method, path, payload, h2, name, validator,
                            allow_recovery=False, redirects=redirects)
        return out

    def _keep_csrf(self, data):
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _recover_session(self, kind):
        ren = self.api(
            "POST", "/v2/session/renew", {}, name="/v2/session/renew",
            validator=lambda s, d, h, t: None if s in (200, 401) else "renew HTTP %s" % s,
            allow_recovery=False,
        )
        renewed = ren["status"] == 200
        if renewed:
            self._keep_csrf(ren["data"])
        else:
            if not self._login():
                return False
        if self.cart_id:
            rec = self.api(
                "POST", "/v2/carts/%s/recover" % self.cart_id, {},
                name="/v2/carts/[id]/recover",
                validator=lambda s, d, h, t: None if s in (200, 201) else "cart recover HTTP %s" % s,
                allow_recovery=False,
            )
            if rec["error"]:
                return False
            self._keep_csrf(rec["data"])
            et = rec["headers"].get("ETag") or rec["headers"].get("etag")
            if et:
                self.cart_etag = et
        return True

    # ------------------------------------------------------------------ session

    def _login(self):
        self.client.cookies.clear()
        self.csrf = None
        form = self.api(
            "GET", "/v2/login-form", name="/v2/login-form", allow_recovery=False,
            validator=lambda s, d, h, t: (
                None if s == 200 and csrf_from_html(t, "/v2/login") else "login-form HTTP %s / no csrf" % s
            ),
        )
        if form["error"]:
            return False
        token = csrf_from_html(form["text"], "/v2/login")
        self.csrf = token
        out = self.api(
            "POST", "/v2/login",
            {"username": self.account, "password": "bench", "csrf": token},
            name="/v2/login", allow_recovery=False, redirects=False,
            validator=lambda s, d, h, t: (
                None if (s == 200 and isinstance(d, dict))
                or (s in (301, 302, 303, 307, 308) and h.get("Location"))
                else "login HTTP %s" % s
            ),
        )
        if out["error"]:
            return False
        data = out["data"]
        if out["status"] in (301, 302, 303, 307, 308):
            loc = out["headers"].get("Location")
            nxt = self.api(
                "GET", loc, name="/v2/login/redirect", allow_recovery=False, redirects=False,
                validator=lambda s, d, h, t: None if s == 200 else "login redirect HTTP %s" % s,
            )
            if nxt["error"]:
                return False
            data = nxt["data"]
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
        else:
            self.csrf = token
        return True

    # ------------------------------------------------------------------ catalog

    def _pick_variant(self):
        products = []
        out = self.api(
            "GET", "/v2/catalog", name="/v2/catalog",
            validator=lambda s, d, h, t: None if s == 200 and isinstance(d, dict) else "catalog HTTP %s" % s,
        )
        if not out["error"]:
            node = out["data"].get("data") or {}
            products = list(node.get("products") or [])
        if not products:
            path = "/v2/catalog/page"
            pages = 0
            while path and pages < MAX_PAGES:
                page = self.api(
                    "GET", path, name="/v2/catalog/page",
                    validator=lambda s, d, h, t: None if s == 200 and isinstance(d, dict) else "catalog page HTTP %s" % s,
                )
                pages += 1
                if page["error"]:
                    break
                d = page["data"] or {}
                node = d.get("data") or {}
                got = node.get("products") or d.get("products") or []
                if not got:
                    single = node.get("product") or d.get("product")
                    if isinstance(single, dict):
                        got = [single]
                products.extend(got)
                path = d.get("next") or node.get("next")
        if self.profile.get("reverse_catalog"):
            products = list(reversed(products))
        for prod in products:
            if not isinstance(prod, dict):
                continue
            variants = prod.get("variants") or []
            if self.profile.get("reverse_catalog"):
                variants = list(reversed(variants))
            for var in variants:
                if isinstance(var, dict) and var.get("in_stock") and prod.get("id") and var.get("id"):
                    return prod["id"], var["id"]
        return None, None

    # ------------------------------------------------------------------ challenge

    def _grant(self):
        form = self.api(
            "GET", "/v2/challenge-form", name="/v2/challenge-form",
            validator=lambda s, d, h, t: (
                None if s == 404 or (s == 200 and challenge_from_html(t)[0]) else "challenge-form HTTP %s" % s
            ),
        )
        if form["error"] or form["status"] == 404:
            return None
        action, challenge = challenge_from_html(form["text"])
        if not action or challenge is None:
            return None
        posted = self.api(
            "POST", action, {"challenge": challenge}, name="/v2/challenges/[id]", redirects=False,
            validator=lambda s, d, h, t: (
                None if s in (301, 302, 303, 307, 308) and h.get("Location") else "challenge POST HTTP %s" % s
            ),
        )
        if posted["error"]:
            return None
        loc = posted["headers"].get("Location")
        got = self.api(
            "GET", loc, name="/v2/challenges/[id]/grant", redirects=False,
            validator=lambda s, d, h, t: (
                None if s == 200 and isinstance(d, dict) and d.get("grant_id") else "grant HTTP %s" % s
            ),
        )
        if got["error"]:
            return None
        self._keep_csrf(got["data"])
        return got["data"]["grant_id"]

    # ------------------------------------------------------------------ cart

    def _create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        out = self.api(
            "POST", "/v2/carts", payload, name="/v2/carts",
            validator=lambda s, d, h, t: (
                None if s == 201 and isinstance(d, dict) and d.get("id") else "cart create HTTP %s" % s
            ),
        )
        if out["error"]:
            return False
        self.cart_id = out["data"]["id"]
        self._keep_csrf(out["data"])
        et = out["headers"].get("ETag") or out["headers"].get("etag")
        if et:
            self.cart_etag = et
        return True

    def _read_etag(self):
        out = self.api(
            "GET", "/v2/carts/%s" % self.cart_id, name="/v2/carts/[id]",
            validator=lambda s, d, h, t: (
                None if s == 200 and (h.get("ETag") or h.get("etag")) else "cart read HTTP %s / no ETag" % s
            ),
        )
        if out["error"]:
            return None
        self.cart_etag = out["headers"].get("ETag") or out["headers"].get("etag")
        return self.cart_etag

    def _set_quantity(self, qty):
        payload = {"quantity": qty}
        for attempt in range(2):
            etag = self._read_etag()
            if not etag:
                return False

            def v(s, d, h, t, attempt=attempt):
                if s in (200, 201):
                    return None
                if s == 412 and attempt == 0:
                    return None  # re-read ETag and retry the same payload once
                return "PATCH cart HTTP %s" % s

            out = self.api(
                "PATCH", "/v2/carts/%s" % self.cart_id, payload,
                headers={"If-Match": etag}, name="/v2/carts/[id]", validator=v,
            )
            if out["status"] == 412 and attempt == 0:
                continue
            if out["error"]:
                return False
            self._keep_csrf(out["data"])
            et = out["headers"].get("ETag") or out["headers"].get("etag")
            if et:
                self.cart_etag = et
            return True
        return False

    # ------------------------------------------------------------------ reservation job

    def _reservation(self):
        created = self.api(
            "POST", "/v2/reservations", {"cart_id": self.cart_id}, name="/v2/reservations",
            validator=lambda s, d, h, t: (
                None if s == 202 and isinstance(d, dict) and d.get("status_url")
                else "reservation submit expected 202+status_url, got HTTP %s" % s
            ),
        )
        if created["error"]:
            return None
        data = created["data"]
        self._keep_csrf(data)
        status_url = data["status_url"]
        job_id = data.get("job_id") or data.get("id")
        if isinstance(data.get("job"), dict):
            job_id = data["job"].get("id") or job_id

        gap = max(MIN_POLL_GAP, float(self.profile.get("poll_interval") or 0.0))
        for _ in range(MAX_POLLS):
            time.sleep(gap)

            def v(s, d, h, t):
                if s != 200 or not isinstance(d, dict):
                    return "job status HTTP %s" % s
                state, rid, jid = job_view(d)
                if job_id and jid and str(jid) != str(job_id):
                    return "job status belongs to another job"
                if state == "ready":
                    return None if rid else "ready without reservation_id"
                if state == "pending":
                    return None
                if state == "failed":
                    return "reservation job failed"
                return "unexpected job status %r" % (state,)

            poll = self.api("GET", status_url, name="/v2/reservations/status", validator=v)
            if poll["error"]:
                return None
            self._keep_csrf(poll["data"])
            state, rid, _jid = job_view(poll["data"])
            if state == "ready" and rid:
                return rid
            if state != "pending":
                return None
        return None

    # ------------------------------------------------------------------ checkout

    def _checkout(self, reservation_id):
        idem = "%s-%s" % (self.cart_id, uuid.uuid4().hex)
        payload = {"cart_id": self.cart_id, "reservation_id": reservation_id}
        for attempt in range(2):
            headers = {"Idempotency-Key": idem}
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            def v(s, d, h, t, attempt=attempt):
                if s == 201 and isinstance(d, dict) and d.get("accepted") is True and d.get("id"):
                    return None
                if s == 200 and isinstance(d, dict) and d.get("accepted") is False:
                    return "order rejected: accepted=false"
                if s == 412 and attempt == 0:
                    return None  # refresh ETag, retry once with the same Idempotency-Key
                return "order HTTP %s" % s

            out = self.api(
                "POST", "/v2/orders", payload, headers=headers, name="/v2/orders", validator=v,
            )
            if out["status"] == 412 and attempt == 0:
                if not self._read_etag():
                    return False
                continue
            if out["error"]:
                return False
            self._keep_csrf(out["data"])
            return True
        return False

    # ------------------------------------------------------------------ journey

    def _journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        idx = self.slot * ITERATIONS + self.iteration
        self.account = "bench-%d" % (idx % 16 + 1)

        if not self._login():
            return
        product_id, variant_id = self._pick_variant()
        if not product_id:
            return
        grant_id = self._grant()
        if not self._create_cart(product_id, variant_id, grant_id):
            return
        if not self._set_quantity(2):
            return
        reservation_id = self._reservation()
        if not reservation_id:
            return  # pending/failed jobs never reach checkout
        self._checkout(reservation_id)

    @task
    def run_journey(self):
        if self.slot is None or self.iteration >= ITERATIONS:
            raise StopUser()
        self.iteration += 1
        try:
            self._journey()
        except StopUser:
            raise
        except Exception:
            pass  # request-level assertions already reported truthfully
        finally:
            _STATE["done"] += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ReservationShape(LoadTestShape):
    def tick(self):
        now = time.time()
        if _STATE["t0"] is None:
            _STATE["t0"] = now
        if _STATE["done"] >= TOTAL_JOURNEYS:
            return None
        if now - _STATE["t0"] > RUN_BUDGET_S:
            return None
        return (int(USERS), float(USERS), [ReservationUser])
