              .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find().saveAs("variant"))
              .check(jsonPath("$.csrf").find().optional().saveAs("csrf")))

          // HTTPSamplerProxy-31 POST /v2/carts, assertion "id"\s*:\s*"cart- , ETag captured
          .exec(http("create_cart")
              .post("/v2/carts")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .body(StringBody(session -> {
                StringBuilder body = new StringBuilder("{\"product_id\":\"")
                    .append(session.getString("product"))
                    .append("\",\"variant_id\":\"")
                    .append(session.getString("variant"))
                    .append("\"");
                if (session.contains("grant")) {
                  body.append(",\"grant_id\":\"").append(session.getString("grant")).append("\"");
                }
                return body.append("}").toString();
              }))
              .check(status().is(201))
              .check(regex("\"id\"\\s*:\\s*\"cart-").exists())
              .check(jsonPath("$.id").find().saveAs("cart"))
              .check(header("ETag").saveAs("etag"))
              .check(jsonPath("$.csrf").find().optional().saveAs("csrf")))

          // HTTPSamplerProxy-38 POST /v2/orders, Idempotency-Key = ${cart}, If-Match = ${etag}
          .exec(http("create_order")
              .post("/v2/orders")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .header("Idempotency-Key", "#{cart}")
              .header("If-Match", "#{etag}")
              .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
              .check(status().is(201))
              .check(regex("\"accepted\"\\s*:\\s*true").exists())
              .check(jsonPath("$.accepted").ofBoolean().is(true))
              .check(jsonPath("$.id").find().saveAs("order"))
              .check(jsonPath("$.csrf").find().optional().saveAs("csrf")));

  private static final ScenarioBuilder SHOP_FLOW = scenario("TestPlan-0")
      .feed(accounts())
      .repeat(ITERATIONS).on(RESET_JOURNEY.exec(JOURNEY));

  {
    setUp(SHOP_FLOW.injectOpen(atOnceUsers(USERS)))
        .protocols(HTTP_PROTOCOL)
        .assertions(global().failedRequests().percent().is(0.0));
  }
}
