```javascript
// k6 1.0.0 translation of TestPlan-0 (source-m01.jmx)
// ThreadGroup-2: 2 threads x 2 loops (iterations per user), ramp 0, on_sample_error=continue
// CookieManager-3: clearEachIteration=true  -> fresh cookies / fresh login / fresh cart per journey
// Flow: GET /v2/login-form -> POST /v2/login -> [IfController-20: GET ${location} once]
//       -> GET /v2/catalog -> POST /v2/carts -> POST /v2/orders   (one committed order per journey)
import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const TIMEOUT = '3s'; // HTTPSampler.response_timeout=3000 (connect_timeout=2000)
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    jmx_thread_group_2: {
      executor: 'per-vu-iterations',
      vus: 2,          // ThreadGroup.num_threads
      iterations: 2,   // LoopController.loops (per user)
      maxDuration: '3m',
      exec: 'default',
    },
  },
  noCookiesReset: false,   // CookieManager.clearEachIteration=true
  maxRedirects: 0,         // follow_redirects=false / auto_redirects=false
  discardResponseBodies: false,
  thresholds: {
    checks: ['rate>0.95'],
  },
};

// ---- per-iteration variables (JMeter Arguments-1 defaults) -------------------
let S;
function freshState() {
  return {
    csrf: null,      // csrf=MISSING
    form: null,      // RegexExtractor-9
    cart: null,      // cart=MISSING (reset by RegexExtractor-10 on login-form)
    etag: null,      // etag=MISSING
    hasCart: false,  // hasCart=false
    grant: null,     // grant=MISSING
    product: null,   // product=MISSING
    variant: null,   // variant=MISSING
    quantity: 2,     // quantity=2 (unused by this plan)
  };
}

function resetCookies() {
  const jar = http.cookieJar();
  try {
    if (typeof jar.clear === 'function') {
      jar.clear(BASE);
      return;
    }
  } catch (e) { /* fall through */ }
  let names = [];
  try {
    names = Object.keys(jar.cookiesForURL(BASE) || {});
  } catch (e) {
    names = [];
  }
  for (let i = 0; i < names.length; i++) {
    try {
      jar.set(BASE, names[i], '', { max_age: 0, path: '/' });
    } catch (e) { /* ignore */ }
  }
}

// ---- helpers ----------------------------------------------------------------
function absolute(path) {
  if (!path) return BASE;
  if (/^https?:\/\//i.test(path)) return path;
  return BASE + (path.charAt(0) === '/' ? path : '/' + path);
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === name.toLowerCase()) {
      const v = res.headers[keys[i]];
      return typeof v === 'string' ? v.trim() : String(v);
    }
  }
  return null;
}

function jbody(res) {
  if (!res || !res.body) return null;
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function field(res, name) {
  const b = jbody(res);
  if (b && typeof b[name] === 'string' && b[name].length > 0) return b[name];
  if (b && typeof b[name] === 'number') return String(b[name]);
  return null;
}

// JSONPostProcessor *.csrf with default ${csrf}: retain previous token if absent
function takeCsrf(res) {
  const v = field(res, 'csrf');
  if (v) S.csrf = v;
}

// RegexExtractor etag on headers, default ${etag}
function takeEtag(res) {
  const v = header(res, 'ETag');
  if (v) S.etag = v;
}

function jsonHeaders() {
  return { 'Content-Type': 'application/json', Accept: 'application/json, text/html;q=0.9, */*;q=0.8' };
}

function authHeaders() {
  const h = jsonHeaders();
  if (S.csrf) h['X-CSRF-Token'] = S.csrf;
  return h;
}

function merge(a, b) {
  const out = {};
  Object.keys(a || {}).forEach((k) => { out[k] = a[k]; });
  Object.keys(b || {}).forEach((k) => { out[k] = b[k]; });
  return out;
}

function raw(method, url, body, headers, name) {
  const params = { headers: headers, timeout: TIMEOUT, redirects: 0, tags: { name: name } };
  return http.request(method, url, body === undefined ? null : body, params);
}

// scheduled 429: honour Retry-After (>=1s), at most 4 retries
function send(method, url, body, headers, name) {
  let res = raw(method, url, body, headers, name);
  let tries = 0;
  while (res.status === 429 && tries < 4) {
    let wait = parseFloat(header(res, 'Retry-After'));
    if (!isFinite(wait) || wait < 1) wait = 1;
    sleep(wait);
    tries++;
    res = raw(method, url, body, headers, name);
  }
  return res;
}

// RegexExtractor-9 equivalent: first <input> whose name is exactly csrf, any attribute order
function extractFormCsrf(body) {
  if (!body) return null;
  const tags = body.match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];
    const nameM = tag.match(/\bname\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!nameM) continue;
    const nameVal = nameM[2] !== undefined ? nameM[2] : (nameM[3] !== undefined ? nameM[3] : nameM[4]);
    if (nameVal !== 'csrf') continue;
    const valM = tag.match(/\bvalue\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!valM) continue;
    const value = valM[2] !== undefined ? valM[2] : (valM[3] !== undefined ? valM[3] : valM[4]);
    if (value) return value;
  }
  return null;
}

function isRedirect(status) {
  return status === 301 || status === 302 || status === 303 || status === 307 || status === 308;
}

function loginSequence(username) {
  const formRes = send('GET', BASE + '/v2/login-form', null, jsonHeaders(), 'login_form');
  takeCsrf(formRes);
  const formOk = check(formRes, { 'login-form status 200': (r) => r.status === 200 });
  const form = extractFormCsrf(formRes.body);
  const tokenOk = check(form, { 'login-form csrf input correlated': (v) => typeof v === 'string' && v.length > 0 });
  if (!formOk || !tokenOk) return false;
  S.form = form;

  const loginRes = send(
    'POST',
    BASE + '/v2/login',
    JSON.stringify({ username: username, password: PASSWORD, csrf: S.form }),
    jsonHeaders(),
    'login'
  );
  takeCsrf(loginRes);
  takeEtag(loginRes);

  let ok;
  const loc = header(loginRes, 'Location');
  if (isRedirect(loginRes.status) && loc) {
    // IfController-20 / HTTPSamplerProxy-21: GET the dynamic Location exactly once
    const redirRes = send('GET', absolute(loc), null, authHeaders(), 'login_redirect');
    takeCsrf(redirRes);
    takeEtag(redirRes);
    const g = field(redirRes, 'grant_id');
    if (g) S.grant = g;
    ok = check(redirRes, {
      'login redirect target has csrf': (r) => r.status === 200 && /"csrf"\s*:/.test(r.body || ''),
    });
  } else {
    // ResponseAssertion-17
    ok = check(loginRes, {
      'login response has csrf': (r) => r.status === 200 && /"csrf"\s*:/.test(r.body || ''),
    });
  }
  return !!ok && !!S.csrf;
}

function refreshCartEtag() {
  if (!S.cart) return;
  const res = send('GET', BASE + '/v2/carts/' + S.cart, null, authHeaders(), 'cart_read');
  takeCsrf(res);
  takeEtag(res);
}

// Bounded 401 recovery: renew (+ fresh login when revoked), recover cart, caller retries once
function recoverSession(err) {
  const renewRes = send('POST', BASE + '/v2/session/renew', '{}', authHeaders(), 'session_renew');
  takeCsrf(renewRes);
  const renewed = renewRes.status >= 200 && renewRes.status < 300;
  if (err === 'session' || !renewed) {
    if (!loginSequence(S.username)) return false;
  }
  if (S.cart) {
    const recRes = send('POST', BASE + '/v2/carts/' + S.cart + '/recover', '{}', authHeaders(), 'cart_recover');
    takeCsrf(recRes);
    if (recRes.status < 200 || recRes.status >= 300) return false;
    refreshCartEtag();
  }
  return true;
}

function authSend(method, path, bodyObj, extraFn, name) {
  const url = absolute(path);
  const body = bodyObj === null || bodyObj === undefined ? null : JSON.stringify(bodyObj);
  let res = send(method, url, body, merge(authHeaders(), extraFn()), name);
  takeCsrf(res);
  takeEtag(res);

  if (res.status === 401) {
    const err = field(res, 'error');
    // error=denied is not expiry: no recovery, the assertion must fail
    if (err === 'expired' || err === 'session') {
      if (recoverSession(err)) {
        res = send(method, url, body, merge(authHeaders(), extraFn()), name);
        takeCsrf(res);
        takeEtag(res);
      }
    }
  }
  return res;
}

// ---- journey ----------------------------------------------------------------
export default function () {
  S = freshState();
  resetCookies();
  S.username = 'bench-' + exec.vu.idInTest; // bench-${__threadNum}

  if (!loginSequence(S.username)) return;

  // HTTPSamplerProxy-26 + JSONPostProcessor-28 (first product with variants[0].in_stock == true)
  const catRes = authSend('GET', '/v2/catalog', null, () => ({}), 'catalog');
  const catOk = check(catRes, { 'catalog status 200': (r) => r.status === 200 });
  const catBody = jbody(catRes);
  const products = catBody && catBody.data && Array.isArray(catBody.data.products) ? catBody.data.products : [];
  let picked = null;
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (p && Array.isArray(p.variants) && p.variants[0] && p.variants[0].in_stock === true) {
      picked = p;
      break;
    }
  }
  if (picked) {
    S.product = picked.id;
    S.variant = picked.variants[0].id;
  }
  const pickOk = check(S.product, {
    'in-stock product/variant correlated': (v) => v !== null && v !== undefined && v !== '',
  });
  if (!catOk || !pickOk || !S.variant) return;

  // HTTPSamplerProxy-31 (grant_id only when actually captured, never a guessed sentinel)
  const cartPayload = { product_id: S.product, variant_id: S.variant };
  if (S.grant) cartPayload.grant_id = S.grant;
  const cartRes = authSend('POST', '/v2/carts', cartPayload, () => ({}), 'cart_create');
  const cartBody = jbody(cartRes);
  if (cartBody && typeof cartBody.id === 'string' && /^cart-/.test(cartBody.id)) {
    S.cart = cartBody.id;   // JSONPostProcessor-33
    S.hasCart = true;       // RegexExtractor-37
  }
  // ResponseAssertion-36
  const cartOk = check(cartRes, {
    'cart created 201': (r) => r.status === 201,
    'cart id is cart-': (r) => /"id"\s*:\s*"cart-/.test(r.body || ''),
  });
  if (!cartOk || !S.cart) return;
  if (!S.etag) refreshCartEtag();

  // HTTPSamplerProxy-38: one order per journey, Idempotency-Key = ${cart} (stable on retry)
  const orderExtra = () => {
    const h = { 'Idempotency-Key': S.cart };
    if (S.etag) h['If-Match'] = S.etag;
    return h;
  };
  let orderRes = authSend('POST', '/v2/orders', { cart_id: S.cart }, orderExtra, 'order_create');

  // stale ETag: re-read once and retry the same payload with the same Idempotency-Key
  if (orderRes.status === 412) {
