USERS = 2                 # ThreadGroup.num_threads
ITERATIONS = 2            # LoopController.loops (per user)
MISSING = "MISSING"
REDIRECTS = (301, 302, 303, 307, 308)
TIMEOUT = (2.0, 3.0)      # connect_timeout 2000 / response_timeout 3000

