def extract_form_csrf(body):
    """input[name=csrf] value, tolerant of attribute order/quoting/decoys."""
    for tag in _INPUT_RE.findall(body or ""):
        attrs = {}
        for m in _ATTR_RE.finditer(tag):
            key = m.group(1).lower()
            val = m.group(2)
            if val is None:
                val = m.group(3)
            if val is None:
                val = m.group(4) or ""
            if key not in attrs:
                attrs[key] = val
        if attrs.get("name", "").strip().lower() != "csrf":
            continue
        value = _html.unescape(attrs.get("value", "")).strip()
        if value:
            return value
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    # ------------------------------------------------------------------ setup
    def on_start(self):
        self.thread_num = next(_USER_SEQ)
        self._extra = self.thread_num > USERS
        self._iterations = 0
        self._counted = False
        self._reset_iteration()

    def _reset_iteration(self):
        # CookieManager.clearEachIteration = true + Argument defaults
        self.client.cookies.clear()
        self.csrf = MISSING
        self.form = MISSING
        self.cart = MISSING
        self.etag = MISSING
        self.grant = MISSING
        self.has_cart = False
        self.product = MISSING
        self.variant = MISSING
        self.quantity = 2
        self._last_status = 0
        self._last_location = None

    def _finish(self):
        global _FINISHED
        if not self._counted:
            self._counted = True
            _FINISHED += 1

    # --------------------------------------------------------------- plumbing
    def _headers(self, idem=False, if_match=False):
        headers = {"Content-Type": "application/json"}
        if self.csrf and self.csrf != MISSING:
            headers["X-CSRF-Token"] = self.csrf
        if if_match and self.etag and self.etag != MISSING:
            headers["If-Match"] = self.etag
        if idem and self.cart and self.cart != MISSING:
            headers["Idempotency-Key"] = self.cart
        return headers

    def _capture(self, resp):
        self._last_status = resp.status_code
        self._last_location = resp.headers.get("Location")
        etag = resp.headers.get("ETag")
        if etag:
            self.etag = etag
        try:
            data = resp.json()
        except Exception:
            data = None
        if isinstance(data, dict):
            token = data.get("csrf")
            if token:
                self.csrf = token
        return data

    def _simple(self, method, path, body=None, name=None, allow_fail=False):
        with self.client.request(
            method,
            path,
            name=name or path,
            json=body,
            headers=self._headers(),
            allow_redirects=False,
            catch_response=True,
            timeout=TIMEOUT,
        ) as resp:
            self._capture(resp)
            ok = resp.status_code < 400
            if not ok and not allow_fail:
                resp.failure("unexpected status %s on %s" % (resp.status_code, path))
            else:
                resp.success()
            return ok

    def _send(self, method, path, body=None, name=None, idem=False,
              if_match=False, validate=None):
        recovered = False
        refreshed = False
        while True:
            with self.client.request(
                method,
                path,
                name=name or path,
                json=body,
                headers=self._headers(idem=idem, if_match=if_match),
                allow_redirects=False,
                catch_response=True,
                timeout=TIMEOUT,
            ) as resp:
                data = self._capture(resp)
                status = self._last_status
                err = data.get("error") if isinstance(data, dict) else None

                if status == 401 and err in ("expired", "session") and not recovered:
                    recovered = True
                    resp.success()          # expected expiry, handled below
                    self._recover(err)
                    continue

                if status == 412 and if_match and not refreshed and self.has_cart:
                    refreshed = True
                    resp.success()
                    self._simple(
                        "GET",
                        "/v2/carts/%s" % self.cart,
                        name="/v2/carts/[id] (etag)",
                        allow_fail=True,
                    )
                    continue

                if validate is not None:
                    problem = validate(status, data)
                elif status >= 400:
                    problem = "unexpected status %s on %s" % (status, path)
                else:
                    problem = None

                if problem:
                    resp.failure(problem)
                    return None
                resp.success()
                return data if isinstance(data, dict) else {}

    def _recover(self, error):
        if error == "expired":
            self._simple("POST", "/v2/session/renew", {}, allow_fail=True)
        else:  # revoked session: renew may fail -> fresh form/login
            if not self._simple("POST", "/v2/session/renew", {}, allow_fail=True):
                self._do_login()
        if self.has_cart and self.cart != MISSING:
            self._simple(
                "POST",
                "/v2/carts/%s/recover" % self.cart,
                {},
                name="/v2/carts/[id]/recover",
                allow_fail=True,
            )

    # ------------------------------------------------------------ login steps
    def _get_login_form(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            headers={"Accept": "text/html,application/xhtml+xml"},
            allow_redirects=False,
            catch_response=True,
            timeout=TIMEOUT,
        ) as resp:
            self._capture(resp)
            if resp.status_code != 200:
                resp.failure("login-form status %s" % resp.status_code)
                return None
            token = extract_form_csrf(resp.text)
            if not token:
                resp.failure("login-form: no input[name=csrf] value")
                return None
            self.form = token
            resp.success()
            return token

    def _login_ok(self, status, data):
        if status in REDIRECTS:
            if not self._last_location:
                return "login redirect without Location"
            return None
        if status != 200:
            return "login status %s" % status
        if not isinstance(data, dict) or not data.get("csrf"):
            return 'login response missing "csrf"'
        return None

    def _redirect_ok(self, status, data):
        if status != 200:
            return "login redirect target status %s" % status
        if not isinstance(data, dict):
            return "login redirect target is not JSON"
        return None

    def _do_login(self):
        if not self._get_login_form():
            return False
        data = self._send(
            "POST",
            "/v2/login",
            body={
                "username": "bench-%d" % self.thread_num,
                "password": "bench",
                "csrf": self.form,
            },
            validate=self._login_ok,
        )
        if data is None:
            return False
        if self._last_status in REDIRECTS and self._last_location:
            location = self._last_location
            landed = self._send(
                "GET", location, name="/v2/login (redirect)", validate=self._redirect_ok
            )
            if landed is None:
                return False
            if landed.get("grant_id"):
                self.grant = landed["grant_id"]
        return True

    # -------------------------------------------------------------- shop steps
    def _catalog_ok(self, status, data):
        if status != 200:
            return "catalog status %s" % status
        if not isinstance(data, dict):
            return "catalog response is not JSON"
        products = (data.get("data") or {}).get("products") or []
        for product in products:
            variants = product.get("variants") or []
            if variants and variants[0].get("in_stock") is True:
                self.product = product.get("id") or MISSING
                self.variant = variants[0].get("id") or MISSING
                if self.product != MISSING and self.variant != MISSING:
                    return None
        return "catalog: no product with in-stock variants[0]"

    def _cart_ok(self, status, data):
        if status != 201:
            return "cart create status %s (expected 201)" % status
        if not isinstance(data, dict):
            return "cart create response is not JSON"
        cart_id = data.get("id")
        if not isinstance(cart_id, str) or not cart_id.startswith("cart-"):
            return 'cart create response missing "id":"cart-...'
        self.cart = cart_id
        self.has_cart = True
        return None

    def _order_ok(self, status, data):
        if not isinstance(data, dict):
            return "order response is not JSON"
        if data.get("accepted") is not True:
            return "order not accepted (status %s, accepted=%r)" % (
                status,
                data.get("accepted"),
            )
        if status != 201:
            return "order status %s (expected 201)" % status
        if not data.get("id"):
            return "order response missing id"
        return None

    def _run_journey(self):
        self._reset_iteration()

        if not self._do_login():
            return

        catalog = self._send("GET", "/v2/catalog", validate=self._catalog_ok)
        if catalog is None:
            return

        cart_body = {"product_id": self.product, "variant_id": self.variant}
        if self.grant and self.grant != MISSING:
            cart_body["grant_id"] = self.grant
        cart = self._send(
            "POST", "/v2/carts", body=cart_body, validate=self._cart_ok
        )
        if cart is None or not self.has_cart:
            return

        self._send(
            "POST",
            "/v2/orders",
            body={"cart_id": self.cart},
            idem=True,
            if_match=True,
            validate=self._order_ok,
        )

    # ------------------------------------------------------------------- task
    @task
    def journey(self):
        if self._extra:
            raise StopUser()
        if self._iterations >= ITERATIONS:
            self._finish()
            raise StopUser()
        self._iterations += 1
        try:
            self._run_journey()
        finally:
            if self._iterations >= ITERATIONS:
                self._finish()
        if self._iterations >= ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    """2 users, ramp_time 0; stop once both users completed their 2 iterations."""

    def tick(self):
        if _FINISHED >= USERS:
            return None
        if self.get_run_time() > 300:
            return None
        return (USERS, USERS)
