import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String CSRF_RE = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";
  private static final String ERR_RE = "\"error\"\\s*:\\s*\"([A-Za-z_]+)\"";
  private static final String DENIED_RE = "\"error\"\\s*:\\s*\"denied\"";
  private static final String FALSE_ACCEPT_RE = "\"accepted\"\\s*:\\s*false";
  private static final String TRUE_ACCEPT_RE = "\"accepted\"\\s*:\\s*true";
  private static final String FORM_RE =
      "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

  private static String baseUrl() {
    String env = System.getenv("BASE_URL");
    return (env == null || env.trim().isEmpty()) ? "http://127.0.0.1:8000" : env.trim();
  }

  private static boolean statusIs(Session s, String key, int code) {
    Object v = s.get(key);
    return (v instanceof Number) && ((Number) v).intValue() == code;
  }

  private static boolean recoverable(Session s) {
    Object e = s.get("err");
    return "expired".equals(e) || "session".equals(e);
  }

  private static String quantityBody(Session s) {
    Object q = s.get("quantity");
    int n = (q instanceof Number) ? ((Number) q).intValue() : Integer.parseInt(String.valueOf(q));
    return "{\"quantity\":" + n + "}";
  }

  private static String cartBody(Session s) {
    StringBuilder sb = new StringBuilder();
    sb.append("{\"product_id\":\"").append(s.getString("product"))
      .append("\",\"variant_id\":\"").append(s.getString("variant")).append("\"");
    if (s.contains("grant")) {
      sb.append(",\"grant_id\":\"").append(s.getString("grant")).append("\"");
    }
    sb.append("}");
    return sb.toString();
  }

  private static long delayMs(Session s) {
    Object d = s.get("delay");
    return (d instanceof Number) ? ((Number) d).longValue() : 0L;
  }

  private static ChainBuilder loginForm(String name) {
    return exec(
        http(name).get("/v2/login-form")
            .check(status().is(200))
            .check(regex(FORM_RE).find().saveAs("form")));
  }

  private static ChainBuilder login(String name) {
    return exec(s -> s.remove("loginLocation"))
        .exec(
            http(name).post("/v2/login")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{form}\"}"))
                .check(status().in(200, 302))
                .check(regex(CSRF_RE).optional().saveAs("csrf"))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(regex(DENIED_RE).notExists()));
  }

  private static ChainBuilder loginRedirect(String name) {
    return exec(
        http(name).get("#{loginLocation}")
            .check(status().is(200))
            .check(regex(CSRF_RE).optional().saveAs("csrf"))
            .check(jsonPath("$.grant_id").optional().saveAs("grant")));
  }

  private static ChainBuilder loginSequence(String tag) {
    return loginForm(tag + "-form")
        .exec(login(tag))
        .doIf(s -> s.contains("loginLocation")).then(loginRedirect(tag + "-redirect"));
  }

  private static ChainBuilder catalog() {
    return exec(
        http("catalog").get("/v2/catalog")
            .check(status().is(200))
            .check(jsonPath("$.data.products").ofList().saveAs("products"))
            .check(regex(CSRF_RE).optional().saveAs("csrf")))
        .exec(s -> {
          List<Object> products = s.getList("products");
          String pid = null;
          String vid = null;
          if (products != null) {
            for (Object po : products) {
              if (!(po instanceof Map)) {
                continue;
              }
              Map<?, ?> p = (Map<?, ?>) po;
              Object vs = p.get("variants");
              if (!(vs instanceof List)) {
                continue;
              }
              for (Object vo : (List<?>) vs) {
                if (!(vo instanceof Map)) {
                  continue;
                }
                Map<?, ?> v = (Map<?, ?>) vo;
                if (Boolean.TRUE.equals(v.get("in_stock"))) {
                  pid = String.valueOf(p.get("id"));
                  vid = String.valueOf(v.get("id"));
                  break;
                }
              }
              if (pid != null) {
                break;
              }
            }
          }
          if (pid == null || vid == null) {
            return s.markAsFailed();
          }
          return s.set("product", pid).set("variant", vid);
        });
  }

  private static ChainBuilder createCart() {
    return exec(
        http("create-cart").post("/v2/carts")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody(ModelSimulation::cartBody))
            .check(status().is(201))
            .check(jsonPath("$.id").saveAs("cart"))
            .check(header("ETag").saveAs("etag"))
            .check(regex(CSRF_RE).optional().saveAs("csrf"))
            .check(regex(DENIED_RE).notExists()))
        .exec(s -> s.remove("grant"));
  }

  private static ChainBuilder readCart(String name) {
    return exec(
        http(name).get("/v2/carts/#{cart}")
            .check(status().is(200))
            .check(header("ETag").saveAs("etag"))
            .check(regex(CSRF_RE).optional().saveAs("csrf")));
  }

  private static ChainBuilder patch(String name, boolean strict) {
    if (strict) {
      return exec(
          http(name).patch("/v2/carts/#{cart}")
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{etag}")
              .body(StringBody(ModelSimulation::quantityBody))
              .check(status().is(200))
              .check(header("ETag").optional().saveAs("etag"))
              .check(regex(CSRF_RE).optional().saveAs("csrf"))
              .check(regex(DENIED_RE).notExists()));
    }
    return exec(
        http(name).patch("/v2/carts/#{cart}")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{etag}")
            .body(StringBody(ModelSimulation::quantityBody))
            .check(status().in(200, 401, 412).saveAs("patchStatus"))
            .check(header("ETag").optional().saveAs("etag"))
            .check(regex(CSRF_RE).optional().saveAs("csrf"))
            .check(regex(ERR_RE).optional().saveAs("err"))
            .check(regex(DENIED_RE).notExists()));
  }

  private static ChainBuilder order(String name, boolean strict) {
    if (strict) {
      return exec(
          http(name).post("/v2/orders")
              .header("X-CSRF-Token", "#{csrf}")
              .header("If-Match", "#{etag}")
              .header("Idempotency-Key", "#{cart}")
              .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
              .check(status().is(201))
              .check(regex(TRUE_ACCEPT_RE).exists())
              .check(jsonPath("$.accepted").optional().saveAs("accepted"))
              .check(regex(CSRF_RE).optional().saveAs("csrf"))
              .check(regex(DENIED_RE).notExists()));
    }
    return exec(
        http(name).post("/v2/orders")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{etag}")
            .header("Idempotency-Key", "#{cart}")
            .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
            .check(status().in(200, 201, 401).saveAs("orderStatus"))
            .check(regex(FALSE_ACCEPT_RE).notExists())
            .check(jsonPath("$.accepted").optional().saveAs("accepted"))
            .check(regex(CSRF_RE).optional().saveAs("csrf"))
            .check(regex(ERR_RE).optional().saveAs("err"))
            .check(regex(DENIED_RE).notExists()));
  }

  private static ChainBuilder recover(String tag) {
    return exec(
        http(tag + "-renew").post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 401).saveAs("renewStatus"))
            .check(regex(CSRF_RE).optional().saveAs("csrf"))
            .check(regex(DENIED_RE).notExists()))
        .doIf(s -> statusIs(s, "renewStatus", 401)).then(loginSequence(tag + "-relogin"))
        .doIf(s -> s.contains("cart")).then(
            exec(
                http(tag + "-recover-cart").post("/v2/carts/#{cart}/recover")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200))
                    .check(header("ETag").optional().saveAs("etag"))
                    .check(regex(CSRF_RE).optional().saveAs("csrf"))
                    .check(regex(DENIED_RE).notExists())));
  }

  private static ChainBuilder patchFlow() {
    return exec(s -> s.remove("err"))
        .exec(patch("patch-cart", false))
        .exitHereIfFailed()
        .doIf(s -> statusIs(s, "patchStatus", 412)).then(
            readCart("patch-reread")
                .exec(patch("patch-retry-precondition", true)))
        .doIf(s -> statusIs(s, "patchStatus", 401) && recoverable(s)).then(
            recover("patch")
                .exec(readCart("patch-recover-reread"))
                .exec(patch("patch-retry-session", true)));
  }

  private static ChainBuilder orderFlow() {
    return exec(s -> s.remove("err").remove("accepted"))
        .exec(order("order", false))
        .exitHereIfFailed()
        .doIf(s -> statusIs(s, "orderStatus", 401) && recoverable(s)).then(
            recover("order")
                .exec(readCart("order-reread"))
                .exec(s -> s.remove("err").remove("accepted"))
                .exec(order("order-retry-session", true)))
        .exitHereIfFailed()
        .exec(s -> Boolean.TRUE.equals(s.get("accepted")) ? s : s.markAsFailed())
        .exitHereIfFailed();
  }

  private static ChainBuilder journey() {
    return exec(flushSessionCookies())
        .exec(s -> s.remove("csrf").remove("form").remove("cart").remove("etag")
            .remove("grant").remove("loginLocation").remove("err").remove("accepted")
            .remove("patchStatus").remove("orderStatus").remove("renewStatus")
            .remove("product").remove("variant").remove("products"))
        .exec(loginSequence("login"))
        .exec(s -> s.contains("csrf") ? s : s.markAsFailed())
        .exitHereIfFailed()
        .exec(catalog())
        .exitHereIfFailed()
        .exec(createCart())
        .exitHereIfFailed()
        .exec(patchFlow())
        .exitHereIfFailed()
        .exec(orderFlow())
        .doIf(s -> delayMs(s) > 0L).then(pause(Duration.ofMillis(500)));
  }

  HttpProtocolBuilder httpProtocol = http
      .baseUrl(baseUrl())
      .disableFollowRedirect()
      .disableCaching()
      .acceptHeader("application/json")
      .contentTypeHeader("application/json")
      .userAgentHeader("gatling-model-simulation");

  ScenarioBuilder shop = scenario("m04-csv-to-feeder")
      .feed(jsonFile("/fixtures/m04-accounts.json").queue())
      .repeat(2).on(journey());

  {
    setUp(shop.injectOpen(atOnceUsers(2)))
        .protocols(httpProtocol)
        .assertions(global().failedRequests().count().is(0L))
        .maxDuration(Duration.ofSeconds(120));
  }
}
