  const row = ROWS[(__VU - 1) % ROWS.length];
  resetState(row);
  http.cookieJar().clear(BASE); // JMeter CookieManager clearEachIteration=true

  const login = doLogin(row);
  check(login.form, { 'login form loaded': (r) => r.status === 200 });
  check(login, {
    'login csrf extracted': (x) => !!x.token,
    'login accepted': (x) => x.ok === true,
  });

  const products = loadCatalog();
  const pick = pickVariant(products);
  check(pick, { 'in-stock variant selected': (p) => !!p && !!p.product_id && !!p.variant_id });

  let cartOk = false;
  let patchOk = false;
  let orderOk = false;

  if (pick) {
    cartOk = createCart(pick);
    if (cartOk) {
      check(row, { 'quantity is integer 1..20': (r) => Number.isInteger(r.quantity) && r.quantity >= 1 && r.quantity <= 20 });
      patchOk = patchQuantity(row.quantity);
      orderOk = placeOrder();
    }
  }

  journeyOk.add(login.ok === true && cartOk && patchOk && orderOk);

  if (typeof row.delay === 'number' && row.delay > 0) sleep(row.delay / 1000);
}
