"""Deterministic Locust translation of TestPlan-0 (m04.jmx).

2 virtual users x 2 iterations, one committed order per journey.
Row-per-user fixture binding (accounts.json == account-1.csv / account-2.csv).
"""

import csv
import html
import json
import os
import re
import time

from locust import HttpUser, LoadTestShape, constant, task

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS = 2

STATE = {"claimed": 0, "done": 0}


# --------------------------------------------------------------------------
# fixture loading (read-only /fixtures/<logical alias>)
# --------------------------------------------------------------------------
def _number(value):
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, (int, float)):
        return value
    text = str(value).strip()
    try:
        return int(text)
    except ValueError:
        return float(text)


def _normalize(row):
    return {
        "username": str(row["username"]),
        "password": str(row["password"]),
        "quantity": int(_number(row["quantity"])),
        "delay": _number(row.get("delay", 0)),
    }


def _read_first(paths):
    for path in paths:
        try:
            with open(path, "r", encoding="utf-8") as handle:
                return handle.read()
        except OSError:
            continue
    return None


def _load_accounts():
    raw = _read_first(["/fixtures/accounts.json", "/fixtures/m04-accounts.json"])
    if raw:
        try:
            parsed = json.loads(raw)
        except ValueError:
            parsed = None
        if isinstance(parsed, dict):
            parsed = parsed.get("accounts") or parsed.get("data") or []
        if isinstance(parsed, list) and parsed:
            return [_normalize(row) for row in parsed]

    rows = []
    for logical, physical in (
        ("account-1.csv", "m04-account-1.csv"),
        ("account-2.csv", "m04-account-2.csv"),
    ):
        text = _read_first(["/fixtures/" + logical, "/fixtures/" + physical])
        if not text:
            continue
        for record in csv.DictReader(text.splitlines()):
            if record.get("username"):
                rows.append(_normalize(record))
    return rows


ACCOUNTS = _load_accounts()


# --------------------------------------------------------------------------
# html helpers (attribute order / decoy tolerant)
# --------------------------------------------------------------------------
_INPUT_RE = re.compile(r"<\s*input\b(?:[^>\"']|\"[^\"]*\"|'[^']*')*>", re.I | re.S)
_ATTR_RE = re.compile(
    r"""([A-Za-z_:][-\w:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))"""
)


def _attributes(tag):
    found = {}
    for match in _ATTR_RE.finditer(tag):
        key = match.group(1).lower()
        value = match.group(2)
        if value is None:
            value = match.group(3)
        if value is None:
            value = match.group(4) or ""
        if key not in found:
            found[key] = value
    return found


def extract_csrf(text):
    if not text:
        return None
    fallback = None
    for match in _INPUT_RE.finditer(text):
        attrs = _attributes(match.group(0))
        if attrs.get("name") != "csrf":
            continue
        value = attrs.get("value")
        if not value:
            continue
        value = html.unescape(value)
        if not value:
            continue
        decoy = (
            attrs.get("data-decoy") is not None
            or attrs.get("disabled") is not None
            or attrs.get("aria-hidden") == "true"
        )
        if decoy:
            if fallback is None:
                fallback = value
            continue
        return value
    return fallback


# --------------------------------------------------------------------------
# validators: return None on success, otherwise a failure message
# --------------------------------------------------------------------------
def v_form(status, data, text):
    if extract_csrf(text):
        return None
    return "login-form has no usable input[name=csrf]"


def v_login(status, data, text):
    if status == 302:
        return None
    if isinstance(data, dict) and isinstance(data.get("csrf"), str) and data["csrf"]:
        return None
    return "login response missing csrf"


def v_csrf(status, data, text):
    if isinstance(data, dict) and isinstance(data.get("csrf"), str) and data["csrf"]:
        return None
    return "redirect target missing csrf"


def v_catalog(status, data, text):
    if isinstance(data, dict):
        products = (data.get("data") or {}).get("products")
        if isinstance(products, list):
            return None
    return "catalog payload missing products"


def v_cart(status, data, text):
    if isinstance(data, dict) and isinstance(data.get("id"), str) and data["id"]:
        return None
    return "cart creation returned no cart id"


def v_order(status, data, text):
    if status == 201 and isinstance(data, dict) and data.get("accepted") is True and data.get("id"):
        return None
    return "order not accepted (status=%s body=%s)" % (status, (text or "")[:200])


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)
    abstract = False

    def on_start(self):
        self.active = False
        self.account = None
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None
        if not ACCOUNTS:
            return
        if STATE["claimed"] >= USERS:
            return
        self.index = STATE["claimed"]
        STATE["claimed"] += 1
        self.account = ACCOUNTS[self.index % len(ACCOUNTS)]
        self.active = True

    # ---------------------------------------------------------------- utils
    def _auth_headers(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        return headers

    def _call(self, method, path, name, payload=None, headers=None,
              ok=(200,), retryable=(), validator=None):
        send_headers = {"Accept": "application/json"}
        if payload is not None:
            send_headers["Content-Type"] = "application/json"
        if headers:
            send_headers.update(headers)

        result = {
            "status": 0, "data": None, "text": "", "etag": None,
            "location": None, "error": None, "outcome": "fail",
        }
        with self.client.request(
            method, path,
            name=name,
            json=payload,
            headers=send_headers,
            catch_response=True,
            allow_redirects=False,
            timeout=15,
        ) as response:
            text = response.text or ""
            try:
                data = response.json()
            except Exception:
                data = None
            status = response.status_code
            etag = response.headers.get("ETag")
            location = response.headers.get("Location")
            error = data.get("error") if isinstance(data, dict) else None

            if isinstance(data, dict):
                token = data.get("csrf")
                if isinstance(token, str) and token:
                    self.csrf = token

            result.update({
                "status": status, "data": data, "text": text,
                "etag": etag, "location": location, "error": error,
            })

            if status == 401 and error in ("expired", "session"):
                # expected, scheduled session events: recovered by the caller
                response.success()
                result["outcome"] = "auth"
            elif status in retryable:
                # expected precondition mismatch: bounded re-read + retry
                response.success()
                result["outcome"] = "retry"
            elif status in ok:
                message = validator(status, data, text) if validator else None
                if message:
                    response.failure(message)
                    result["outcome"] = "fail"
                else:
                    response.success()
                    result["outcome"] = "ok"
            else:
                response.failure(
                    "%s unexpected status %s error=%s body=%s"
                    % (name, status, error, text[:200])
                )
                result["outcome"] = "fail"
        return result

    # -------------------------------------------------------------- session
    def _login(self):
        form = self._call("GET", "/v2/login-form", "/v2/login-form",
                          ok=(200,), validator=v_form)
        if form["outcome"] != "ok":
            return False
        token = extract_csrf(form["text"])
        if not token:
            return False

        payload = {
            "username": self.account["username"],
            "password": self.account["password"],
            "csrf": token,
        }
        login = self._call("POST", "/v2/login", "/v2/login", payload=payload,
                           headers=self._auth_headers(), ok=(200, 302),
                           validator=v_login)
        if login["outcome"] != "ok":
            return False

        if login["status"] == 302:
            location = login["location"]
            if not location:
                return False
            landed = self._call("GET", location, "/v2/login [redirect]",
                                ok=(200,), validator=v_csrf)
            if landed["outcome"] != "ok":
                return False
            data = landed["data"]
        else:
            data = login["data"]

        if isinstance(data, dict) and data.get("grant_id"):
            self.grant_id = data["grant_id"]
        return bool(self.csrf)

    def _recover_session(self, kind):
        """Bounded recovery. Returns 'renewed', 'relogin' or None."""
        mode = None
        if kind == "expired":
            renewed = self._call("POST", "/v2/session/renew", "/v2/session/renew",
                                 payload={}, headers=self._auth_headers(),
                                 ok=(200,))
            if renewed["outcome"] == "ok" and self.csrf:
                mode = "renewed"
        if mode is None:
            if not self._login():
                return None
            mode = "relogin"
        if self.cart_id:
            self._call("POST", "/v2/carts/%s/recover" % self.cart_id,
                       "/v2/carts/[id]/recover", payload={},
                       headers=self._auth_headers(), ok=(200,))
        return mode

    def _refresh_etag(self):
        read = self._call("GET", "/v2/carts/%s" % self.cart_id,
                          "/v2/carts/[id] GET", ok=(200,))
        if read["etag"]:
            self.etag = read["etag"]
        return read["outcome"] == "ok"

    # -------------------------------------------------------------- catalog
    def _choose_product(self):
        result = self._call("GET", "/v2/catalog", "/v2/catalog",
                            ok=(200,), validator=v_catalog)
        pages = 1
        while result["outcome"] == "ok":
            data = result["data"] or {}
            products = (data.get("data") or {}).get("products") or []
            for product in products:
                variants = product.get("variants") or []
                for variant in variants:
                    if variant.get("in_stock") is True:
                        return product.get("id"), variant.get("id")
            nxt = data.get("next")
            if not nxt or pages >= 3:
                return None
            pages += 1
            result = self._call("GET", nxt, "/v2/catalog/page",
                                ok=(200,), validator=v_catalog)
        return None

    # ----------------------------------------------------------------- cart
    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        recovered = False
        for _ in range(3):
            result = self._call("POST", "/v2/carts", "/v2/carts", payload=payload,
                                headers=self._auth_headers(), ok=(201,),
                                validator=v_cart)
            if result["etag"]:
                self.etag = result["etag"]
            if result["outcome"] == "ok":
                self.cart_id = result["data"]["id"]
                self.grant_id = None
                if not self.etag:
                    self._refresh_etag()
                return True
            if result["outcome"] == "auth" and not recovered:
                recovered = True
                mode = self._recover_session(result["error"])
                if mode is None:
                    return False
                if mode == "relogin":
                    payload.pop("grant_id", None)
                    self.grant_id = None
                continue
            return False
        return False

    def _patch_quantity(self, quantity):
        path = "/v2/carts/%s" % self.cart_id
        payload = {"quantity": int(quantity)}
        recovered = False
        refreshed = False
        for _ in range(4):
            headers = self._auth_headers()
            if self.etag:
                headers["If-Match"] = self.etag
            result = self._call("PATCH", path, "/v2/carts/[id]", payload=payload,
                                headers=headers, ok=(200,), retryable=(412,))
            if result["etag"]:
                self.etag = result["etag"]
            if result["outcome"] == "ok":
                if not self.etag:
                    self._refresh_etag()
                return True
            if result["outcome"] == "auth" and not recovered:
                recovered = True
                if self._recover_session(result["error"]) is None:
                    return False
                self._refresh_etag()
                continue
            if result["outcome"] == "retry" and not refreshed:
                refreshed = True
                if not self._refresh_etag():
                    return False
                continue
            return False
        return False

    def _submit_order(self):
        payload = {"cart_id": self.cart_id}
        idempotency_key = "order-%s" % self.cart_id
        recovered = False
        refreshed = False
        for _ in range(4):
            headers = self._auth_headers()
            headers["Idempotency-Key"] = idempotency_key
            if self.etag:
                headers["If-Match"] = self.etag
            result = self._call("POST", "/v2/orders", "/v2/orders", payload=payload,
                                headers=headers, ok=(201,), retryable=(412,),
                                validator=v_order)
            if result["etag"]:
                self.etag = result["etag"]
            if result["outcome"] == "ok":
                return True
            if result["outcome"] == "auth" and not recovered:
                recovered = True
                if self._recover_session(result["error"]) is None:
                    return False
                self._refresh_etag()
                continue
            if result["outcome"] == "retry" and not refreshed:
                refreshed = True
                if not self._refresh_etag():
                    return False
                continue
            return False
        return False

    # -------------------------------------------------------------- journey
    def _journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None

        delay = self.account["delay"]
        if delay:
            time.sleep(float(delay) / 1000.0)

        if not self._login():
            return
        chosen = self._choose_product()
        if not chosen:
            return
        product_id, variant_id = chosen
        if not self._create_cart(product_id, variant_id):
            return
        if not self._patch_quantity(self.account["quantity"]):
            return
        self._submit_order()

    @task
    def run_plan(self):
        if not self.active:
            raise StopUser()
        for _ in range(ITERATIONS):
            self._journey()
        STATE["done"] += 1
        raise StopUser()


class ShopShape(LoadTestShape):
    """Fixed 2 users; stop as soon as both virtual users finished 2 iterations."""

    def tick(self):
        if STATE["done"] >= USERS:
            return None
        if self.get_run_time() > 240:
            return None
        return (USERS, USERS)
