import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  // ThreadGroup-2: 4 threads, ramp 0, scheduler duration 38s, loop forever.
  private static final int USERS = 4;
  private static final long RUN_SECONDS = 38L;

  // ConstantThroughputTimer-26: 121.2/min, calcMode 4 (shared across the thread group)
  // -> ~2.02 committed checkout starts per second for the whole group -> 500ms global grid.
  private static final long PERIOD_MS = 500L;

  private static final AtomicLong NEXT_SLOT = new AtomicLong(0L);
  private static final AtomicInteger THREAD_NUM = new AtomicInteger(0);

  private static final String BASE_URL = resolveBaseUrl();

  private static final String CSRF_INPUT_REGEX =
      "(?i)<input(?=[^>]*\\sname\\s*=\\s*[\"']?csrf[\"']?(?=[\\s/>]))"
          + "(?=[^>]*\\svalue\\s*=\\s*[\"']?([^\"'\\s>]+))[^>]*>";

  private static String resolveBaseUrl() {
    String env = System.getenv("BASE_URL");
    return (env == null || env.trim().isEmpty()) ? "http://127.0.0.1:8000" : env.trim();
  }

  private static long reserveSlot() {
    while (true) {
      long now = System.currentTimeMillis();
      long current = NEXT_SLOT.get();
      long start = Math.max(current, now);
      if (NEXT_SLOT.compareAndSet(current, start + PERIOD_MS)) {
        return start;
      }
    }
  }

  private static String text(Object value) {
    return value == null ? "" : String.valueOf(value);
  }

  private static boolean inStock(Object value) {
    if (value instanceof Boolean) {
      return (Boolean) value;
    }
    return "true".equalsIgnoreCase(text(value));
  }

  private static Session applyCsrf(Session session) {
    if (session.contains("newCsrf")) {
      String fresh = session.getString("newCsrf");
      if (fresh != null && !fresh.isEmpty()) {
        return session.set("csrf", fresh).remove("newCsrf");
      }
      return session.remove("newCsrf");
    }
    return session;
  }

  private static Session afterLogin(Session session) {
    String csrf = session.contains("loginCsrf") ? session.getString("loginCsrf") : "";
    String location = session.contains("loginLocation") ? session.getString("loginLocation") : "";
    boolean redirect = location != null && !location.isEmpty();
    Session next = session.set("redirect", redirect);
    if (csrf != null && !csrf.isEmpty()) {
      next = next.set("csrf", csrf);
    } else if (!redirect) {
      next = next.markAsFailed();
    }
    return next;
  }

  @SuppressWarnings("unchecked")
  private static Session selectProduct(Session session) {
    Session next = applyCsrf(session);
    String product = "";
    String variant = "";
    List<Object> products = next.contains("products") ? next.getList("products") : null;
    if (products != null) {
      for (Object candidate : products) {
        if (!(candidate instanceof Map)) {
          continue;
        }
        Map<String, Object> productMap = (Map<String, Object>) candidate;
        Object variants = productMap.get("variants");
        if (!(variants instanceof List)) {
          continue;
        }
        for (Object item : (List<Object>) variants) {
          if (!(item instanceof Map)) {
            continue;
          }
          Map<String, Object> variantMap = (Map<String, Object>) item;
          if (inStock(variantMap.get("in_stock"))) {
            product = text(productMap.get("id"));
            variant = text(variantMap.get("id"));
            break;
          }
        }
        if (!product.isEmpty() && !variant.isEmpty()) {
          break;
        }
      }
    }
    if (product.isEmpty() || variant.isEmpty()) {
      return next.markAsFailed();
    }
    return next.set("product", product).set("variant", variant);
  }

  private static Session afterCart(Session session) {
    Session next = applyCsrf(session);
    String cart = next.contains("cart") ? next.getString("cart") : "";
    if (cart == null || !cart.startsWith("cart-")) {
      return next.markAsFailed();
    }
    String etag = next.contains("etagNew") ? next.getString("etagNew") : "";
    next = next.remove("etagNew");
    next = next.set("etag", (etag == null || etag.isEmpty()) ? "*" : etag);
    return next.set("hasCart", true);
  }

  private static ChainBuilder gated(ChainBuilder chain) {
    return doIf("#{ok}")
        .then(chain)
        .exec((Session s) -> s.set("ok", !s.isFailed()));
  }

  private static final ChainBuilder RESET = exec((Session s) -> s
      .markAsSucceeded()
      .set("ok", true)
      .set("csrf", "")
      .set("form", "")
      .set("cart", "")
      .set("etag", "")
      .set("hasCart", false)
      .set("redirect", false)
      .set("waitMs", 0L)
      .remove("loginCsrf")
      .remove("loginLocation")
      .remove("newCsrf")
      .remove("etagNew")
      .remove("products")
      .remove("orderId"));

  private static final ChainBuilder LOGIN_FORM = gated(exec(
      http("login_form")
          .get("/v2/login-form")
          .check(status().is(200))
          .check(regex(CSRF_INPUT_REGEX).find().saveAs("form"))));

  private static final ChainBuilder LOGIN = gated(exec(
      http("login")
          .post("/v2/login")
          .header("Content-Type", "application/json")
          .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
          .check(status().in(200, 302))
          .check(jsonPath("$.csrf").optional().saveAs("loginCsrf"))
          .check(header("Location").optional().saveAs("loginLocation")))
      .exec(ModelSimulation::afterLogin));

  private static final ChainBuilder LOGIN_REDIRECT = gated(doIf("#{redirect}").then(
      exec(http("login_redirect")
          .get("#{loginLocation}")
          .check(status().is(200))
          .check(jsonPath("$.csrf").optional().saveAs("newCsrf")))
          .exec(ModelSimulation::applyCsrf)));

  private static final ChainBuilder CATALOG = gated(exec(
      http("catalog")
          .get("/v2/catalog")
          .check(status().is(200))
          .check(jsonPath("$.data.products[0].id").exists())
          .check(jsonPath("$.data.products").ofList().saveAs("products"))
          .check(jsonPath("$.csrf").optional().saveAs("newCsrf")))
      .exec(ModelSimulation::selectProduct));

  private static final ChainBuilder CART = gated(exec(
      http("cart_create")
          .post("/v2/carts")
          .header("Content-Type", "application/json")
          .header("X-CSRF-Token", "#{csrf}")
          .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\"}"))
          .check(status().is(201))
          .check(jsonPath("$.id").exists().saveAs("cart"))
          .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
          .check(header("ETag").optional().saveAs("etagNew")))
      .exec(ModelSimulation::afterCart));

  private static final ChainBuilder CHECKOUT = gated(
      exec((Session s) -> s.set("waitMs", Math.max(0L, reserveSlot() - System.currentTimeMillis())))
          .pause(s -> Duration.ofMillis(s.getLong("waitMs")))
          .exec(http("checkout")
              .post("/v2/orders")
              .header("Content-Type", "application/json")
              .header("X-CSRF-Token", "#{csrf}")
              .header("Idempotency-Key", "#{cart}")
              .header("If-Match", "#{etag}")
              .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
              .check(status().is(201))
              .check(jsonPath("$.accepted").ofBoolean().is(true))
              .check(jsonPath("$.id").exists().saveAs("orderId"))
              .check(jsonPath("$.csrf").optional().saveAs("newCsrf")))
          .exec(ModelSimulation::applyCsrf));

  private static final ChainBuilder JOURNEY = RESET
      .exec(LOGIN_FORM)
      .exec(LOGIN)
      .exec(LOGIN_REDIRECT)
      .exec(CATALOG)
      .exec(CART)
      .exec(CHECKOUT);

  private final HttpProtocolBuilder httpProtocol = http
      .baseUrl(BASE_URL)
      .disableFollowRedirect()
      .disableCaching()
      .maxConnectionsPerHost(USERS)
      .acceptHeader("application/json")
      .userAgentHeader("gatling-owned-checkout");

  private final ScenarioBuilder ownedCheckout = scenario("owned_checkout")
      .exec((Session s) -> s.set("username", "bench-" + THREAD_NUM.incrementAndGet()))
      .exec(during(Duration.ofSeconds(RUN_SECONDS)).on(JOURNEY));

  {
    setUp(ownedCheckout.injectOpen(atOnceUsers(USERS)))
        .protocols(httpProtocol)
        .maxDuration(Duration.ofSeconds(RUN_SECONDS + 5L));
  }
}

