// k6 1.0.0 translation of source-m05.jmx
// ThreadGroup: 4 threads, ramp 0, scheduler duration 38s, loop forever,
// ConstantThroughputTimer(calcMode=4, throughput=121.2/min) -> ~2 iterations/s shared.
// Pacing is therefore translated to a constant-arrival-rate of 2 *journeys*/s
// (one committed POST /v2/orders per journey), maxVUs=4, 36s of arrivals + 2s drain (=38s).
// Journey sequence preserved: login-form -> login -> [dynamic Location once] -> catalog
// -> carts -> orders. No /v2/health, /v2/work, /v2/browse or any undeclared pool.

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import exec from 'k6/execution';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const REQ_TIMEOUT = '3s';
const TARGET_RATE = 2;
const MAX_VUS = 4;

const committedOrders = new Counter('committed_orders');
const orderAttempts = new Counter('order_attempts');
const ordersAccepted = new Rate('orders_accepted');
const journeyErrors = new Counter('journey_errors');
const setupErrors = new Counter('setup_errors');
const journeyDuration = new Trend('journey_duration', true);

export const options = {
  discardResponseBodies: false,
  scenarios: {
    checkout_journey: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: '36s',
      preAllocatedVUs: MAX_VUS,
      maxVUs: MAX_VUS,
      gracefulStop: '2s',
      exec: 'journey',
    },
  },
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)'],
};

/* ------------------------------------------------------------------ utils */

function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    const j = res.json();
    return j && typeof j === 'object' ? j : null;
  } catch (e) {
    return null;
  }
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const want = String(name).toLowerCase();
  for (const k in res.headers) {
    if (String(k).toLowerCase() === want) return res.headers[k];
  }
  return null;
}

function absUrl(path) {
  const p = String(path || '');
  if (/^https?:\/\//i.test(p)) return p;
  if (p.charAt(0) === '/') return BASE + p;
  return BASE + '/' + p;
}

function decodeEntities(s) {
  return String(s == null ? '' : s)
    .replace(/&quot;/gi, '"')
    .replace(/&apos;/gi, "'")
    .replace(/&#0*39;/g, "'")
    .replace(/&#x0*27;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&amp;/gi, '&');
}

function stripNoise(body) {
  return String(body == null ? '' : body)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style>/gi, ' ');
}

// attribute-order / quote-style tolerant attribute parser (html_layout variants)
function parseAttrs(s) {
  const out = {};
  const re = /([A-Za-z_:][-A-Za-z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+)))?/g;
  let m;
  while ((m = re.exec(String(s || ''))) !== null) {
    const k = m[1].toLowerCase();
    const v = m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4] !== undefined ? m[4] : '';
    if (!(k in out)) out[k] = decodeEntities(v);
  }
  return out;
}

function htmlInputs(body) {
  const cleaned = stripNoise(body);
  const res = [];
  const re = /<input\b((?:[^>"']|"[^"]*"|'[^']*')*)>/gi;
  let m;
  while ((m = re.exec(cleaned)) !== null) res.push(parseAttrs(m[1]));
  return res;
}

// exact input name only: decoy names (csrf_token, csrf-decoy, ...) never match
function findToken(body, name) {
  const wanted = String(name).toLowerCase();
  const inputs = htmlInputs(body);
  let fallback = null;
  for (let i = 0; i < inputs.length; i++) {
    const a = inputs[i];
    if (String(a.name || '').toLowerCase() !== wanted) continue;
    if ('disabled' in a) continue;
    const v = a.value || '';
    if (!v) continue;
    const t = String(a.type || '').toLowerCase();
    if (t === 'submit' || t === 'button' || t === 'reset' || t === 'image') continue;
    let decoy = String(v).toLowerCase().indexOf('decoy') >= 0;
    for (const k in a) {
      if (k.indexOf('decoy') >= 0 || String(a[k]).toLowerCase().indexOf('decoy') >= 0) decoy = true;
    }
    if (decoy) continue;
    if (t === 'hidden') return v;
    if (!fallback) fallback = v;
  }
  if (fallback) return fallback;
  const j = typeof body === 'string' && body.charAt(0) === '{' ? null : null;
  return j;
}

function findChallenge(body) {
  const cleaned = stripNoise(body);
  const re = /<form\b((?:[^>"']|"[^"]*"|'[^']*')*)>([\s\S]*?)<\/form>/gi;
  let m;
  let fallback = null;
  while ((m = re.exec(cleaned)) !== null) {
    const attrs = parseAttrs(m[1]);
    const action = attrs.action || '';
    const ch = findToken(m[2], 'challenge');
    if (!ch) continue;
    if (/\/v2\/challenges\//i.test(action)) return { action: action, challenge: ch };
    if (!fallback) fallback = { action: action || null, challenge: ch };
  }
  const am = /action\s*=\s*(?:"([^"]*\/v2\/challenges\/[^"]*)"|'([^']*\/v2\/challenges\/[^']*)')/i.exec(cleaned);
  const globalAction = am ? am[1] || am[2] : null;
  if (fallback) {
    if (!fallback.action && globalAction) fallback.action = globalAction;
    return fallback.action ? fallback : null;
  }
  const ch = findToken(cleaned, 'challenge');
  if (ch && globalAction) return { action: globalAction, challenge: ch };
  return null;
}

/* --------------------------------------------------------------- transport */

function absorb(state, res) {
  const j = safeJson(res);
  if (!j) return;
  if (typeof j.csrf === 'string' && j.csrf.length > 0) state.csrf = j.csrf;
  if (typeof j.grant_id === 'string' && j.grant_id.length > 0) state.grant = j.grant_id;
}

function req(state, method, path, body, extra, statuses, name) {
  const h = {};
  if (extra) for (const k in extra) h[k] = extra[k];
  let payload = null;
  if (body !== null && body !== undefined) {
    payload = JSON.stringify(body);
    h['Content-Type'] = 'application/json';
  }
  if (method !== 'GET' && state && state.csrf) h['X-CSRF-Token'] = state.csrf;
  const params = {
    headers: h,
    redirects: 0,
    timeout: REQ_TIMEOUT,
    tags: { name: name || method + ' ' + path },
  };
  if (statuses && statuses.length) params.responseCallback = http.expectedStatuses.apply(null, statuses);
  const res = http.request(method, absUrl(path), payload, params);
  absorb(state, res);
  return res;
}

function renew(state) {
  const r = req(state, 'POST', '/v2/session/renew', {}, null, [200, 401, 403], 'POST /v2/session/renew');
  return r.status === 200;
}

function relogin(state) {
  const f = req(state, 'GET', '/v2/login-form', null, null, [200], 'GET /v2/login-form');
  const tok = findToken(f.body, 'csrf');
  if (!tok) return false;
  state.csrf = tok;
  const r = req(
    state,
    'POST',
    '/v2/login',
    { username: state.user, password: PASSWORD, csrf: tok },
    null,
    [200, 301, 302, 303, 307, 308],
    'POST /v2/login'
  );
  const loc = header(r, 'Location');
  if (loc) {
    const l = req(state, 'GET', loc, null, null, [200], 'GET /v2/login-landing');
    absorbLanding(state, l);
  }
  return r.status === 200 || !!loc;
}

function recoverCart(state) {
  if (!state.cartId) return;
  const r = req(
    state,
    'POST',
    '/v2/carts/' + state.cartId + '/recover',
    {},
    null,
    [200, 201, 202, 401, 404, 409],
    'POST /v2/carts/{id}/recover'
  );
  const e = header(r, 'ETag');
  if (e) state.etag = e;
}

// bounded: at most one retry of the interrupted operation, never restart checkout
function handleAuth(state, res, retry) {
  if (!res || res.status !== 401) return res;
  const j = safeJson(res);
  const err = j ? j.error : null;
  if (err === 'expired') {
    renew(state);
    recoverCart(state);
    return retry();
  }
  if (err === 'session') {
    relogin(state);
    recoverCart(state);
    return retry();
  }
  return res; // denied (or unknown) -> the assertion must fail
}

function absorbLanding(state, res) {
  const j = safeJson(res);
  if (j) {
    if (typeof j.csrf === 'string' && j.csrf) state.csrf = j.csrf;
    if (typeof j.grant_id === 'string' && j.grant_id) state.grant = j.grant_id;
    return;
  }
  const ch = findChallenge(res ? res.body : '');
  if (ch) state.pendingChallenge = ch;
  if (!state.csrf) {
    const tok = findToken(res ? res.body : '', 'csrf');
    if (tok) state.csrf = tok;
  }
}

function solveChallenge(state) {
  const c = state.pendingChallenge;
  if (!c || !c.action) return false;
  const r = req(
    state,
    'POST',
    c.action,
    { challenge: c.challenge },
    null,
    [200, 301, 302, 303, 307, 308, 401, 403, 410],
    'POST /v2/challenges/{id}'
  );
  let last = r;
  const loc = header(r, 'Location');
  if (loc) last = req(state, 'GET', loc, null, null, [200, 401, 404, 410], 'GET /v2/challenge-grant');
  const j = safeJson(last) || safeJson(r);
  if (j && typeof j.grant_id === 'string' && j.grant_id) {
    state.grant = j.grant_id;
    state.pendingChallenge = null;
    return true;
  }
  return false;
}

function fetchChallenge(state) {
  const r = req(state, 'GET', '/v2/challenge-form', null, null, [200, 401, 404], 'GET /v2/challenge-form');
  if (r.status !== 200) return false;
  const ch = findChallenge(r.body);
  if (!ch) return false;
  state.pendingChallenge = ch;
  return solveChallenge(state);
}

/* ----------------------------------------------------------------- catalog */

function inStock(v) {
  return v && (v.in_stock === true || v.in_stock === 1 || v.in_stock === 'true');
}

function pickFrom(j) {
  if (!j) return null;
  let products = j.data && j.data.products;
  if (!products && j.data && j.data.product) products = [j.data.product];
  if (!products && j.products) products = j.products;
  if (!Array.isArray(products)) return null;
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p || p.id == null || !Array.isArray(p.variants)) continue;
    for (let k = 0; k < p.variants.length; k++) {
      const v = p.variants[k];
      if (inStock(v) && v.id != null) return { product_id: String(p.id), variant_id: String(v.id) };
    }
  }
  return null;
}

function selectProduct(state) {
  const r = req(state, 'GET', '/v2/catalog', null, null, [200, 401, 404], 'GET /v2/catalog');
  let pick = pickFrom(safeJson(r));
  if (pick) return pick;
  let next = '/v2/catalog/page';
  for (let page = 0; page < 3 && next; page++) {
    const pr = req(state, 'GET', next, null, null, [200, 401, 404], 'GET /v2/catalog/page');
    const j = safeJson(pr);
    pick = pickFrom(j);
    if (pick) return pick;
    next = j && typeof j.next === 'string' && j.next ? j.next : null;
  }
  return null;
}

/* ----------------------------------------------------------------- journey */

export function journey() {
  const started = Date.now();
  const jar = http.cookieJar();
  jar.clear(BASE); // fresh login/cart per journey, per-user cookie jar preserved

  const vuId = exec.vu.idInTest || 1;
  const state = {
    user: 'bench-' + (((vuId - 1) % 16) + 1),
    csrf: null,
    etag: null,
    cartId: null,
    grant: null,
    pendingChallenge: null,
  };

  // 1. login form (nonce cookie + csrf hidden input, decoy tolerant)
  const formRes = req(state, 'GET', '/v2/login-form', null, null, [200], 'GET /v2/login-form');
  let formToken = findToken(formRes.body, 'csrf');
  if (!formToken) {
    const fj = safeJson(formRes);
    if (fj && typeof fj.csrf === 'string') formToken = fj.csrf;
  }
  const formOk = formRes.status === 200 && !!formToken;
  check(formRes, { 'login form 200 + csrf input': () => formOk });
  if (!formOk) {
    setupErrors.add(1);
    journeyErrors.add(1);
    journeyDuration.add(Date.now() - started);
    return;
  }
  state.csrf = formToken;

  // 2. login (no auto redirects; dynamic Location followed exactly once)
  const loginRes = req(
    state,
    'POST',
    '/v2/login',
    { username: state.user, password: PASSWORD, csrf: formToken },
    null,
    [200, 301, 302, 303, 307, 308, 401, 403],
    'POST /v2/login'
  );
  const loginLoc = header(loginRes, 'Location');
  if (loginLoc) {
    const landing = req(state, 'GET', loginLoc, null, null, [200, 401, 404], 'GET /v2/login-landing');
    absorbLanding(state, landing);
  }
  const loginOk = (loginRes.status === 200 || !!loginLoc) && !!state.csrf && state.csrf !== formToken
    ? true
    : (loginRes.status === 200 || !!loginLoc) && !!state.csrf;
  check(loginRes, { 'login authenticated with csrf': () => loginOk });
  if (!loginOk) {
    setupErrors.add(1);
    journeyErrors.add(1);
    journeyDuration.add(Date.now() - started);
    return;
  }

  // 3. catalog selection (order independent: scans every product/variant)
  const pick = selectProduct(state);
  check(null, { 'in-stock product/variant selected': () => !!pick });
  if (!pick) {
    setupErrors.add(1);
    journeyErrors.add(1);
    journeyDuration.add(Date.now() - started);
    return;
  }

  // 4. challenge grant, solved right before cart creation (grants expire in 2s)
  if (!state.grant && state.pendingChallenge) solveChallenge(state);

  // 5. cart creation
  const cartBody = { product_id: pick.product_id, variant_id: pick.variant_id };
  if (state.grant) cartBody.grant_id = state.grant;
  const cartCall = () =>
    req(state, 'POST', '/v2/carts', cartBody, null, [201, 400, 401, 403, 409, 410, 422, 429], 'POST /v2/carts');

  let cartRes = cartCall();
  cartRes = handleAuth(state, cartRes, cartCall);
  if (cartRes.status === 429) {
    const ra = parseFloat(header(cartRes, 'Retry-After') || '1');
    sleep(isFinite(ra) && ra > 0 ? Math.min(ra, 2) : 1);
    cartRes = cartCall();
  }
  let cj = safeJson(cartRes);
  const grantProblem =
    cartRes.status !== 201 &&
    (cartRes.status === 400 || cartRes.status === 403 || cartRes.status === 409 || cartRes.status === 410 || cartRes.status === 422) &&
    /grant|challenge/i.test(String(cartRes.body || ''));
  if (grantProblem) {
    state.grant = null;
    if (fetchChallenge(state)) {
      cartBody.grant_id = state.grant;
      cartRes = cartCall();
      cj = safeJson(cartRes);
    }
  }
  const cartEtag = header(cartRes, 'ETag');
  if (cartEtag) state.etag = cartEtag;
  if (cj && cj.id != null) state.cartId = String(cj.id);
  const cartOk = cartRes.status === 201 && !!state.cartId;
  check(cartRes, {
    'cart created 201': () => cartOk,
    'cart id is cart-*': () => !!state.cartId && state.cartId.indexOf('cart-') === 0,
  });
  if (!cartOk) {
    setupErrors.add(1);
    journeyErrors.add(1);
    journeyDuration.add(Date.now() - started);
    return;
  }

  // 6. checkout: exactly one owned POST /v2/orders per journey
  const idemKey = state.cartId; // unique per cart, stable across retries
  const orderCall = () => {
    const h = { 'Idempotency-Key': idemKey };
    if (state.etag) h['If-Match'] = state.etag;
    return req(
      state,
      'POST',
      '/v2/orders',
      { cart_id: state.cartId },
      h,
      [200, 201, 400, 401, 403, 409, 412, 422, 428, 429],
      'POST /v2/orders'
    );
  };
  const placeOrder = () => {
    let r = orderCall();
    let n = 0;
    while (r.status === 429 && n < 4) {
      const ra = parseFloat(header(r, 'Retry-After') || '1');
      sleep(isFinite(ra) && ra > 0 ? Math.min(ra, 2) : 1);
      n++;
      r = orderCall();
    }
    return r;
  };
  const refreshEtag = () => {
    const g = req(state, 'GET', '/v2/carts/' + state.cartId, null, null, [200, 401, 404], 'GET /v2/carts/{id}');
    const e = header(g, 'ETag');
    if (e) state.etag = e;
  };

  let orderRes = placeOrder();
  if (orderRes.status === 401) {
    orderRes = handleAuth(state, orderRes, placeOrder);
  } else if (orderRes.status === 412 || orderRes.status === 428) {
    refreshEtag();
    orderRes = placeOrder();
  }

  const oj = safeJson(orderRes);
  const accepted = orderRes.status === 201 && !!oj && oj.accepted === true && oj.id != null;
  const denied = orderRes.status === 401 && !!oj && oj.error === 'denied';
  orderAttempts.add(1);
  ordersAccepted.add(accepted ? 1 : 0);
  check(orderRes, {
    'order committed 201 accepted:true': () => accepted,
    'checkout not denied': () => !denied,
    'no 200 accepted:false business failure': () => !(orderRes.status === 200 && oj && oj.accepted === false),
  });
  if (accepted) committedOrders.add(1);
  else journeyErrors.add(1);

  journeyDuration.add(Date.now() - started);
}

export default journey;
