```python
"""Locust translation of TestPlan-0 (source-m05.jmx).

Journey (one owned checkout per iteration):
    GET  /v2/login-form  -> extract input[name=csrf]
    POST /v2/login       -> session cookie (+ optional 302 Location, followed once)
    GET  /v2/catalog     -> first in-stock product/variant
    POST /v2/carts       -> cart id + ETag
    POST /v2/orders      -> 201 accepted:true  (the only counted pool start)

Pacing: the JMX ConstantThroughputTimer (121.2/min ~= 2/s) is a *journey*
pacer, so the shared slot clock below schedules the committed-checkout
request start, not the sum of HTTP requests.  4 virtual users, ramp 0,
warmup 5s + scored 30s of arrivals, bounded drain.
"""

import os
import re
import time
import html as html_lib
import itertools

from gevent import sleep
from locust import HttpUser, LoadTestShape, constant, task

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")

RATE = 2.0                      # committed checkout starts / second
MAX_VUS = 4                     # ThreadGroup.num_threads
WARMUP = 5.0
SCORED = 30.0
PACING_SPAN = WARMUP + SCORED   # arrivals issued over [T0, T0+35)
DRAIN = 5.0
RUN_LIMIT = PACING_SPAN + DRAIN
TOTAL_SLOTS = int(round(PACING_SPAN * RATE))
LAUNCH = time.monotonic()

_ACCOUNTS = itertools.count(0)

_INPUT_RE = re.compile(r"<input\b[^>]*>", re.I | re.S)
_ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-\w:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))"""
)


def form_csrf(text):
    """input[name=csrf] regardless of attribute order / decoys."""
    candidates = []
    for tag in _INPUT_RE.findall(text or ""):
        attrs = {}
        for m in _ATTR_RE.finditer(tag):
            val = m.group(2)
            if val is None:
                val = m.group(3)
            if val is None:
                val = m.group(4)
            attrs[m.group(1).lower()] = html_lib.unescape(val or "")
        if attrs.get("name") == "csrf" and "value" in attrs:
            candidates.append(attrs)
    for attrs in candidates:
        if (attrs.get("type") or "").lower() == "hidden":
            return attrs["value"]
    if candidates:
        return candidates[0]["value"]
    return None


class Pacer(object):
    """Greenlet-safe slot clock: slot n is reserved for T0 + n / RATE."""

    def __init__(self):
        self.base = None
        self.n = 0

    def claim(self):
        if self.n >= TOTAL_SLOTS:
            return None
        now = time.monotonic()
        if self.base is None:
            self.base = now
        slot = self.base + self.n / RATE
        self.n += 1
        return slot

    def done(self):
        return self.n >= TOTAL_SLOTS


PACER = Pacer()


def _committed(res):
    data = res["data"] if isinstance(res["data"], dict) else {}
    return res["status"] == 201 and data.get("accepted") is True and bool(data.get("id"))


def _v_login_form(res):
    return None if form_csrf(res["text"]) else "login-form: no input[name=csrf]"


def _v_login(res):
    if res["status"] == 302:
        return None if res["headers"].get("Location") else "login 302 without Location"
    data = res["data"] if isinstance(res["data"], dict) else {}
    return None if data.get("csrf") else "login: missing csrf"


def _v_session(res):
    data = res["data"] if isinstance(res["data"], dict) else {}
    if data.get("csrf") or data.get("user"):
        return None
    return "login redirect: no csrf/user payload"


def _v_catalog(res):
    data = res["data"] if isinstance(res["data"], dict) else {}
    products = ((data.get("data") or {}).get("products")) or []
    for p in products:
        for v in (p.get("variants") or []):
            if v.get("in_stock") and p.get("id") and v.get("id"):
                return None
    return "catalog: no in-stock product/variant"


def _cart_error(res):
    data = res["data"] if isinstance(res["data"], dict) else {}
    cid = data.get("id")
    if not cid or not str(cid).startswith("cart-"):
        return "cart: missing cart id"
    return None


def _v_cart(res):
    if res["status"] == 201:
        return _cart_error(res)
    data = res["data"] if isinstance(res["data"], dict) else {}
    if res["status"] == 401 and data.get("error") in ("expired", "session"):
        return None
    return "cart create failed (%s)" % res["status"]


def _v_cart_strict(res):
    return _cart_error(res) if res["status"] == 201 else "cart retry failed (%s)" % res["status"]


def _v_soft_auth(res):
    if res["status"] == 200:
        return None
    data = res["data"] if isinstance(res["data"], dict) else {}
    if res["status"] == 401 and data.get("error") in ("expired", "session"):
        return None
    return "recovery call failed (%s)" % res["status"]


def _order_error(res):
    if _committed(res):
        return None
    data = res["data"] if isinstance(res["data"], dict) else {}
    return "order not committed (status=%s accepted=%r)" % (
        res["status"], data.get("accepted"))


def _v_order(res):
    if _committed(res):
        return None
    data = res["data"] if isinstance(res["data"], dict) else {}
    if res["status"] == 401 and data.get("error") in ("expired", "session"):
        return None
    if res["status"] == 412:
        return None
    return _order_error(res)


def _v_order_strict(res):
    return _order_error(res)


class CheckoutUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        idx = next(_ACCOUNTS)
        self.username = "bench-%d" % ((idx % 16) + 1)
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.product_id = None
        self.variant_id = None
        self.stop_at = LAUNCH + RUN_LIMIT - 1.0

    # ---------- transport ----------

    def _call(self, method, path, payload=None, extra=None, name=None,
              ok=(200,), validate=None, capture_etag=False):
        headers = {"Accept": "application/json"}
        if method != "GET" and self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if extra:
            headers.update(extra)
        kwargs = {
            "headers": headers,
            "name": name or path,
            "allow_redirects": False,
            "catch_response": True,
            "timeout": (2.0, 5.0),
        }
        if payload is not None:
            kwargs["json"] = payload
        res = {"status": 0, "data": None, "text": "", "headers": {},
               "etag": None, "ok": False}
        try:
            with self.client.request(method, path, **kwargs) as r:
                res["status"] = r.status_code
                res["headers"] = r.headers
                res["text"] = r.text or ""
                try:
                    res["data"] = r.json()
                except Exception:
                    res["data"] = None
                if isinstance(res["data"], dict) and res["data"].get("csrf"):
                    self.csrf = res["data"]["csrf"]
                tag = r.headers.get("ETag")
                if tag:
                    res["etag"] = tag
                    if capture_etag:
                        self.etag = tag
                if r.status_code in ok:
                    err = validate(res) if validate else None
                    if err:
                        r.failure(err)
                    else:
                        r.success()
                        res["ok"] = True
                else:
                    r.failure("unexpected status %s on %s" % (r.status_code, path))
        except Exception as exc:  # transport error: already a failed sample
            res["status"] = 0
            res["ok"] = False
            res["text"] = str(exc)
        return res

    # ---------- journey steps ----------

    def _login(self):
        self.client.cookies.clear()
        self.csrf = None
        res = self._call("GET", "/v2/login-form", ok=(200,), validate=_v_login_form)
        if not res["ok"]:
            return False
        token = form_csrf(res["text"])
        res = self._call("POST", "/v2/login",
                         {"username": self.username, "password": "bench", "csrf": token},
                         ok=(200, 302), validate=_v_login)
        if not res["ok"]:
            return False
        if res["status"] == 302:
            location = res["headers"].get("Location")
            res = self._call("GET", location, name="/v2/login/redirect",
                             ok=(200,), validate=_v_session)
            if not res["ok"]:
                return False
        return bool(self.csrf)

    def _select_product(self):
        res = self._call("GET", "/v2/catalog", ok=(200,), validate=_v_catalog)
        if not res["ok"]:
            return False
        products = ((res["data"].get("data") or {}).get("products")) or []
        for p in products:
            for v in (p.get("variants") or []):
                if v.get("in_stock"):
                    self.product_id = p["id"]
                    self.variant_id = v["id"]
                    return True
        return False

    def _read_cart(self):
        res = self._call("GET", "/v2/carts/%s" % self.cart_id,
                         name="/v2/carts/{id}", ok=(200,), capture_etag=True)
        return res["ok"]

    def _renew(self):
        res = self._call("POST", "/v2/session/renew", {},
                         ok=(200, 401), validate=_v_soft_auth)
        return res["status"] == 200

    def _recover_cart(self):
        if not self.cart_id:
            return True
        res = self._call("POST", "/v2/carts/%s/recover" % self.cart_id, {},
                         name="/v2/carts/{id}/recover",
                         ok=(200, 401), validate=_v_soft_auth, capture_etag=True)
        return res["status"] == 200

    def _recover_session(self, kind):
        if kind == "expired":
            alive = self._renew()
        else:
            alive = self._login()
        self._recover_cart()
        return alive

    def _create_cart(self):
        self.cart_id = None
        self.etag = None
        payload = {"product_id": self.product_id, "variant_id": self.variant_id}
        res = self._call("POST", "/v2/carts", payload,
                         ok=(201, 401), validate=_v_cart, capture_etag=True)
        data = res["data"] if isinstance(res["data"], dict) else {}
        if res["status"] == 401 and data.get("error") in ("expired", "session"):
            if not self._recover_session(data.get("error")):
                return False
            res = self._call("POST", "/v2/carts", payload,
                             ok=(201,), validate=_v_cart_strict, capture_etag=True)
        if res["status"] == 201 and res["ok"]:
            self.cart_id = res["data"]["id"]
            return True
        return False

    def _checkout(self):
        payload = {"cart_id": self.cart_id}
        extra = {"Idempotency-Key": "checkout-%s" % self.cart_id}
        if self.etag:
            extra["If-Match"] = self.etag
        res = self._call("POST", "/v2/orders", payload, extra=extra,
                         ok=(200, 201, 401, 412), validate=_v_order)
        if _committed(res):
            return True
        data = res["data"] if isinstance(res["data"], dict) else {}
        status = res["status"]
        if status == 412:
            self._read_cart()
        elif status == 401 and data.get("error") in ("expired", "session"):
            if not self._recover_session(data.get("error")):
                return False
        else:
            return False
        if self.etag:
            extra["If-Match"] = self.etag
        res = self._call("POST", "/v2/orders", payload, extra=extra,
                         ok=(200, 201), validate=_v_order_strict)
        return _committed(res)

    # ---------- iteration ----------

    @task
    def journey(self):
        if time.monotonic() >= self.stop_at or PACER.done():
            raise StopUser()

        if not self._login():
            sleep(0.25)
            return
        if not self._select_product():
            sleep(0.25)
            return
        if not self._create_cart():
            sleep(0.25)
            return

        slot = PACER.claim()
        if slot is None:
            raise StopUser()
        delay = slot - time.monotonic()
        if delay > 0:
            sleep(delay)

        self._checkout()

        if time.monotonic() >= self.stop_at or PACER.done():
            raise StopUser()


class CheckoutShape(LoadTestShape):
    """4 users, ramp 0; arrivals stop at T0+35s, bounded drain, then None."""

    def tick(self):
        now = time.monotonic()
        if self.get_run_time() >= RUN_LIMIT:
            return None
        if PACER.base is not None and now >= PACER.base + PACING_SPAN + 3.0:
            return None
        if PACER.done():
            return (0, MAX_VUS)
        return (MAX_VUS, MAX_VUS)
