import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  // ---- execution contract: users=2, iterations(per user)=2, mode=decline ----
  private static final int USERS = 2;
  private static final int ITERATIONS = 2;
  private static final long JOURNEYS = (long) USERS * (long) ITERATIONS; // 4 order attempts, 4 carts

  private static final String BASE_URL =
      (System.getenv("BASE_URL") == null || System.getenv("BASE_URL").trim().isEmpty())
          ? "http://127.0.0.1:8000"
          : System.getenv("BASE_URL").trim();

  private static final HttpProtocolBuilder PROTOCOL =
      http.baseUrl(BASE_URL)
          .disableFollowRedirect()
          .disableAutoReferer()
          .acceptHeader("application/json")
          .contentTypeHeader("application/json")
          .connectTimeout(Duration.ofMillis(2000))
          .requestTimeout(Duration.ofMillis(3000));

  /** Retain previous value when a mutation omits a fresh token/etag. */
  private static ChainBuilder keep(String tmp, String key) {
    return exec((Session s) -> {
      String v = s.contains(tmp) ? s.getString(tmp) : null;
      if (v != null && !v.trim().isEmpty() && !"MISSING".equals(v)) {
        return s.set(key, v).remove(tmp);
      }
      return s.remove(tmp);
    });
  }

  private static Iterator<Map<String, Object>> accounts() {
    List<Map<String, Object>> rows = new ArrayList<>();
    for (int i = 1; i <= USERS; i++) {
      Map<String, Object> row = new HashMap<>();
      row.put("username", "bench-" + i);
      rows.add(row);
    }
    return rows.iterator();
  }

  // ---- fresh login / fresh cart per iteration (JMX CookieManager clearEachIteration) ----
  private static final ChainBuilder RESET =
      exec(flushSessionCookies(), flushHttpCache())
          .exec((Session s) ->
              s.set("csrf", "MISSING")
                  .set("form", "MISSING")
                  .set("cart", "MISSING")
                  .set("etag", "*")
                  .set("grant", "MISSING")
                  .set("product", "MISSING")
                  .set("variant", "MISSING")
                  .set("quantity", 2)
                  .remove("loginLocation")
                  .remove("order"));

  private static final ChainBuilder LOGIN_FORM =
      exec(
              http("login_form")
                  .get("/v2/login-form")
                  .check(status().is(200))
                  .check(
                      regex("<input(?=[^>]*\\sname=[\"']csrf[\"'])(?=[^>]*\\svalue=[\"']([^\"']+)[\"'])[^>]*>")
                          .saveAs("form")))
          .exec((Session s) -> s.set("csrf", s.getString("form")));

  private static final ChainBuilder LOGIN =
      exec(
              http("login")
                  .post("/v2/login")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
                  .check(status().in(200, 302))
                  .check(regex("\"csrf\"\\s*:"))
                  .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                  .check(jsonPath("$.user").optional().saveAs("user"))
                  .check(header("Location").optional().saveAs("loginLocation")))
          .exec(keep("csrfNew", "csrf"));

  private static final ChainBuilder LOGIN_REDIRECT =
      doIf((Session s) -> {
            String loc = s.contains("loginLocation") ? s.getString("loginLocation") : null;
            return loc != null && !loc.trim().isEmpty();
          })
          .then(
              exec(
                      http("login_redirect")
                          .get("#{loginLocation}")
                          .check(status().is(200))
                          .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                          .check(jsonPath("$.grant_id").optional().saveAs("grantNew")))
                  .exec(keep("csrfNew", "csrf"))
                  .exec(keep("grantNew", "grant")));

  private static final ChainBuilder CATALOG =
      exec(
              http("catalog")
                  .get("/v2/catalog")
                  .check(status().is(200))
                  .check(
                      jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                          .find()
                          .saveAs("product"))
                  .check(
                      jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                          .find()
                          .saveAs("variant"))
                  .check(jsonPath("$.csrf").optional().saveAs("csrfNew")))
          .exec(keep("csrfNew", "csrf"));

  private static final ChainBuilder CART =
      exec((Session s) -> {
            String grant = s.contains("grant") ? s.getString("grant") : null;
            StringBuilder body = new StringBuilder("{\"product_id\":\"")
                .append(s.getString("product"))
                .append("\",\"variant_id\":\"")
                .append(s.getString("variant"))
                .append("\"");
            if (grant != null && !grant.trim().isEmpty() && !"MISSING".equals(grant)) {
              body.append(",\"grant_id\":\"").append(grant).append("\"");
            }
            body.append("}");
            return s.set("cartBody", body.toString());
          })
          .exec(
              http("cart_create")
                  .post("/v2/carts")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody("#{cartBody}"))
                  .check(status().is(201))
                  .check(regex("\"id\"\\s*:\\s*\"cart-"))
                  .check(jsonPath("$.id").saveAs("cart"))
                  .check(jsonPath("$.csrf").optional().saveAs("csrfNew"))
                  .check(header("ETag").optional().saveAs("etagNew")))
          .exec(keep("csrfNew", "csrf"))
          .exec(keep("etagNew", "etag"));

  /** HTTP 200 accepted:false is a business failure: the accepted check must fail. */
  private static final ChainBuilder ORDER =
      exec(
              http("order_submit")
                  .post("/v2/orders")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("Idempotency-Key", "#{cart}")
                  .header("If-Match", "#{etag}")
                  .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
