def check_catalog(text, data, headers, status):
    if select_variant(data) is None:
        return "assertion failed: no in-stock product/variant in catalog"
    return None


def check_cart(text, data, headers, status):
    if not _CART_ASSERT.search(text or ""):
        return 'assertion failed: cart body missing "id":"cart-'
    return None


def check_cart_read(text, data, headers, status):
    if not data.get("id"):
        return "assertion failed: cart read missing id"
    return None


def check_checkout(text, data, headers, status):
    if data.get("accepted") is False:
        return "business failure: order declined (accepted=false)"
    if status != 201:
        return "unexpected checkout status %s (expected 201)" % status
    if not _ACCEPT_ASSERT.search(text or ""):
        return 'assertion failed: order body missing "accepted":true'
    return None


def select_variant(data):
    """Order-independent selection: stable across the reverse_catalog variant."""
    products = (data.get("data") or {}).get("products") or []
    best = None
    for product in products:
        if not isinstance(product, dict):
            continue
        pid = product.get("id")
        if not pid:
            continue
        for variant in product.get("variants") or []:
            if not isinstance(variant, dict):
                continue
            vid = variant.get("id")
            if variant.get("in_stock") is True and vid:
                key = str(pid)
                if best is None or key < best[0]:
                    best = (key, pid, vid)
    if best is None:
        return None
    return best[1], best[2]


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.account = "bench-%d" % (((next(_ACCOUNT_SEQ) - 1) % 16) + 1)
        self.iteration = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        _STATE["started"] += 1

    def on_stop(self):
        _STATE["finished"] += 1

    # ---------------- transport ----------------

    def _perform(self, method, path, name, payload=None, expect=(200,),
                 check=None, if_match=False, idempotency_key=None,
                 allow_recovery=True):
        method = method.upper()
        throttled = 0
        recovered = False
        precondition_retried = False
        while True:
            headers = {"Accept": "application/json"}
            if method != "GET":
                headers["Content-Type"] = "application/json"
                if self.csrf:
                    headers["X-CSRF-Token"] = self.csrf
            if if_match and self.etag:
                headers["If-Match"] = self.etag
            if idempotency_key:
                headers["Idempotency-Key"] = idempotency_key

            kwargs = {
                "name": name,
                "headers": headers,
                "catch_response": True,
                "allow_redirects": False,
                "timeout": (CONNECT_TIMEOUT, RESPONSE_TIMEOUT),
            }
            if method != "GET" and payload is not None:
                kwargs["json"] = payload

            with self.client.request(method, path, **kwargs) as resp:
                status = getattr(resp, "status_code", 0) or 0
                try:
                    text = resp.text or ""
                except Exception:
                    text = ""
                raw_headers = getattr(resp, "headers", None) or {}
                rh = {str(k).lower(): v for k, v in dict(raw_headers).items()}
                data = body_json(text)
                error = data.get("error")

                if status == 429 and throttled < MAX_429_RETRIES:
                    throttled += 1
                    resp.success()  # scheduled throttle: expected, not a failure
                    time.sleep(retry_after(rh.get("retry-after")))
                    continue

                if (status == 401 and error in ("expired", "session")
                        and allow_recovery and not recovered):
                    recovered = True
                    resp.success()  # expected expiry: not a failure
                    self._recover_session(error)
                    continue

                if (status == 412 and method != "GET" and self.cart_id
                        and not precondition_retried):
                    precondition_retried = True
                    resp.failure("412 precondition failed on %s" % name)
                    self._refresh_etag()
                    continue

                reason = None
                if status not in expect:
                    reason = "unexpected status %s on %s (expected %s)" % (
                        status, name, list(expect))
                elif check is not None:
                    reason = check(text, data, rh, status)
                if reason is None:
                    ok = True
                    resp.success()
                else:
                    ok = False
                    resp.failure(reason)

            if ok:
                token = data.get("csrf")
                if isinstance(token, str) and token:
                    self.csrf = token
                tag = rh.get("etag")
                if tag:
                    self.etag = tag
            return ok, status, data, rh, text

    # ---------------- bounded recovery ----------------

    def _recover_session(self, error):
        renewed = False
        if error == "expired":
            ok, _, _, _, _ = self._perform(
                "POST", "/v2/session/renew", "aux:renew", payload={},
                expect=(200, 201, 202), allow_recovery=False)
            renewed = ok
        if not renewed:
            self._login("aux")
        if self.cart_id:
            self._perform(
                "POST", "/v2/carts/%s/recover" % self.cart_id, "aux:recover",
                payload={}, expect=(200, 201, 202), allow_recovery=False)

    def _refresh_etag(self):
        if not self.cart_id:
            return
        self._perform("GET", "/v2/carts/%s" % self.cart_id, "aux:cart-read",
                      expect=(200,), check=check_cart_read,
                      allow_recovery=False)

    # ---------------- journey steps ----------------

    def _login(self, prefix):
        self.client.cookies.clear()
        self.csrf = None
        ok, _, _, _, text = self._perform(
            "GET", "/v2/login-form", prefix + ":login-form", expect=(200,),
            check=check_form, allow_recovery=False)
        if not ok:
            return False
        token = form_csrf(text)
        ok, status, _, rh, _ = self._perform(
            "POST", "/v2/login", prefix + ":login",
            payload={"username": self.account, "password": PASSWORD,
                     "csrf": token},
            expect=(200, 302), check=check_login, allow_recovery=False)
        if not ok:
            return False
        if status == 302:
            path = local_path(rh.get("location"))
            if path is None:
                return False
            ok, _, data, _, _ = self._perform(
                "GET", path, prefix + ":login-redirect", expect=(200,),
                check=check_redirect, allow_recovery=False)
            if not ok:
                return False
            grant = data.get("grant_id")
            if grant:
                self.grant_id = grant
        return bool(self.csrf)

    def _catalog(self):
        ok, _, data, _, _ = self._perform(
            "GET", "/v2/catalog", "tx:catalog", expect=(200,),
            check=check_catalog)
        if not ok:
            return False
        picked = select_variant(data)
        if picked is None:
            return False
        self.product_id, self.variant_id = picked
        return True

    def _create_cart(self):
        payload = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
            self.grant_id = None  # a grant is passed exactly once
        ok, _, data, _, _ = self._perform(
            "POST", "/v2/carts", "tx:cart", payload=payload, expect=(201,),
            check=check_cart)
        if not ok:
            return False
        cart = data.get("id")
        if not cart:
            return False
        self.cart_id = cart
        return True

    def _checkout(self):
        self._perform("GET", "/v2/carts/%s" % self.cart_id, "tx:cart-read",
                      expect=(200,), check=check_cart_read)
        self._perform(
            "POST", "/v2/orders", CHECKOUT_NAME,
            payload={"cart_id": self.cart_id},
            expect=(200, 201), check=check_checkout,
            if_match=True, idempotency_key=str(self.cart_id))

    def _journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        if not self._login("tx"):
            return
        if not self._catalog():
            return
        if not self._create_cart():
            return
        self._checkout()

    @task
    def run_plan(self):
        if self.iteration >= ITERATIONS:
            raise StopUser()
        self.iteration += 1
        try:
            self._journey()
        except StopUser:
            raise
        except Exception as exc:  # keep the sample truthful, never restart checkout
            self.environment.runner.stats.log_error(
                "tx:journey", "journey error: %r" % (exc,))
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    """2 users, ramp 0; each user runs exactly 2 iterations then StopUser."""

    def tick(self):
        runner = getattr(self, "runner", None)
        elapsed = self.get_run_time() if runner is not None else 0.0
        if _STATE["finished"] >= USERS or elapsed > MAX_RUN_SECONDS:
            self._finalize()
            return None
        return (USERS, USERS)

    def _finalize(self):
        runner = getattr(self, "runner", None)
        if runner is None:
            return
        entry = runner.stats.get(CHECKOUT_NAME, CHECKOUT_METHOD)
        total = entry.num_requests          # checkout transaction denominator
        failed = entry.num_failures
        allowed = int(MAX_TX_ERROR_RATIO * total)
        complete = total >= EXPECTED_TX
        runner.environment.process_exit_code = 0 if (complete and failed <= allowed) else 1
