import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final int USERS = 2;
    private static final int ITERATIONS = 2;

    private static final String BASE_URL = System.getenv("BASE_URL") == null
        ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");

    private static final ObjectMapper JSON = new ObjectMapper();

    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static final Pattern INPUT_TAG = Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern ATTRIBUTE = Pattern.compile(
        "(?is)([a-zA-Z_:][-a-zA-Z0-9_:.]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'>]+))");

    private static String decode(String raw) {
        return raw.replace("&quot;", "\"").replace("&#39;", "'").replace("&#x27;", "'")
            .replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&");
    }

    private static String escape(String raw) {
        return raw.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private static String attribute(String tag, String wanted) {
        Matcher matcher = ATTRIBUTE.matcher(tag);
        while (matcher.find()) {
            if (wanted.equalsIgnoreCase(matcher.group(1))) {
                String value = matcher.group(2) != null ? matcher.group(2)
                    : matcher.group(3) != null ? matcher.group(3) : matcher.group(4);
                return decode(value == null ? "" : value);
            }
        }
        return null;
    }

    private static String formToken(String html, String name) {
        if (html == null) return null;
        Matcher tags = INPUT_TAG.matcher(html);
        while (tags.find()) {
            String tag = tags.group();
            String found = attribute(tag, "name");
            if (found == null || !name.equals(found.trim())) continue;
            String value = attribute(tag, "value");
            if (value != null && !value.trim().isEmpty()) return value.trim();
        }
        return null;
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static Session resetJourney(Session session) {
        return session.set("csrf", "").set("formCsrf", "")
            .remove("location").remove("loginFormHtml").remove("catalogBody")
            .remove("product").remove("variant").remove("cart").remove("etag")
            .remove("orderId");
    }

    private static Session requireToken(Session session) {
        String token = session.contains("csrf") ? session.getString("csrf") : "";
        return token == null || token.isEmpty() ? session.markAsFailed() : session;
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (Exception error) {
            return session.markAsFailed();
        }
        return session.markAsFailed();
    }

    private static ChainBuilder login() {
        return exec(session -> resetJourney(session))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginFormHtml")))
            .exec(session -> {
                String token = formToken(session.getString("loginFormHtml"), "csrf");
                return token == null ? session.markAsFailed() : session.set("formCsrf", token);
            })
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + escape(username(session))
                    + "\",\"password\":\"bench\",\"csrf\":\""
                    + escape(session.getString("formCsrf")) + "\"}"))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.user").optional().saveAs("loginUser"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .check(status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.user").optional().saveAs("loginUser")))))
            .exec(session -> requireToken(session));
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(login())
            .exec(http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.data.products").exists(),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(session -> selectProduct(session))
            .exec(http("cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> "{\"product_id\":\"" + escape(session.getString("product"))
                    + "\",\"variant_id\":\"" + escape(session.getString("variant")) + "\"}"))
                .check(status().is(201),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .header("Idempotency-Key", "order-#{cart}")
                .body(StringBody(session -> "{\"cart_id\":\"" + escape(session.getString("cart")) + "\"}"))
                .check(status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").saveAs("orderId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    public ModelSimulation() {
        setUp(scenario("flow")
            .exec(repeat(ITERATIONS, "journey").on(journey()))
            .injectOpen(atOnceUsers(USERS)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}
