};

const BAD = { status: 0, headers: {}, body: '', url: '' };
let vuIteration = 0;

/* ---------- helpers ---------- */

function hdr(r, name) {
  if (!r || !r.headers) return '';
  const want = String(name).toLowerCase();
  const keys = Object.keys(r.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) {
      const v = r.headers[keys[i]];
      return v === undefined || v === null ? '' : String(v);
    }
  }
  return '';
}

function body(r) {
  try {
    const b = r.json();
    return b && typeof b === 'object' ? b : {};
  } catch (_) {
    return {};
  }
}

function resolve(path) {
  if (!path) return '';
  const p = String(path);
  if (/^https?:\/\//i.test(p)) return p.indexOf(BASE) === 0 ? p : '';
  return BASE + (p.charAt(0) === '/' ? p : '/' + p);
}

function decode(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#0*39;/g, "'")
    .replace(/&#x0*27;/gi, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
