    const val = m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : (m[4] !== undefined ? m[4] : ''));
    if (!(key in out)) out[key] = decode(val);
  }
  return out;
}

function inputTags(html) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, ' ');
  const tags = clean.match(/<input\b[^>]*>/gi) || [];
  const list = [];
  for (let i = 0; i < tags.length; i++) list.push(tagAttrs(tags[i]));
