ATTR = re.compile(
    r'([A-Za-z_:][\w:.-]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))')


def attributes(tag):
    found = {}
    for match in ATTR.finditer(tag):
        value = match.group(2)
        if value is None:
            value = match.group(3)
        if value is None:
            value = match.group(4) or ''
        found[match.group(1).lower()] = value
    return found


def form_value(html, field):
    for tag in re.findall(r'<input\b[^>]*>', html or '', re.IGNORECASE):
        attrs = attributes(tag)
        if attrs.get('name') != field:
            continue
        if 'disabled' in attrs or 'decoy' in tag.lower():
            continue
        value = attrs.get('value')
        if value:
            return value
    return None


def form_action(html):
    for tag in re.findall(r'<form\b[^>]*>', html or '', re.IGNORECASE):
        action = attributes(tag).get('action')
        if action:
            return action
    return None


class MatrixUser(HttpUser):
    wait_time = lambda self: 0

    def on_start(self):
        with STATE['lock']:
            STATE['assigned'] += 1
            number = STATE['assigned']
        self.row = ROWS[(number - 1) % len(ROWS)]
        self.username = self.row['username']
        self.password = self.row.get('password', 'bench')
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    def fail(self, message):
        self.environment.process_exit_code = 99
        return False

    def raw(self, path, method='GET', data=None, headers=None, name=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name, catch_response=True, allow_redirects=False,
                                 timeout=5) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}
            error = body.get('error')
            bare = path.split('?', 1)[0]
            allowed = (response.status_code < 400
                       or response.status_code == 401 and error in ('expired', 'session')
                       or response.status_code == 412
                       or response.status_code == 429 and bare in ('/v2/work', '/v2/browse'))
