                                   'csrf': token})
        if response.status_code == 302:
            location = response.headers.get('Location')
            if not location:
                return self.fail('login redirect without Location')
            response, body = self.raw(location)
        if response.status_code != 200 or not self.csrf:
            return self.fail('login did not establish a session')
        return True

    def recover(self):
        renewed, _ = self.raw('/v2/session/renew', 'POST', {})
        if renewed.status_code != 200:
            self.login()
        if self.cart:
            response, _ = self.raw('/v2/carts/' + self.cart + '/recover', 'POST', {})
            self.etag = response.headers.get('ETag', self.etag)

    def request(self, path, method='GET', data=None, headers=None, name=None):
        response, body = self.raw(path, method, data, headers, name)
        if response.status_code == 401 and body.get('error') in ('expired', 'session'):
            self.recover()
            response, body = self.raw(path, method, data, headers, name)
        return response, body

    def pick_product(self):
        page = '/v2/catalog'
        for _ in range(3):
            response, body = self.request(page)
            if response.status_code != 200:
                return None
            products = body.get('data', {}).get('products', []) or []
            for item in products:
                for variant in item.get('variants', []) or []:
                    if variant.get('in_stock') and item.get('id') and variant.get('id'):
                        return item['id'], variant['id']
            page = body.get('next')
            if not page:
                break
        return None

    def flow(self):
        self.client.cookies.clear()
        if not self.login():
            return
        picked = self.pick_product()
        if not picked:
            self.fail('no in-stock product')
            return
        product_id, variant_id = picked
        payload = {'product_id': product_id, 'variant_id': variant_id}
        if self.grant:
            payload['grant_id'] = self.grant
        response, body = self.request('/v2/carts', 'POST', payload)
        self.cart = body.get('id', '')
        self.etag = response.headers.get('ETag', '')
        if response.status_code != 201 or not self.cart:
            self.fail('cart not created')
            return
        self.grant = ''
        order = {'cart_id': self.cart}
        headers = {'Idempotency-Key': 'order-' + str(self.cart)}
        if self.etag:
            headers['If-Match'] = self.etag
        response, body = self.request('/v2/orders', 'POST', order, headers, 'checkout')
        if response.status_code == 412:
            fresh, _ = self.request('/v2/carts/' + self.cart)
