            response, body = self.request('/v2/orders', 'POST', order, headers, 'checkout')
        if response.status_code != 201 or body.get('accepted') is not True or not body.get('id'):
            self.fail('order not accepted')
            return
        self.cart = ''
        self.etag = ''

    @task
    def run_scenario(self):
        self.flow()
        self.iteration += 1
        if self.iteration >= CFG.get('iterations', 2):
            with STATE['lock']:
                STATE['finished'] += 1
            raise StopUser()


class MatrixShape(LoadTestShape):
    def tick(self):
        users = CFG.get('users', 2)
        with STATE['lock']:
            finished = STATE['finished']
        if finished >= users or self.get_run_time() > 180:
            return None
        if finished > 0:
            current = self.runner.user_count if self.runner is not None else users
            return (current, max(1, users))
        return (users, max(1, users))
