import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final ObjectMapper JSON = new ObjectMapper();
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;

    private static final Pattern COMMENTS = Pattern.compile("(?s)<!--.*?-->");
    private static final Pattern INPUT_TAG = Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern FORM_TAG = Pattern.compile("(?is)<form\\b[^>]*>");
    private static final Pattern ATTRIBUTE = Pattern.compile(
        "(?is)([a-z_:][-a-z0-9_:.]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'>]+))");
    private static final Pattern DISABLED = Pattern.compile("(?i)\\sdisabled(\\s|=|/?>)");

    private static final String[] JOURNEY_KEYS = {
        "csrf", "formCsrf", "loginHtml", "user", "location", "grant",
        "catalogBody", "catalogStatus", "product", "variant", "nextPage",
        "cart", "etag", "cartStatus", "renewStatus", "orderId", "accepted",
        "pollUrl", "reservation", "jobState", "workStatus", "retryAfter",
        "challengeHtml", "challengeAction", "challengeToken"
    };

    private static final HttpProtocolBuilder HTTP = http
        .baseUrl(resolveBaseUrl())
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static String resolveBaseUrl() {
        String env = System.getenv("BASE_URL");
        return env == null || env.trim().isEmpty() ? "http://127.0.0.1:8000" : env.trim();
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static String password() {
        return "bench";
    }

    private static String unescape(String value) {
        return value.replace("&quot;", "\"").replace("&apos;", "'").replace("&#39;", "'")
            .replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&");
    }

    private static Map<String, String> attributes(String tag) {
        Map<String, String> attrs = new HashMap<>();
        Matcher matcher = ATTRIBUTE.matcher(tag);
        while (matcher.find()) {
            String value = matcher.group(2) != null ? matcher.group(2)
                : matcher.group(3) != null ? matcher.group(3)
                : matcher.group(4) != null ? matcher.group(4) : "";
            String key = matcher.group(1).toLowerCase();
            if (!attrs.containsKey(key)) {
                attrs.put(key, unescape(value));
            }
        }
        return attrs;
    }

    private static String hiddenInput(String html, String name) {
        if (html == null) {
            return null;
        }
        Matcher tags = INPUT_TAG.matcher(COMMENTS.matcher(html).replaceAll(""));
        String best = null;
        int bestScore = -1;
        while (tags.find()) {
            String tag = tags.group();
            Map<String, String> attrs = attributes(tag);
            if (!name.equalsIgnoreCase(attrs.get("name"))) {
                continue;
            }
            String value = attrs.get("value");
            if (value == null || value.isEmpty()) {
                continue;
            }
            String lower = tag.toLowerCase();
            int score = 2;
            if (lower.contains("decoy") || DISABLED.matcher(tag).find()) {
                score = 0;
            } else if (!"hidden".equalsIgnoreCase(attrs.get("type"))) {
                score = 1;
            }
            if (score > bestScore) {
                bestScore = score;
                best = value;
            }
        }
        return best;
    }

    private static String formAction(String html) {
        if (html == null) {
            return null;
        }
        Matcher tags = FORM_TAG.matcher(COMMENTS.matcher(html).replaceAll(""));
        while (tags.find()) {
            String action = attributes(tags.group()).get("action");
            if (action != null && !action.isEmpty()) {
                return action;
            }
        }
        return null;
    }

    private static ChainBuilder freshJourney() {
        return exec(flushCookieJar())
            .exec(flushHttpCache())
            .exec(session -> {
                Session fresh = session;
                for (String key : JOURNEY_KEYS) {
                    fresh = fresh.remove(key);
                }
                return fresh.set("csrf", "");
            });
    }

    private static ChainBuilder login() {
        return exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginHtml")))
            .exec(session -> {
                String token = hiddenInput(session.getString("loginHtml"), "csrf");
                return token == null ? session.markAsFailed() : session.set("formCsrf", token);
            })
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"" + password()
                    + "\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    header("Location").optional().saveAs("location"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.user").optional().saveAs("user")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .check(status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.user").optional().saveAs("user")))
                .exec(session -> session.remove("location"))))
            .exec(session -> {
                String csrf = session.contains("csrf") ? session.getString("csrf") : "";
                return csrf == null || csrf.isEmpty() ? session.markAsFailed() : session;
            });
    }

    private static ChainBuilder renew() {
        return exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 401), status().saveAs("renewStatus"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static Session selectProduct(Session session) {
        List<String[]> options = new ArrayList<>();
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)) {
                        options.add(new String[] {
                            product.path("id").asText(), variant.path("id").asText()});
                    }
                }
            }
        } catch (Exception error) {
            return session.markAsFailed();
        }
        if (options.isEmpty()) {
            return session.markAsFailed();
        }
        String[] choice = options.get((int) ((session.userId() - 1) % options.size()));
        return session.set("product", choice[0]).set("variant", choice[1]);
    }

    private static ChainBuilder catalog() {
        return exec(http("catalog").get("/v2/catalog")
                .check(status().in(200, 401), status().saveAs("catalogStatus"),
                    bodyString().optional().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("catalogStatus") == 401).then(
                renew()
                .exec(http("catalog retry").get("/v2/catalog")
                    .check(status().is(200), bodyString().saveAs("catalogBody"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))))
            .exec(session -> selectProduct(session));
    }

    private static ChainBuilder createCart() {
        return exec(http("cart").post("/v2/carts")
            .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
            .body(StringBody(session -> "{\"product_id\":\"" + session.getString("product")
                + "\",\"variant_id\":\"" + session.getString("variant") + "\""
                + (session.contains("grant") && !session.getString("grant").isEmpty()
                    ? ",\"grant_id\":\"" + session.getString("grant") + "\"" : "")
                + "}"))
            .check(status().is(201), jsonPath("$.id").saveAs("cart"),
                header("ETag").saveAs("etag"), jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder cartState() {
        return exec(http("cart state").get("/v2/carts/#{cart}")
                .check(status().in(200, 401), status().saveAs("cartStatus"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("cartStatus") == 401).then(
                renew()
                .exec(doIf(session -> session.getInt("renewStatus") == 401).then(
                    login()
                    .exec(http("cart recover").post("/v2/carts/#{cart}/recover")
                        .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().is(200), header("ETag").optional().saveAs("etag"),
                            jsonPath("$.csrf").optional().saveAs("csrf")))))
                .exec(http("cart state retry").get("/v2/carts/#{cart}")
                    .check(status().is(200), header("ETag").saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder commit() {
        return exec(http("commit").post("/v2/orders")
            .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}").header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
            .check(status().is(201), jsonPath("$.accepted").ofBoolean().is(true),
                jsonPath("$.id").saveAs("orderId"), jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder journey() {
        return freshJourney()
            .exec(login())
            .exec(doIf(session -> session.contains("csrf") && !session.getString("csrf").isEmpty())
                .then(catalog()))
            .exec(doIf(session -> session.contains("product") && session.contains("variant"))
                .then(createCart()
                    .exec(cartState())
                    .exec(commit())))
            .exec(pause(Duration.ofMillis(50)));
    }

    public ModelSimulation() {
        setUp(scenario("flow")
            .exec(repeat(ITERATIONS).on(journey()))
            .injectOpen(atOnceUsers(USERS)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}

