// VU-local only. Every iteration replaces this with a brand new cookie jar,
// CSRF token and cart, so nothing (session, nonce, cart, ETag) leaks forward.
const vuJar = new http.CookieJar();
let S = null;
let prevCart = '';
const seenOrders = [];

function freshJar() {
  try { vuJar.clear(BASE); } catch (e) { /* older jar API */ }
  try {
    const j = new http.CookieJar();
    if (j) return j;
  } catch (e) { /* fall back to the cleared per-VU jar */ }
  return vuJar;
}

function newState() {
  return { jar: freshJar(), csrf: '', cart: '', etag: '' };
}

function body(r) {
  if (!r || !r.body) return {};
  try {
    const b = r.json();
    return b && typeof b === 'object' ? b : {};
  } catch (e) { return {}; }
}

function header(r, name) {
  if (!r || !r.headers) return '';
  const keys = Object.keys(r.headers);
  const want = String(name).toLowerCase();
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return r.headers[keys[i]];
