  const a = {};
  const re = /([A-Za-z_:][-A-Za-z0-9_:.]*)(\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'`=<>]+)))?/g;
  let m;
  while ((m = re.exec(fragment)) !== null) {
    const k = m[1].toLowerCase();
    let v = '';
    if (m[4] !== undefined) v = m[4];
    else if (m[5] !== undefined) v = m[5];
    else if (m[6] !== undefined) v = m[6].replace(/\/+$/, '');
    if (!(k in a)) a[k] = decode(v);
  }
  return a;
}

function isDecoy(a) {
  if ('disabled' in a) return true;
  if ('data-decoy' in a || 'decoy' in a) return true;
  const cls = String(a['class'] || '').toLowerCase();
  const id = String(a.id || '').toLowerCase();
  if (cls.indexOf('decoy') >= 0 || id.indexOf('decoy') >= 0) return true;
  const t = String(a.type || '').toLowerCase();
