// Layout tolerant hidden-field reader: attribute order/quoting/case agnostic,
// decoys and commented/template markup ignored, real form preferred.
function pickToken(markup, name, actionHint) {
  if (!markup) return '';
  const clean = String(markup)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<template\b[\s\S]*?<\/template>/gi, ' ');

