  for (let i = 0; i < forms.length; i++) scopes.push(forms[i].inner);
  scopes.push(clean);

  for (let s = 0; s < scopes.length; s++) {
    const inputRe = /<input\b([^>]*)>/gi;
    let t;
    const hidden = [];
    const other = [];
    while ((t = inputRe.exec(scopes[s])) !== null) {
      const a = attrsOf(t[1]);
      if (String(a.name || '').trim().toLowerCase() !== name) continue;
      if (isDecoy(a)) continue;
      const v = String(a.value || '').trim();
      if (!v) continue;
      if (String(a.type || '').toLowerCase() === 'hidden') hidden.push(v);
      else other.push(v);
    }
    if (hidden.length) return hidden[0];
    if (other.length) return other[0];
  }
  return '';
}

