  if (/^https?:\/\//i.test(path)) return path;
  return BASE + (path.charAt(0) === '/' ? path : '/' + path);
}

function allowed(path) {
  return path.charAt(0) === '/' || path.indexOf(BASE + '/') === 0 || path === BASE;
