    {"username": "bench-16", "password": "bench", "quantity": 17},
]

STATE = {'lock': Semaphore(), 'allocated': 0, 'done': 0}

TAG_RE = re.compile(r'<input\b[^>]*>', re.IGNORECASE | re.DOTALL)
FORM_RE = re.compile(r'<form\b[^>]*>', re.IGNORECASE | re.DOTALL)
ATTR_RE = re.compile(
    r'([A-Za-z_:][-A-Za-z0-9_:.]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))')


def attrs_of(tag):
    found = {}
    for match in ATTR_RE.finditer(tag):
        key = match.group(1).lower()
        value = match.group(2)
        if value is None:
            value = match.group(3)
        if value is None:
            value = match.group(4) or ''
        if key not in found:
            found[key] = html.unescape(value)
    return found


def input_value(markup, field):
    candidates = []
    for tag in TAG_RE.findall(markup or ''):
        attrs = attrs_of(tag)
        if attrs.get('name') != field:
            continue
        if 'disabled' in attrs:
            continue
        if (attrs.get('type') or '').lower() in ('submit', 'button', 'reset'):
            continue
        if not attrs.get('value'):
            continue
        candidates.append(attrs)
    if not candidates:
        return ''
    hidden = [a for a in candidates if (a.get('type') or '').lower() == 'hidden']
    return (hidden or candidates)[0]['value']


def form_action(markup, prefix):
    for tag in FORM_RE.findall(markup or ''):
        action = attrs_of(tag).get('action', '')
        if action.startswith(prefix):
            return action
    return ''


def pick_product(body):
    products = (body.get('data') or {}).get('products') or []
    for product in products:
        for variant in product.get('variants') or []:
            if variant.get('in_stock') and product.get('id') and variant.get('id'):
                return product, variant
    return None


class MatrixUser(HttpUser):
    wait_time = lambda self: 0

    def on_start(self):
        with STATE['lock']:
            if STATE['allocated'] < USERS:
                self.slot = STATE['allocated']
                STATE['allocated'] += 1
            else:
                self.slot = None
        if self.slot is None:
            self.username = 'bench-1'
            self.quantity = 2
        else:
            self.row = ROWS[self.slot % len(ROWS)]
            self.username = 'bench-%d' % (self.slot % 16 + 1)
            self.quantity = int(self.row.get('quantity', 2))
        self.password = 'bench'
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.iteration = 0

    def raw(self, path, method='GET', data=None, headers=None, name=None, check=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name or path.split('?', 1)[0],
                                 catch_response=True, allow_redirects=False,
                                 timeout=10) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}
            status = response.status_code
            error = body.get('error')
            allowed = status < 400
            if status == 401 and error in ('expired', 'session'):
                allowed = True
            elif status == 412:
                allowed = True
            elif status == 429 and path.split('?', 1)[0] in ('/v2/work', '/v2/browse'):
                allowed = True
            if (method == 'POST' and path.split('?', 1)[0] == '/v2/orders'
                    and status < 400 and body.get('accepted') is not True):
                allowed = False
            problem = None if allowed else 'unexpected status %s error=%s' % (status, error)
            if problem is None and check is not None:
                problem = check(response, body)
            if problem:
                response.failure(problem)
            else:
                response.success()
            if body.get('csrf'):
                self.csrf = body['csrf']
            return response, body

