        self.client.cookies.clear()
        self.csrf = ''
        holder = {'token': ''}

        def check_form(response, body):
            if response.status_code != 200:
                return 'login-form status %s' % response.status_code
            holder['token'] = input_value(response.text, 'csrf')
            if not holder['token']:
                return 'login-form csrf input missing'
            return None

        self.raw('/v2/login-form', check=check_form)
        if not holder['token']:
            return False

        def check_login(response, body):
            if response.status_code == 302:
                if not response.headers.get('Location'):
                    return 'login redirect without Location'
                return None
            if response.status_code != 200:
                return 'login status %s' % response.status_code
            if not body.get('csrf') or not body.get('user'):
                return 'login did not establish session'
            return None

        response, body = self.raw('/v2/login', 'POST',
                                  {'username': self.username,
                                   'password': self.password,
                                   'csrf': holder['token']},
                                  check=check_login)
        if response.status_code == 302:
            location = response.headers.get('Location')
            if not location:
                return False

            def check_landing(resp, payload):
                if resp.status_code != 200:
                    return 'login landing status %s' % resp.status_code
                if not payload.get('csrf'):
                    return 'login landing missing csrf'
                return None

            self.raw(location, check=check_landing)
        return bool(self.csrf)

    def recover(self, kind):
        renewed = False
        if kind == 'expired':
            response, _ = self.raw('/v2/session/renew', 'POST', {})
            renewed = response.status_code == 200 and bool(self.csrf)
        if not renewed:
            if not self.login():
                return False
        if self.cart:
            response, _ = self.raw('/v2/carts/' + self.cart + '/recover', 'POST', {})
            if response.status_code >= 400:
                return False
            self.etag = response.headers.get('ETag', self.etag)
        return True

    def request(self, path, method='GET', data=None, headers=None, name=None, check=None):
        response, body = self.raw(path, method, data, headers, name, check)
        if response.status_code == 401 and body.get('error') in ('expired', 'session'):
            if self.recover(body.get('error')):
                response, body = self.raw(path, method, data, headers, name, check)
        return response, body

    def read_etag(self):
        def check(response, body):
            if response.status_code != 200:
                return 'cart read status %s' % response.status_code
            if not response.headers.get('ETag'):
                return 'cart read missing ETag'
            return None

        response, _ = self.request('/v2/carts/' + self.cart, check=check)
        self.etag = response.headers.get('ETag', self.etag)
        return response.status_code == 200 and bool(self.etag)

    def patch_cart(self):
        payload = {'quantity': self.quantity}
        if not self.etag and not self.read_etag():
            return False

        def check(response, body):
            if response.status_code == 412:
                return None
            if response.status_code >= 400:
                return 'cart patch status %s' % response.status_code
            return None

        response, _ = self.request('/v2/carts/' + self.cart, 'PATCH', payload,
                                   {'If-Match': self.etag}, check=check)
        if response.status_code == 412:
            if not self.read_etag():
                return False

            def check_retry(resp, body):
                if resp.status_code >= 400:
                    return 'cart patch retry status %s' % resp.status_code
                return None

            response, _ = self.request('/v2/carts/' + self.cart, 'PATCH', payload,
                                       {'If-Match': self.etag}, check=check_retry)
        self.etag = response.headers.get('ETag', self.etag)
        return response.status_code < 400

    def checkout(self):
        key = 'order-%s' % self.cart
        payload = {'cart_id': self.cart}
        if not self.etag and not self.read_etag():
            return False

        def check(response, body):
            if response.status_code == 412:
                return None
            if response.status_code != 201 or body.get('accepted') is not True:
                return 'order not accepted (%s)' % response.status_code
            if not body.get('id'):
                return 'order missing id'
            return None

        response, _ = self.request('/v2/orders', 'POST', payload,
                                   {'Idempotency-Key': key, 'If-Match': self.etag},
                                   'checkout', check)
        if response.status_code == 412:
            if not self.read_etag():
                return False
            response, _ = self.request('/v2/orders', 'POST', payload,
                                       {'Idempotency-Key': key, 'If-Match': self.etag},
                                       'checkout', check)
        self.etag = response.headers.get('ETag', self.etag)
        return response.status_code == 201

    def flow(self):
        self.cart = ''
        self.etag = ''
        if not self.login():
            return
        holder = {'choice': None}

        def check_catalog(response, body):
            if response.status_code != 200:
                return 'catalog status %s' % response.status_code
            holder['choice'] = pick_product(body)
            if holder['choice'] is None:
                return 'no in-stock variant in catalog'
            return None

        self.request('/v2/catalog', check=check_catalog)
        if holder['choice'] is None:
            return
        product, variant = holder['choice']

        def check_cart(response, body):
            if response.status_code != 201 or not body.get('id'):
                return 'cart creation failed (%s)' % response.status_code
            return None

        response, body = self.request('/v2/carts', 'POST',
                                      {'product_id': product['id'],
                                       'variant_id': variant['id']},
                                      check=check_cart)
        if response.status_code != 201 or not body.get('id'):
            return
        self.cart = body['id']
        self.etag = response.headers.get('ETag', '')
        if not self.patch_cart():
            self.cart = ''
            return
        self.checkout()
        self.cart = ''
        self.etag = ''

    @task
    def run_scenario(self):
        if self.slot is None:
            raise StopUser()
        self.flow()
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            with STATE['lock']:
                STATE['done'] += 1
            raise StopUser()


class MatrixShape(LoadTestShape):
    def tick(self):
        with STATE['lock']:
            done = STATE['done']
        if done >= USERS:
            return None
        if self.get_run_time() > 180:
            return None
        return (USERS, max(1, USERS))
