import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final int USERS = 2;
    private static final int ITERATIONS = 2;
    private static final Duration EXPIRY_WAIT = Duration.ofMillis(2200);
    private static final ObjectMapper JSON = new ObjectMapper();

    private static final Pattern COMMENT = Pattern.compile("(?s)<!--.*?-->");
    private static final Pattern TEMPLATE = Pattern.compile("(?is)<template\\b.*?</template\\s*>");
    private static final Pattern INPUT = Pattern.compile("(?is)<input\\b([^>]*)>");
    private static final Pattern ATTRIBUTE = Pattern.compile(
        "(?is)([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`]+)))?");

    private static String baseUrl() {
        String url = System.getenv("BASE_URL");
        return url == null || url.isEmpty() ? "http://127.0.0.1:8000" : url;
    }

    private static final HttpProtocolBuilder HTTP = http.baseUrl(baseUrl())
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static Map<String, String> attributes(String tag) {
        Map<String, String> out = new LinkedHashMap<>();
        Matcher matcher = ATTRIBUTE.matcher(tag);
        while (matcher.find()) {
            String key = matcher.group(1).toLowerCase(Locale.ROOT);
            String value = matcher.group(2);
            if (value == null) value = matcher.group(3);
            if (value == null) value = matcher.group(4);
            if (value == null) value = "";
            if (!out.containsKey(key)) out.put(key, value);
        }
        return out;
    }

    private static String inputToken(String html, String field) {
        if (html == null || html.isEmpty()) return "";
        String clean = TEMPLATE.matcher(COMMENT.matcher(html).replaceAll(" ")).replaceAll(" ");
        Matcher tags = INPUT.matcher(clean);
        String fallback = "";
        while (tags.find()) {
            Map<String, String> attrs = attributes(tags.group(1));
            String name = attrs.get("name");
            if (name == null || !name.trim().equalsIgnoreCase(field)) continue;
            if (attrs.containsKey("disabled")) continue;
            String value = attrs.get("value");
            if (value == null || value.isEmpty()) continue;
            String type = attrs.get("type") == null ? "" : attrs.get("type").toLowerCase(Locale.ROOT);
            if (type.equals("hidden")) return value;
            if (type.equals("submit") || type.equals("button") || type.equals("reset")) continue;
            if (fallback.isEmpty()) fallback = value;
        }
        return fallback;
    }

    private static String username(Session session) {
        long index = ((session.userId() - 1) % 16) + 1;
        return "bench-" + index;
    }

    private static String loginBody(Session session) {
        return JSON.createObjectNode()
            .put("username", username(session))
            .put("password", "bench")
            .put("csrf", session.contains("formCsrf") ? session.getString("formCsrf") : "")
            .toString();
    }

    private static String cartBody(Session session) {
        com.fasterxml.jackson.databind.node.ObjectNode node = JSON.createObjectNode()
            .put("product_id", session.contains("product") ? session.getString("product") : "")
            .put("variant_id", session.contains("variant") ? session.getString("variant") : "");
        if (session.contains("grant") && !session.getString("grant").isEmpty()) {
            node.put("grant_id", session.getString("grant"));
        }
        return node.toString();
    }

    private static String orderBody(Session session) {
        return JSON.createObjectNode()
            .put("cart_id", session.contains("cart") ? session.getString("cart") : "")
            .toString();
    }

    private static boolean statusIs(Session session, String key, int code) {
        return session.contains(key) && session.getInt(key) == code;
    }

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "")
                .remove("formCsrf").remove("location").remove("loginHtml"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginHtml")))
            .exec(session -> session.set("formCsrf",
                inputToken(session.contains("loginHtml") ? session.getString("loginHtml") : "", "csrf")))
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(ModelSimulation::loginBody))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .check(status().in(200, 204), jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(session -> session.remove("location"))));
    }

    private static ChainBuilder relogin() {
        return exec(flushCookieJar()).exec(login());
    }

    private static ChainBuilder refreshSession() {
        return exec(session -> session.remove("renewStatus"))
            .exec(http("renew").post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().saveAs("renewStatus"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    status().in(200, 401)))
            .exec(doIf(session -> !statusIs(session, "renewStatus", 200)).then(relogin()));
    }

    private static ChainBuilder recoverCart() {
        return doIf(session -> session.contains("cart")).then(
            exec(http("cart recover").post("/v2/carts/#{cart}/recover")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 201),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("cart state").get("/v2/carts/#{cart}")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf"))));
    }

    private static Session selectProduct(Session session) {
        if (!session.contains("catalogBody")) return session;
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException error) {
            return session;
        }
        return session;
    }

    private static ChainBuilder catalogStep() {
        return exec(session -> session.remove("catalogStatus"))
            .exec(http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().saveAs("catalogStatus"),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    status().in(200, 401),
                    jsonPath("$.error").optional().not("denied")))
            .exitHereIfFailed()
            .exec(doIf(session -> statusIs(session, "catalogStatus", 401)).then(
                refreshSession()
                .exec(http("catalog retry").get("/v2/catalog")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200),
                        bodyString().saveAs("catalogBody"),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.error").optional().not("denied")))))
            .exitHereIfFailed()
            .exec(ModelSimulation::selectProduct);
    }

    private static ChainBuilder cartStep() {
        return exec(session -> session.remove("cartStatus"))
            .exec(http("cart create").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(ModelSimulation::cartBody))
                .check(status().saveAs("cartStatus"),
                    jsonPath("$.id").optional().saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    status().in(200, 201, 401),
                    jsonPath("$.error").optional().not("denied")))
            .exitHereIfFailed()
            .exec(doIf(session -> statusIs(session, "cartStatus", 401)).then(
                refreshSession()
                .exec(http("cart create retry").post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(ModelSimulation::cartBody))
                    .check(status().in(200, 201),
                        jsonPath("$.id").saveAs("cart"),
                        header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.error").optional().not("denied")))))
            .exitHereIfFailed()
            .exec(doIf(session -> session.contains("cart") && !session.contains("etag")).then(
                exec(http("cart etag").get("/v2/carts/#{cart}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().is(200), header("ETag").optional().saveAs("etag")))))
            .exec(session -> session.contains("etag") ? session : session.set("etag", "*"));
    }

    private static ChainBuilder checkout() {
        return exec(session -> session.remove("orderStatus").remove("orderError"))
            .exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "ord-#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(ModelSimulation::orderBody))
                .check(status().saveAs("orderStatus"),
                    jsonPath("$.error").optional().saveAs("orderError"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    status().in(201, 401),
                    jsonPath("$.error").optional().not("denied"),
                    jsonPath("$.accepted").optional().is("true")))
            .exitHereIfFailed()
            .exec(doIf(session -> statusIs(session, "orderStatus", 401)).then(
                refreshSession()
                .exec(recoverCart())
                .exec(http("commit retry").post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("Idempotency-Key", "ord-#{cart}")
                    .header("If-Match", "#{etag}")
                    .body(StringBody(ModelSimulation::orderBody))
                    .check(status().is(201),
                        jsonPath("$.accepted").is("true"),
                        jsonPath("$.error").optional().not("denied"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(session -> session.remove("cart").remove("etag")
                .remove("product").remove("variant").remove("grant")
                .remove("catalogBody").remove("catalogStatus").remove("cartStatus")
                .remove("orderStatus").remove("orderError").remove("renewStatus"))
            .exec(login())
            .exitHereIfFailed()
            .exec(catalogStep())
            .exec(cartStep())
            .pause(EXPIRY_WAIT)
            .exec(checkout());
    }

    public ModelSimulation() {
        setUp(scenario("denial").exec(repeat(ITERATIONS).on(journey()))
            .injectOpen(atOnceUsers(USERS)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}

