  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 }
];
const failure = new Rate('business_failure');
const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: { executor: 'per-vu-iterations', vus: cfg.users, iterations: cfg.iterations, maxDuration: '60s' }
  },
  thresholds: { checks: ['rate==1'] }
};

let csrf = '';
let cart = '';
let grant = '';
let etag = '';

function url(path) {
  if (/^https?:\/\//i.test(path)) return path;
  return BASE + (path.charAt(0) === '/' ? path : '/' + path);
}
function body(r) {
  try { const b = r.json(); return b && typeof b === 'object' ? b : {}; } catch (_) { return {}; }
}
function header(r, name) {
