import os
import re

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')
CFG = {'users': 2, 'iterations': 2, 'mode': 'denial'}
USERS = max(1, int(CFG.get('users', 2)))
ITERATIONS = max(1, int(CFG.get('iterations', 2)))
TOTAL_JOURNEYS = USERS * ITERATIONS
EXPIRE_AFTER = 2
PASSWORD = 'bench'
QUANTITY = 2

STATE = {'lock': Semaphore(), 'seq': 0, 'claimed': 0, 'done': 0}

COMMENT_RE = re.compile(r'<!--.*?-->', re.DOTALL)
INPUT_RE = re.compile(r'<input\b[^>]*>', re.IGNORECASE)
META_RE = re.compile(r'<meta\b[^>]*>', re.IGNORECASE)
ATTR_RE = re.compile(
    r'''([A-Za-z_:][-A-Za-z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))''')
QUOTED_RE = re.compile(r'"[^"]*"|\'[^\']*\'')
BAD_TYPES = ('submit', 'button', 'reset', 'image', 'checkbox', 'radio')
DECOY_WORDS = ('decoy', 'dummy', 'fake', 'placeholder-token')


def parse_attrs(tag):
    attrs = {}
    for match in ATTR_RE.finditer(tag):
        key = match.group(1).lower()
        value = match.group(2)
        if value is None:
            value = match.group(3)
        if value is None:
            value = match.group(4) or ''
        if key not in attrs:
            attrs[key] = value
    return attrs


def response_text(response):
    try:
        return getattr(response, 'text', '') or ''
    except Exception:
        return ''


def extract_csrf(html):
    html = COMMENT_RE.sub(' ', html or '')
    for tag in INPUT_RE.findall(html):
        attrs = parse_attrs(tag)
        if attrs.get('name', '').strip().lower() != 'csrf':
            continue
        if attrs.get('type', '').strip().lower() in BAD_TYPES:
            continue
        bare = QUOTED_RE.sub(' ', tag)
        if re.search(r'\bdisabled\b', bare, re.IGNORECASE):
            continue
        blob = ' '.join(k + '=' + v for k, v in attrs.items()).lower()
        if any(word in blob for word in DECOY_WORDS):
            continue
        value = attrs.get('value', '').strip()
        if value:
            return value
    for tag in META_RE.findall(html):
        attrs = parse_attrs(tag)
        if attrs.get('name', '').strip().lower() == 'csrf':
            value = (attrs.get('content') or attrs.get('value') or '').strip()
            if value and not any(word in value.lower() for word in DECOY_WORDS):
                return value
    return ''


def safe_json(response):
    try:
        body = response.json()
    except Exception:
        return {}
    return body if isinstance(body, dict) else {}


def header(response, key):
    try:
        return response.headers.get(key)
    except Exception:
        return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        with STATE['lock']:
            index = STATE['seq']
            STATE['seq'] += 1
        self.username = 'bench-%d' % (index % USERS + 1)
        self.password = PASSWORD
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    # ---- single native sample per raw HTTP call -------------------------
    def raw(self, path, method='GET', data=None, headers=None, name=None,
            expiry_ok=True, extra_ok=(), check=None):
        request_headers = {'Content-Type': 'application/json', 'Accept': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        label = name or path
