                                 name=label, catch_response=True,
                                 allow_redirects=False, timeout=15) as response:
            body = safe_json(response)
            if body.get('csrf'):
                self.csrf = body['csrf']
            code = response.status_code or 0
            error = body.get('error')
            problem = None
            if code == 401 and error in ('expired', 'session') and expiry_ok:
                problem = None                      # expected expiry, caller recovers
            elif code == 429 and header(response, 'Retry-After'):
                problem = None                      # scheduled throttle, caller retries
            elif code in extra_ok:
                problem = None
            elif code < 200 or code >= 400:
                problem = 'HTTP %s %s' % (code, error or response_text(response)[:120])
            if problem is None and method == 'POST' and path.split('?', 1)[0] == '/v2/orders':
                if code < 400 and body.get('accepted') is not True:
                    problem = 'order not accepted: %s' % (body or error or code,)
            if problem is None and check is not None:
                problem = check(response, body)
            if problem:
                response.failure('%s %s: %s' % (method, label, problem))
            else:
                response.success()
            return response, body

    # ---- session handling ----------------------------------------------
    def login(self):
        self.client.cookies.clear()
        self.csrf = ''
        self.grant = ''
        holder = {}

        def form_check(response, body):
            token = extract_csrf(response_text(response))
            if not token:
                return 'login form has no usable csrf input'
            holder['token'] = token
            return None

        self.raw('/v2/login-form', name='login_form', check=form_check)
        token = holder.get('token')
        if not token:
            return False

        def login_check(response, body):
            if (response.status_code or 0) in (301, 302, 303, 307, 308):
                return None if header(response, 'Location') else 'login redirect without Location'
            return None if body.get('csrf') else 'login response missing csrf'

        response, body = self.raw(
            '/v2/login', 'POST',
            {'username': self.username, 'password': self.password, 'csrf': token},
            name='login', check=login_check)
        if (response.status_code or 0) in (301, 302, 303, 307, 308):
            location = header(response, 'Location')
            if not location:
                return False
            response, body = self.raw(
                location, name='login_redirect',
                check=lambda r, b: None if b.get('csrf') else 'login landing missing csrf')
        if (response.status_code or 0) >= 400 or not self.csrf:
            return False
        if body.get('grant_id'):
            self.grant = body['grant_id']
        return True

    def restore(self, error):
        ok = True
        if error == 'expired':
            response, _ = self.raw('/v2/session/renew', 'POST', {}, name='session_renew')
            if (response.status_code or 0) != 200:
                ok = self.login()
        else:
            ok = self.login()
        if self.cart:
            response, _ = self.raw('/v2/carts/%s/recover' % self.cart, 'POST', {},
                                   name='cart_recover')
            etag = header(response, 'ETag')
            if etag:
                self.etag = etag
            if (response.status_code or 0) >= 400 or (response.status_code or 0) == 0:
                ok = False
        return bool(ok and self.csrf)

    # ---- bounded per-operation recovery --------------------------------
    def call(self, path, method='GET', data=None, headers=None, name=None,
             extra_ok=(), check=None):
        hdrs = dict(headers or {})
        response, body = self.raw(path, method, data, hdrs, name,
                                  extra_ok=extra_ok, check=check)
        for _ in range(4):
            if (response.status_code or 0) != 429:
                break
            retry_after = header(response, 'Retry-After')
            if not retry_after:
                break
            try:
                delay = float(retry_after)
            except (TypeError, ValueError):
                delay = 1.0
            sleep(max(1.0, delay))
            response, body = self.raw(path, method, data, hdrs, name,
                                      extra_ok=extra_ok, check=check)
        error = body.get('error')
        if (response.status_code or 0) == 401 and error in ('expired', 'session'):
            if self.restore(error):
                if 'If-Match' in hdrs and self.etag:
                    hdrs['If-Match'] = self.etag
                response, body = self.raw(path, method, data, hdrs, name,
                                          expiry_ok=False, extra_ok=extra_ok, check=check)
        return response, body

    # ---- catalogue ------------------------------------------------------
    def pick_product(self):
        path = '/v2/catalog'
        for _ in range(3):
            response, body = self.call(path, name='catalog')
            if (response.status_code or 0) >= 400:
                return None, None
            products = ((body.get('data') or {}).get('products')) or []
            for item in products:
                for variant in (item.get('variants') or []):
                    if variant.get('in_stock') and item.get('id') and variant.get('id'):
                        return item, variant
            nxt = body.get('next')
            if not nxt:
                break
            path = nxt
        self.raw('/v2/catalog', name='catalog_assert',
                 check=lambda r, b: 'no in-stock product reachable in catalogue')
        return None, None

    # ---- one journey = one login, one cart, one committed order ---------
    def journey(self):
        self.cart = ''
        self.etag = ''
        self.grant = ''
        if not self.login():
            return
        product, variant = self.pick_product()
        if not product:
            return
        payload = {'product_id': product['id'], 'variant_id': variant['id']}
        if self.grant:
            payload['grant_id'] = self.grant
        response, body = self.call(
            '/v2/carts', 'POST', payload, name='cart_create',
            check=lambda r, b: None if (r.status_code or 0) >= 400 or b.get('id')
            else 'cart creation returned no id')
        if (response.status_code or 0) not in (200, 201):
            return
        self.cart = body.get('id') or ''
        if not self.cart:
            return
        self.etag = header(response, 'ETag') or self.etag

        # let the configured session lifetime lapse so expiry recovery is exercised
        sleep(EXPIRE_AFTER + 0.15)

        cart_path = '/v2/carts/%s' % self.cart
        response, body = self.call(cart_path, 'PATCH', {'quantity': QUANTITY},
                                   {'If-Match': self.etag} if self.etag else None,
                                   name='cart_patch', extra_ok=(412,))
        if (response.status_code or 0) == 412:
            read, _ = self.call(cart_path, name='cart_read')
            self.etag = header(read, 'ETag') or self.etag
            response, body = self.call(cart_path, 'PATCH', {'quantity': QUANTITY},
                                       {'If-Match': self.etag} if self.etag else None,
                                       name='cart_patch_retry')
        if (response.status_code or 0) >= 400 or (response.status_code or 0) == 0:
            return
        self.etag = header(response, 'ETag') or self.etag

        order_headers = {'Idempotency-Key': self.cart}
        if self.etag:
            order_headers['If-Match'] = self.etag
        response, body = self.call('/v2/orders', 'POST', {'cart_id': self.cart},
                                   order_headers, name='checkout')
        if (response.status_code or 0) in (200, 201) and body.get('accepted') is True:
            self.cart = ''
            self.etag = ''

    @task
    def run_scenario(self):
        with STATE['lock']:
            exhausted = STATE['claimed'] >= TOTAL_JOURNEYS
            if not exhausted:
                STATE['claimed'] += 1
        if exhausted:
            raise StopUser()
        try:
            self.journey()
        finally:
            with STATE['lock']:
                STATE['done'] += 1
            self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        with STATE['lock']:
            done = STATE['done']
        if done >= TOTAL_JOURNEYS:
            return None
        if self.get_run_time() > 180:
            return None
        return (USERS, max(1, USERS))
