import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    // Execution contract: {"users": 2, "iterations": 2, "mode": "decline"}
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;

    private static final ObjectMapper JSON = new ObjectMapper();

    private static final Pattern INPUT_TAG =
        Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern CSRF_NAME =
        Pattern.compile("(?is)(?:^|\\s)name\\s*=\\s*(?:\"csrf\"|'csrf'|csrf(?=[\\s/>]))");
    private static final Pattern VALUE_ATTR =
        Pattern.compile("(?is)(?:^|\\s)value\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s/>]+))");
    private static final Pattern DISABLED_ATTR =
        Pattern.compile("(?is)(?:^|\\s)disabled(?:[\\s=/>]|$)");

    private static String baseUrl() {
        String env = System.getenv("BASE_URL");
        return env == null || env.trim().isEmpty() ? "http://127.0.0.1:8000" : env.trim();
    }

    private static final HttpProtocolBuilder HTTP = http.baseUrl(baseUrl())
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    /** Never throws on a missing attribute: keeps failures as failed samples, not crashes. */
    private static String str(Session session, String key) {
        if (!session.contains(key)) return "";
        String value = session.getString(key);
        return value == null ? "" : value;
    }

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    /** Attribute-order / quote / layout tolerant extraction of the real csrf input. */
    private static String csrfFromHtml(String html) {
        if (html == null || html.isEmpty()) return null;
        Matcher tags = INPUT_TAG.matcher(html);
        while (tags.find()) {
            String tag = tags.group();
            if (!CSRF_NAME.matcher(tag).find()) continue;
            if (DISABLED_ATTR.matcher(tag).find()) continue;
            Matcher value = VALUE_ATTR.matcher(tag);
            if (!value.find()) continue;
            String extracted = value.group(1) != null ? value.group(1)
                : value.group(2) != null ? value.group(2) : value.group(3);
            if (extracted != null && !extracted.isEmpty()) return extracted;
        }
        return null;
    }

    private static ChainBuilder login() {
        return exec(session -> session
                .remove("csrf").remove("formCsrf").remove("loginHtml").remove("location")
                .remove("catalogBody").remove("product").remove("variant")
                .remove("cart").remove("etag").remove("orderId").remove("grant"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginHtml")))
            .exec(session -> {
                String csrf = csrfFromHtml(str(session, "loginHtml"));
                return csrf == null ? session : session.set("formCsrf", csrf);
            })
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + str(session, "formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .check(status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.grant_id").optional().saveAs("grant")))));
    }

    private static Session selectProduct(Session session) {
        String body = str(session, "catalogBody");
        if (body.isEmpty()) return session;
        try {
            JsonNode products = JSON.readTree(body).path("data").path("products");
            for (JsonNode product : products) {
                String productId = product.path("id").asText("");
                if (productId.isEmpty()) continue;
                for (JsonNode variant : product.path("variants")) {
                    if (!variant.path("in_stock").asBoolean(false)) continue;
                    String variantId = variant.path("id").asText("");
                    if (variantId.isEmpty()) continue;
                    return session.set("product", productId).set("variant", variantId);
                }
            }
        } catch (Exception error) {
            return session;
        }
        return session;
    }

    private static ChainBuilder flow() {
        return exec(flushCookieJar())
            .exec(login())
            .exec(http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(session -> selectProduct(session))
            .exec(doIf(session -> session.contains("product") && session.contains("variant")).then(
                exec(http("cart").post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session -> {
                        StringBuilder body = new StringBuilder("{\"product_id\":\"")
                            .append(str(session, "product"))
                            .append("\",\"variant_id\":\"")
                            .append(str(session, "variant")).append("\"");
                        String grant = str(session, "grant");
                        if (!grant.isEmpty()) body.append(",\"grant_id\":\"").append(grant).append("\"");
                        return body.append("}").toString();
