import os
from html.parser import HTMLParser

from gevent import sleep
from gevent.lock import Semaphore

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {"users": 2, "iterations": 2, "mode": "decline"}
BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ACCOUNTS = ["bench-%d" % index for index in range(1, 17)]
PASSWORD = "bench"

_ACCOUNT_LOCK = Semaphore()
_ACCOUNT_STATE = {"next": 0}


def next_account():
    with _ACCOUNT_LOCK:
        index = _ACCOUNT_STATE["next"]
        _ACCOUNT_STATE["next"] = index + 1
    return ACCOUNTS[index % len(ACCOUNTS)]


class InputFinder(HTMLParser):
    """Attribute-order independent <input name=...> value extraction."""

    def __init__(self, wanted):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.wanted = wanted
        self.candidates = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        fields = {}
        for key, value in attrs:
            fields[key.lower()] = value if value is not None else ""
        if fields.get("name") != self.wanted:
            return
        if "disabled" in fields:
            return
        self.candidates.append((fields.get("type", "").lower(), fields.get("value", "")))


def input_value(markup, wanted):
    parser = InputFinder(wanted)
    try:
        parser.feed(markup or "")
        parser.close()
    except Exception:
        pass
    hidden = [value for kind, value in parser.candidates if kind == "hidden" and value]
    if hidden:
        return hidden[0]
    other = [value for _kind, value in parser.candidates if value]
    return other[0] if other else ""


class ShopUser(HttpUser):
    host = BASE_URL
    abstract = False

    def wait_time(self):
        return 0

    def on_start(self):
        self.username = next_account()
        self.password = PASSWORD
        self.quantity = 2
        self.csrf = ""
        self.login_token = ""
        self.cart_id = ""
        self.etag = ""
        self.declined = False
        self.iteration = 0
        self._pick = None

    # ---------------- transport with truthful sample classification ----------------

    def raw(self, method, path, payload=None, headers=None, name=None, check=None):
        request_headers = {"Accept": "application/json"}
        if payload is not None:
            request_headers["Content-Type"] = "application/json"
        if self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})
        endpoint = path.split("?", 1)[0]
        with self.client.request(
            method,
            path,
            json=payload,
            headers=request_headers,
            name=name or path,
            catch_response=True,
            allow_redirects=False,
            timeout=10,
        ) as response:
            body = {}
            try:
                parsed = response.json()
            except Exception:
                parsed = None
            if isinstance(parsed, dict):
                body = parsed

            status = response.status_code
            error = body.get("error")
            problem = None

            if status in (200, 201, 202, 302):
                problem = None
            elif status == 401 and error in ("expired", "session"):
                problem = None  # handled by bounded recovery
            elif status == 412:
                problem = None  # handled by one If-Match retry
            elif status == 429 and endpoint in ("/v2/work", "/v2/browse"):
                problem = None  # scheduled backoff
            else:
                problem = "unexpected HTTP %s (error=%s)" % (status, error)

            if status == 401 and error == "denied":
                problem = "access denied (error=denied), not an expiry"

            # Business outcome, not just transport status: HTTP 200 accepted:false
            # is a declined transaction and must fail the checkout assertion.
            if endpoint == "/v2/orders" and status in (200, 201):
                if body.get("accepted") is not True:
                    self.declined = True
                    problem = "checkout declined: HTTP %s accepted=%r error=%s" % (
                        status,
                        body.get("accepted"),
                        body.get("error"),
                    )
                elif not body.get("id"):
                    problem = "checkout accepted without order id"

            if check is not None:
                extra = check(response, body)
                if extra:
                    problem = extra

            fresh = body.get("csrf")
            if fresh:
                self.csrf = fresh

            if problem:
                response.failure(problem)
            else:
                response.success()
            return response, body

    def call(self, method, path, payload=None, headers=None, name=None, check=None):
        response, body = self.raw(method, path, payload, headers, name, check)
        if response.status_code == 401 and body.get("error") in ("expired", "session"):
            self.recover()
            response, body = self.raw(method, path, payload, headers, name, check)
        return response, body

    # ---------------- session ----------------

    def login(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.login_token = ""

        def form_check(response, _body):
            self.login_token = input_value(response.text, "csrf")
            return None if self.login_token else "login form: no csrf input value found"

        response, _body = self.call("GET", "/v2/login-form", name="/v2/login-form",
                                    check=form_check)
        if response.status_code != 200 or not self.login_token:
            return False

        def login_check(resp, body):
            if resp.status_code == 302:
                return None if resp.headers.get("Location") else "login 302 without Location"
            if resp.status_code == 200:
                return None if (body.get("csrf") or body.get("user")) else "login body missing csrf/user"
            return None

        response, body = self.call(
            "POST",
            "/v2/login",
            {"username": self.username, "password": self.password, "csrf": self.login_token},
            name="/v2/login",
            check=login_check,
        )
        if response.status_code == 302:
            location = response.headers.get("Location")
            if location:
                self.call("GET", location, name="/v2/login (redirect)")
        return response.status_code in (200, 302)

    def recover(self):
        response, _body = self.raw("POST", "/v2/session/renew", {}, name="/v2/session/renew")
        if response.status_code != 200:
            self.login()
        if self.cart_id:
            resp, _body = self.raw(
                "POST", "/v2/carts/%s/recover" % self.cart_id, {},
                name="/v2/carts/{id}/recover",
            )
            tag = resp.headers.get("ETag")
            if tag:
                self.etag = tag

    # ---------------- catalog / cart ----------------

    def browse(self):
        self._pick = None
        path = "/v2/catalog"
        for page_index in range(3):
            last_page = page_index == 2

            def catalog_check(response, body, last_page=last_page):
                if response.status_code != 200:
                    return None
                data = body.get("data") or {}
                products = data.get("products") or []
                for product in products:
                    for variant in product.get("variants") or []:
                        if variant.get("in_stock") and product.get("id") and variant.get("id"):
                            self._pick = (product, variant)
                            return None
                if self._pick is None and (last_page or not body.get("next")):
                    return "catalog: no in-stock product/variant reachable"
                return None

            response, body = self.call("GET", path, name="/v2/catalog", check=catalog_check)
            if self._pick:
                return self._pick
            following = body.get("next")
            if response.status_code != 200 or not following:
                break
            path = following
        return self._pick

    def refresh_etag(self):
        response, _body = self.call("GET", "/v2/carts/%s" % self.cart_id,
                                    name="/v2/carts/{id}")
        tag = response.headers.get("ETag")
        if tag:
            self.etag = tag

    def update_quantity(self):
        if not self.etag:
            self.refresh_etag()
        if not self.etag:
            return
        url = "/v2/carts/%s" % self.cart_id
        payload = {"quantity": self.quantity}
        response, _body = self.call("PATCH", url, payload, {"If-Match": self.etag},
                                    name="/v2/carts/{id}")
        if response.status_code == 412:
            self.refresh_etag()
            response, _body = self.call("PATCH", url, payload, {"If-Match": self.etag},
                                        name="/v2/carts/{id}")
        tag = response.headers.get("ETag")
        if tag:
            self.etag = tag

    def checkout(self):
        # Never check out an invalid/absent cart, and never re-drive a declined order.
        if not self.cart_id or self.declined:
            return
        payload = {"cart_id": self.cart_id}
        headers = {"Idempotency-Key": "order-%s" % self.cart_id}
        if self.etag:
            headers["If-Match"] = self.etag
        response, _body = self.call("POST", "/v2/orders", payload, headers,
                                    name="/v2/orders")
        if response.status_code == 412 and not self.declined:
            self.refresh_etag()
            headers["If-Match"] = self.etag
            self.call("POST", "/v2/orders", payload, headers, name="/v2/orders")

    def journey(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.cart_id = ""
        self.etag = ""
        self.declined = False
        self._pick = None

        if not self.login():
            return

        picked = self.browse()
        if not picked:
            return
        product, variant = picked

        def cart_check(response, body):
            if response.status_code == 201 and not body.get("id"):
                return "cart creation returned 201 without id"
            return None

        response, body = self.call(
            "POST",
            "/v2/carts",
            {"product_id": product["id"], "variant_id": variant["id"]},
            name="/v2/carts",
            check=cart_check,
        )
        if response.status_code != 201 or not body.get("id"):
            return
        self.cart_id = body["id"]
        self.etag = response.headers.get("ETag", "")

        self.update_quantity()
        self.checkout()

    @task
    def run_journey(self):
        if self.iteration >= CFG["iterations"]:
            raise StopUser()
        self.iteration += 1
        self.journey()
        if self.iteration >= CFG["iterations"]:
            raise StopUser()


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.spawned = False

    def tick(self):
        elapsed = self.get_run_time()
        if elapsed > 180:
            return None
        count = self.runner.user_count if self.runner is not None else 0
        if count > 0:
            self.spawned = True
        if self.spawned and count == 0:
            return None
        users = CFG["users"]
        return (users, max(1, users))
