import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const RATE = 5;
const USERS = [];
for (let i = 1; i <= 16; i++) USERS.push({ username: 'bench-' + i, password: 'bench' });

const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    work_pool: {
      executor: 'constant-arrival-rate',
      rate: RATE,
      timeUnit: '1s',
      duration: '38s',
      startTime: '0s',
      preAllocatedVUs: 16,
      maxVUs: 32,
      gracefulStop: '3s',
      exec: 'default',
    },
  },
  thresholds: {
    checks: ['rate>=0.99'],
    business_failure: ['rate<0.01'],
  },
  noCookiesReset: true,
};

let csrf = '';

function parse(r) {
  try {
    const b = r.json();
    return b && typeof b === 'object' ? b : {};
  } catch (_) {
    return {};
  }
}

function absolute(path) {
  if (/^https?:\/\//i.test(path)) return path;
  return BASE + (path.charAt(0) === '/' ? path : '/' + path);
}

function decode(s) {
  return String(s)
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

function attr(tag, key) {
  const re = new RegExp('(^|\\s)' + key + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s"\'>]+))', 'i');
  const m = re.exec(tag);
  if (!m) return '';
  if (m[3] !== undefined) return decode(m[3]);
  if (m[4] !== undefined) return decode(m[4]);
  return decode(m[5] || '');
}

function formToken(htmlText, name) {
  const text = String(htmlText || '').replace(/<!--[\s\S]*?-->/g, '');
  const tags = text.match(/<input\b[^>]*>/gi) || [];
  let fallback = '';
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];
    if (attr(tag, 'name') !== name) continue;
    if (/\bdisabled\b/i.test(tag)) continue;
    if (/decoy|bogus|fake|dummy/i.test(tag)) continue;
    const value = attr(tag, 'value');
    if (!value) continue;
    const type = attr(tag, 'type').toLowerCase();
    if (!type || type === 'hidden' || type === 'text') return value;
    if (!fallback) fallback = value;
  }
  return fallback;
}

function header(r, name) {
  const h = r.headers || {};
  return h[name] !== undefined ? h[name] : h[name.toLowerCase()];
}

function scoreWork(r, b) {
  const ok = r.status === 200 && b.ok === true;
  const expectedExpiry = r.status === 401 && (b.error === 'expired' || b.error === 'session');
  const scheduled = r.status === 429;
  failure.add(!ok && !expectedExpiry && !scheduled);
}

function raw(method, path, data, extra) {
  const headers = Object.assign({ 'Content-Type': 'application/json' }, extra || {});
  if (csrf) headers['X-CSRF-Token'] = csrf;
  const payload = data === null || data === undefined ? null : JSON.stringify(data);
  const r = http.request(method, absolute(path), payload, {
    headers: headers,
    redirects: 0,
    timeout: '10s',
  });
  const b = parse(r);
  if (b.csrf) csrf = b.csrf;
  if (path === '/v2/work') scoreWork(r, b);
  return r;
}

function login() {
  csrf = '';
  const row = USERS[(__VU - 1) % USERS.length];
  for (let attempt = 0; attempt < 2; attempt++) {
    const form = raw('GET', '/v2/login-form', null);
    const token = formToken(form.body, 'csrf');
    let r = raw('POST', '/v2/login', { username: row.username, password: row.password, csrf: token });
    if (r.status >= 300 && r.status < 400) {
      const loc = header(r, 'Location');
      if (loc) r = raw('GET', loc, null);
    }
    const b = parse(r);
    if (b.csrf) csrf = b.csrf;
    if (r.status === 200 && csrf) return true;
  }
  return false;
}

function work() {
  let r = raw('POST', '/v2/work', {});
  let throttles = 0;
  let recoveries = 0;
  for (;;) {
    if (r.status === 429 && throttles < 4) {
      const ra = Number(header(r, 'Retry-After'));
      sleep(Math.max(1, isFinite(ra) && ra > 0 ? ra : 1));
      throttles++;
      r = raw('POST', '/v2/work', {});
      continue;
    }
    if (r.status === 401 && recoveries < 1) {
      const b = parse(r);
      if (b.error === 'expired') {
        const renewed = raw('POST', '/v2/session/renew', {});
        if (renewed.status !== 200) login();
        recoveries++;
        r = raw('POST', '/v2/work', {});
        continue;
      }
      if (b.error === 'session') {
        login();
        recoveries++;
        r = raw('POST', '/v2/work', {});
        continue;
      }
    }
    break;
  }
  check(r, { 'work accepted': (x) => x.status === 200 && parse(x).ok === true });
}

export default function () {
  const ready = login();
  check(ready, { 'authenticated session': (v) => v === true });
  if (!ready) return;
  work();
}

