            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static int clampQuantity(int value) {
        if (value < 1) {
            return 1;
        }
        return value > 20 ? 20 : value;
    }

    /** One exclusive credential per (user, iteration) journey: fixture rows first, then free bench slots. */
    private static String[][] buildAccounts() {
        int needed = USERS * ITERATIONS;
        List<String[]> rows = new ArrayList<>();
        try {
            JsonNode arr = JSON.readTree(Files.readString(Path.of("/fixtures/accounts.json")));
            if (arr.isArray()) {
                for (JsonNode node : arr) {
                    String user = node.path("username").asText("");
                    if (!user.isEmpty()) {
                        String[] row = new String[3];
                        row[0] = user;
                        row[1] = node.path("password").asText("bench");
                        row[2] = String.valueOf(clampQuantity(node.path("quantity").asInt(2)));
                        rows.add(row);
                    }
                }
            }
        } catch (IOException | RuntimeException error) {
            rows.clear();
        }
        String[][] result = new String[needed][3];
        Set<String> used = new LinkedHashSet<>();
        int cursor = 0;
        int candidate = 1;
        for (int index = 0; index < needed; index++) {
            String[] chosen = null;
            while (cursor < rows.size()) {
                String[] row = rows.get(cursor);
                cursor++;
                if (!used.contains(row[0])) {
                    chosen = row;
                    break;
                }
            }
            if (chosen == null) {
                while (candidate <= 16 && used.contains("bench-" + candidate)) {
                    candidate++;
                }
                String user = candidate <= 16 ? "bench-" + candidate : "bench-" + (index + 1);
                candidate++;
                chosen = new String[] {user, "bench", "2"};
            }
            used.add(chosen[0]);
            result[index] = chosen;
        }
        return result;
    }

    private static int slot(Session session) {
        int iteration = session.contains("journey") ? session.getInt("journey") : 0;
        int user = (int) ((session.userId() - 1) % USERS);
        int index = iteration * USERS + user;
        if (index < 0) {
            index = 0;
        }
        return index % ACCOUNTS.length;
    }

    private static int quantity(Session session) {
        return clampQuantity(session.contains("quantity") ? session.getInt("quantity") : 2);
    }

    private static String decode(String value) {
        if (value == null) {
            return null;
        }
        return value.replace("&quot;", "\"").replace("&#34;", "\"")
            .replace("&apos;", "'").replace("&#39;", "'").replace("&#x27;", "'")
            .replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&");
    }

    /** Attribute-order / quoting tolerant extraction of an exact-named input, skipping decoys. */
    private static String inputValue(String html, String name) {
        if (html == null) {
            return null;
        }
        String fallback = null;
        Matcher tags = INPUT_TAG.matcher(html);
        while (tags.find()) {
            String tag = tags.group();
            Map<String, String> attributes = new HashMap<>();
            Matcher found = ATTRIBUTE.matcher(tag);
            while (found.find()) {
                String value = found.group(2) != null ? found.group(2)
                    : found.group(3) != null ? found.group(3) : found.group(4);
                attributes.put(found.group(1).toLowerCase(Locale.ROOT), decode(value));
            }
            if (!name.equals(attributes.get("name"))) {
                continue;
            }
            String value = attributes.get("value");
            if (value == null || value.isEmpty()) {
                continue;
            }
            String lower = tag.toLowerCase(Locale.ROOT);
            if (lower.contains("decoy") || lower.contains("disabled") || lower.contains("aria-hidden")) {
                if (fallback == null) {
                    fallback = value;
                }
                continue;
            }
            return value;
        }
        return fallback;
    }

    private static ChainBuilder login() {
        ChainBuilder init = exec(session -> {
            String[] account = ACCOUNTS[slot(session)];
            Session next = session.set("username", account[0]);
            next = next.set("password", account[1]);
            next = next.set("quantity", Integer.parseInt(account[2]));
            String[] cleared = new String[] {"csrf", "formCsrf", "loginHtml", "location", "product",
                "variant", "cart", "etag", "catalogBody", "catalogStatus", "cartStatus",
                "etagStatus", "patchStatus", "orderStatus", "renewStatus"};
            for (int i = 0; i < cleared.length; i++) {
                next = next.remove(cleared[i]);
            }
            return next;
        });
        ChainBuilder form = exec(http("login form").get("/v2/login-form")
            .check(status().is(200), bodyString().saveAs("loginHtml")));
        ChainBuilder capture = exec(session -> {
            String token = inputValue(session.getString("loginHtml"), "csrf");
            return token == null ? session : session.set("formCsrf", token);
        });
        ChainBuilder submit = exec(http("login").post("/v2/login")
            .header("Content-Type", "application/json")
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{formCsrf}\"}"))
            .check(status().in(200, 302), jsonPath("$.csrf").optional().saveAs("csrf"),
                header("Location").optional().saveAs("location")));
        ChainBuilder redirect = exec(http("login redirect").get("#{location}")
            .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")));
        ChainBuilder follow = exec(doIf(session -> session.contains("location")).then(redirect));
        return init.exec(form).exec(capture).exec(submit).exec(follow);
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException error) {
            return session;
        }
        return session;
    }

    private static ChainBuilder catalogOp(boolean strict) {
        if (strict) {
            return exec(http("catalog retry").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200), bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(session -> selectProduct(session));
        }
        return exec(http("catalog").get("/v2/catalog")
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().in(200, 401), status().saveAs("catalogStatus"),
                bodyString().saveAs("catalogBody"), jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(session -> selectProduct(session));
    }

    private static ChainBuilder cartOp(boolean strict) {
        if (strict) {
            return exec(http("cart retry").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\"}"))
                .check(status().is(201), jsonPath("$.id").saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("cart").post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\"}"))
            .check(status().in(201, 401), status().saveAs("cartStatus"),
                jsonPath("$.id").optional().saveAs("cart"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder readEtagOp(boolean strict) {
        if (strict) {
            return exec(http("cart read retry").get("/v2/carts/#{cart}")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200), header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("cart read").get("/v2/carts/#{cart}")
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().in(200, 401), status().saveAs("etagStatus"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder patchOp(boolean strict) {
        if (strict) {
            return exec(http("cart update retry").patch("/v2/carts/#{cart}")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"quantity\":" + quantity(session) + "}"))
                .check(status().is(200), header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("cart update").patch("/v2/carts/#{cart}")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"quantity\":" + quantity(session) + "}"))
            .check(status().in(200, 401, 412), status().saveAs("patchStatus"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder orderOp(boolean strict) {
        if (strict) {
            return exec(http("commit retry").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                .check(status().is(201), jsonPath("$.accepted").is("true"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("commit").post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}")
            .header("If-Match", "#{etag}")
            .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
            .check(status().in(201, 401), status().saveAs("orderStatus"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    /** Bounded recovery: renew, re-login only if revoked, recover cart, retry the interrupted op once. */
    private static ChainBuilder guarded(String statusKey, Function<Boolean, ChainBuilder> operation) {
        ChainBuilder stash = exec(session -> {
            String cart = session.contains("cart") ? session.getString("cart") : "";
            String etag = session.contains("etag") ? session.getString("etag") : "";
            return session.set("recoveryCart", cart).set("recoveryEtag", etag);
        });
        ChainBuilder renew = exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 401), status().saveAs("renewStatus"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
        ChainBuilder restore = exec(session -> {
            Session next = session;
            String cart = session.getString("recoveryCart");
            String etag = session.getString("recoveryEtag");
            if (cart != null && !cart.isEmpty()) {
                next = next.set("cart", cart);
            }
            if (etag != null && !etag.isEmpty()) {
                next = next.set("etag", etag);
            }
            return next;
        });
        ChainBuilder relogin = exec(doIf(session -> session.getInt("renewStatus") == 401)
            .then(login().exec(restore)));
        ChainBuilder recover = exec(http("cart recover").post("/v2/carts/#{cart}/recover")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200), header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
        ChainBuilder recoverIfCart = exec(doIf(session -> session.contains("cart")).then(recover));
        ChainBuilder recovery = stash.exec(renew).exec(relogin).exec(recoverIfCart)
            .exec(operation.apply(true));
        ChainBuilder onExpiry = exec(doIf(session ->
            session.contains(statusKey) && session.getInt(statusKey) == 401).then(recovery));
        return operation.apply(false).exec(onExpiry);
    }

    private static ChainBuilder journey() {
        ChainBuilder etagConflict = exec(doIf(session ->
            session.contains("patchStatus") && session.getInt("patchStatus") == 412).then(
            readEtagOp(true).exec(patchOp(true))));
        return exec(flushCookieJar())
            .exec(login())
            .exec(guarded("catalogStatus", ModelSimulation::catalogOp))
            .exec(pause(Duration.ofMillis(200)))
            .exec(guarded("cartStatus", ModelSimulation::cartOp))
            .exec(guarded("etagStatus", ModelSimulation::readEtagOp))
            .exec(guarded("patchStatus", ModelSimulation::patchOp))
            .exec(etagConflict)
            .exec(guarded("orderStatus", ModelSimulation::orderOp));
    }

    public ModelSimulation() {
        setUp(scenario("partitioned credentials")
            .exec(repeat(ITERATIONS, "journey").on(journey()))
            .injectOpen(atOnceUsers(USERS)))
            .assertions(global().failedRequests().count().is(0L))
            .protocols(HTTP);
    }
}
