import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Rate } from 'k6/metrics';

/* ------------------------------------------------------------------ *
 * Partitioned credentials: one exclusive account per VU, pinned for
 * every iteration of that VU. No shared cookie/CSRF state across VUs.
 * ------------------------------------------------------------------ */

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const CFG = { users: 2, iterations: 2, mode: 'partition' };
const failure = new Rate('business_failure');

function num(v, d) {
  const n = Number(v);
  return isFinite(n) ? n : d;
}
function clampQty(v) {
  const n = Math.round(num(v, 2));
  if (!isFinite(n) || n < 1) return 2;
  return n > 20 ? 20 : n;
}
function csvRows(text) {
  const lines = String(text).split(/\r?\n/);
  const out = [];
  let head = null;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const cells = line.split(',').map(function (c) { return c.trim(); });
    if (!head) { head = cells.map(function (c) { return c.toLowerCase(); }); continue; }
    const row = {};
    for (let j = 0; j < head.length; j++) row[head[j]] = cells[j];
    out.push(row);
  }
  return out;
}
function loadAccounts() {
  const text = open('/fixtures/accounts.json');
  let parsed = null;
  try { parsed = JSON.parse(text); } catch (e) { parsed = null; }
  let list = [];
  if (parsed) {
    if (Array.isArray(parsed)) list = parsed;
    else if (Array.isArray(parsed.accounts)) list = parsed.accounts;
    else if (Array.isArray(parsed.rows)) list = parsed.rows;
    else if (parsed.data && Array.isArray(parsed.data.accounts)) list = parsed.data.accounts;
    else if (typeof parsed === 'object') list = [parsed];
  } else {
    list = csvRows(text);
  }
  const out = [];
  const seen = {};
  for (let i = 0; i < list.length; i++) {
    const r = list[i] || {};
    const name = r.username || r.user || r.account || r.name;
    if (!name) continue;
