  const et = header(g, 'ETag');
  if (et) S.etag = et;
}

/* ---------------- one journey = one login, one cart, one order ---------------- */
function journey() {
  resetSession();
  S.csrf = '';
  S.cart = '';
  S.etag = '';

  if (S.delay > 0) sleep(S.delay / 1000);
  if (!login()) return;
  sleep(0.3);

