  sleep(0.3);

  businessWork('/v2/browse');
  sleep(0.25);
  businessWork('/v2/work');
  sleep(0.3);

  const key = 'order-' + S.cart + '-' + exec.vu.idInTest + '-' + exec.scenario.iterationInTest;
  const payload = { cart_id: S.cart };
  let ordered = request('/v2/orders', 'POST', payload, { 'Idempotency-Key': key, 'If-Match': S.etag });
  if (ordered.status === 412) {
    refreshEtag();
    ordered = request('/v2/orders', 'POST', payload, { 'Idempotency-Key': key, 'If-Match': S.etag });
  }
  check(ordered, {
    'order committed once': function (x) { return x.status === 201 && body(x).accepted === true; }
  });
  sleep(0.2);
}

export default function () {
  const idx = exec.vu.idInTest - 1;
  const acct = accountFor(idx);
  S.username = acct.username;
  S.password = acct.password;
  S.quantity = acct.quantity;
  S.delay = acct.delay;
  check(acct, {
    'exclusive account assigned': function (a) { return !!a.username; },
    'account index in range': function () { return idx >= 0 && idx < CFG.users; }
  });
  journey();
}
