import csv
import json
import os
import re

from gevent import sleep
from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

USERS = 2
ITERATIONS = 2
HOST = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def load_rows():
    rows = []
    try:
        with open("/fixtures/accounts.json", encoding="utf-8") as handle:
            data = json.load(handle)
        if isinstance(data, dict):
            data = data.get("accounts") or data.get("rows") or []
        if isinstance(data, list):
            rows = [row for row in data if isinstance(row, dict) and row.get("username")]
    except (OSError, ValueError):
        rows = []
    if not rows:
        for number in range(1, USERS + 1):
            try:
                with open("/fixtures/account-%d.csv" % number, encoding="utf-8") as handle:
                    for row in csv.DictReader(handle):
                        if row.get("username"):
                            rows.append(row)
                            break
            except OSError:
                continue
    while len(rows) < USERS:
        rows.append({"username": "bench-%d" % (len(rows) + 1), "password": "bench"})
    return rows


ROWS = load_rows()

ALLOC = {"lock": Semaphore(), "next": 0, "done": 0, "barriers": {}}

INPUT_RE = re.compile(r"<input\b[^>]*>", re.IGNORECASE)
ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))"""
)


def extract_field(html, field):
    candidates = []
    for tag in INPUT_RE.findall(html or ""):
        attrs = {}
        for match in ATTR_RE.finditer(tag):
            value = match.group(2)
            if value is None:
                value = match.group(3)
            if value is None:
                value = match.group(4)
            attrs[match.group(1).lower()] = value or ""
        if attrs.get("name") != field:
            continue
        if "disabled" in attrs:
            continue
        if any("decoy" in key or "decoy" in val.lower() for key, val in attrs.items()):
            continue
        value = attrs.get("value", "")
        if not value:
            continue
        candidates.append((attrs.get("type", "").lower() == "hidden", value))
    if not candidates:
        return None
    for preferred, value in candidates:
        if preferred:
            return value
    return candidates[0][1]


