import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import java.io.IOException;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final String CONFIG_JSON =
        "{\"users\": 2, \"iterations\": 2, \"mode\": \"flow\", \"workload\": true, \"operation\": \"journey\", \"path\": \"/v2/orders\", \"rate\": 1, \"max_vus\": 4}";

    private static final ObjectMapper JSON = new ObjectMapper();
    private static final JsonNode CFG = config();
    private static final double RATE = Math.max(0.05, CFG.path("rate").asDouble(1.0));
    private static final int MAX_VUS = Math.max(1, Math.min(4, CFG.path("max_vus").asInt(4)));
    private static final int VUS = Math.max(1, Math.min(MAX_VUS, (int) Math.ceil(RATE)));
    private static final Duration ITERATION_PACE =
        Duration.ofMillis(Math.max(1L, Math.round(1000.0 * VUS / RATE)));
    private static final Duration RUN = Duration.ofSeconds(45);
    private static final Duration HARD_STOP = Duration.ofSeconds(50);

    private static final Pattern INPUT_TAG = Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern NAME_ATTR = attributePattern("name");
    private static final Pattern VALUE_ATTR = attributePattern("value");
    private static final Pattern TYPE_ATTR = attributePattern("type");

    private static final HttpProtocolBuilder HTTP = http.baseUrl(baseUrl())
        .disableWarmUp()
        .disableFollowRedirect();

    private static JsonNode config() {
        try {
            return JSON.readTree(CONFIG_JSON);
        } catch (IOException error) {
            throw new IllegalStateException(error);
        }
    }

    private static String baseUrl() {
        String base = System.getenv("BASE_URL");
        return base == null || base.trim().isEmpty() ? "http://127.0.0.1:8000" : base.trim();
    }

    private static Pattern attributePattern(String attribute) {
        return Pattern.compile("(?is)(?:^|\\s)" + attribute
            + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))");
    }

    private static String attribute(String tag, Pattern pattern) {
        Matcher matcher = pattern.matcher(tag);
        if (!matcher.find()) {
            return "";
        }
        if (matcher.group(1) != null) {
            return matcher.group(1).trim();
        }
        if (matcher.group(2) != null) {
            return matcher.group(2).trim();
        }
        String raw = matcher.group(3) == null ? "" : matcher.group(3).trim();
        while (raw.endsWith("/")) {
            raw = raw.substring(0, raw.length() - 1);
        }
        return raw;
    }

    private static String decode(String value) {
        if (value.indexOf('&') < 0) {
            return value;
        }
        return value.replace("&quot;", "\"").replace("&apos;", "'").replace("&#39;", "'")
            .replace("&#x27;", "'").replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&");
    }

    private static String loginCsrf(String html) {
        if (html == null || html.isEmpty()) {
            return "";
        }
        Matcher tags = INPUT_TAG.matcher(html);
        String fallback = "";
        while (tags.find()) {
            String tag = tags.group();
            if (!"csrf".equalsIgnoreCase(attribute(tag, NAME_ATTR))) {
                continue;
            }
            String value = attribute(tag, VALUE_ATTR);
            if (value.isEmpty()) {
                continue;
            }
            if ("hidden".equalsIgnoreCase(attribute(tag, TYPE_ATTR))) {
                return decode(value);
            }
            if (fallback.isEmpty()) {
                fallback = value;
            }
        }
        return decode(fallback);
    }

    private static String username(Session session) {
        long seq = session.contains("seq") ? session.getLong("seq") : 1L;
        long index = ((session.userId() - 1 + seq - 1) % 16) + 1;
        return "bench-" + index;
    }

    private static Session selectProduct(Session session) {
        if (!session.contains("catalogBody")) {
            return session;
        }
        try {
            JsonNode root = JSON.readTree(session.getString("catalogBody"));
            JsonNode products = root.path("data").path("products");
            if (!products.isArray()) {
                products = root.path("products");
            }
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)) {
                        return session.set("productJson", product.path("id").toString())
                            .set("variantJson", variant.path("id").toString());
                    }
                }
            }
        } catch (IOException | RuntimeException error) {
            return session;
        }
        return session;
    }

    private static Session cartIdentity(Session session) {
        if (!session.contains("cartBody")) {
            return session;
        }
        try {
            JsonNode id = JSON.readTree(session.getString("cartBody")).path("id");
            if (id.isMissingNode() || id.isNull()) {
                return session;
            }
            return session.set("cart", id.asText())
                .set("cartJson", id.toString())
                .set("idem", "checkout-" + session.userId() + "-" + id.asText());
        } catch (IOException | RuntimeException error) {
            return session;
        }
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("location").remove("loginHtml"))
            .exec(http("login form").get("/v2/login-form")
                .header("Accept", "text/html")
                .check(status().is(200), bodyString().optional().saveAs("loginHtml")))
            .exec(session -> {
                String token = loginCsrf(session.contains("loginHtml") ? session.getString("loginHtml") : "");
                return session.set("formCsrf", token).set("csrf", token);
            })
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .header("Accept", "application/json")
                .body(StringBody(session -> {
                    ObjectNode payload = JSON.createObjectNode();
                    payload.put("username", username(session));
                    payload.put("password", "bench");
                    payload.put("csrf", session.getString("formCsrf"));
                    return payload.toString();
                }))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .header("Accept", "application/json")
                    .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(session -> session.remove("location"))));
    }

    private static ChainBuilder renewSession() {
        return exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("Accept", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().in(200, 401), status().saveAs("renewStatus"),
                jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("renewStatus") == 401).then(login()));
    }

    private static ChainBuilder catalogRequest(String path, String name) {
        return exec(http(name).get(path)
            .header("Accept", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().in(200, 401), status().saveAs("catalogStatus"),
                bodyString().optional().saveAs("catalogBody"),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.next").optional().saveAs("nextPage")));
    }

    private static ChainBuilder catalog() {
        ChainBuilder chain = exec(session -> session.remove("nextPage")
                .remove("productJson").remove("variantJson"))
            .exec(catalogRequest("/v2/catalog", "catalog"))
            .exec(doIf(session -> session.getInt("catalogStatus") == 401).then(
                renewSession().exec(catalogRequest("/v2/catalog", "catalog retry"))))
            .exec(session -> selectProduct(session));
        for (int page = 1; page < 3; page++) {
            chain = chain.exec(doIf(session -> !session.contains("productJson")
                && session.contains("nextPage")).then(
                exec(session -> session.set("pageUrl", session.getString("nextPage")).remove("nextPage"))
                    .exec(catalogRequest("#{pageUrl}", "catalog page"))
                    .exec(session -> selectProduct(session))));
        }
        return chain;
    }

    private static ChainBuilder cartRequest(String name) {
        return exec(http(name).post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("Accept", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody(session -> "{\"product_id\":" + session.getString("productJson")
                + ",\"variant_id\":" + session.getString("variantJson") + "}"))
            .check(status().in(200, 201, 401), status().saveAs("cartStatus"),
                bodyString().optional().saveAs("cartBody"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder cart() {
        return exec(cartRequest("cart"))
            .exec(doIf(session -> session.getInt("cartStatus") == 401).then(
                renewSession().exec(cartRequest("cart retry"))))
            .exec(session -> cartIdentity(session));
    }

    private static ChainBuilder orderRequest(boolean withEtag) {
        if (withEtag) {
            return exec(http("commit").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("Accept", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{idem}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"cart_id\":" + session.getString("cartJson") + "}"))
                .check(status().is(201), jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").exists(), jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("commit").post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("Accept", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{idem}")
            .body(StringBody(session -> "{\"cart_id\":" + session.getString("cartJson") + "}"))
            .check(status().is(201), jsonPath("$.accepted").is("true"),
                jsonPath("$.id").exists(), jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder checkout() {
        return doIf(session -> session.contains("cart") && session.contains("etag"))
            .then(orderRequest(true))
            .exec(doIf(session -> session.contains("cart") && !session.contains("etag"))
                .then(orderRequest(false)));
    }

    private static ChainBuilder iteration() {
        return exec(flushCookieJar())
            .exec(session -> {
                long seq = session.contains("seq") ? session.getLong("seq") + 1L : 1L;
                return session.set("seq", seq);
            })
            .exec(login())
            .exec(catalog())
            .exec(cart())
            .exec(checkout());
    }

    public ModelSimulation() {
        setUp(
            scenario("owned checkout journey")
                .exec(forever().on(pace(ITERATION_PACE).exec(iteration())))
                .injectClosed(constantConcurrentUsers(VUS).during(RUN))
        )
            .maxDuration(HARD_STOP)
            .protocols(HTTP);
    }
}

