import html
import os
import re
import time
import uuid

from gevent import sleep
from gevent.lock import Semaphore

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {'workload': True, 'operation': 'journey', 'path': '/v2/orders', 'rate': 1, 'max_vus': 4}

HOST = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')
RATE = float(CFG['rate'])
MAX_VUS = int(CFG['max_vus'])
CHECKOUT_PATH = CFG['path']

THINK_TIME = 1.0
WARMUP = 5.0
SCORED = 30.0
DRAIN = 2.0
SLOTS = int(round(RATE * (WARMUP + SCORED + 1.0)))
HARD_STOP = WARMUP + SCORED + 25.0

ACCOUNTS = ['bench-%d' % index for index in range(1, 17)]
PASSWORD = 'bench'
ACCOUNT_LOCK = Semaphore()
ACCOUNT_CURSOR = [0]

_INPUT = re.compile(r'<input\b[^>]*>', re.IGNORECASE)
_ATTR = re.compile(r"""([\w:.\-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))""")
_COMMENT = re.compile(r'<!--.*?-->', re.DOTALL)


def form_value(markup, field):
    markup = _COMMENT.sub(' ', markup or '')
    fallback = None
    for tag in _INPUT.findall(markup):
        lowered = tag.lower()
        if 'decoy' in lowered:
            continue
        attrs = {}
        for match in _ATTR.finditer(tag):
            raw = match.group(2)
            if raw is None:
                raw = match.group(3)
            if raw is None:
                raw = match.group(4)
            attrs[match.group(1).lower()] = html.unescape(raw or '')
        if attrs.get('name') != field:
            continue
        if 'disabled' in attrs:
            continue
        value = attrs.get('value')
        if not value:
            continue
        if attrs.get('type', 'text').lower() == 'hidden':
            return value
        if fallback is None:
            fallback = value
    return fallback


def json_body(response):
    try:
        data = response.json()
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


class ArrivalPlan:
    """One scheduled checkout start per business iteration, never per request."""

    def __init__(self, rate, slots):
        self.rate = rate
        self.slots = slots
        self.lock = Semaphore()
        self.base = None
        self.issued = 0
        self.done = 0
        self.finished = False
        self.activity = time.monotonic()

    def ticket(self):
        with self.lock:
            if self.issued >= self.slots:
                return None
            number = self.issued
            self.issued += 1
            now = time.monotonic()
            if self.base is None:
                self.base = now
            offset = number / self.rate
            if number:
                offset += 0.5 / self.rate
            self.activity = now
            return self.base + offset

    def wait_until(self, deadline):
        delay = deadline - time.monotonic()
        if delay > 0:
            sleep(delay)

    def completed(self):
        with self.lock:
            self.done += 1
            self.activity = time.monotonic()
            if self.done >= self.slots:
                self.finished = True

    def exhausted(self):
        with self.lock:
            return self.issued >= self.slots

    def idle_for(self):
        with self.lock:
            return time.monotonic() - self.activity


PLAN = ArrivalPlan(RATE, SLOTS)


class CheckoutUser(HttpUser):
    host = HOST
    wait_time = lambda self: 0.0

    def on_start(self):
        with ACCOUNT_LOCK:
            index = ACCOUNT_CURSOR[0]
            ACCOUNT_CURSOR[0] += 1
        self.username = ACCOUNTS[index % len(ACCOUNTS)]
        self.password = PASSWORD
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.idempotency_key = ''

    def raw(self, method, path, payload=None, headers=None, validate=None):
        request_headers = {'Accept': 'application/json'}
        if payload is not None:
            request_headers['Content-Type'] = 'application/json'
        if method != 'GET' and self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        if headers:
            request_headers.update(headers)
        with self.client.request(method, path, json=payload, headers=request_headers,
                                 catch_response=True, allow_redirects=False,
                                 timeout=5) as response:
            body = json_body(response)
            status = response.status_code
            error = body.get('error')
            problem = None
            if status == 401 and error in ('expired', 'session'):
                problem = None
            elif status == 412:
                problem = None
            elif not 200 <= status < 400:
                problem = 'unexpected status %s' % status
            elif validate is not None:
                problem = validate(response, body)
            if problem:
                response.failure(problem)
            else:
                response.success()
            if body.get('csrf'):
                self.csrf = body['csrf']
            return response, body

    def request(self, method, path, payload=None, headers=None, validate=None):
        response, body = self.raw(method, path, payload, headers, validate)
        if response.status_code == 401 and body.get('error') in ('expired', 'session'):
            self.recover(body.get('error'))
            if headers and 'If-Match' in headers and self.etag:
                headers = dict(headers)
                headers['If-Match'] = self.etag
            response, body = self.raw(method, path, payload, headers, validate)
        return response, body

    def recover(self, error):
        if error == 'expired':
            response, _ = self.raw('POST', '/v2/session/renew', {})
            if response.status_code != 200:
                self.login()
        else:
            self.login()
        if self.cart:
            response, _ = self.raw('POST', '/v2/carts/%s/recover' % self.cart, {})
            etag = response.headers.get('ETag')
            if etag:
                self.etag = etag

    def login(self):
        self.client.cookies.clear()
        self.csrf = ''
        captured = {}

        def check_form(response, body):
            token = form_value(response.text, 'csrf')
            if not token:
                return 'login form csrf missing'
            captured['token'] = token
            return None

        self.raw('GET', '/v2/login-form', validate=check_form)
        if 'token' not in captured:
            return False

        def check_login(response, body):
            if response.status_code == 302:
                return None if response.headers.get('Location') else 'login redirect without Location'
            if body.get('csrf') or body.get('user'):
                return None
            return 'login rejected'

        response, body = self.raw('POST', '/v2/login',
                                  {'username': self.username, 'password': self.password,
                                   'csrf': captured['token']}, validate=check_login)
        if response.status_code == 302:
            location = response.headers.get('Location')
            if not location:
                return False
            self.raw('GET', location, validate=check_login)
        return bool(self.csrf)

    def select_product(self):
        path = '/v2/catalog'
        for _ in range(3):
            response, body = self.request('GET', path)
            if response.status_code != 200:
                return None
            data = body.get('data') or {}
            for product in data.get('products') or []:
                for variant in product.get('variants') or []:
                    if variant.get('in_stock') and product.get('id') and variant.get('id'):
                        return product['id'], variant['id']
            nxt = body.get('next')
            if not nxt:
                return None
            path = nxt
        return None

    def journey(self):
        self.client.cookies.clear()
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.idempotency_key = ''

        if not self.login():
            return
        picked = self.select_product()
        if not picked:
            return
        product_id, variant_id = picked

        def check_cart(response, body):
            return None if response.status_code == 201 and body.get('id') else 'cart not created'

        response, body = self.request('POST', '/v2/carts',
                                      {'product_id': product_id, 'variant_id': variant_id},
                                      validate=check_cart)
        self.cart = body.get('id') or ''
        self.etag = response.headers.get('ETag') or ''
        if not self.cart:
            return
        self.idempotency_key = uuid.uuid4().hex
        cart_path = '/v2/carts/%s' % self.cart

        def check_patch(response, body):
            return None if response.status_code in (200, 204) else 'quantity not updated'

        response, _ = self.request('GET', cart_path)
        etag = response.headers.get('ETag')
        if etag:
            self.etag = etag
        headers = {'If-Match': self.etag} if self.etag else None
        response, _ = self.request('PATCH', cart_path, {'quantity': 2}, headers, check_patch)
        if response.status_code == 412:
            response, _ = self.request('GET', cart_path)
            self.etag = response.headers.get('ETag') or self.etag
            response, _ = self.request('PATCH', cart_path, {'quantity': 2},
                                       {'If-Match': self.etag}, check_patch)
        etag = response.headers.get('ETag')
        if etag:
            self.etag = etag
        if response.status_code not in (200, 204):
            return

        deadline = PLAN.ticket()
        if deadline is None:
            raise StopUser()
        PLAN.wait_until(deadline)

        order_headers = {'Idempotency-Key': self.idempotency_key}
        if self.etag:
            order_headers['If-Match'] = self.etag

        def check_order(response, body):
            if response.status_code == 201 and body.get('accepted') is True and body.get('id'):
                return None
            return 'checkout not accepted'

        try:
            self.request('POST', CHECKOUT_PATH, {'cart_id': self.cart},
                         order_headers, check_order)
        finally:
            PLAN.completed()

    @task
    def run_journey(self):
        if PLAN.exhausted():
            raise StopUser()
        self.journey()
        sleep(THINK_TIME)
        if PLAN.exhausted():
            raise StopUser()


class CheckoutShape(LoadTestShape):
    def tick(self):
        elapsed = self.get_run_time()
        if elapsed >= HARD_STOP:
            return None
        if PLAN.finished and PLAN.idle_for() >= DRAIN:
            return None
        return (MAX_VUS, MAX_VUS)
