import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    // Execution contract: {"users": 2, "iterations": 2, "mode": "errors"}
    // Non-workload counts are iterations per user; 4 POST /v2/work operations per iteration.
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;
    private static final int WORK_OPERATIONS = 4;
    private static final int MAX_RATE_RETRIES = 4;
    private static final int MAX_RECOVERY_STEPS = MAX_RATE_RETRIES + 1;

    private static final Pattern INPUT_TAG = Pattern.compile("(?is)<input\\b[^>]*>");
    private static final Pattern ATTRIBUTE = Pattern.compile(
        "(?is)([a-z_:][-a-z0-9_:.]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s\"'=<>`]+))");

    private static final HttpProtocolBuilder HTTP = http.baseUrl(baseUrl())
        .disableWarmUp()
        .disableFollowRedirect()
        .acceptHeader("application/json");

    private static String baseUrl() {
        String configured = System.getenv("BASE_URL");
        return configured == null || configured.trim().isEmpty() ? "http://127.0.0.1:8000" : configured.trim();
    }

    private static String username(Session session) {
        return "bench-" + (((session.userId() - 1) % 16) + 1);
    }

    private static String attribute(String tag, String name) {
        Matcher matcher = ATTRIBUTE.matcher(tag);
        while (matcher.find()) {
            if (name.equalsIgnoreCase(matcher.group(1))) {
                String value = matcher.group(2) != null ? matcher.group(2)
                    : matcher.group(3) != null ? matcher.group(3) : matcher.group(4);
                return value == null ? "" : value;
            }
        }
        return null;
    }

    private static String extractCsrf(String html) {
        if (html == null) {
            return "";
        }
        Matcher tags = INPUT_TAG.matcher(html);
        while (tags.find()) {
            String tag = tags.group();
            String name = attribute(tag, "name");
            if (name == null || !name.equalsIgnoreCase("csrf")) {
                continue;
            }
            if (attribute(tag, "data-decoy") != null || tag.toLowerCase().contains("disabled")) {
                continue;
            }
            String value = attribute(tag, "value");
            if (value != null && !value.isEmpty()) {
                return value;
            }
        }
        return "";
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("csrf").remove("formCsrf").remove("loginFormHtml")
                .remove("loginLocation").remove("user"))
            .exec(http("login form").get("/v2/login-form")
                .check(status().is(200), bodyString().saveAs("loginFormHtml")))
            .exec(session -> session.set("formCsrf", extractCsrf(session.getString("loginFormHtml"))))
            .exec(http("login").post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    header("Location").optional().saveAs("loginLocation"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.user").optional().saveAs("user")))
            .exec(doIf(session -> session.contains("loginLocation")).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.user").optional().saveAs("user")))))
            .exec(session -> session.contains("csrf") ? session
                : session.set("csrf", session.getString("formCsrf")));
    }

    private static ChainBuilder renew() {
        return exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static Duration retryDelay(Session session) {
        try {
            String raw = session.contains("retryAfter") ? session.getString("retryAfter") : null;
            if (raw == null || raw.trim().isEmpty()) {
                return Duration.ofMillis(1010);
            }
            long millis = (long) (Double.parseDouble(raw.trim()) * 1000.0) + 10;
            return Duration.ofMillis(Math.max(1010, millis));
        } catch (RuntimeException error) {
            return Duration.ofMillis(1010);
        }
    }

    /**
     * One raw /v2/work response == one native sample.
     * 200 ok, scheduled 429 (Retry-After) and expected 401 error=expired/session are OK samples.
     * Unexpected 500 (and 401 error=denied, ok:false) are failed samples.
     */
    private static ChainBuilder workPost() {
        return exec(session -> session.set("workStatus", 0).remove("workError").remove("retryAfter"))
            .exec(http("work").post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().saveAs("workStatus"),
                    header("Retry-After").optional().saveAs("retryAfter"),
                    jsonPath("$.error").optional().saveAs("workError"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    status().in(200, 401, 429),
                    regex("\"error\"\\s*:\\s*\"denied\"").notExists(),
                    regex("\"ok\"\\s*:\\s*false").notExists()));
    }

    private static boolean recoverableExpiry(Session session) {
        String error = session.contains("workError") ? session.getString("workError") : null;
        return "expired".equals(error) || "session".equals(error);
    }

    private static boolean shouldRetry(Session session) {
        int status = session.contains("workStatus") ? session.getInt("workStatus") : 0;
        if (status == 429) {
            return session.getInt("rateRetries") < MAX_RATE_RETRIES;
        }
        if (status == 401) {
            return !session.getBoolean("recovered") && recoverableExpiry(session);
        }
        return false;
    }

    private static ChainBuilder recoveryStep() {
        return exec(doIf(session -> shouldRetry(session)).then(
            exec(doIf(session -> session.getInt("workStatus") == 401).then(
                exec(session -> session.set("recovered", true))
                    .exec(doIf(session -> "session".equals(session.getString("workError"))).then(login()))
                    .exec(doIf(session -> !"session".equals(session.getString("workError"))).then(renew()))))
            .exec(doIf(session -> session.getInt("workStatus") == 429).then(
                exec(session -> session.set("rateRetries", session.getInt("rateRetries") + 1))
                    .exec(pause(session -> retryDelay(session)))))
            .exec(workPost())));
    }

    private static ChainBuilder workOperation() {
        ChainBuilder chain = exec(session -> session.set("rateRetries", 0).set("recovered", false))
            .exec(workPost());
        for (int step = 0; step < MAX_RECOVERY_STEPS; step++) {
            chain = chain.exec(recoveryStep());
        }
        return chain;
    }

    private static ChainBuilder journey() {
        return exec(flushCookieJar())
            .exec(login())
            .exec(repeat(WORK_OPERATIONS).on(workOperation()));
    }

    public ModelSimulation() {
        setUp(scenario("errors")
            .exec(repeat(ITERATIONS).on(journey()))
            .injectOpen(atOnceUsers(USERS)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}
