import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = { users: 2, iterations: 2, mode: 'errors', workPerIteration: 4 };
const rows = [
  { username: 'bench-1', password: 'bench' }, { username: 'bench-2', password: 'bench' },
  { username: 'bench-3', password: 'bench' }, { username: 'bench-4', password: 'bench' },
  { username: 'bench-5', password: 'bench' }, { username: 'bench-6', password: 'bench' },
  { username: 'bench-7', password: 'bench' }, { username: 'bench-8', password: 'bench' },
  { username: 'bench-9', password: 'bench' }, { username: 'bench-10', password: 'bench' },
  { username: 'bench-11', password: 'bench' }, { username: 'bench-12', password: 'bench' },
  { username: 'bench-13', password: 'bench' }, { username: 'bench-14', password: 'bench' },
  { username: 'bench-15', password: 'bench' }, { username: 'bench-16', password: 'bench' }
];

const failure = new Rate('business_failure');
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '60s'
    }
  },
  thresholds: {
    checks: ['rate==1'],
    business_failure: ['rate==0']
  }
};

let csrf = '';

function body(r) {
  try { const b = r.json(); return b && typeof b === 'object' ? b : {}; } catch (_) { return {}; }
}

function header(r, name) {
  const h = (r && r.headers) || {};
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === name.toLowerCase()) return h[keys[i]];
  }
  return undefined;
}

function workSuccess(r) {
  return r.status === 200 && body(r).ok === true;
}

function expectedInterruption(r) {
  if (r.status === 429) return true;
  if (r.status === 401 && body(r).error === 'expired') return true;
  return false;
}

function raw(path, method, data, extra) {
  method = method || 'GET';
  const headers = Object.assign({ 'Content-Type': 'application/json' }, extra || {});
  if (csrf) headers['X-CSRF-Token'] = csrf;
  const url = /^https?:\/\//i.test(path) ? path : base + path;
  const r = http.request(method, url, data === null || data === undefined ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '5s'
  });
  const b = body(r);
  if (b.csrf) csrf = b.csrf;
  if (path === '/v2/work') {
    failure.add(!(workSuccess(r) || expectedInterruption(r)));
  }
  return r;
}

function formToken(htmlText) {
  const text = htmlText || '';
  const tags = text.match(/<input\b[^>]*>/gi) || [];
  const candidates = [];
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];
    const attrs = {};
    const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))/g;
    let m;
    while ((m = re.exec(tag)) !== null) {
      const v = m[2] !== undefined ? m[2] : (m[3] !== undefined ? m[3] : m[4]);
      attrs[m[1].toLowerCase()] = v === undefined ? '' : v;
    }
    if ((attrs.name || '') !== 'csrf') continue;
    let decoy = /decoy/i.test(tag);
    const keys = Object.keys(attrs);
    for (let k = 0; k < keys.length; k++) {
      if (/decoy|fake|bogus/i.test(keys[k]) || /decoy|fake|bogus/i.test(attrs[keys[k]])) decoy = true;
    }
    if ('disabled' in attrs) decoy = true;
    candidates.push({
      value: attrs.value || '',
      decoy: decoy,
      hidden: (attrs.type || '').toLowerCase() === 'hidden'
    });
  }
  const usable = candidates.filter(function (c) { return !c.decoy && c.value; });
  const hidden = usable.filter(function (c) { return c.hidden; });
  if (hidden.length) return hidden[0].value;
  if (usable.length) return usable[0].value;
  const any = candidates.filter(function (c) { return c.value; });
  if (any.length) return any[0].value;
  return '';
}

function login() {
  csrf = '';
  const form = raw('/v2/login-form');
  let token = formToken(form.body);
  if (!token) {
    try { token = form.html().find('input[name="csrf"]').first().attr('value') || ''; } catch (_) { token = ''; }
  }
  const row = rows[(__VU - 1) % rows.length];
  let r = raw('/v2/login', 'POST', { username: row.username, password: row.password, csrf: token });
  if (r.status >= 300 && r.status < 400) {
    const loc = header(r, 'Location');
    if (loc) r = raw(loc);
  }
  return check(r, { 'login ok': function (x) { return x.status === 200 && !!csrf; } });
}

function api(path, method, data, extra) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const err = body(r).error;
    if (err === 'expired' || err === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200 || !csrf) login();
      r = raw(path, method, data, extra);
    }
  }
  return r;
}

function work() {
  let r = api('/v2/work', 'POST', {});
  let retries = 0;
  while (r.status === 429 && retries < 4) {
    const ra = Number(header(r, 'Retry-After'));
    sleep((isFinite(ra) && ra > 0 ? ra : 1) + 0.01);
    r = api('/v2/work', 'POST', {});
    retries++;
  }
  check(r, { 'work ok': function (x) { return workSuccess(x); } });
}

export default function () {
  if (!login()) return;
  for (let i = 0; i < cfg.workPerIteration; i++) work();
}

