import os
import re

from gevent import sleep
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

HOST = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS = 2
WORK_PATH = "/v2/work"
WORK_PER_ITERATION = 4
MAX_THROTTLE_RETRIES = 4

INPUT_RE = re.compile(r"<input\b[^>]*>", re.IGNORECASE | re.DOTALL)
META_RE = re.compile(r"<meta\b[^>]*>", re.IGNORECASE | re.DOTALL)
NAME_RE = re.compile(r"(?<![\w-])name\s*=\s*([\"']?)csrf\1(?![\w-])", re.IGNORECASE)
VALUE_RE = re.compile(r"(?<![\w-])value\s*=\s*([\"'])(.*?)\1", re.IGNORECASE | re.DOTALL)
CONTENT_RE = re.compile(r"(?<![\w-])content\s*=\s*([\"'])(.*?)\1", re.IGNORECASE | re.DOTALL)
HIDDEN_RE = re.compile(r"(?<![\w-])type\s*=\s*([\"']?)hidden\1(?![\w-])", re.IGNORECASE)

ACCOUNTS = ["bench-%d" % index for index in range(1, 17)]
SEQUENCE = {"next": 0, "lock": Semaphore()}


def next_account():
    with SEQUENCE["lock"]:
        number = SEQUENCE["next"]
        SEQUENCE["next"] = number + 1
    return ACCOUNTS[number % len(ACCOUNTS)]


def extract_csrf(html):
    text = html or ""
    candidates = []
    for tag in INPUT_RE.findall(text):
        lowered = tag.lower()
        if "disabled" in lowered or "decoy" in lowered:
            continue
        if not NAME_RE.search(tag):
            continue
        value = VALUE_RE.search(tag)
        if not value or not value.group(2):
            continue
        if "decoy" in value.group(2).lower():
            continue
        candidates.append((0 if HIDDEN_RE.search(tag) else 1, value.group(2)))
    for tag in META_RE.findall(text):
        if not NAME_RE.search(tag):
            continue
        value = CONTENT_RE.search(tag)
        if value and value.group(2) and "decoy" not in value.group(2).lower():
            candidates.append((2, value.group(2)))
    if not candidates:
        return ""
    candidates.sort(key=lambda item: item[0])
    return candidates[0][1]


class WorkUser(HttpUser):
    host = HOST
    wait_time = constant(0)
    abstract = False

    def on_start(self):
        self.username = next_account()
        self.password = "bench"
        self.csrf = ""
        self.form_csrf = ""
        self.iteration = 0

    # ---- sample level classification -------------------------------------
    def raw(self, path, method="GET", data=None, headers=None, name=None,
            tolerate=None, check=None):
        """One native sample per raw response, with truthful classification."""
        tolerate = tolerate or {}
        request_headers = {"Content-Type": "application/json", "Accept": "application/json"}
        if self.csrf and method != "GET":
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name or path, catch_response=True,
                                 allow_redirects=False, timeout=10) as response:
            try:
                body = response.json()
            except Exception:
                body = {}
            if not isinstance(body, dict):
                body = {}
            code = response.status_code
            expected = False
            reason = "unexpected status %s" % code
            if code == 401 and body.get("error") in ("expired", "session") and tolerate.get("expiry"):
                # expected session expiry: recoverable, not a failure sample
                expected = True
            elif (code == 429 and tolerate.get("throttle")
                  and response.headers.get("Retry-After") is not None):
                # scheduled throttling with Retry-After: not a failure sample
                expected = True
            allowed = code < 400 or expected
            if allowed and not expected and check is not None:
                problem = check(response, body)
                if problem:
                    allowed = False
                    reason = problem
            if allowed:
                response.success()
            else:
                response.failure(reason)
                self.environment.process_exit_code = 99
            if body.get("csrf"):
                self.csrf = body["csrf"]
            return response, body

    # ---- checks ----------------------------------------------------------
    def check_login_form(self, response, body):
        self.form_csrf = extract_csrf(response.text)
        if not self.form_csrf:
            return "login form missing csrf token"
        return None

    def check_login(self, response, body):
        if response.status_code == 302:
            if not response.headers.get("Location"):
                return "login redirect without Location"
            return None
        if response.status_code != 200:
            return "login rejected (%s)" % response.status_code
        if not body.get("csrf") or not body.get("user"):
            return "login response missing csrf/user"
        return None

    def check_login_landing(self, response, body):
        if response.status_code != 200 or not body.get("csrf"):
            return "login landing missing csrf"
        return None

    def check_renew(self, response, body):
        if response.status_code != 200 or not body.get("csrf"):
            return "session renew did not return fresh csrf"
        return None

    def check_work(self, response, body):
        if response.status_code != 200:
            return "work unexpected status %s" % response.status_code
        if body.get("ok") is not True:
            return "work response not ok"
        return None

    # ---- protocol steps --------------------------------------------------
    def login(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.form_csrf = ""
        self.raw("/v2/login-form", "GET", check=self.check_login_form)
        if not self.form_csrf:
            return False
        response, body = self.raw("/v2/login", "POST",
                                  {"username": self.username,
                                   "password": self.password,
                                   "csrf": self.form_csrf},
                                  check=self.check_login)
        if response.status_code == 302:
            location = response.headers.get("Location")
            if not location:
                return False
            self.raw(location, "GET", check=self.check_login_landing)
        return bool(self.csrf)

    def recover_session(self, error):
        response, body = self.raw("/v2/session/renew", "POST", {},
                                  tolerate={"expiry": error == "session"},
                                  check=self.check_renew)
        if response.status_code != 200 or not body.get("csrf"):
            self.login()

    def work_once(self):
        recovered = False
        throttled = 0
        while True:
            tolerate = {"expiry": not recovered,
                        "throttle": throttled < MAX_THROTTLE_RETRIES}
            response, body = self.raw(WORK_PATH, "POST", {},
                                      tolerate=tolerate, check=self.check_work)
            code = response.status_code
            if (code == 401 and body.get("error") in ("expired", "session")
                    and not recovered):
                recovered = True
                self.recover_session(body.get("error"))
                continue
            if (code == 429 and throttled < MAX_THROTTLE_RETRIES
                    and response.headers.get("Retry-After") is not None):
                throttled += 1
                try:
                    delay = float(response.headers.get("Retry-After"))
                except (TypeError, ValueError):
                    delay = 1.0
                sleep(max(delay, 0.05))
                continue
            return response, body

    @task
    def run_scenario(self):
        if not self.login():
            raise StopUser()
        for _ in range(WORK_PER_ITERATION):
            self.work_once()
        self.iteration += 1
        if self.iteration >= ITERATIONS:
            raise StopUser()


class WorkShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if not self.started:
            self.started = True
            return (USERS, USERS)
        if self.get_run_time() > 300:
            return None
        if self.runner is None or self.runner.user_count == 0:
            return None
        return (USERS, USERS)
