import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final AtomicInteger SEQ = new AtomicInteger(0);

    private static final String BASE_URL =
            (System.getenv("BASE_URL") != null && !System.getenv("BASE_URL").isEmpty())
                    ? System.getenv("BASE_URL")
                    : "http://127.0.0.1:8000";

    private static String str(Session s, String k) {
        return s.contains(k) ? s.getString(k) : null;
    }

    private static int num(Session s, String k) {
        return s.contains(k) ? s.getInt(k) : 0;
    }

    private static boolean flag(Session s, String k) {
        return s.contains(k) && Boolean.TRUE.equals(s.getBoolean(k));
    }

    /* Fresh login journey: form nonce + csrf, JSON login, single dynamic redirect follow. */
    private static final ChainBuilder LOGIN =
            exec(s -> s.set("username", "bench-" + (1 + Math.floorMod(SEQ.getAndIncrement(), 16)))
                       .remove("loginLocation"))
            .exec(http("login_form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(css("input[name=csrf]", "value").optional().saveAs("csrfCss"))
                    .check(regex("name=[\"']csrf[\"'][^>]*value=[\"']([^\"']+)[\"']").optional().saveAs("csrfA"))
                    .check(regex("value=[\"']([^\"']+)[\"'][^>]*name=[\"']csrf[\"']").optional().saveAs("csrfB")))
            .exec(s -> {
                String t = str(s, "csrfCss");
                if (t == null || t.isEmpty()) t = str(s, "csrfA");
                if (t == null || t.isEmpty()) t = str(s, "csrfB");
                Session out = s.remove("csrfCss").remove("csrfA").remove("csrfB");
                return out.set("csrf", t == null ? "" : t);
            })
            .exec(http("login")
                    .post("/v2/login")
                    .header("Content-Type", "application/json")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("loginLocation"))
                    .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf")))
            .doIf(s -> s.contains("loginLocation")).then(
                    exec(http("login_redirect")
                            .get("#{loginLocation}")
                            .check(status().is(200))
                            .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf")))
            );

    /* Declared pool operation: POST /v2/work only. Bounded 429 / expiry recovery. */
    private static final ChainBuilder WORK =
            exec(s -> s.set("attempt", 0)
                       .set("done", false)
                       .set("recovered", false)
                       .set("workStatus", 0)
                       .set("renewStatus", 0))
            .asLongAs(s -> !flag(s, "done") && num(s, "attempt") < 5 && !s.isFailed()).on(
                    exec(s -> s.set("attempt", num(s, "attempt") + 1))
                    .exec(http("work")
                            .post("/v2/work")
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody("{}"))
                            .check(status().saveAs("workStatus"))
                            .check(status().in(200, 401, 429))
                            .check(regex("\"error\"\\s*:\\s*\"denied\"").notExists())
                            .check(regex("\"ok\"\\s*:\\s*false").notExists()))
                    .doIf(s -> num(s, "workStatus") == 200).then(
                            exec(s -> s.set("done", true)))
                    .doIf(s -> num(s, "workStatus") == 429).then(
                            pause(Duration.ofSeconds(1)))
                    .doIf(s -> num(s, "workStatus") == 401 && !flag(s, "recovered")).then(
                            exec(s -> s.set("recovered", true))
                            .exec(http("renew")
                                    .post("/v2/session/renew")
                                    .header("Content-Type", "application/json")
                                    .header("X-CSRF-Token", "#{csrf}")
                                    .body(StringBody("{}"))
                                    .check(status().saveAs("renewStatus"))
                                    .check(status().in(200, 401))
                                    .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf")))
                            .doIf(s -> num(s, "renewStatus") != 200).then(LOGIN)
                    )
            );

    private static final HttpProtocolBuilder HTTP = http
            .baseUrl(BASE_URL)
            .disableFollowRedirect()
            .disableCaching()
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8")
            .userAgentHeader("gatling-work-pool");

    private static final ScenarioBuilder SCN = scenario("work_pool")
            .exec(LOGIN)
            .exec(WORK);

    {
        setUp(SCN.injectOpen(constantUsersPerSec(5.0).during(Duration.ofSeconds(38))))
                .protocols(HTTP);
    }
}
