// k6 1.0.0 — declared pool: POST /v2/work only.
// 5 business-request starts/s, warmup 5s + scored 30s ([T0+5,T0+35)), drain <= 5s.
// No cart/catalog/order/health routes are used by this pool.
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate } from 'k6/metrics';
import execution from 'k6/execution';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const ACCOUNTS = 16;
const TARGET_RATE = 5;

const workOk = new Counter('work_ok');
const workRaw = new Counter('work_raw_responses');
const workUnexpected = new Counter('work_unexpected_failures');
const loginFailures = new Counter('login_failures');
const businessFailure = new Rate('business_failure');

const JSON_HEADERS = { 'Content-Type': 'application/json', Accept: 'application/json' };
const EXPECT_200 = http.expectedStatuses(200);
const EXPECT_LOGIN = http.expectedStatuses(200, 301, 302, 303, 307, 308);
const EXPECT_WORK = http.expectedStatuses(200, 401, 429);
const EXPECT_RENEW = http.expectedStatuses(200, 401);

export const options = {
  discardResponseBodies: false,
  scenarios: {
    work_pool: {
      executor: 'constant-arrival-rate',
      exec: 'workPool',
      rate: TARGET_RATE,
      timeUnit: '1s',
      // T0 = first eligible work POST start (~launch). 5s warmup + 30s scored + margin.
      duration: '36s',
      preAllocatedVUs: 8,
      maxVUs: 16, // <= 32 concurrent VUs, one distinct account per VU
      gracefulStop: '3s',
    },
  },
};

// Module scope is per-VU: session cookie jar + CSRF are preserved per user.
const state = { username: null, csrf: null, ready: false };

function urlFor(path) {
  if (/^https?:\/\//i.test(path)) {
    const m = String(path).match(/^https?:\/\/[^/]+(\/[\s\S]*)?$/i);
    return BASE_URL + (m && m[1] ? m[1] : '/');
  }
  return BASE_URL + (String(path).charAt(0) === '/' ? String(path) : '/' + String(path));
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const want = String(name).toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return res.headers[keys[i]];
  }
  return null;
}

function jsonOf(res) {
  if (!res || !res.body) return null;
  try {
    const parsed = res.json();
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (e) {
    return null;
  }
}

function errorCode(body) {
  if (!body) return '';
  if (typeof body.error === 'string') return body.error;
  if (body.error && typeof body.error.code === 'string') return body.error.code;
  if (typeof body.code === 'string') return body.code;
  return '';
}

function authHeaders() {
  return {
    'Content-Type': 'application/json',
    Accept: 'application/json',
    'X-CSRF-Token': state.csrf || '',
  };
}

function accountName() {
  const id = execution.vu.idInTest || 1;
  return 'bench-' + (((id - 1) % ACCOUNTS) + 1);
}

function decodeEntities(s) {
  return String(s)
    .replace(/&#x([0-9a-f]+);/gi, function (_, h) { return String.fromCharCode(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (_, d) { return String.fromCharCode(parseInt(d, 10)); })
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function parseAttrs(text) {
  const attrs = {};
  const re = /([^\s=\/>"']+)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+)))?/g;
  let m;
  while ((m = re.exec(String(text))) !== null) {
    const key = String(m[1]).toLowerCase();
    let val = '';
    if (m[2] !== undefined) val = m[2];
    else if (m[3] !== undefined) val = m[3];
    else if (m[4] !== undefined) val = m[4];
    if (!(key in attrs)) attrs[key] = decodeEntities(val);
  }
  return attrs;
}

function collectCsrfInputs(text, inLoginForm, out) {
  const tagRe = /<input\b((?:[^>"']|"[^"]*"|'[^']*')*)>/gi;
  let m;
  while ((m = tagRe.exec(String(text))) !== null) {
    const a = parseAttrs(m[1]);
    if (String(a.name || '').toLowerCase() !== 'csrf') continue;
    const value = a.value || '';
    if (!value) continue;
    const type = String(a.type || '').toLowerCase();
    let score = 0;
    if (type === 'hidden') score += 4;
    if (inLoginForm) score += 3;
    let markers = '';
    const keys = Object.keys(a);
    for (let i = 0; i < keys.length; i++) {
      if (keys[i] === 'value') continue;
      markers += keys[i] + '=' + a[keys[i]] + ' ';
    }
    if (/decoy|fake|dummy|trap|bogus|placeholder-token/i.test(markers)) score -= 100;
    if ('disabled' in a) score -= 100;
    if (['submit', 'button', 'reset', 'checkbox', 'radio', 'image', 'file'].indexOf(type) >= 0) score -= 50;
    out.push({ value: value, score: score });
  }
}

function extractTokens(html) {
  const cleaned = String(html)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style>/gi, ' ');

  const found = [];
  const formRe = /<form\b((?:[^>"']|"[^"]*"|'[^']*')*)>([\s\S]*?)<\/form>/gi;
  let fm;
  while ((fm = formRe.exec(cleaned)) !== null) {
    const attrs = parseAttrs(fm[1]);
    collectCsrfInputs(fm[2], /login/i.test(String(attrs.action || '')), found);
  }
  collectCsrfInputs(cleaned, false, found);

  if (!found.length) {
    const metaRe = /<meta\b((?:[^>"']|"[^"]*"|'[^']*')*)>/gi;
    let mm;
    while ((mm = metaRe.exec(cleaned)) !== null) {
      const a = parseAttrs(mm[1]);
      if (String(a.name || '').toLowerCase() === 'csrf' && a.content) {
        found.push({ value: a.content, score: 1 });
      }
    }
  }
  if (!found.length) {
    const jm = cleaned.match(/"csrf"\s*:\s*"([^"]+)"/);
    if (jm) found.push({ value: decodeEntities(jm[1]), score: 0 });
  }

  found.sort(function (x, y) { return y.score - x.score; });
  const seen = {};
  const tokens = [];
  for (let i = 0; i < found.length && tokens.length < 4; i++) {
    if (seen[found[i].value]) continue;
    seen[found[i].value] = true;
    tokens.push(found[i].value);
  }
  return tokens;
}

function fetchLoginTokens() {
  const res = http.get(urlFor('/v2/login-form'), {
    headers: { Accept: 'text/html,application/json' },
    redirects: 0,
    tags: { name: 'login_form' },
    responseCallback: EXPECT_200,
  });
  check(res, { 'login form 200': function (r) { return r.status === 200; } });
  if (res.status !== 200) return [];
  const body = jsonOf(res);
  if (body && typeof body.csrf === 'string' && body.csrf) return [body.csrf];
  return extractTokens(res.body || '');
}

function login() {
  if (!state.username) state.username = accountName();
  for (let round = 0; round < 2; round++) {
    const tokens = fetchLoginTokens();
    for (let i = 0; i < tokens.length; i++) {
      const res = http.post(
        urlFor('/v2/login'),
        JSON.stringify({ username: state.username, password: PASSWORD, csrf: tokens[i] }),
        {
          headers: JSON_HEADERS,
          redirects: 0, // auto redirects disabled; dynamic Location followed exactly once
          tags: { name: 'login' },
          responseCallback: EXPECT_LOGIN,
        }
      );
      let payload = null;
      if (res.status >= 300 && res.status < 400) {
        const target = header(res, 'Location');
        if (target) {
          const followed = http.get(urlFor(target), {
            headers: { Accept: 'application/json' },
            redirects: 0,
            tags: { name: 'login_redirect' },
            responseCallback: EXPECT_200,
          });
          payload = jsonOf(followed);
        }
      } else if (res.status === 200) {
        payload = jsonOf(res);
      }
      if (payload && typeof payload.csrf === 'string' && payload.csrf) {
        state.csrf = payload.csrf;
        state.ready = true;
        check(res, { 'login accepted': function () { return true; } });
        return true;
      }
    }
  }
  state.ready = false;
  loginFailures.add(1);
  check(state, { 'login succeeded': function () { return false; } });
  return false;
}

function renewSession() {
  const res = http.post(urlFor('/v2/session/renew'), JSON.stringify({}), {
    headers: authHeaders(),
    redirects: 0,
    tags: { name: 'session_renew' },
    responseCallback: EXPECT_RENEW,
  });
  const body = jsonOf(res);
  if (res.status === 200 && body && typeof body.csrf === 'string' && body.csrf) {
    state.csrf = body.csrf;
    return true;
  }
  return false;
}

export function workPool() {
  if (!state.ready && !login()) {
    workUnexpected.add(1);
    return;
  }

  let authRepairs = 0;
  let throttles = 0;

  for (let attempt = 0; attempt < 8; attempt++) {
    const res = http.post(urlFor('/v2/work'), JSON.stringify({}), {
      headers: authHeaders(),
      redirects: 0,
      tags: { name: 'work', pool: 'work' },
      responseCallback: EXPECT_WORK,
    });
    workRaw.add(1);
    const body = jsonOf(res);

    if (res.status === 200) {
      const ok = !!body && body.ok === true;
      businessFailure.add(ok ? 0 : 1);
      check(res, { 'work 200 ok:true': function () { return ok; } });
      if (ok) {
        workOk.add(1);
        if (typeof body.csrf === 'string' && body.csrf) state.csrf = body.csrf;
        return;
      }
      workUnexpected.add(1);
      return;
    }

    if (res.status === 429) {
      const retryAfter = header(res, 'Retry-After');
      const scheduled = retryAfter !== null && retryAfter !== undefined && retryAfter !== '';
      businessFailure.add(scheduled ? 0 : 1);
      if (!scheduled || throttles >= 4) {
        workUnexpected.add(1);
        check(res, { 'work 429 scheduled and within retry budget': function () { return false; } });
        return;
      }
      throttles++;
      const parsed = Number(retryAfter);
      sleep(Math.max(1, isFinite(parsed) && parsed > 0 ? parsed : 1));
      continue;
    }

    if (res.status === 401) {
      const code = errorCode(body);
      if (code === 'expired') {
        businessFailure.add(0); // expected expiry: denominator only
        if (authRepairs >= 1) {
          workUnexpected.add(1);
          check(res, { 'work expiry recovery bounded': function () { return false; } });
          return;
        }
        authRepairs++;
        // No cart belongs to this pool, so no cart recovery call is made.
        if (!renewSession() && !login()) {
          workUnexpected.add(1);
          return;
        }
        continue; // retry the interrupted operation exactly once
      }
      businessFailure.add(1);
      if (code === 'session') {
        if (authRepairs >= 1) {
          workUnexpected.add(1);
          check(res, { 'work revoked-session recovery bounded': function () { return false; } });
          return;
        }
        authRepairs++;
        state.ready = false;
        if (!login()) {
          workUnexpected.add(1);
          return;
        }
        continue;
      }
      // denied (or any other 401) is not expiry: fail the assertion.
      workUnexpected.add(1);
      check(res, { 'work not denied': function () { return false; } });
      return;
    }

    businessFailure.add(1);
    workUnexpected.add(1);
    check(res, { 'work status below 400': function () { return false; } });
    return;
  }

  workUnexpected.add(1);
  check(state, { 'work completed within bounded retries': function () { return false; } });
}
