import os
import re
import time
import html as html_escape
import itertools

import gevent
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task, constant

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")

RATE = 5.0
WARMUP = 5.0
MEASURED = 30.0
TOTAL_SLOTS = int(RATE * (WARMUP + MEASURED))
USERS = 16
SLOT_PAD = 0.06
STOP_AFTER_T0 = WARMUP + MEASURED + 1.0

ACCOUNTS = ["bench"] + ["bench-%d" % i for i in range(1, 17)]
_account_cycle = itertools.count()

_INPUT_RE = re.compile(r"<input\b[^>]*>", re.IGNORECASE)
_ATTR_RE = re.compile(
    r"""([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))"""
)


def extract_csrf(markup):
    if not markup:
        return None
    for tag in _INPUT_RE.findall(markup):
        attrs = {}
        for m in _ATTR_RE.finditer(tag):
            key = m.group(1).lower()
            val = m.group(2)
            if val is None:
                val = m.group(3)
            if val is None:
                val = m.group(4)
            if val is None:
                val = ""
            attrs[key] = html_escape.unescape(val)
        if attrs.get("name", "") == "csrf":
            value = attrs.get("value", "")
            if value:
                return value
    return None


def as_json(resp):
    try:
        data = resp.json()
    except Exception:
        return {}
    if isinstance(data, dict):
        return data
    return {}


class Pacer(object):
    def __init__(self, rate, total):
        self.rate = rate
        self.total = total
        self.index = 0
        self.t0 = None
        self.lock = Semaphore()

    def next_slot(self):
        with self.lock:
            if self.index >= self.total:
                return None
            now = time.monotonic()
            if self.t0 is None:
                self.t0 = now
            i = self.index
            self.index += 1
            when = self.t0 + (i / self.rate)
            if i > 0:
                when += SLOT_PAD
            return when


PACER = Pacer(RATE, TOTAL_SLOTS)


class WorkShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._launch = time.monotonic()

    def tick(self):
        now = time.monotonic()
        t0 = PACER.t0
        if t0 is None:
            if now - self._launch > 12.0:
                return None
            return (USERS, USERS)
        if now >= t0 + STOP_AFTER_T0:
            return None
        return (USERS, USERS)


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.account = ACCOUNTS[next(_account_cycle) % len(ACCOUNTS)]
        self.csrf = None
        self.login()

    def _headers(self):
        return {
            "X-CSRF-Token": self.csrf or "",
            "Accept": "application/json",
        }

    def _keep_csrf(self, data):
        token = data.get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token

    def login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as form:
            if form.status_code != 200:
                form.failure("login-form status %s" % form.status_code)
                return False
            token = extract_csrf(form.text)
            if not token:
                form.failure("login-form csrf missing")
                return False
            form.success()

        payload = {"username": self.account, "password": "bench", "csrf": token}
        with self.client.post(
            "/v2/login",
            json=payload,
            name="/v2/login",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login redirect without Location")
                    return False
                resp.success()
            elif resp.status_code == 200:
                data = as_json(resp)
                self.csrf = data.get("csrf") or token
                if not data.get("user"):
                    resp.failure("login response missing user")
                    return False
                resp.success()
                return True
            else:
                resp.failure("login status %s" % resp.status_code)
                return False

        with self.client.get(
            location,
            name="/v2/login",
            allow_redirects=False,
            catch_response=True,
        ) as landing:
            if landing.status_code != 200:
                landing.failure("login landing status %s" % landing.status_code)
                return False
            data = as_json(landing)
            self.csrf = data.get("csrf") or token
            if not data.get("user"):
                landing.failure("login landing missing user")
                return False
            landing.success()
            return True

    def renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            name="/v2/session/renew",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                self._keep_csrf(as_json(resp))
                resp.success()
                return True
            if resp.status_code == 401:
                resp.success()
                return False
            resp.failure("renew status %s" % resp.status_code)
            return False

    def work_once(self):
        with self.client.post(
            "/v2/work",
            json={},
            headers=self._headers(),
            name="/v2/work",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            status = resp.status_code
            data = as_json(resp)
            if status == 200 and data.get("ok") is True:
                self._keep_csrf(data)
                resp.success()
                return ("ok", 0.0)
            if status == 429:
                resp.success()
                raw = resp.headers.get("Retry-After", "1")
                try:
                    delay = float(raw)
                except (TypeError, ValueError):
                    delay = 1.0
                if delay < 1.0:
                    delay = 1.0
                return ("throttled", delay)
            if status == 401:
                err = data.get("error")
                if err == "expired":
                    resp.success()
                    return ("expired", 0.0)
                if err == "session":
                    resp.success()
                    return ("revoked", 0.0)
                resp.failure("work 401 error=%s" % err)
                return ("fail", 0.0)
            resp.failure("work status %s" % status)
            return ("fail", 0.0)

    def do_work(self):
        auth_recovered = False
        throttles = 0
        while True:
            outcome, delay = self.work_once()
            if outcome == "ok" or outcome == "fail":
                return
            if outcome == "throttled":
                if throttles >= 4:
                    return
                throttles += 1
                gevent.sleep(delay)
                continue
            if auth_recovered:
                return
            auth_recovered = True
            if outcome == "expired":
                if not self.renew():
                    if not self.login():
                        return
                continue
            if outcome == "revoked":
                if not self.login():
                    return
                continue
            return

    @task
    def paced_work(self):
        while True:
            when = PACER.next_slot()
            if when is None:
                t0 = PACER.t0
                if t0 is not None:
                    remaining = (t0 + WARMUP + MEASURED + 0.5) - time.monotonic()
                    if remaining > 0:
                        gevent.sleep(remaining)
                raise StopUser()
            delay = when - time.monotonic()
            if delay > 0:
                gevent.sleep(delay)
            self.do_work()
