import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final AtomicInteger SEQ = new AtomicInteger(0);

    private static final String CSRF_PATTERN =
            "<input(?=[^>]*\\sname\\s*=\\s*[\"']csrf[\"'])[^>]*\\svalue\\s*=\\s*[\"']([^\"']+)[\"']";

    private static String envOr(String key, String fallback) {
        String v = System.getenv(key);
        return (v == null || v.trim().isEmpty()) ? fallback : v.trim();
    }

    private static double targetRate() {
        String raw = envOr("RATE", envOr("TARGET_RATE", envOr("WORKLOAD_RATE", envOr("TARGET_RPS", "5"))));
        double r;
        try {
            r = Double.parseDouble(raw);
        } catch (NumberFormatException e) {
            r = 5.0;
        }
        if (r <= 0.0 || r > 100.0) {
            r = 5.0;
        }
        return r;
    }

    private static String nonEmpty(Session s, String... keys) {
        for (String k : keys) {
            if (s.contains(k)) {
                String v = s.getString(k);
                if (v != null && !v.isEmpty()) {
                    return v;
                }
            }
        }
        return "";
    }

    private static Session classifyWork(Session s) {
        String fresh = nonEmpty(s, "workCsrf");
        Session out = s;
        if (!fresh.isEmpty()) {
            out = out.set("csrf", fresh);
        }
        int status = out.contains("workStatus") ? out.getInt("workStatus") : -1;
        String error = nonEmpty(s, "workError");
        int authRetries = out.contains("authRetries") ? out.getInt("authRetries") : 0;

        boolean done = true;
        String recover = "none";

        if (status == 429) {
            done = false;
            recover = "throttle";
        } else if (status == 401
                && ("expired".equals(error) || "session".equals(error))
                && authRetries < 1) {
            done = false;
            recover = error;
            authRetries = authRetries + 1;
        }

        return out.set("workDone", done)
                .set("recover", recover)
                .set("authRetries", authRetries)
                .set("workCsrf", "")
                .set("workError", "");
    }

    private static final ChainBuilder LOGIN =
            exec(s -> s.set("formCss", "")
                    .set("formRe", "")
                    .set("loginStatus", 0)
                    .set("loginLocation", "")
                    .set("loginCsrf", "")
                    .set("loginUser", ""))
            .exec(http("login-form")
                    .get("/v2/login-form")
                    .header("Accept", "text/html")
                    .check(status().is(200))
                    .check(css("input[name=csrf]", "value").find().optional().saveAs("formCss"))
                    .check(regex(CSRF_PATTERN).find().optional().saveAs("formRe")))
            .exec(s -> {
                String token = nonEmpty(s, "formCss", "formRe");
                if (token.isEmpty()) {
                    throw new IllegalStateException("login-form: csrf input not found");
                }
                return s.set("csrf", token);
            })
            .exec(http("login")
                    .post("/v2/login")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                    .asJson()
                    .check(status().in(200, 302))
                    .check(status().saveAs("loginStatus"))
                    .check(header("Location").find().optional().saveAs("loginLocation"))
                    .check(jsonPath("$.csrf").find().optional().saveAs("loginCsrf"))
                    .check(jsonPath("$.user").find().optional().saveAs("loginUser")))
            .doIf(s -> s.getInt("loginStatus") == 302 && !nonEmpty(s, "loginLocation").isEmpty())
            .then(exec(http("login-redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").find().optional().saveAs("loginCsrf"))
                    .check(jsonPath("$.user").find().optional().saveAs("loginUser"))))
            .exec(s -> {
                String token = nonEmpty(s, "loginCsrf");
                String user = nonEmpty(s, "loginUser");
                if (token.isEmpty() && user.isEmpty()) {
                    throw new IllegalStateException("login did not establish a session");
                }
                return token.isEmpty() ? s : s.set("csrf", token);
            });

    private static final ChainBuilder RENEW =
            exec(s -> s.set("renewCsrf", ""))
            .exec(http("session-renew")
                    .post("/v2/session/renew")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .asJson()
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").find().optional().saveAs("renewCsrf")))
            .exec(s -> {
                String token = nonEmpty(s, "renewCsrf");
                return token.isEmpty() ? s : s.set("csrf", token);
            });

    private static final ChainBuilder WORK =
            exec(http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .asJson()
                    .check(status().saveAs("workStatus"))
                    .check(status().in(200, 401, 429))
                    .check(jsonPath("$.ok").find().optional().is("true"))
                    .check(jsonPath("$.error").find().optional().not("denied"))
                    .check(jsonPath("$.csrf").find().optional().saveAs("workCsrf"))
                    .check(jsonPath("$.error").find().optional().saveAs("workError")));

    public ModelSimulation() {
        double rate = targetRate();
        int users = (int) Math.max(1L, Math.min(32L, (long) Math.ceil(rate)));
        long periodMs = Math.max(250L, Math.round((users * 1000.0) / rate));
        int iterations = (int) Math.ceil(35000.0 / periodMs) + 1;

        HttpProtocolBuilder protocol = http
                .baseUrl(envOr("BASE_URL", "http://127.0.0.1:8000"))
                .disableFollowRedirect()
                .disableCaching()
                .acceptHeader("*/*")
                .acceptLanguageHeader("en-US,en;q=0.9")
                .userAgentHeader("model-work-pool")
                .connectionHeader("keep-alive");

        ChainBuilder attempt =
                exec(s -> s.set("attempt", s.getInt("attempt") + 1)
                        .set("workStatus", -1)
                        .set("workCsrf", "")
                        .set("workError", ""))
                .exec(WORK)
                .exec(s -> classifyWork(s))
                .doIf(s -> "expired".equals(s.getString("recover"))).then(RENEW)
                .doIf(s -> "session".equals(s.getString("recover"))).then(LOGIN)
                .doIf(s -> "throttle".equals(s.getString("recover"))).then(pause(Duration.ofSeconds(1)));

        ChainBuilder iteration =
                exec(s -> s.set("attempt", 0)
                        .set("workDone", false)
                        .set("authRetries", 0)
                        .set("recover", "none")
                        .set("workStatus", -1)
                        .set("workCsrf", "")
                        .set("workError", ""))
                .asLongAs(s -> !s.getBoolean("workDone") && s.getInt("attempt") < 5).on(attempt)
                .pace(Duration.ofMillis(periodMs));

        ScenarioBuilder scn = scenario("work-pool")
                .exec(s -> s.set("username", "bench-" + ((SEQ.getAndIncrement() % 16) + 1))
                        .set("csrf", ""))
                .exec(LOGIN)
                .repeat(iterations).on(iteration);

        setUp(scn.injectOpen(rampUsers(users).during(Duration.ofMillis(periodMs))))
                .protocols(protocol)
                .maxDuration(Duration.ofSeconds(80))
                .assertions(global().successfulRequests().count().gt(0L));
    }
}
