// k6 1.0.0 — sustained authenticated POST /v2/work at 5 starts/s against a 200ms server.
// Only declared pool route: POST /v2/work. Login / renewal are setup, never operations.
import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Counter, Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = __ENV.BENCH_PASSWORD || 'bench';
const TARGET_RATE = 5;

const ACCOUNTS = [];
for (let i = 1; i <= 16; i++) ACCOUNTS.push('bench-' + i);
ACCOUNTS.push('bench');

const workOk = new Counter('work_ok');
const workUnexpected = new Counter('work_unexpected');
const workDropped = new Counter('work_dropped');
// numerator = unexpected failures (expected expiry / scheduled 429 excluded)
// denominator = every raw /v2/work business response
const businessFailure = new Rate('business_failure');

export const options = {
  discardResponseBodies: false,
  noConnectionReuse: false,
  scenarios: {
    work_pool: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: 8,   // 3x target (15/s * 0.2s = 3 VUs) fits with headroom
      maxVUs: 16,           // hard bound, well under the 32 VU ceiling
      gracefulStop: '5s',
      exec: 'work',
    },
  },
};

/* ------------------------------ per-VU state ------------------------------ */
let csrf = null;
let loggedIn = false;
let account = null;

function currentAccount() {
  if (account === null) {
    let id = 1;
    try { id = exec.vu.idInTest || 1; } catch (e) { id = 1; }
    account = ACCOUNTS[(id - 1) % ACCOUNTS.length];
  }
  return account;
}

/* --------------------------------- helpers -------------------------------- */
function safeJson(res) {
  if (!res || !res.body) return null;
  try {
    const j = res.json();
    return j && typeof j === 'object' ? j : null;
  } catch (e) { /* not JSON */ }
  try {
    const j = JSON.parse(String(res.body));
    return j && typeof j === 'object' ? j : null;
  } catch (e) { return null; }
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const want = name.toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === want) return res.headers[keys[i]];
  }
  return null;
}

function isRedirect(res) {
  return !!res && res.status >= 300 && res.status < 400 && !!header(res, 'Location');
}

function absolute(loc) {
  if (!loc) return null;
  const raw = String(loc).trim();
  if (/^https?:\/\//i.test(raw)) return raw.indexOf(BASE_URL) === 0 ? raw : null;
  if (raw.charAt(0) === '/') return BASE_URL + raw;
  return BASE_URL + '/' + raw;
}

function jsonHeaders(token) {
  const h = { 'Content-Type': 'application/json', Accept: 'application/json, text/html;q=0.9' };
  if (token) h['X-CSRF-Token'] = String(token);
  return h;
}

function decodeEntities(s) {
  if (s === null || s === undefined) return '';
  let out = String(s);
  out = out.replace(/&#x([0-9a-fA-F]+);/g, function (_, h) {
    const c = parseInt(h, 16); return isNaN(c) ? '' : String.fromCharCode(c);
  });
  out = out.replace(/&#(\d+);/g, function (_, d) {
    const c = parseInt(d, 10); return isNaN(c) ? '' : String.fromCharCode(c);
  });
  out = out.replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
  return out.trim();
}

const TAG_RE = /<(input|meta|form)\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;
const ATTR_RE = /([a-zA-Z_:][-\w:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+))/g;

function parseAttrs(tag) {
  const out = {};
  let m;
  ATTR_RE.lastIndex = 0;
  while ((m = ATTR_RE.exec(tag)) !== null) {
    const k = m[1].toLowerCase();
    let v = m[2];
    if (v === undefined) v = m[3];
    if (v === undefined) v = m[4];
    if (v === undefined) v = '';
    if (!Object.prototype.hasOwnProperty.call(out, k)) out[k] = decodeEntities(v);
  }
  if (/(?:\s)disabled(?:\s|=|>|\/|$)/i.test(tag) && !Object.prototype.hasOwnProperty.call(out, 'disabled')) {
    out.disabled = '';
  }
  return out;
}

function looksDecoy(attrs) {
  const keys = Object.keys(attrs);
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    if (k === 'value') continue;
    if (/decoy|dummy|fake|trap|bogus/i.test(k + '=' + attrs[k])) return true;
  }
  return /decoy|dummy|fake|trap|bogus|placeholder|changeme/i.test(String(attrs.value || ''));
}

function csrfCandidates(scope) {
  const found = [];
  let m;
  TAG_RE.lastIndex = 0;
  while ((m = TAG_RE.exec(scope)) !== null) {
    const tag = m[0];
    const kind = m[1].toLowerCase();
    const a = parseAttrs(tag);
    if (kind === 'input') {
      if (String(a.name || '') !== 'csrf') continue;
      if (Object.prototype.hasOwnProperty.call(a, 'disabled')) continue;
      if (String(a.type || '').toLowerCase() === 'submit') continue;
      if (!a.value) continue;
      let score = 0;
      if (String(a.type || '').toLowerCase() === 'hidden') score += 4;
      if (!looksDecoy(a)) score += 6;
      score += Math.min(String(a.value).length, 64) / 100;
      found.push({ value: a.value, score: score });
    } else if (kind === 'meta') {
      if (String(a.name || '').toLowerCase() !== 'csrf') continue;
      const v = a.content || a.value;
      if (!v) continue;
      found.push({ value: v, score: looksDecoy(a) ? 0 : 2 });
    }
  }
  return found;
}

function bestOf(list) {
  let best = null;
  for (let i = 0; i < list.length; i++) {
    if (best === null || list[i].score > best.score) best = list[i];
  }
  return best ? best.value : null;
}

function extractCsrf(body) {
  if (body === null || body === undefined) return null;
  const text = String(body);
  const j = safeJson({ body: text, json: function () { return JSON.parse(text); } });
  if (j && j.csrf) return String(j.csrf);

  // Prefer inputs inside the real login form; decoy forms are deprioritised.
  const formRe = /<form\b(?:[^>"']|"[^"]*"|'[^']*')*>[\s\S]*?<\/form>/gi;
  const forms = text.match(formRe) || [];
  const ranked = [];
  for (let i = 0; i < forms.length; i++) {
    const open = forms[i].match(/<form\b(?:[^>"']|"[^"]*"|'[^']*')*>/i);
    const a = open ? parseAttrs(open[0]) : {};
    const action = String(a.action || '');
    let bonus = 0;
    if (/\/v2\/login/i.test(action)) bonus += 5;
    if (/decoy|dummy|fake|trap/i.test(action) || looksDecoy(a)) bonus -= 8;
    ranked.push({ body: forms[i], bonus: bonus });
  }
  ranked.sort(function (x, y) { return y.bonus - x.bonus; });
  for (let i = 0; i < ranked.length; i++) {
    const cands = csrfCandidates(ranked[i].body);
    for (let k = 0; k < cands.length; k++) cands[k].score += ranked[i].bonus;
    const pick = bestOf(cands);
    if (pick) return pick;
  }
  return bestOf(csrfCandidates(text));
}

/* ------------------------------ authentication ---------------------------- */
function doLogin() {
  const user = currentAccount();
  let formRes = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    tags: { route: 'login_form' },
  });
  if (isRedirect(formRes)) {
    const loc = absolute(header(formRes, 'Location'));
    if (!loc) {
      check(formRes, { 'login form reachable': function () { return false; } });
      return false;
    }
    formRes = http.get(loc, { redirects: 0, tags: { route: 'login_form' } });
  }
  const formToken = extractCsrf(formRes.body);
  const formOk = check(formRes, {
    'login form 200 + input[name=csrf]': function (r) { return r.status === 200 && !!formToken; },
  });
  if (!formOk || !formToken) return false;

  let res = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({ username: user, password: PASSWORD, csrf: formToken }),
    { headers: jsonHeaders(formToken), redirects: 0, tags: { route: 'login' } }
  );
  if (isRedirect(res)) {
    const loc = absolute(header(res, 'Location'));
    if (!loc) {
      check(res, { 'login session established': function () { return false; } });
      return false;
    }
    res = http.get(loc, { redirects: 0, tags: { route: 'login_redirect' } });
  }
  const j = safeJson(res);
  const token = j && j.csrf ? String(j.csrf) : null;
  const ok = check(res, {
    'login session established': function (r) { return r.status === 200 && !!token; },
  });
  if (!ok) return false;
  csrf = token;
  loggedIn = true;
  return true;
}

function renewSession() {
  const res = http.post(BASE_URL + '/v2/session/renew', JSON.stringify({}), {
    headers: jsonHeaders(csrf),
    redirects: 0,
    tags: { route: 'session_renew' },
  });
  const j = safeJson(res);
  if (res.status === 200 && j && j.csrf) {
    csrf = String(j.csrf);
    return true;
  }
  if (res.status === 200 && j && j.ok === true) return true;
  return false;
}

/* --------------------------------- workload -------------------------------- */
function callWork() {
  let authRetried = false;   // at most one retry of the interrupted operation
  let rateRetries = 0;       // at most four scheduled-429 retries

  for (let attempt = 0; attempt < 7; attempt++) {
    const res = http.post(BASE_URL + '/v2/work', JSON.stringify({}), {
      headers: jsonHeaders(csrf),
      redirects: 0,
      tags: { route: 'work' },
    });
    const j = safeJson(res);
    const err = j && j.error ? String(j.error) : '';
    const success = res.status === 200 && !!j && j.ok === true;
    const expectedExpiry = res.status === 401 && (err === 'expired' || err === 'session');
    const scheduled429 = res.status === 429;

    // one point per raw /v2/work response; expected expiry / scheduled 429 excluded
    businessFailure.add(!success && !expectedExpiry && !scheduled429);

    if (success) {
      if (j.csrf) csrf = String(j.csrf); // retain previous token when absent
      check(res, { 'work 200 ok:true': function (r) { return r.status === 200; } });
      return true;
    }

    if (scheduled429) {
      const ra = header(res, 'Retry-After');
      check(res, { 'scheduled 429 carries Retry-After': function () { return !!ra; } });
      if (rateRetries < 4 && ra) {
        rateRetries++;
        let wait = parseFloat(ra);
        if (isNaN(wait) || wait < 1) wait = 1;
        sleep(Math.min(wait, 5));
        continue;
      }
      workUnexpected.add(1);
      check(res, { 'work 200 ok:true': function () { return false; } });
      return false;
    }

    if (expectedExpiry && !authRetried) {
      authRetried = true;
      if (err === 'expired') {
        if (!renewSession() && !doLogin()) {
          workUnexpected.add(1);
          check(res, { 'work 200 ok:true': function () { return false; } });
          return false;
        }
      } else {
        // revoked session: renew is useless, take a fresh form/login
        loggedIn = false;
        if (!doLogin()) {
          workUnexpected.add(1);
          check(res, { 'work 200 ok:true': function () { return false; } });
          return false;
        }
      }
      continue; // retry the interrupted operation exactly once, no checkout restart
    }

    if (res.status === 401 && err === 'denied') {
      check(res, { 'work denied is not expiry (must fail)': function () { return false; } });
    } else {
      check(res, { 'work 200 ok:true': function () { return false; } });
    }
    workUnexpected.add(1);
    return false;
  }

  workUnexpected.add(1);
  return false;
}

export function work() {
  if (!loggedIn && !doLogin()) {
    workDropped.add(1);
    return;
  }
  if (callWork()) {
    workOk.add(1);
  } else {
    workDropped.add(1);
  }
}

export default function () {
  work();
}
