Only the declared pool operation (/v2/work) is exercised as business work.
Login-form / login / session-renew are used solely to obtain and keep a valid
authenticated session; they are never counted as operations by the harness.
No catalog, cart, order, challenge, reservation, browse or health calls.
"""

import json
import os
import re
import time
from html.parser import HTMLParser
from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")

TARGET_RATE = 5.0
INTERVAL = 1.0 / TARGET_RATE
USER_COUNT = 10                 # far below the 32 virtual-user ceiling
SPAWN_RATE = 20.0
SHAPE_SECONDS = 38.0            # T0 (<~1.5s) + 35s scored + short drain
SCORE_END_OFFSET = 35.4         # stop issuing work just past the scored window

ACCOUNTS = ["bench-%d" % i for i in range(1, 17)] + ["bench"]
PASSWORD = "bench"

# Cooperative (gevent) shared state: every mutation below happens without an
# intervening yield, so slot claiming is atomic between greenlets.
_sched = {"anchor": None, "next": 0.0, "deadline": None}
_seq = {"n": 0}


def _claim_slot():
    """Reserve the next absolute start instant for one work operation."""
    now = time.monotonic()
    if _sched["anchor"] is None:
        _sched["anchor"] = now
        _sched["next"] = now
        _sched["deadline"] = now + SCORE_END_OFFSET
    if now >= _sched["deadline"]:
        return None
    if _sched["next"] < now - INTERVAL:
        # Far behind (never expected with this pool): resynchronise instead of
        # emitting a catch-up burst.
        _sched["next"] = now
    slot = _sched["next"]
    if slot >= _sched["deadline"]:
        return None
    _sched["next"] = slot + INTERVAL
    return slot


def _payload(resp):
    try:
        data = resp.json()
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def _retry_after(value):
    try:
        return max(1.0, float(value))
    except (TypeError, ValueError):
        return 1.0


class _CsrfParser(HTMLParser):
    """input[name=csrf] extraction tolerant of attribute order/quoting/decoys."""

    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.good = []
        self.marked = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        a = {}
        for key, val in attrs:
            if key is None:
                continue
            a[key.lower()] = val if val is not None else ""
        if a.get("name", "").strip() != "csrf":
            return
        value = a.get("value", "")
        if not value:
            return
        hint = " ".join(
            "%s=%s" % (k, v)
            for k, v in a.items()
            if k in ("id", "class", "data-role", "data-decoy", "data-kind", "rel")
        ).lower()
        if "decoy" in hint or "dummy" in hint or "fake" in hint or "trap" in hint:
            self.marked.append(value)
        else:
            self.good.append(value)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


_TAG_RE = re.compile(r"<input\b[^>]*>", re.IGNORECASE)
_NAME_RE = re.compile(r"""\bname\s*=\s*("csrf"|'csrf'|csrf)(?=[\s/>])""", re.IGNORECASE)
_VALUE_RE = re.compile(
    r"""\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))""", re.IGNORECASE
)


def extract_csrf(text):
    if not text:
        return None
    parser = _CsrfParser()
    try:
        parser.feed(text)
        parser.close()
    except Exception:
        pass
    if parser.good:
        return parser.good[0]
    for tag in _TAG_RE.findall(text):
        if not _NAME_RE.search(tag):
            continue
        match = _VALUE_RE.search(tag)
        if match:
            value = match.group(1) or match.group(2) or match.group(3) or ""
            if value:
                return value
    if parser.marked:
        return parser.marked[0]
    data = None
    try:
        data = json.loads(text)
    except Exception:
        data = None
    if isinstance(data, dict) and data.get("csrf"):
        return data["csrf"]
    return None


class WorkUser(HttpUser):
    """One virtual user = one persistent cookie jar / one authenticated owner."""

    host = BASE_URL
    wait_time = constant(0)
    abstract = False

    def on_start(self):
        index = _seq["n"]
        _seq["n"] = index + 1
        self.account = ACCOUNTS[index % len(ACCOUNTS)]
        self.csrf = None
        self._login()

    # ---------------------------------------------------------------- helpers

    def _headers(self):
        return {"X-CSRF-Token": self.csrf or ""}

    def _absorb(self, body):
        token = body.get("csrf") if isinstance(body, dict) else None
        if token:
            self.csrf = token

    def _login(self):
        """Fresh login-form + login for this session. Never counted as work."""
        token = None
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            catch_response=True,
        ) as resp:
            if resp.status_code >= 400:
                resp.failure("login-form status %s" % resp.status_code)
                return False
            token = extract_csrf(resp.text)
            if not token:
                resp.failure("login-form: no input[name=csrf]")
                return False
            resp.success()

        body = {}
        location = None
        with self.client.post(
            "/v2/login",
            json={"username": self.account, "password": PASSWORD, "csrf": token},
            name="/v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            status = resp.status_code
            if status in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login redirect without Location")
                    return False
                resp.success()
            elif status >= 400:
                resp.failure("login status %s" % status)
                return False
            else:
                body = _payload(resp)
                if not body.get("csrf"):
                    resp.failure("login response missing csrf")
                    return False
                self.csrf = body["csrf"]
                resp.success()
                return True

        url = location if location.startswith("http") else urljoin(BASE_URL + "/", location)
        with self.client.get(
            url,
            name="/v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code >= 400:
                resp.failure("login redirect target status %s" % resp.status_code)
                return False
            body = _payload(resp)
            fresh = body.get("csrf") or extract_csrf(resp.text)
            if not fresh:
                resp.failure("login redirect target missing csrf")
                return False
            self.csrf = fresh
            resp.success()
            return True

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            name="/v2/session/renew",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            body = _payload(resp)
            if resp.status_code < 400:
                self._absorb(body)
                resp.success()
                return True
            if resp.status_code == 401 and body.get("error") in ("expired", "session"):
                # Controlled revocation: renew is allowed to fail.
                resp.success()
                return False
            resp.failure("renew status %s" % resp.status_code)
            return False

    # ------------------------------------------------------------ pool sample

    def _perform_work(self):
        throttles = 0
        recovery_used = False
        while True:
            with self.client.post(
                "/v2/work",
                json={},
                headers=self._headers(),
                name="/v2/work",
                catch_response=True,
                allow_redirects=False,
            ) as resp:
                status = resp.status_code
                body = _payload(resp)
                self._absorb(body)

                if status == 429:
                    # Scheduled throttle: expected, not a failed sample.
                    resp.success()
                    if throttles >= 4:
                        return
                    throttles += 1
                    time.sleep(min(2.0, _retry_after(resp.headers.get("Retry-After"))))
                    continue

                if status == 401:
                    error = body.get("error")
                    if error == "denied":
                        resp.failure("401 denied on /v2/work")
                        return
                    if error in ("expired", "session"):
                        # Expected controlled expiry/revocation.
                        resp.success()
                        if recovery_used:
                            return
                        recovery_used = True
                        if error == "expired":
                            ok = self._renew()
                            if not ok:
                                ok = self._login()
                        else:
                            ok = self._login()
                        if not ok:
                            return
                        # Retry only the interrupted operation, exactly once.
                        continue
                    resp.failure("401 (%s) on /v2/work" % error)
                    return

                if status >= 400:
                    resp.failure("unexpected /v2/work status %s" % status)
                    return

                if status == 200 and body.get("ok") is True:
                    resp.success()
                    return

                resp.failure("/v2/work not ok (status %s)" % status)
                return

    @task
    def work(self):
        if not self.csrf:
            if not self._login():
                time.sleep(0.5)
                raise StopUser()
        slot = _claim_slot()
        if slot is None:
            raise StopUser()
        delay = slot - time.monotonic()
        if delay > 0:
            time.sleep(delay)
        self._perform_work()


class WorkShape(LoadTestShape):
    """Fixed, bounded population; ends the run by returning None."""

    def __init__(self):
        LoadTestShape.__init__(self)
        self._started = None

    def tick(self):
        now = time.monotonic()
        if self._started is None:
            self._started = now
        if now - self._started >= SHAPE_SECONDS:
            return None
        return USER_COUNT, SPAWN_RATE
