import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.core.Simulation;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

/**
 * Pool: POST /v2/work only (login/renew are setup, never operations).
 * Pacing: one open-model arrival == one authenticated work start.
 * constantUsersPerSec(8) is evenly spaced (125ms), so 1s bursts stay ~8 (cap 13),
 * and pacing is coordinated globally by the injection profile, not per user.
 */
public class ModelSimulation extends Simulation {

    private static final double TARGET = 8.0;
    private static final Duration INJECT_FOR = Duration.ofSeconds(37); // warmup 5 + scored 30 + small tail
    private static final Duration HARD_STOP = Duration.ofSeconds(46);

    // real csrf input: name attribute must be exactly csrf (rejects data-name / csrf_x / csrf-x decoys)
    private static final String FORM_CSRF =
            "(?is)<input\\b(?=[^>]*\\sname\\s*=\\s*[\"']?csrf[\"']?(?![\\w-]))[^>]*?\\svalue\\s*=\\s*[\"']?([^\"'\\s>]+)";
    private static final String JSON_CSRF = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";
    private static final String JSON_ERROR = "\"error\"\\s*:\\s*\"([^\"]+)\"";
    private static final String OK_TRUE = "\"ok\"\\s*:\\s*true";
    // business failure only: ok:false with no error/retry marker (scheduled 429 / expiry stay non-failures)
    private static final String OK_FALSE =
            "(?s)^(?!.*(?:\"error\"|retry|throttl|rate_limit|ratelimit)).*\"ok\"\\s*:\\s*false";
    private static final String DENIED = "\"error\"\\s*:\\s*\"denied\"";

    private static String base() {
        String env = System.getenv("BASE_URL");
        String v = (env == null || env.trim().isEmpty()) ? "http://127.0.0.1:8000" : env.trim();
        while (v.endsWith("/")) v = v.substring(0, v.length() - 1);
        return v;
    }

    private static boolean ok(Session s) {
        return s.contains("workOk");
    }

    private static boolean throttled(Session s) {
        return !ok(s) && s.contains("retryAfter");
    }

    private static boolean errored(Session s) {
        return !ok(s) && !s.contains("retryAfter") && s.contains("workError");
    }

    private static boolean unexpected(Session s) {
        return !ok(s) && !s.contains("retryAfter") && !s.contains("workError");
    }

    private static boolean recoverable(Session s) {
        String e = s.getString("workError");
        return "expired".equals(e) || "session".equals(e);
    }

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(base())
            .disableFollowRedirect()
            .disableCaching()
            .acceptHeader("application/json, text/html;q=0.9, */*;q=0.8")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-work-pool");

    // fresh login per journey (also used as bounded recovery for revoked sessions)
    private final ChainBuilder login =
            exec(s -> s.remove("loginLocation"))
                    .exec(http("login_form")
                            .get("/v2/login-form")
                            .check(status().is(200))
                            .check(regex(FORM_CSRF).saveAs("csrf")))
                    .exec(http("login")
                            .post("/v2/login")
                            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                            .check(status().in(200, 302))
                            .check(header("Location").optional().saveAs("loginLocation"))
                            .check(regex(JSON_CSRF).optional().saveAs("csrf")))
                    .doIf(s -> s.contains("loginLocation")).then(
                            exec(http("login_redirect")
                                    .get("#{loginLocation}")
                                    .check(status().is(200))
                                    .check(regex(JSON_CSRF).optional().saveAs("csrf"))
                                    .check(regex(FORM_CSRF).optional().saveAs("csrf"))));

    // renewal is never an operation; fall back to a fresh login if no fresh token came back
    private final ChainBuilder renew =
            exec(s -> s.set("prevCsrf", s.getString("csrf")))
                    .exec(http("renew")
                            .post("/v2/session/renew")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody("{}"))
                            .check(status().in(200, 401))
                            .check(regex(JSON_CSRF).optional().saveAs("csrf")))
                    .doIf(s -> s.getString("csrf") == null
                            || s.getString("csrf").equals(s.getString("prevCsrf"))).then(login);

    // one raw response == one native sample; 401 expiry / scheduled 429 are not failures
    private final ChainBuilder work =
            exec(http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().in(200, 401, 429))
                    .check(regex(DENIED).notExists())
                    .check(regex(OK_FALSE).notExists())
                    .check(regex(OK_TRUE).optional().saveAs("workOk"))
                    .check(regex(JSON_ERROR).optional().saveAs("workError"))
                    .check(header("Retry-After").optional().saveAs("retryAfter"))
                    .check(regex(JSON_CSRF).optional().saveAs("csrf")));

    private final ChainBuilder journey =
            exec(s -> s
                    .set("username", "bench-" + (1 + (int) (s.userId() % 16L)))
                    .set("done", 0)
                    .set("tries", 0)
                    .set("throttleRetries", 0)
                    .set("recoveries", 0))
                    .exec(login)
                    .asLongAs(s -> s.getInt("done") == 0 && s.getInt("tries") < 6).on(
                            exec(s -> s.set("tries", s.getInt("tries") + 1)
                                    .remove("workOk")
                                    .remove("workError")
                                    .remove("retryAfter"))
                                    .exec(work)
                                    .doIf(ModelSimulation::ok).then(exec(s -> s.set("done", 1)))
                                    .doIf(ModelSimulation::throttled).then(
                                            exec(s -> s.set("throttleRetries", s.getInt("throttleRetries") + 1))
                                                    .doIf(s -> s.getInt("throttleRetries") > 4)
                                                    .then(exec(s -> s.set("done", 1)))
                                                    .doIf(s -> s.getInt("throttleRetries") <= 4)
                                                    .then(pause(Duration.ofSeconds(1))))
                                    .doIf(ModelSimulation::errored).then(
                                            exec(s -> s.set("recoveries", s.getInt("recoveries") + 1))
                                                    .doIf(s -> s.getInt("recoveries") <= 2
                                                            && "expired".equals(s.getString("workError"))).then(renew)
                                                    .doIf(s -> s.getInt("recoveries") <= 2
                                                            && "session".equals(s.getString("workError"))).then(login)
                                                    .doIf(s -> s.getInt("recoveries") > 2 || !recoverable(s))
                                                    .then(exec(s -> s.set("done", 1))))
                                    .doIf(ModelSimulation::unexpected).then(exec(s -> s.set("done", 1))))
                    .exitHereIfFailed();

    private final ScenarioBuilder scn = scenario("work_pool_8_starts_per_sec").exec(journey);

    {
        setUp(scn.injectOpen(constantUsersPerSec(TARGET).during(INJECT_FOR)))
                .protocols(httpProtocol)
                .maxDuration(HARD_STOP)
                .assertions(global().failedRequests().percent().lte(5.0));
    }
}
