// k6 1.0.0 — pool: work (POST /v2/work only)
// Global arrival pacing: 8 operation starts/s, evenly spaced 125ms slots shared
// across all VUs via the scenario-wide iteration index. No idle/flood cycles.
import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Rate, Counter } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const USER_COUNT = 16;

const TARGET_RATE = 8;            // counted operation starts per second
const WORK_PER_JOURNEY = 2;       // fresh login per journey, then paced work ops
const SLOT_MS = 1000 / TARGET_RATE;               // 125ms between work starts
const JOURNEY_MS = SLOT_MS * WORK_PER_JOURNEY;    // 250ms between journey arrivals
const FIRST_OFFSET_MS = 90;       // head-room for login before first work slot

const businessFailure = new Rate('business_failure');
const workAccepted = new Counter('work_accepted');
const journeyLost = new Counter('journey_lost');

export const options = {
  discardResponseBodies: false,
  insecureSkipTLSVerify: true,
  noVUConnectionReuse: false,
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)', 'p(99)'],
  scenarios: {
    work_pool: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE / WORK_PER_JOURNEY,
      timeUnit: '1s',
      duration: '37s',
      preAllocatedVUs: 16,
      maxVUs: 16,
      gracefulStop: '3s',
      exec: 'workJourney',
    },
  },
};

// Protocol-declared conditions (scheduled 429, expiry/revocation 401) are expected
// transport outcomes; truthfulness is kept by checks + business_failure below.
http.setResponseCallback(http.expectedStatuses({ min: 200, max: 399 }, 401, 429));

/* ------------------------------- helpers -------------------------------- */

function headerOf(res, name) {
  if (!res || !res.headers) return null;
  if (res.headers[name] !== undefined) return res.headers[name];
  const lower = String(name).toLowerCase();
  for (const k in res.headers) {
    if (String(k).toLowerCase() === lower) return res.headers[k];
  }
  return null;
}

function jsonOf(res) {
  if (!res || !res.body) return null;
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return null;
  }
}

function absUrl(loc) {
  const s = String(loc);
  if (/^https?:\/\//i.test(s)) return s;
  if (s.charAt(0) === '/') return BASE_URL + s;
  return BASE_URL + '/' + s;
}

function decodeEntities(s) {
  return String(s)
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#0*39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

function attrsOf(tag) {
  const out = {};
  const re = /([A-Za-z_:][-A-Za-z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'`=<>]+)))?/g;
  let m;
  while ((m = re.exec(tag)) !== null) {
    const key = m[1].toLowerCase();
    let val = '';
    if (m[2] !== undefined) val = m[2];
    else if (m[3] !== undefined) val = m[3];
    else if (m[4] !== undefined) val = m[4];
    if (!(key in out)) out[key] = decodeEntities(val);
  }
  return out;
}

function isDecoy(attrs) {
  if ('disabled' in attrs) return true;
  for (const k in attrs) {
    if (k.indexOf('decoy') >= 0) return true;
    if (String(attrs[k]).toLowerCase().indexOf('decoy') >= 0) return true;
  }
  return false;
}

function csrfInputIn(scope) {
  const cands = [];
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(scope)) !== null) {
    const a = attrsOf(m[0]);
    if ((a.name || '') !== 'csrf') continue;
    if (!a.value) continue;
    if (isDecoy(a)) continue;
    const type = (a.type || '').toLowerCase();
    cands.push({ v: a.value, rank: type === 'hidden' ? 0 : 1 });
  }
  if (cands.length > 0) {
    cands.sort(function (x, y) { return x.rank - y.rank; });
    return cands[0].v;
  }
  const metaRe = /<meta\b[^>]*>/gi;
  while ((m = metaRe.exec(scope)) !== null) {
    const a = attrsOf(m[0]);
    const nm = (a.name || a.property || '').toLowerCase();
    if (nm === 'csrf' && a.content && !isDecoy(a)) return a.content;
  }
  return null;
}

function csrfFromMarkup(markup, actionHint) {
  const clean = String(markup)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<template\b[\s\S]*?<\/template\s*>/gi, ' ');
  const scopes = [];
  const formRe = /<form\b[^>]*>[\s\S]*?<\/form\s*>/gi;
  let fm;
  while ((fm = formRe.exec(clean)) !== null) {
    const chunk = fm[0];
    const openEnd = chunk.indexOf('>');
    const a = attrsOf(chunk.slice(0, openEnd + 1));
    const action = (a.action || '').toLowerCase();
    if (actionHint && action.indexOf(actionHint) >= 0) scopes.unshift(chunk);
    else scopes.push(chunk);
  }
  scopes.push(clean);
  for (let i = 0; i < scopes.length; i++) {
    const t = csrfInputIn(scopes[i]);
    if (t) return t;
  }
  return null;
}

function extractCsrf(body, actionHint) {
  if (body === null || body === undefined) return null;
  const text = String(body);
  const trimmed = text.trim();
  const c0 = trimmed.charAt(0);
  if (c0 === '{' || c0 === '[') {
    try {
      const j = JSON.parse(trimmed);
      if (j && typeof j.csrf === 'string' && j.csrf) return j.csrf;
      if (j && j.data && typeof j.data.csrf === 'string' && j.data.csrf) return j.data.csrf;
    } catch (e) { /* markup below */ }
  }
  return csrfFromMarkup(text, actionHint);
}

let startRef = null;
function scenarioStart() {
  if (startRef === null) {
    let st = 0;
    try { st = exec.scenario.startTime; } catch (e) { st = 0; }
    startRef = (typeof st === 'number' && st > 0) ? st : Date.now();
  }
  return startRef;
}

function sleepUntil(t) {
  const d = t - Date.now();
  if (d > 0) sleep(d / 1000);
}

/* ------------------------------- session -------------------------------- */

function login(state) {
  for (let attempt = 0; attempt < 2; attempt++) {
    const formRes = http.get(BASE_URL + '/v2/login-form', {
      jar: state.jar,
      redirects: 0,
      headers: { Accept: 'text/html,application/xhtml+xml,application/json' },
      tags: { name: 'login_form', role: 'setup' },
    });
    if (formRes.status !== 200) continue;
    const formCsrf = extractCsrf(formRes.body, '/v2/login');
    if (!formCsrf) continue;

    let res = http.post(
      BASE_URL + '/v2/login',
      JSON.stringify({ username: state.username, password: PASSWORD, csrf: formCsrf }),
      {
        jar: state.jar,
        redirects: 0,
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
          'X-CSRF-Token': formCsrf,
        },
        tags: { name: 'login', role: 'setup' },
      }
    );

    if (res.status >= 300 && res.status < 400) {
      const loc = headerOf(res, 'Location');
      if (!loc) continue;
      res = http.get(absUrl(loc), {
        jar: state.jar,
        redirects: 0,
        headers: { Accept: 'application/json,text/html' },
        tags: { name: 'login_redirect', role: 'setup' },
      });
    }

    if (res.status < 200 || res.status >= 400) continue;
    const body = jsonOf(res);
    const token = body && typeof body.csrf === 'string' && body.csrf
      ? body.csrf
      : extractCsrf(res.body, '/v2/login');
    state.csrf = token || formCsrf;
    return true;
  }
  return false;
}

function renewSession(state) {
  const res = http.post(BASE_URL + '/v2/session/renew', JSON.stringify({}), {
    jar: state.jar,
    redirects: 0,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    tags: { name: 'session_renew', role: 'setup' },
  });
  if (res.status < 200 || res.status >= 400) return false;
  const b = jsonOf(res);
  if (b && typeof b.csrf === 'string' && b.csrf) state.csrf = b.csrf;
  return true;
}

/* ------------------------------ operation ------------------------------- */
// One business_failure point per raw /v2/work response.
// Numerator: unexpected failures only (expiry / scheduled 429 excluded).

function workOperation(state) {
  let retry429 = 0;
  let recoveryUsed = false;

  for (let guard = 0; guard < 8; guard++) {
    const res = http.post(BASE_URL + '/v2/work', JSON.stringify({}), {
      jar: state.jar,
      redirects: 0,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'X-CSRF-Token': state.csrf || '',
      },
      tags: { name: 'work', pool: 'work' },
    });
    const status = res.status;
    const body = jsonOf(res);

    if (status === 200 && body && body.ok === true) {
      businessFailure.add(0);
      workAccepted.add(1);
      if (typeof body.csrf === 'string' && body.csrf) state.csrf = body.csrf;
      check(res, { 'work 200 ok': function (r) { return r.status === 200; } });
      return true;
    }

    if (status === 429) {
      businessFailure.add(0);
      if (retry429 >= 4) {
        check(false, { 'work retry budget honoured': function () { return false; } });
        return false;
      }
      retry429++;
      let ra = parseFloat(headerOf(res, 'Retry-After') || '1');
      if (!isFinite(ra) || ra < 1) ra = 1;
      if (ra > 2) ra = 2;
      sleep(ra);
      continue;
    }

    if (status === 401) {
      const err = body && body.error;
      if (err === 'expired' || err === 'session') {
        businessFailure.add(0);
        if (recoveryUsed) {
          check(false, { 'work recovery bounded': function () { return false; } });
          return false;
        }
        recoveryUsed = true;
        const recovered = err === 'expired' ? renewSession(state) : login(state);
        if (!recovered) {
          check(false, { 'work session recovered': function () { return false; } });
          return false;
        }
        continue; // retry only the interrupted operation, once
      }
      businessFailure.add(1); // denied or unknown 401 must fail its assertion
      check(res, { 'work not denied': function (r) { return r.status !== 401; } });
      return false;
    }

    businessFailure.add(1);
    check(res, {
      'work status < 400': function (r) { return r.status >= 200 && r.status < 400; },
    });
    return false;
  }
  return false;
}

/* -------------------------------- journey ------------------------------- */

export function workJourney() {
  const vuId = exec.vu.idInTest;
  const username = 'bench-' + (((vuId - 1) % USER_COUNT) + 1);
  const state = { username: username, csrf: null, jar: http.cookieJar() };

  let idx = 0;
  try { idx = exec.scenario.iterationInTest; } catch (e) { idx = 0; }
  const base = scenarioStart() + idx * JOURNEY_MS + FIRST_OFFSET_MS;

  const loggedIn = login(state);
  check(loggedIn, { 'journey login ok': function (v) { return v === true; } });
  if (!loggedIn) {
    journeyLost.add(WORK_PER_JOURNEY);
    return;
  }

  for (let k = 0; k < WORK_PER_JOURNEY; k++) {
    sleepUntil(base + k * SLOT_MS);
    const ok = workOperation(state);
    if (!ok) journeyLost.add(1);
  }
}

export default workJourney;
