# locustfile.py -- paced authenticated POST /v2/work pool @ 8 starts/s
# Locust 2.47, headless, one LoadTestShape, per-user cookies, no extra routes.

import json
import os
import random
import re
import time
from html import unescape
from urllib.parse import urljoin, urlparse

import gevent
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")

TARGET_RATE = 8.0
INTERVAL = 1.0 / TARGET_RATE
USER_COUNT = 16
SPAWN_RATE = 16.0

WARMUP = 5.0
SCORED = 30.0
ZERO_AT = WARMUP + SCORED + 1.0        # 36.0s after T0: shape asks users to stop
USER_DEADLINE = WARMUP + SCORED + 2.5  # 37.5s after T0: per-user backstop
STOP_AT = WARMUP + SCORED + 4.0        # 39.0s after T0: tick() -> None (drain 4s)
LAUNCH_TIMEOUT = 15.0
HARD_TIMEOUT = 90.0
MAX_ITERATIONS = 80
MAX_429_RETRIES = 4
MAX_RECOVERIES = 1
PASSWORD = "bench"
ACCOUNTS = 16


# --------------------------------------------------------------------------
# Global cross-user pacer.  Pure CPU code (no yields) => atomic under gevent,
# so slot hand-out is coordinated across every virtual user without threads.
# --------------------------------------------------------------------------
class Pacer(object):
    def __init__(self, interval):
        self.interval = interval
        self.epoch = None
        self.next_index = 0
        self.t0 = None
        self.issued = 0

    def acquire(self):
        now = time.monotonic()
        if self.epoch is None:
            self.epoch = now
        slot = self.epoch + self.next_index * self.interval
        self.next_index += 1
        if slot < now - 0.02:
            # Behind schedule: drop missed slots instead of flooding a burst.
            skip = int((now - slot) / self.interval) + 1
            self.next_index += skip
            slot += skip * self.interval
        if self.t0 is None:
            self.t0 = slot
        self.issued += 1
        return slot

    def age(self):
        if self.t0 is None:
            return None
        return time.monotonic() - self.t0


PACER = Pacer(INTERVAL)
_ACCOUNT_SEQ = 0


# --------------------------------------------------------------------------
# HTML helpers (tolerant of decoys / attribute-order / quote variants)
# --------------------------------------------------------------------------
_INPUT_RE = re.compile(r"<\s*input\b[^>]*>", re.I | re.S)
_FORM_RE = re.compile(r"<\s*form\b[^>]*>.*?<\s*/\s*form\s*>", re.I | re.S)
_FORM_OPEN_RE = re.compile(r"<\s*form\b[^>]*>", re.I | re.S)
_META_RE = re.compile(r"<\s*meta\b[^>]*>", re.I | re.S)
_ATTR_RE = re.compile(
    r"""([^\s=/>"']+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?""", re.S
)
_JSON_CSRF_RE = re.compile(r"""["']csrf["']\s*:\s*["']([^"']+)["']""")


def _attrs(tag):
    body = tag.strip()
    if body.startswith("<"):
        body = body[1:]
    if body.endswith(">"):
        body = body[:-1]
    body = re.sub(r"^\s*[A-Za-z0-9:_\-]+\s*", "", body, count=1)
    out = {}
    for m in _ATTR_RE.finditer(body):
        key = (m.group(1) or "").strip().lower()
        if not key or key in ("/", "<"):
            continue
        val = m.group(2)
        if val is None:
            val = m.group(3)
        if val is None:
            val = m.group(4)
        if val is None:
            val = ""
        if key not in out:
            out[key] = val
    return out


def _pick_csrf(scope):
    best = None
    best_score = None
    for m in _INPUT_RE.finditer(scope):
        a = _attrs(m.group(0))
        if (a.get("name") or "").strip().lower() != "csrf":
            continue
        if "disabled" in a:
            continue
        value = unescape(a.get("value") or "").strip()
        if not value:
            continue
        blob = " ".join("%s=%s" % (k, v) for k, v in a.items()).lower()
        score = 0
        if "decoy" in blob or "fake" in blob or "honeypot" in blob:
            score += 10
        if (a.get("type") or "").strip().lower() not in ("hidden", "text", ""):
            score += 2
        if len(value) < 8:
            score += 1
        if best is None or score < best_score:
            best, best_score = value, score
    return best


def extract_login_csrf(text):
    if not text:
        return None
    stripped = text.strip()
    if stripped.startswith("{"):
        try:
            data = json.loads(stripped)
        except Exception:
            data = None
        if isinstance(data, dict):
            tok = data.get("csrf")
            if not tok and isinstance(data.get("data"), dict):
                tok = data["data"].get("csrf")
            if tok:
                return str(tok)
    for m in _FORM_RE.finditer(text):
        opening = _FORM_OPEN_RE.match(text[m.start():])
        if not opening:
            continue
        action = (_attrs(opening.group(0)).get("action") or "").lower()
        if "login" in action:
            tok = _pick_csrf(m.group(0))
            if tok:
                return tok
    tok = _pick_csrf(text)
    if tok:
        return tok
    for m in _META_RE.finditer(text):
        a = _attrs(m.group(0))
        if (a.get("name") or "").lower() in ("csrf", "csrf-token"):
            val = unescape(a.get("content") or "").strip()
            if val:
                return val
    m = _JSON_CSRF_RE.search(text)
    if m:
        return m.group(1)
    return None


def safe_json(resp):
    try:
        data = resp.json()
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def retry_after_seconds(resp):
    raw = resp.headers.get("Retry-After")
    if raw is None:
        return None
    try:
        val = float(str(raw).strip())
    except Exception:
        return 1.0
    if val < 0.0 or val > 5.0:
        return 1.0
    return val


class WorkShape(LoadTestShape):
    """Constant population; ends the run relative to the first work start."""

    def __init__(self):
        super().__init__()
        self._launch = None

    def tick(self):
        now = time.monotonic()
        if self._launch is None:
            self._launch = now
        elapsed = now - self._launch
        age = PACER.age()
        if age is None:
            if elapsed > LAUNCH_TIMEOUT:
                return None
            return (USER_COUNT, SPAWN_RATE)
        if age >= STOP_AT or elapsed > HARD_TIMEOUT:
            return None
        if age >= ZERO_AT:
            return (0, SPAWN_RATE)
        return (USER_COUNT, SPAWN_RATE)


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    # ---------------- setup helpers (never counted as operations) ----------
    def on_start(self):
        global _ACCOUNT_SEQ
        idx = _ACCOUNT_SEQ % ACCOUNTS
        _ACCOUNT_SEQ += 1
        self.username = "bench-%d" % (idx + 1)
        self.csrf = None
        self.logged_in = False
        self.iterations = 0
        self.cart_id = None  # this pool owns no checkout/cart
        self._login()

    def _headers(self):
        h = {"Content-Type": "application/json"}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        return h

    def _keep_csrf(self, data):
        tok = data.get("csrf")
        if isinstance(tok, str) and tok:
            self.csrf = tok

    def _safe_url(self, location):
        url = urljoin(self.host.rstrip("/") + "/", location)
        p = urlparse(url)
        b = urlparse(self.host)
        if p.netloc and p.netloc != b.netloc:
            return None
        return url

    def _login(self):
        self.logged_in = False
        with self.client.get(
            "/v2/login-form", name="/v2/login-form", catch_response=True
        ) as r:
            if r.status_code >= 400 or r.status_code == 0:
                r.failure("login-form status %s" % r.status_code)
                return False
            body = r.text or ""
            r.success()
        token = extract_login_csrf(body)
        if not token:
            return False
        payload = {"username": self.username, "password": PASSWORD, "csrf": token}
        data = {}
        with self.client.post(
            "/v2/login",
            json=payload,
            name="/v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            status = r.status_code
            if status in (301, 302, 303, 307, 308):
                location = r.headers.get("Location")
                r.success()
                if not location:
                    return False
                url = self._safe_url(location)
                if url is None:
                    return False
                with self.client.get(
                    url,
                    name="/v2/login",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code >= 400 or r2.status_code == 0:
                        r2.failure("login redirect status %s" % r2.status_code)
                        return False
                    data = safe_json(r2)
                    r2.success()
            elif 200 <= status < 300:
                data = safe_json(r)
                r.success()
            else:
                r.failure("login status %s" % status)
                return False
        tok = data.get("csrf")
        self.csrf = tok if isinstance(tok, str) and tok else token
        self.logged_in = True
        return True

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            name="/v2/session/renew",
            catch_response=True,
        ) as r:
            status = r.status_code
            data = safe_json(r)
            if 200 <= status < 300:
                self._keep_csrf(data)
                r.success()
                return True
            if status == 401 and data.get("error") in ("expired", "session"):
                r.success()  # expected expiry path, not a sample failure
                return False
            r.failure("renew status %s" % status)
            return False

    # ---------------- the declared operation -------------------------------
    def _work(self):
        throttled = 0
        recovered = 0
        while True:
            with self.client.post(
                "/v2/work",
                json={},
                headers=self._headers(),
                name="/v2/work",
                catch_response=True,
            ) as r:
                status = r.status_code
                data = safe_json(r)
                if status == 200 and data.get("ok") is True:
                    self._keep_csrf(data)
                    r.success()
                    return True
                if status == 429:
                    wait = retry_after_seconds(r)
                    if wait is not None and throttled < MAX_429_RETRIES:
                        r.success()  # scheduled backpressure is expected
                        throttled += 1
                        gevent.sleep(wait + random.uniform(0.0, 0.04))
                        continue
                    r.failure("work 429 without usable Retry-After / retry budget")
                    return False
                if status == 401:
                    err = data.get("error")
                    if err == "denied":
                        r.failure("work denied (not an expiry)")
                        return False
                    if err in ("expired", "session") and recovered < MAX_RECOVERIES:
                        r.success()  # expected expiry is not a failure
                        recovered += 1
                        if err == "expired":
                            if not self._renew():
                                if not self._login():
                                    return False
                        else:
                            if not self._login():
                                return False
                        # no cart belongs to this pool -> nothing to recover
                        continue
                    r.failure("work 401 %s (recovery budget exhausted)" % err)
                    return False
                if 200 <= status < 300:
                    r.failure("work response not ok:true")
                    return False
                r.failure("unexpected work status %s" % status)
                return False

    # ---------------- paced journey loop -----------------------------------
    @task
    def paced_work(self):
        self.iterations += 1
        if self.iterations > MAX_ITERATIONS:
            raise StopUser()
        age = PACER.age()
        if age is not None and age >= USER_DEADLINE:
            raise StopUser()
        if not self.logged_in or not self.csrf:
            if not self._login():
                gevent.sleep(0.25)
                return
        slot = PACER.acquire()
        delay = slot - time.monotonic()
        if delay > 0:
            gevent.sleep(delay)
        age = PACER.age()
        if age is not None and age >= USER_DEADLINE:
            raise StopUser()
        if not self.logged_in or not self.csrf:
            if not self._login():
                return
        self._work()
